DEFICIT_CARB_MIN_G = 130

GLP1_TARGET_KCAL_BY_SEX = {"male": 1500.0, "female": 1200.0}
GLP1_TARGET_KCAL = 1200.0

def glp1_target_kcal(person) -> float:
    """GLP-1 intake target for this person. Falls back to the flat value."""
    sex = str(getattr(person, "sex", "") or "").lower()
    return float(GLP1_TARGET_KCAL_BY_SEX.get(sex, GLP1_TARGET_KCAL))

LOW_ENERGY_THRESHOLD = {"female": 1200.0, "male": 1500.0}
VLCD_HARD_FLOOR_KCAL = 800.0

AMDR_BANDS = {
    "protein": (0.10, 0.40),
    "fat":     (0.15, 0.40),
    "carb":    (0.20, 0.65),
}

def check_energy_and_amdr(person, target_kcal, protein_g, fat_g, carb_g,
                          verbose=True):
    """Flag a very-low-energy target and any macro share outside AMDR.

    REPORTS, does not enforce. Both findings are clinical judgements that need
    a human: a low target may be exactly right for a GLP-1 patient, and a high
    protein share may be a deliberate lean-mass strategy. What is not
    acceptable is either happening silently.
    """
    out, notes = {}, []
    sex = str(getattr(person, "sex", "") or "").lower()
    thresh = LOW_ENERGY_THRESHOLD.get(sex, 1200.0)
    out["target_kcal"] = float(target_kcal)
    out["low_energy"] = bool(target_kcal < thresh)
    out["below_vlcd_floor"] = bool(target_kcal < VLCD_HARD_FLOOR_KCAL)

    if out["below_vlcd_floor"]:
        notes.append(
            f"ENERGY BELOW {VLCD_HARD_FLOOR_KCAL:.0f} kcal: this is a formal "
            f"very-low-calorie diet and requires medical supervision. This "
            f"framework should not be issuing it unsupervised.")
    elif out["low_energy"]:
        notes.append(
            f"LOW ENERGY TARGET: {target_kcal:.0f} kcal is below the "
            f"{thresh:.0f} kcal level conventionally treated as needing "
            f"supervision for an adult {sex or 'person'}. This may be correct "
            f"for a GLP-1 patient whose intake is appetite-limited, but the "
            f"plan must record WHO it is for and WHY -- age, weight, activity "
            f"and relevant history -- before it is handed to anyone.")

    kcal = float(target_kcal) or 1.0
    shares = {"protein": 4.0 * float(protein_g or 0) / kcal,
              "fat": 9.0 * float(fat_g or 0) / kcal,
              "carb": 4.0 * float(carb_g or 0) / kcal}
    out["shares"] = shares
    out["amdr_violations"] = []
    for k, (lo, hi) in AMDR_BANDS.items():
        v = shares.get(k, 0.0)
        if v < lo or v > hi:
            out["amdr_violations"].append(k)
            notes.append(
                f"MACRO SHARE OUT OF RANGE: {k} is {v:.0%} of energy against "
                f"an accepted {lo:.0%}-{hi:.0%}. Protein targets here are set "
                f"per kg of body weight, which fixes the GRAMS and lets the "
                f"SHARE move with the energy target -- the same gram target is "
                f"unremarkable at 2000 kcal and extreme at 1200.")
    out["notes"] = notes
    if verbose:
        print(BOLD + "\n--- ENERGY LEVEL AND MACRO DISTRIBUTION ---" + RESET)
        print(f"  target {target_kcal:.0f} kcal | protein {shares['protein']:.0%}"
              f"  fat {shares['fat']:.0%}  carb {shares['carb']:.0%} of energy")
        for n in notes:
            print(f"  ! {n}")
        if not notes:
            print("  Within accepted ranges.")
    return out

@dataclass
class Person:
    sex: str
    age: float
    weight_kg: float
    height_cm: float
    activity: str = "active"
    pregnant: bool = False
    trimester: Optional[int] = None
    lactating: bool = False
    lactation_stage: Optional[str] = None
    deficit: float = 500.0
    on_glp1_or_weightloss_drug: bool = False
    glp1_drug: Optional[str] = None
    meals_per_day: Optional[int] = None

