def protein_per_kg(p: Person) -> float:
    """IOM RDA for protein, g/kg/day."""
    if p.age < 0.5:   return 1.52
    if p.age < 1:     return 1.20
    if p.age < 4:     return 1.05
    if p.age < 19:    return 0.95 if p.age < 14 else 0.85
    if p.pregnant or p.lactating:
        return 1.1
    return 0.8

def leucine_per_kg(p: Person) -> float:
    """IOM RDA (AI for 0-6 mo) for leucine, mg/kg body weight/day."""
    return LEUCINE_MG_PER_KG.get(life_stage_key(p))

def fat_amdr_fraction(p: Person) -> float:
    """Midpoint of the age-appropriate fat AMDR (fraction of total kcal)."""
    if p.age < 1:    return 0.475
    if p.age < 4:    return 0.35
    if p.age < 19:   return 0.30
    return 0.275

def carb_amdr_fraction(p: Person) -> float:
    """Midpoint of the carbohydrate AMDR (fraction of total kcal)."""
    if p.age < 1:    return None
    return 0.55

def water_target_ml(p: Person) -> int:
    return WATER_AI_ML.get(life_stage_key(p))

def omega3_ala_target_g(p: Person) -> float:
    """IOM Adequate Intake (AI) for omega-3 (alpha-linolenic acid), g/day.

    NIH/IOM set an AI for ALA, not an RDA, and no UL exists. For infants
    0-12 mo the AI is for total omega-3s; for ages 1+ it is for ALA.
    Source: NIH ODS Omega-3 Fatty Acids fact sheet; IOM DRI 2005.
    """
    return RDA_AI['omega3_ala_g'].get(life_stage_key(p))

