EPA_DHA_FDA_SUPPLEMENT_CAP_MG = 2000
EPA_DHA_FDA_NOT_ADVISED_MG = 5000
EPA_DHA_EFSA_SAFE_MG = 5000
DHA_ALONE_EFSA_SAFE_MG = 1000

def epa_dha_recommendation(p: Person) -> dict:
    """EPA + DHA intake target and safety ceilings (NOT an RDA/UL).

    Returns the combined EPA+DHA target (mg/day) from EFSA/expert consensus,
    any additional DHA recommended in pregnancy/lactation, and the FDA/EFSA
    safety ceilings. None of these are IOM DRIs - no RDA or UL exists for
    EPA/DHA.
    """
    key = life_stage_key(p)
    target = EPA_DHA_TARGET_MG.get(key)
    extra_dha = EPA_DHA_PREG_LACT_EXTRA_DHA_MG if (p.pregnant or p.lactating) else None
    return {
        "epa_dha_target_mg": target,
        "extra_dha_preg_lact_mg": extra_dha,
        "fda_gras_max_mg": EPA_DHA_FDA_GRAS_MG,
        "fda_supplement_cap_mg": EPA_DHA_FDA_SUPPLEMENT_CAP_MG,
        "fda_not_advised_above_mg": EPA_DHA_FDA_NOT_ADVISED_MG,
        "efsa_safe_combined_mg": EPA_DHA_EFSA_SAFE_MG,
        "efsa_safe_dha_alone_mg": DHA_ALONE_EFSA_SAFE_MG,
    }

def fiber_target(p: Person, kcal: float) -> float:
    if p.age < 1:    return 0
    base = round(14 * kcal / 1000, 1)
    if p.pregnant:   return 28
    if p.lactating:  return 29
    return base

def macronutrient_targets(p: Person, kcal: float) -> dict:
    protein_g = round(protein_per_kg(p) * p.weight_kg, 1)
    protein_pct = round(100 * (protein_g * 4) / kcal, 1) if kcal else 0.0

    leu_per_kg = leucine_per_kg(p)
    leucine_mg = round(leu_per_kg * p.weight_kg) if leu_per_kg is not None else None

    fat_frac = fat_amdr_fraction(p)
    fat_g = round((fat_frac * kcal) / 9, 1)

    carb_frac = carb_amdr_fraction(p)
    if carb_frac is not None:
        carbs_g = round((carb_frac * kcal) / 4, 1)
    else:
        carbs_g = round((kcal - (protein_g * 4 + fat_g * 9)) / 4, 1)

    kcal_from_macros = protein_g * 4 + fat_g * 9 + carbs_g * 4
    carb_pct = round(100 * (carbs_g * 4) / kcal, 1) if kcal else 0.0
    fat_pct = round(100 * (fat_g * 9) / kcal, 1) if kcal else 0.0

    return {
        "protein_g": protein_g,
        "leucine_mg": leucine_mg,
        "fat_g": fat_g,
        "carbohydrate_g": carbs_g,
        "fiber_g": fiber_target(p, kcal),
        "water_ml": water_target_ml(p),
        "omega3_ala_g": omega3_ala_target_g(p),
        "epa_dha": epa_dha_recommendation(p),
        "_amdr_percent": {
            "protein_pct_kcal": protein_pct,
            "fat_pct_kcal": fat_pct,
            "carbohydrate_pct_kcal": carb_pct,
        },
        "_energy_from_macros_kcal": round(kcal_from_macros),
    }

def deficit_targets(p: Person, maintenance_kcal: float) -> dict:
    applied_deficit = getattr(p, "deficit", DEFICIT_KCAL)
    deficit_kcal = round(maintenance_kcal - applied_deficit)

    protein_per_kg_activity = DEFICIT_PROTEIN_G_PER_KG_BY_ACTIVITY.get(
        p.activity.lower(), DEFICIT_PROTEIN_G_PER_KG)
    protein_g = round(protein_per_kg_activity * p.weight_kg, 1)
    protein_kcal = protein_g * 4

    fat_g = round((DEFICIT_FAT_MIN_FRACTION * deficit_kcal) / 9, 1)
    fat_kcal = fat_g * 9

    carb_remainder_kcal = deficit_kcal - protein_kcal - fat_kcal
    carbs_g = round(carb_remainder_kcal / 4, 1)
    carb_floor_applied = carbs_g < DEFICIT_CARB_MIN_G
    if carb_floor_applied:
        carbs_g = float(DEFICIT_CARB_MIN_G)

    kcal_from_macros = round(protein_g * 4 + fat_g * 9 + carbs_g * 4)
    over_budget = kcal_from_macros > deficit_kcal

    def _pct(kcal_part):
        return round(100 * kcal_part / deficit_kcal, 1) if deficit_kcal else 0.0

    return {
        "deficit_kcal": deficit_kcal,
        "applied_deficit": applied_deficit,
        "protein_g": protein_g,
        "fat_g": fat_g,
        "carbohydrate_g": carbs_g,
        "fiber_g": fiber_target(p, deficit_kcal),
        "water_ml": water_target_ml(p),
        "_percent": {
            "protein_pct_kcal": _pct(protein_kcal),
            "fat_pct_kcal": _pct(fat_kcal),
            "carbohydrate_pct_kcal": _pct(carbs_g * 4),
        },
        "_energy_from_macros_kcal": kcal_from_macros,
        "_carb_floor_applied": carb_floor_applied,
        "_over_budget": over_budget,
    }

