def life_stage_key(p: Person) -> str:
    a = p.age
    if p.pregnant:
        if a < 19:   return "preg_14_18"
        if a < 31:   return "preg_19_30"
        return "preg_31_50"
    if p.lactating:
        if a < 19:   return "lact_14_18"
        if a < 31:   return "lact_19_30"
        return "lact_31_50"
    if a < 0.5:  return "infant_0_6mo"
    if a < 1:    return "infant_7_12mo"
    if a < 4:    return "child_1_3"
    if a < 9:    return "child_4_8"
    sex = p.sex.lower()
    if a < 14:   return f"{sex}_9_13"
    if a < 19:   return f"{sex}_14_18"
    if a < 31:   return f"{sex}_19_30"
    if a < 51:   return f"{sex}_31_50"
    if a < 71:   return f"{sex}_51_70"
    return f"{sex}_70p"

def micronutrient_rda(p: Person) -> dict:
    key = life_stage_key(p)
    return {n: vals[key] for n, vals in RDA_AI.items()}

def micronutrient_ul(p: Person) -> dict:
    key = life_stage_key(p)
    return {n: vals.get(key) for n, vals in UPPER_LIMIT.items()}

def build_report(p: Person) -> dict:
    kcal = round(maintenance_calories(p))
    report = {
        "life_stage": life_stage_key(p),
        "maintenance_kcal": kcal,
        "macronutrients": macronutrient_targets(p, kcal),
        "micronutrients_rda": micronutrient_rda(p),
        "micronutrients_ul": micronutrient_ul(p),
    }
    if p.age >= 19 and not p.pregnant and not p.lactating:
        report["bmr_kcal"] = round(bmr_mifflin_st_jeor(p))
        report["deficit"] = deficit_targets(p, kcal)
    return report

def _fmt_macro(key, value) -> str:
    label, unit = NUTRIENT_UNITS.get(key, (key, ""))
    if value is None:
        return f"  {label:<28}see pediatric AI"
    if isinstance(value, str):
        return f"  {label:<28}{value}"
    return f"  {label:<28}{value} {unit}"

def _fmt_micro(key, rda, ul) -> str:
    label, unit = NUTRIENT_UNITS.get(key, (key, ""))
    rda_str = f"{rda} {unit}"
    ul_str = "no UL" if ul is None else f"{ul} {unit}"
    return f"  {label:<30}RDA/AI: {rda_str:<18}  UL: {ul_str}"

def print_report(p: Person) -> None:
    r = build_report(p)
    state = []
    if p.pregnant:  state.append(f"pregnant T{p.trimester}")
    if p.lactating: state.append(f"lactating {p.lactation_stage}")
    extra = (" [" + ", ".join(state) + "]") if state else ""

    print("\n" + "=" * 70)
    print(f"Profile: {p.sex}, {p.age}y, {p.weight_kg}kg, "
          f"{p.height_cm}cm, activity={p.activity}{extra}")
    print(f"Life-stage group: {r['life_stage']}")
    if "bmr_kcal" in r:
        print(f"BMR (reference):     {r['bmr_kcal']} kcal/day")
    print(f"Maintenance energy:  {r['maintenance_kcal']} kcal/day")

    macros = r["macronutrients"]
    pct = macros.get("_amdr_percent", {})
    print("\n--- Macronutrient Targets (protein RDA + fat/carb AMDR midpoints) ---")
    for k in ("protein_g", "leucine_mg", "fat_g", "carbohydrate_g",
              "fiber_g", "water_ml"):
        print(_fmt_macro(k, macros.get(k)))
    print(f"  {'(leucine: RDA 42 mg/kg adults)':<28}no UL established")
    if pct:
        print(f"  {'(% of energy)':<28}"
              f"protein {pct.get('protein_pct_kcal')}%, "
              f"fat {pct.get('fat_pct_kcal')}%, "
              f"carb {pct.get('carbohydrate_pct_kcal')}%")
        print(f"  {'(energy from macros)':<28}"
              f"{macros.get('_energy_from_macros_kcal')} kcal")

    print("\n--- Essential Fatty Acids (Omega-3) ---")
    for k in ESSENTIAL_FATTY_ACIDS:
        rda = r["micronutrients_rda"].get(k)
        ul = r["micronutrients_ul"].get(k)
        print(_fmt_micro(k, rda, ul))
    print("  (ALA value is an IOM Adequate Intake; no RDA, no UL)")

    epa_dha = macros.get("epa_dha", {})
    tgt = epa_dha.get("epa_dha_target_mg")
    extra = epa_dha.get("extra_dha_preg_lact_mg")
    print("\n  EPA + DHA (long-chain omega-3) - no RDA and no UL exist:")
    if tgt is None:
        print("    Target intake          covered by total omega-3 AI (infants)")
    else:
        line = f"    Target intake          {tgt} mg/day combined EPA+DHA (EFSA)"
        print(line)
    if extra:
        lo, hi = extra
        print(f"    Pregnancy/lactation    + {lo}-{hi} mg/day additional DHA (EFSA)")
    print(f"    Safety ceiling         {epa_dha.get('fda_gras_max_mg')} mg/day "
          f"EPA+DHA GRAS (FDA);")
    print(f"    {'':<27}<= {epa_dha.get('fda_supplement_cap_mg')} mg/day from "
          f"supplements (FDA label);")
    print(f"    {'':<27}> {epa_dha.get('fda_not_advised_above_mg')} mg/day not "
          f"advised (FDA, bleeding risk);")
    print(f"    {'':<27}up to {epa_dha.get('efsa_safe_combined_mg')} mg/day EPA+DHA "
          f"safe (EFSA),")
    print(f"    {'':<27}DHA alone up to {epa_dha.get('efsa_safe_dha_alone_mg')} "
          f"mg/day safe (EFSA)")
    print("    (these are EFSA/FDA targets & safety limits, NOT IOM RDA/UL values)")

    deficit = r.get("deficit")
    if deficit:
        dpct = deficit.get("_percent", {})
        print(f"\n--- Calorie-Deficit Targets (weight loss: maintenance "
              f"- {deficit['applied_deficit']} kcal, ~0.45 kg/week) ---")
        print(f"  {'Deficit energy':<28}{deficit['deficit_kcal']} kcal/day")
        for k in ("protein_g", "fat_g", "carbohydrate_g", "fiber_g", "water_ml"):
            print(_fmt_macro(k, deficit.get(k)))
        print(f"  {'(% of energy)':<28}"
              f"protein {dpct.get('protein_pct_kcal')}%, "
              f"fat {dpct.get('fat_pct_kcal')}%, "
              f"carb {dpct.get('carbohydrate_pct_kcal')}%")
        print(f"  {'(energy from macros)':<28}"
              f"{deficit.get('_energy_from_macros_kcal')} kcal")
        print(f"  Floors: protein >= 1.6 g/kg, fat >= 20% kcal, carb >= 130 g.")
        if deficit.get("_carb_floor_applied"):
            print("  Note: carbohydrate held at the 130 g floor.")
        if deficit.get("_over_budget"):
            print("  Note: the three floors together exceed the deficit budget;")
            print("  a full 500 kcal deficit isn't possible without dropping")
            print("  below one of them. Carbohydrate is held at 130 g, so the")
            print("  actual deficit will be smaller than 500 kcal.")

    rda, ul = r["micronutrients_rda"], r["micronutrients_ul"]
    for title, keys in [("Fat-Soluble Vitamins", VITAMINS_FAT),
                        ("Water-Soluble Vitamins", VITAMINS_WATER),
                        ("Major Minerals (Macrominerals)", MACROMINERALS),
                        ("Trace Minerals (Microminerals)", TRACEMINERALS)]:
        print(f"\n--- {title} ---")
        for k in keys:
            print(_fmt_micro(k, rda.get(k), ul.get(k)))

    print("\nNote: 'no UL' means the National Academies did not establish a")
    print("Tolerable Upper Intake Level for that nutrient/life stage (usually")
    print("insufficient data). It does NOT mean unlimited intake is safe.")
    print("Note: fat/carb targets are AMDR midpoints; any range within the AMDR")
    print("is acceptable. Protein is the RDA floor. Carb/fat %s may not sum to")
    print("100% of energy because protein is fixed by the RDA, not by an AMDR.")
    print("Note: leucine is the IOM RDA in mg/kg/day (42 mg/kg for adults),")
    print("scaled by body weight like protein; no UL exists for amino acids.")
    print("Note: omega-3 (ALA) is an IOM Adequate Intake (g/day); NIH/IOM set")
    print("no RDA and no UL for omega-3. EPA+DHA have NO IOM DRI at all - the")
    print("EPA+DHA figures are EFSA/FDA intake targets and safety ceilings, not")
    print("an RDA or UL.")
    print("Note: calorie-deficit targets are shown only for non-pregnant,")
    print("non-lactating adults, for whom an energy deficit is appropriate.")

def _ask(prompt, cast=str, valid=None, allow_blank=False, default=None):
    while True:
        raw = input(prompt).strip()
        if raw == "" and allow_blank:
            return default
        try:
            val = cast(raw)
        except ValueError:
            print("  ! Please enter a valid value.")
            continue
        if valid is not None and val not in valid:
            print(f"  ! Choose one of: {', '.join(map(str, valid))}")
            continue
        return val

def get_person_from_input() -> Person:
    print("=== Nutrition Calculator - enter your details ===")
    sex = _ask("Sex (male/female): ", lambda s: s.lower(),
               valid={"male", "female"})
    age = _ask("Age in years (use decimals for infants, e.g. 0.5): ", float)
    weight = _ask("Weight in kg: ", float)
    height = _ask("Height in cm: ", float)

    if age >= 19:
        print("\nActivity level (PAL category):")
        for name, desc in ACTIVITY_CATEGORIES.items():
            print(f"  - {name:<12} {desc}")
        activity = _ask("Enter activity category: ", lambda s: s.lower(),
                        valid=set(ACTIVITY_CATEGORIES))
    else:
        activity = "active"

    pregnant = lactating = False
    trimester = lactation_stage = None
    if sex == "female" and age >= 10:
        if _ask("Pregnant? (y/n) [n]: ", lambda s: s.lower(),
                valid={"y", "n"}, allow_blank=True, default="n") == "y":
            pregnant = True
            trimester = _ask("Trimester (1/2/3): ", int, valid={1, 2, 3})
        elif _ask("Lactating? (y/n) [n]: ", lambda s: s.lower(),
                  valid={"y", "n"}, allow_blank=True, default="n") == "y":
            lactating = True
            lactation_stage = _ask("Lactation stage (0-6mo/7-12mo): ",
                                   str, valid={"0-6mo", "7-12mo"})

    print("\nAre you currently taking a GLP-1 receptor agonist or other "
          "appetite-suppressing weight-loss medication?")
    on_glp1 = _ask("(y/n) [n]: ", lambda s: s.lower(),
                   valid={"y", "n"}, allow_blank=True, default="n") == "y"

    glp1_drug = meals_per_day = None
    if on_glp1:
        deficit = 0.0
    else:
        deficit = _ask("Daily calorie deficit below maintenance [500]: ",
                       float, allow_blank=True, default=500.0)

    person = Person(sex=sex, age=age, weight_kg=weight, height_cm=height,
                    activity=activity, pregnant=pregnant, trimester=trimester,
                    lactating=lactating, lactation_stage=lactation_stage,
                    deficit=deficit, on_glp1_or_weightloss_drug=on_glp1,
                    glp1_drug=glp1_drug, meals_per_day=meals_per_day)

    if on_glp1:
        maint = maintenance_calories(person)
        _glp1 = glp1_target_kcal(person)
        person.deficit = max(0.0, maint - _glp1)
        print(f"  -> GLP-1/weight-loss drug: total energy target fixed at "
              f"{_glp1:.0f} kcal/day "
              f"(maintenance {maint:.0f} - implied deficit "
              f"{person.deficit:.0f} kcal/day). Replaces the manual deficit "
              f"question.")
        if person.deficit > 1000:
            print(f"     NOTE: the implied deficit of {person.deficit:.0f} "
                  "kcal/day is large. The macronutrient floors may not fit "
                  "inside a 1200 kcal budget for this profile; check the "
                  "over-budget flag in the report.")

    return person

