_INDIAN_DISH_RULES_C = [(re.compile(_plural_tolerant(p)), t, s)
                        for p, t, s in _INDIAN_DISH_RULES]

def _indian_dish_class(text, segments=None):
    """Classify a head-final composite dish name.

    Returns (Food_Type, Food_Subgroup), or ("Unknown", "Unknown") for a
    deliberate exclusion, or None if no rule applies -- in which case
    classify_food() carries on with its normal USDA-oriented logic, so
    behaviour on USDA-style rows is unchanged.
    """
    for rx in _INDIAN_DENY_RE:
        if rx.search(text):
            return ("Unknown", "Unknown")

    if _is_condiment_primary(text):
        return ("Unknown", "Unknown")

    if _FRUIT_SALAD_RE.search(text):
        return ("Unknown", "Unknown")

    if _FRIED_SNACK_RE.search(text) and not _CURD_BASED_RE.search(text):
        return ("Unknown", "Unknown")

    veg_guarded = bool(_VEG_GUARD_RE.search(text))

    for rx, ftype, sub in _INDIAN_DISH_RULES_C:
        if not rx.search(text):
            continue
        if ftype == "NonVeg" and veg_guarded:
            continue
        return (ftype, sub)
    return None

_ACCOMPANIMENT_SPLIT_RE = re.compile(r",?\s+\b(?:with|in)\b\s+")

def _is_denied_text(text):
    """True if this text is an explicit exclusion (confection/condiment)."""
    t = str(text).lower().replace("-", " ")
    if _is_condiment_primary(t):
        return True
    if _FRIED_SNACK_RE.search(t) and not _CURD_BASED_RE.search(t):
        return True
    return any(rx.search(t) for rx in _INDIAN_DENY_RE)

def classify_food(description):
    if pd.isna(description):
        return ("Unknown", "Unknown")

    if _is_denied_text(description):
        return ("Unknown", "Unknown")

    head_split = _ACCOMPANIMENT_SPLIT_RE.split(str(description), maxsplit=1)
    if len(head_split) > 1 and head_split[0].strip():
        head = head_split[0]
        if _is_denied_text(head):
            return ("Unknown", "Unknown")
        res = _classify_food_core(head)
        if res[0] != "Unknown":
            return res
    return _classify_food_core(description)

def _classify_food_core(description):

    if pd.isna(description):
        return ("Unknown", "Unknown")

    text = str(description).lower()
    text = text.replace("-", " ")
    segments = _text_segments(text)

    for _rx in _INDIAN_DENY_RE:
        if _rx.search(text):
            return ("Unknown", "Unknown")

    if _is_condiment_primary(text):
        return ("Unknown", "Unknown")

    _acc = _CONDIMENT_ACCOMPANIMENT_RE.search(text)
    if _acc and _acc.start() > 0:
        text = text[:_acc.start()].strip(" ,-")
        segments = _text_segments(text)

    if _is_yogurt_primary(segments):
        return ("Dairy", "Yogurt")

    if _COCONUT_WATER_RE.search(text):
        return ("Unknown", "Unknown")

    if _is_dried_chile_pepper(segments, text):
        return ("Veg", "Spices")

    if _is_sweet_or_veg_pepper(segments):
        return ("Veg", "Other Vegetables")

    if _is_spice_primary(segments):
        return ("Veg", "Spices")

    if _is_tomato_primary(segments):
        return ("Veg", "Other Vegetables")

    if segments and _SAUCE_FIRST_RE.match(segments[0]):
        return ("Unknown", "Unknown")

    if segments and _SALAD_DRESSING_FIRST_RE.match(segments[0]):
        return ("Unknown", "Unknown")

    if _is_syrup_primary(segments):
        return ("Unknown", "Unknown")

    if _ANIMAL_FAT_IDENTITY_RE.search(text):
        return ("Fats & Oils", "Animal Fat")

    oil_type = _is_oil_primary(segments, text)
    if oil_type:
        return ("Fats & Oils", oil_type)

    if not _is_dessert_or_beverage(text, segments):
        for kw in food_groups["Veg"]["Plant Milk"]:
            if _keyword_matches(kw, text, segments):
                return ("Veg", "Plant Milk")

    if _is_beverage_primary(segments):
        return ("Unknown", "Unknown")

    for food_type, groups in food_groups.items():
        for subgroup, keywords in groups.items():
            for keyword in keywords:
                if _keyword_matches(keyword, text, segments):
                    if subgroup == "Vegetable Oil":
                        oil_type = _is_oil_primary(segments, text)
                        if oil_type:
                            return ("Fats & Oils", oil_type)
                        continue
                    if subgroup == "Eggs":
                        if not _is_egg_primary(segments):
                            continue
                        return food_type, subgroup
                    if subgroup == "Milk":
                        if not _is_milk_primary(segments):
                            continue
                    if subgroup == "Seafood" and keyword == "scallop" and "squash" in text:
                        continue
                    if subgroup == "Seafood" and keyword == "oyster":
                        if not _is_oyster_primary(text):
                            continue
                    if subgroup == "Game" and keyword == "bear":
                        if not _is_bear_primary(text):
                            continue
                    if subgroup == "Pork":
                        if not _is_pork_primary(text):
                            continue
                    if subgroup == "Seeds" and keyword == "dill":
                        if not _is_dill_primary(text):
                            continue
                    if subgroup == "Game" and keyword == "buffalo":
                        if segments and segments[0].strip().startswith("milk"):
                            continue
                    if subgroup == "Tropical Fruits" and keyword == "melon":
                        if segments and "gourd" in segments[0]:
                            continue
                    if subgroup == "Butter":
                        if not _is_butter_primary(segments, text):
                            continue
                    if subgroup == "Beef" and keyword == "steak":
                        if not _is_steak_primary(segments, text):
                            continue
                    if subgroup == "Refined Grains" and keyword == "cracker":
                        if not _is_cracker_primary(text):
                            continue
                    if (subgroup in COMPOSITE_EXCLUSION_SUBGROUPS
                            and _is_dessert_or_beverage(text, segments)):
                        continue
                    return food_type, subgroup

    ind = _indian_dish_class(text, segments)
    if ind is not None:
        return ind

    return ("Unknown", "Unknown")

