_FISH_MORPHOLOGY_RE = re.compile(
    r"(\bmeen\b\s*$|\bpaarai\b|\bparai\b|\bmachh?li\b|\bmacher\b|\bmaach\b|"
    r"\bkora\b\s*$|\bmeenu\b)")

_FUZZY_VOCAB = None

def _build_fuzzy_vocab():
    global _FUZZY_VOCAB
    vocab = set()
    for groups in food_groups.values():
        for keywords in groups.values():
            for kw in keywords:
                for w in kw.split():
                    if len(w) >= INDIAN_EXT_CONFIG["fuzzy_min_token_len"]:
                        vocab.add(w)
    _FUZZY_VOCAB = sorted(vocab)
    return _FUZZY_VOCAB

def _fuzzy_repair(text):
    """Return a repaired name, or None. See the fencing notes above."""
    if not INDIAN_EXT_CONFIG["enable_fuzzy_fallback"]:
        return None
    tokens = re.findall(r"[a-z]+", text.lower())
    if not tokens or len(tokens) > INDIAN_EXT_CONFIG["fuzzy_max_tokens"]:
        return None
    vocab = _FUZZY_VOCAB if _FUZZY_VOCAB is not None else _build_fuzzy_vocab()
    for tok in tokens:
        if len(tok) < INDIAN_EXT_CONFIG["fuzzy_min_token_len"]:
            continue
        if tok in vocab:
            continue
        near = _difflib.get_close_matches(
            tok, vocab, n=1, cutoff=INDIAN_EXT_CONFIG["fuzzy_cutoff"])
        if near:
            return re.sub(rf"\b{re.escape(tok)}\b", near[0], text.lower())
    return None

_classify_food_base = classify_food

def classify_food(description):
    """Indian-aware classifier.

    Delegates to the original classify_food for everything it already
    handled; adds normalisation, an exact-name lexicon, mixed-dish
    detection, head-final oil identity and a bounded typo repair around it.
    """
    if pd.isna(description):
        return ("Unknown", "Unknown")

    raw = _norm_food_text(description)
    low = raw.lower().replace("-", " ")
    low = _MULTISPACE_RE.sub(" ", low).strip()

    if is_dessert_or_sweet(low):
        return ("Discretionary", "Desserts & Sweets")

    if is_culinary_herb(low):
        return ("Veg", "Herbs & Aromatics")

    if re.match(r"^cheese\s*,", low):
        return ("Dairy", "Cheese")
    if re.match(r"^spices?\s*,", low) and not re.search(
            r"\b(mix|blend)\s+for\b", low):
        return ("Veg", "Spices")

    if re.match(r"^bananas?\s*,", low) and not re.search(
            r"\b(plantain|cooking\s+banana|green\s+banana|flour|chips)\b",
            low):
        return ("Veg", "Tropical Fruits")

    if re.search(r"\b(peanut|almond|cashew|hazelnut|pecan|walnut|macadamia|"
                 r"pistachio|sunflower|pumpkin\s*seed|sesame|tahini|"
                 r"nut|seed)[\s-]*butters?\b", low):
        return ("Fat", "Nuts")

    if re.search(r"\b(tofu|bean\s+curd|curd\s+cheese|soybean\s+curd|"
                 r"tempeh|natto|soy\s+protein|textured\s+vegetable\s+protein)\b",
                 low) and not re.search(r"\b(dairy|cow|buffalo|goat)\b", low):
        return ("Protein", "Soy Products")

    if _DENY_EXEMPT_RE.search(low):
        return ("Veg", "Tropical Fruits")

    if _NON_FOOD_DENY_RE.search(low):
        return ("Unknown", "Unknown")

    if INDIAN_EXT_CONFIG["enable_exact_name_lexicon"]:
        key = re.sub(r"\([^)]*\)", " ", low)
        key = _MULTISPACE_RE.sub(" ", key).strip(" ,.-")
        hit = _EXACT_NAME_LEXICON.get(key)
        if hit is None:
            hit = _EXACT_NAME_LEXICON.get(key.split(",")[0].strip())
        if hit is not None:
            return hit

    for _rx, _t, _s in _STRUCTURAL_OVERRIDES:
        if _rx.search(low):
            return (_t, _s)

    compound = _compound_species_class(low)
    if compound is not None:
        return compound

    rice = _whole_grain_rice_class(low)
    if rice is not None:
        return rice

    leafy = _leafy_head_class(low)
    if leafy is not None:
        return leafy

    organ = _organ_meat_class(low)
    if organ is not None:
        return organ

    if not _is_denied_text(low):
        mixed = _mixed_dish_class(low)
        if mixed is not None:
            return mixed

    oil = _head_final_oil_class(low)
    if oil is not None:
        return oil

    for _ctx, _tok in _FALSE_FRIEND_STRIP:
        if _ctx.search(low):
            _stripped = _MULTISPACE_RE.sub(" ", _tok.sub(" ", low)).strip(" ,-")
            _res = _classify_food_base(_stripped)
            if _res[0] != "Unknown":
                return _res

    result = _classify_food_base(raw)
    if result[0] != "Unknown":
        fixed = _colour_word_misread(low, result)
        if fixed is not None:
            return fixed
        if result[1] == "Leafy Greens":
            segs = [_MULTISPACE_RE.sub(" ", x).strip()
                    for x in re.sub(r"\([^)]*\)", " ", low).split(",")]
            if any(x in ("seed", "seeds", "kernel", "kernels")
                   for x in segs[1:]):
                return ("Veg", "Seeds")
        return result

    if _FISH_MORPHOLOGY_RE.search(low) and not _is_denied_text(low):
        return ("NonVeg", "Lean Fish")

    repaired = _fuzzy_repair(low)
    if repaired:
        result = _classify_food_base(repaired)
        if result[0] != "Unknown":
            return result

    return ("Unknown", "Unknown")

FISH_FAT_THRESHOLD_G = 5.0

def refine_fish_subgroup_by_fat(df, fat_col=None, threshold=FISH_FAT_THRESHOLD_G,
                                verbose=True):
    """Reassign Fatty Fish / Lean Fish from measured total lipid.

    Only touches rows ALREADY classified into one of those two subgroups --
    it never turns a non-fish into a fish. Tuna is left alone (it has its
    own subgroup and its own cap).
    """
    if "Food_Subgroup" not in df.columns:
        return df
    if fat_col is None:
        for c in df.columns:
            if "total lipid" in str(c).lower() or str(c).strip().lower() == "fat (g)":
                fat_col = c
                break
    if fat_col is None or fat_col not in df.columns:
        if verbose:
            print("  refine_fish_subgroup_by_fat: no fat column found; "
                  "leaving name-based fish assignment in place.")
        return df

    mask = df["Food_Subgroup"].isin(["Fatty Fish", "Lean Fish"])
    if not mask.any():
        return df
    fat = pd.to_numeric(df.loc[mask, fat_col], errors="coerce")
    new = pd.Series("Lean Fish", index=fat.index)
    new[fat >= threshold] = "Fatty Fish"
    new[fat.isna()] = df.loc[mask, "Food_Subgroup"][fat.isna()]

    changed = int((new != df.loc[mask, "Food_Subgroup"]).sum())
    df.loc[mask, "Food_Subgroup"] = new
    if verbose:
        print(f"  refine_fish_subgroup_by_fat: {int(mask.sum())} fish rows "
              f"checked against '{fat_col}' at {threshold} g/100 g; "
              f"{changed} reassigned.")
    return df

