def run_classifier_selftest(verbose=True):
    """Run CLASSIFIER_TEST_CASES. Returns (n_pass, n_fail, failures)."""
    failures = []
    for name, want_t, want_s in CLASSIFIER_TEST_CASES:
        got = classify_food(name)
        if got != (want_t, want_s):
            failures.append((name, (want_t, want_s), got))
    n_pass = len(CLASSIFIER_TEST_CASES) - len(failures)
    if verbose:
        print(f"\nClassifier self-test: {n_pass}/{len(CLASSIFIER_TEST_CASES)} passed")
        for name, want, got in failures:
            print(f"    FAIL  {name!r}\n          want {want}\n          got  {got}")
    return n_pass, len(failures), failures

def classifier_coverage_report(descriptions, verbose=True):
    """Coverage over an arbitrary list of names. Prints subgroup counts and
    the first 40 unclassified names, so a gap is visible rather than silent."""
    rows = [(d, ) + classify_food(d) for d in descriptions]
    unknown = [d for d, t, s in rows if t == "Unknown"]
    if verbose:
        from collections import Counter
        counts = Counter(f"{t} / {s}" for _, t, s in rows)
        print(f"\nCoverage: {len(rows) - len(unknown)}/{len(rows)} classified "
              f"({100.0 * (len(rows) - len(unknown)) / max(len(rows), 1):.1f}%)")
        for k, v in sorted(counts.items(), key=lambda kv: -kv[1]):
            print(f"    {k:<40}{v:>5}")
        if unknown:
            print(f"\n  Unclassified ({len(unknown)}), first 40:")
            for d in unknown[:40]:
                print(f"    {d}")
    return rows, unknown

