NOT_RECOGNISED = "Not recognised (classifier gap)"

def classification_reason(description):
    """For a row that classify_food() sent to Unknown, name the bucket.

    Returns "" for a row that DID classify. Tests the head noun as well as
    the full name, because the wrapper does -- "Saunth chutney with
    tamarind" is excluded on its head ("chutney"), not on its tail.
    """
    if pd.isna(description):
        return NOT_RECOGNISED
    t = _norm_food_text(description).lower().replace("-", " ")
    t = _MULTISPACE_RE.sub(" ", t)
    head = _ACCOMPANIMENT_SPLIT_RE.split(t, maxsplit=1)[0]
    for label, rx in EXCLUSION_REASONS:
        if rx.search(t) or rx.search(head):
            return label
    if _is_condiment_primary(t) or _is_condiment_primary(head):
        return "Condiment, pickle or preserve"
    if _FRIED_SNACK_RE.search(t) and not _CURD_BASED_RE.search(t):
        return "Deep-fried snack"
    if any(rx.search(t) or rx.search(head) for rx in _INDIAN_DENY_RE):
        return "Excluded by deny rule (other)"
    return NOT_RECOGNISED

def pool_diagnostic_report(df, desc_col="description", verbose=True):
    """Break the non-pool rows into 'excluded on purpose' vs 'not recognised'.

    Call after the Food_Type/Food_Subgroup columns exist. Returns a dict of
    counts. Purely a report -- it does not modify df.
    """
    n = len(df)
    unknown = df[df["Food_Type"] == "Unknown"]
    known = df[df["Food_Type"] != "Unknown"]
    norole = known[~known["Food_Subgroup"].isin(SUBGROUP_MEAL_ROLE.keys())]
    pool = len(known) - len(norole)

    from collections import Counter
    reasons = Counter(classification_reason(d) for d in unknown[desc_col])
    gaps = reasons.get(NOT_RECOGNISED, 0)

    if verbose:
        print("\n  Why rows are not in the candidate pool:")
        print(f"    {'in pool':<38}{pool:>6}{100.0*pool/max(n,1):>8.1f}%")
        if len(norole):
            print(f"    {'classified, no meal role':<38}"
                  f"{len(norole):>6}{100.0*len(norole)/n:>8.1f}%")
            for sg, c in norole["Food_Subgroup"].value_counts().items():
                print(f"        - {sg:<32}{c:>6}")
        for label, c in sorted(reasons.items(), key=lambda kv: -kv[1]):
            if label == NOT_RECOGNISED:
                continue
            print(f"    {label:<38}{c:>6}{100.0*c/n:>8.1f}%")
        print(f"    {NOT_RECOGNISED:<38}{gaps:>6}{100.0*gaps/max(n,1):>8.1f}%"
              f"   <- the only defect bucket")
        if gaps:
            print("      first 20:")
            for d in [d for d in unknown[desc_col]
                      if classification_reason(d) == NOT_RECOGNISED][:20]:
                print(f"        {d}")
    return {"total": n, "pool": pool, "no_role": len(norole),
            "not_recognised": gaps, "reasons": dict(reasons)}

def select_multiple(options, prompt, display=None):
    """
    Show a numbered menu and let the user pick one OR MORE options.

    Accepts:
      - numbers:            1,3,5   or   1 3 5
      - names:              Veg, Dairy
      - a mix of both:      1, Dairy
      - everything:         all  (or  *)

    Multi-word names (e.g. "Leafy Greens") are matched whole.
    Returns a list of the chosen canonical option strings.
    """
    labels = display if display is not None else options

    print()
    for i, label in enumerate(labels, start=1):
        print(f"{i}. {label}")

    lower_map = {opt.lower(): opt for opt in options}

    while True:
        raw = input(prompt).strip()

        if raw == "" or raw == "0" or raw.lower() in ("all", "*"):
            return list(options)

        tokens = []
        for part in re.split(r"[,\n]+", raw):
            part = part.strip()
            if not part:
                continue
            if part.lower() in lower_map:
                tokens.append(part)
            else:
                tokens.extend(part.split())

        chosen, invalid = [], []

        for tok in tokens:
            if tok.isdigit():
                idx = int(tok)
                if 1 <= idx <= len(options):
                    chosen.append(options[idx - 1])
                else:
                    invalid.append(tok)
            elif tok.lower() in lower_map:
                chosen.append(lower_map[tok.lower()])
            else:
                invalid.append(tok)

        seen = set()
        chosen = [x for x in chosen if not (x in seen or seen.add(x))]

        if invalid:
            print(f"Not recognized: {', '.join(invalid)}. "
                  f"Use numbers, names, or 'all'.")
            continue
        if not chosen:
            print("Nothing selected. Try again.")
            continue

        return chosen

