MAX_ROWS = 50

INFLAMM_WEIGHTS = (0.248133, 0.273940, 0.248133, 0.229794)
WHO_TRANS_PCT_E = 0.01
WHO_SUGAR_PCT_E = 0.10
WHO_SATFAT_PCT_E = 0.05
