def configure_scoring(df: pd.DataFrame, person: nc.Person):
    rep = nc.build_report(person)
    if "deficit" in rep:
        energy_basis = rep["deficit"]["deficit_kcal"]
    else:
        energy_basis = rep["maintenance_kcal"]

    nc.K_M = nc.WHO_TRANS_PCT_E * energy_basis / nc.TRANS_KCAL_PER_G
    nc.K_N = nc.WHO_SUGAR_PCT_E * energy_basis / nc.SUGAR_KCAL_PER_G
    nc.K_O = nc.WHO_SATFAT_PCT_E * energy_basis / nc.SATFAT_KCAL_PER_G
    nc.K_SODIUM = 2000.0
    nc.TRANS_COL = nc._resolve_col(df, nc.TRANS_COL_CANDIDATES)
    nc.SUGAR_COL = nc._resolve_col(df, nc.SUGAR_COL_CANDIDATES)
    nc.SATFAT_COL = nc._resolve_col(df, nc.SATFAT_COL_CANDIDATES)

    nc.DF_COLUMNS = set(df.columns)
    nc.COLS = {name: nc._resolve_col(df, cands)
               for name, cands in nc.COL_CANDIDATES.items()}
    nc.K = nc.build_k_constants(person)
    nc.HAIR_SCORE_ACTIVE = (getattr(person, "deficit", 0.0) >= 800.0
                             or getattr(person, "on_glp1_or_weightloss_drug", False))
    return rep, energy_basis

@dataclass
class FoodModel:
    df: pd.DataFrame
    cand_idx: np.ndarray
    person: nc.Person
    cfg: OptConfig

    n: int = 0
    xl: np.ndarray = field(default=None)
    xu: np.ndarray = field(default=None)
    energy_arr: np.ndarray = field(default=None)
    col_arr: dict = field(default_factory=dict)
    energy_col: Optional[str] = None
    target_kcal: float = 0.0
    ul_list: list = field(default_factory=list)
    macro_band_list: list = field(default_factory=list)
    soft_list: list = field(default_factory=list)
    soft_weights: list = field(default_factory=list)
    names: list = field(default_factory=list)

    def __post_init__(self):
        df, ci = self.df, self.cand_idx
        self.n = len(ci)

        best_col, best_cov = None, -1.0
        for c in nc.COL_CANDIDATES["energy"]:
            if c in df.columns:
                s = pd.to_numeric(df[c], errors="coerce")
                cov = float((s > 0).mean())
                if cov > best_cov:
                    best_col, best_cov = c, cov
        if best_col is None:
            raise ValueError("No energy column found in dataset.")
        self.energy_col = best_col
        self.energy_arr = self._arr(self.energy_col)

        needed_cols = set()
        for c in nc.COLS.values():
            if c:
                needed_cols.add(c)
        for c in (nc.TRANS_COL, nc.SUGAR_COL, nc.SATFAT_COL, self.energy_col):
            if c:
                needed_cols.add(c)
        for c in needed_cols:
            self.col_arr[c] = self._arr(c)

        rep = nc.build_report(self.person)
        if "deficit" in rep:
            self.target_kcal = rep["deficit"]["deficit_kcal"]
            macro = rep["deficit"]
        else:
            self.target_kcal = rep["maintenance_kcal"]
            macro = rep["macronutrients"]

        ul = nc.micronutrient_ul(self.person)
        for dri_key, short in DRI_TO_SHORT.items():
            col = nc.COLS.get(short)
            ul_v = ul.get(dri_key)
            if col and (ul_v is not None):
                self.ul_list.append((col, float(ul_v)))

        fat_col = next((c for c in TOTAL_FAT_CANDIDATES if c in df.columns), None)
        macro_targets = [
            (nc.COLS.get("protein"), macro.get("protein_g")),
            (nc.COLS.get("carb"),    macro.get("carbohydrate_g")),
            (nc.COLS.get("fiber"),   macro.get("fiber_g")),
            (fat_col,                macro.get("fat_g")),
        ]
        protein_col = nc.COLS.get("protein")
        for col, tgt in macro_targets:
            if col and tgt and tgt > 0:
                if col not in self.col_arr:
                    self.col_arr[col] = self._arr(col)
                self.soft_list.append((col, float(tgt)))
                self.soft_weights.append("protein" if col == protein_col else "macro")
        self.macro_cols = {col for col, tgt in macro_targets if col and tgt and tgt > 0}

        if hasattr(nc, "build_macro_bands"):
            self.macro_band_list = nc.build_macro_bands(
                macro_targets,
                protein_col=nc.COLS.get("protein"),
                fat_col=fat_col,
                fiber_col=nc.COLS.get("fiber"),
                carb_col=nc.COLS.get("carb"))

        if EFA_FLOORS_ENABLED:
            for _key, _kname in (("la", "LA"), ("ala", "ALA")):
                _c = nc.COLS.get(_key)
                _t = nc.K.get(_kname)
                if (_c and _c in df.columns and _t and _t > 0
                        and self._column_has_data(_c)):
                    if _c not in self.col_arr:
                        self.col_arr[_c] = self._arr(_c)
                    self.soft_list.append((_c, float(_t)))
                    self.soft_weights.append("macro")
            _epa, _dha = nc.COLS.get("epa"), nc.COLS.get("dha")
            _ed = nc.K.get("EPA_DHA") or EPA_DHA_TARGET_RANGE_G[0]
            _have = [c for c in (_epa, _dha)
                     if c and c in df.columns and self._column_has_data(c)]
            if _have and _ed and _ed > 0:
                for _c in _have:
                    if _c not in self.col_arr:
                        self.col_arr[_c] = self._arr(_c)
                for _c in _have:
                    self.soft_list.append((_c, float(_ed) / len(_have)))
                    self.soft_weights.append("macro")

        leu_col = nc.COLS.get("leucine")
        leu_mg = macro.get("leucine_mg")
        if (leu_col and leu_col in df.columns and leu_mg and leu_mg > 0
                and self._column_has_data(leu_col)):
            if leu_col not in self.col_arr:
                self.col_arr[leu_col] = self._arr(leu_col)
            self.soft_list.append((leu_col, float(leu_mg) / 1000.0))
            self.soft_weights.append("micro")

        rda = nc.micronutrient_rda(self.person)
        self.unmeasured_cols = []
        if not hasattr(self, "nutrient_coverage"):
            self.nutrient_coverage = {}
        for dri_key, short in DRI_TO_SHORT.items():
            col = nc.COLS.get(short)
            tgt = rda.get(dri_key)
            if not (col and tgt and tgt > 0):
                continue
            if short in EXCLUDED_NUTRIENTS or col in EXCLUDED_NUTRIENT_COLS:
                continue
            if not self._column_has_data(col):
                self.unmeasured_cols.append(col)
                continue
            self.soft_list.append((col, float(tgt)))
            self.soft_weights.append("micro")

        self.xl = np.zeros(self.n)
        self.xu = np.full(self.n, 3.0)

        self.names = [str(df.iloc[i].get(self._desc_col(), f"food_{i}"))
                      for i in ci]

        caps_g, _ = nc.subgroup_serving_caps(self.target_kcal)
        subs = self.df.iloc[self.cand_idx]["Food_Subgroup"].astype(str).to_numpy()
        self.subgroup_arr = subs
        fatdairy_subs = {sg for sg, roles in nc.SUBGROUP_MEAL_ROLE.items()
                          if "Fat/Dairy" in roles}
        self.fatdairy_mask = np.isin(subs, list(fatdairy_subs))
        wholegrain_subs = {sg for sg, roles in nc.SUBGROUP_MEAL_ROLE.items()
                            if getattr(nc, "CARB_ROLE", "Whole Grain") in roles}
        self.wholegrain_mask = np.isin(subs, list(wholegrain_subs))
        self.unknown_subgroup_fallback_g = 10.0
        self.subgroup_groups = [
            (np.where(subs == sg)[0],
             float(caps_g.get(sg, self.unknown_subgroup_fallback_g)))
            for sg in np.unique(subs)
        ]

        for sg_label, sg_members, target_g in (
                ("Healthy Fats", ["Healthy Fats"], nc.HEALTHY_FATS_MIN_G),
                ("Legumes", ["Legumes"], nc.LEGUMES_MIN_G),
                ("Vegetables", nc.VEGETABLE_SUBGROUPS, nc.VEGETABLES_MIN_G),
                ("Whole Grains", getattr(nc, "WHOLE_GRAIN_SUBGROUPS",
                                         ["Whole Grains"]),
                 nc.WHOLE_GRAINS_MIN_G),
                ("Fruits", nc.FRUIT_SUBGROUPS, nc.FRUITS_MIN_G)):
            member_mask = np.isin(subs, sg_members)
            if member_mask.any() and target_g and target_g > 0:
                col_name = f"{sg_label} (g, subgroup total)"
                self.col_arr[col_name] = np.where(member_mask, 100.0, 0.0)
                self.soft_list.append((col_name, float(target_g)))
                self.soft_weights.append("macro")
                self.macro_cols.add(col_name)
            else:
                print(f"  NOTE: no candidate foods tagged '{sg_label}' in "
                      f"this pool -- its {target_g:g} g/day soft minimum "
                      f"will show 100% shortfall until such foods are "
                      f"included in the Food Type/Subgroup selection.")

    def _column_has_data(self, col):
        """True if the column is populated well enough to SCORE.

        "At least one value" is not enough, and assuming it was is what
        produced two false deficiencies in clinical review:

          molybdenum 0.00       FNDDS carries no molybdenum. The FDC fetch
                                returned it for a handful of ingredients, so
                                the column held a few non-zero cells, passed
                                an any()-style check, entered soft_list, and
                                the plan then scored 0% of floor -- reported
                                as a deficiency for a nutrient that was
                                never measured for 99% of the pool.
          pantothenic acid 31%  FNDDS carries it for MOST codes but not all.
                                Blanks summed as zero, so a plan with 262 g
                                Greek yogurt scored 1.53 mg -- arithmetically
                                impossible, and a partial-coverage artifact
                                rather than a diet problem.

        A nutrient is scored only if at least MIN_NUTRIENT_COVERAGE of the
        candidate pool carries a real value. Below that the intake sum is
        dominated by blanks-as-zero and the percentage is meaningless.
        Coverage is recorded either way so the panel can show it.
        """
        if not hasattr(self, "nutrient_coverage"):
            self.nutrient_coverage = {}
        if col not in self.df.columns:
            self.nutrient_coverage[col] = 0.0
            return False
        v = pd.to_numeric(self.df.iloc[self.cand_idx][col], errors="coerce")
        n = max(len(v), 1)
        cov = float(v.notna().sum()) / n
        self.nutrient_coverage[col] = cov
        return cov >= MIN_NUTRIENT_COVERAGE

    def _arr(self, col):
        return pd.to_numeric(self.df.iloc[self.cand_idx][col],
                             errors="coerce").fillna(0.0).clip(lower=0).to_numpy()

    def _desc_col(self):
        for c in ["description", "food_description", "food_name"]:
            if c in self.df.columns:
                return c
        return self.df.columns[0]

    def daily(self, x):
        x = np.asarray(x, dtype=float)
        total_grams = float(x.sum()) * 100.0
        total_kcal = float(np.dot(x, self.energy_arr))
        row = {}
        for col, arr in self.col_arr.items():
            row[col] = float(np.dot(x, arr))
        if total_grams > 0:
            row[self.energy_col] = (total_kcal / total_grams) * 100.0
        else:
            row[self.energy_col] = 0.0
        return row, total_kcal, total_grams

    def raw_objectives(self, x):
        """Human-readable objectives (NOT yet converted to minimization)."""
        row, total_kcal, _ = self.daily(x)
        mood = nc.mood_score(row)
        hair = nc.hair_score(row)
        muscle = nc.muscle_protection_score(row)
        satiety = nc.satiety_score(row)
        transfat = nc.transfat_score(row)
        addedsugar = nc.addedsugar_score(row)
        satfat = nc.satfat_score(row)
        inflammation = nc.inflammation_score(row)
        return dict(Mood=mood, Hair=hair, Muscle=muscle, Satiety=satiety,
                    TransFat=transfat,
                    AddedSugar=addedsugar, SatFat=satfat,
                    Inflammation=inflammation, Energy_kcal=total_kcal)

    def soft_shortfall(self, x):
        """Mean fractional shortfall below all soft minimums, in [0,1].
        Flat, unweighted average over EVERY soft entry (macros + subgroup
        totals + all micronutrient RDAs) -- this is deliberately back to
        the original per-entry-equal-weight behaviour, so micronutrient
        pressure is exactly what it always was. Protein (and the other
        macro/"good food" targets) get their EXTRA push from
        boost_shortfall() below instead, which is additive on top of this
        rather than sharing/diluting this average -- see the comment
        there for why: weighting entries directly inside one shared
        average necessarily steals relative pull from whichever entries
        aren't up-weighted (confirmed regression -- see conversation)."""
        if not self.soft_list:
            return 0.0
        short = 0.0
        ul_map = dict(getattr(self, "ul_list", []) or [])
        for col, tgt in self.soft_list:
            intake = float(np.dot(x, self.col_arr[col]))
            short += max(0.0, (tgt - intake) / tgt)

            if "(g, subgroup total)" in col:
                continue
            try:
                ceiling = nc.soft_ceiling_for(col, tgt, ul_map.get(col))
                if ceiling and intake > ceiling:
                    short += ((intake - ceiling) / ceiling
                              * float(getattr(nc, "MICRO_CEILING_BOOST", 0.0))
                              / max(len(self.soft_list), 1))
            except Exception:
                pass
        n = len(self.soft_list)
        try:
            _na = float(np.dot(x, self.col_arr[_sodium_col_name(self)])) \
                if _sodium_col_name(self) else 0.0
            _tgt = float(globals().get("SODIUM_TARGET_MG_PER_DAY", 1800.0))
            if _tgt > 0 and _na > _tgt:
                short += SODIUM_SOFT_WEIGHT * min((_na - _tgt) / _tgt, 2.0)
                n += 1
        except Exception:
            pass
        return short / max(n, 1)

    def boost_shortfall(self, x):
        """Extra, SEPARATE shortfall pressure for protein, the other
        macro/"good food" subgroup targets, and Fat/Dairy food DIVERSITY
        -- added on TOP of soft_shortfall() in _evaluate(), not blended
        into it. This is what actually fixes protein routinely landing
        under target and Fat/Dairy collapsing to one repeated food,
        without taking anything away from the micronutrient RDAs: those
        keep drawing their full, original, undiminished pressure from
        soft_shortfall() above, while these get this additional,
        independent push. Returns (protein_boost, macro_group_boost,
        fatdairy_diversity_boost, wholegrain_diversity_boost) as four
        separate numbers so each can carry its own weight in _evaluate()."""
        protein_col = nc.COLS.get("protein")
        protein_short = 0.0
        macro_short = 0.0
        n_macro = 0
        weights = self.soft_weights if self.soft_weights else [None] * len(self.soft_list)
        for (col, tgt), tag in zip(self.soft_list, weights):
            if col != protein_col and tag != "macro":
                continue
            intake = float(np.dot(x, self.col_arr[col]))
            shortfall = max(0.0, (tgt - intake) / tgt)
            if col == protein_col:
                protein_short = shortfall
            else:
                if "(g, subgroup total)" in col:
                    shortfall *= float(getattr(
                        nc, "SUBGROUP_FLOOR_BOOST", 1.0))
                    try:
                        ceiling = tgt * nc.subgroup_ceiling_mult(col)
                        if ceiling > 0 and intake > ceiling:
                            shortfall += ((intake - ceiling) / ceiling
                                          * float(getattr(
                                              nc, "SUBGROUP_CEILING_BOOST",
                                              0.0)))
                    except Exception:
                        pass
                macro_short += shortfall
                n_macro += 1
        macro_short = (macro_short / n_macro) if n_macro else 0.0

        n_distinct = int(np.count_nonzero((x > 0) & self.fatdairy_mask))
        fatdairy_short = max(0.0, (nc.FAT_DAIRY_MIN_DISTINCT - n_distinct)
                              / nc.FAT_DAIRY_MIN_DISTINCT)

        n_wg_distinct = int(np.count_nonzero((x > 0) & self.wholegrain_mask))
        wholegrain_short = max(0.0, (nc.WHOLE_GRAIN_MIN_DISTINCT - n_wg_distinct)
                                / nc.WHOLE_GRAIN_MIN_DISTINCT)

        return protein_short, macro_short, fatdairy_short, wholegrain_short

    def ul_violation(self, x):
        """g(x) = intake - (UL x safety fraction); <=0 is feasible.

        PATCHED (PART 2F-6): the ceiling is UL_SAFETY_FRAC of the
        published UL, not the UL itself. A UL is the highest intake with
        no expected risk of adverse effects -- a ceiling, not a target --
        so planning to sit exactly on it leaves nothing for the gap
        between a modelled plan and a real day's eating.
        """
        frac = float(getattr(nc, "UL_SAFETY_FRAC", 1.0))
        g = []
        for col, ul_v in self.ul_list:
            intake = float(np.dot(x, self.col_arr[col]))
            g.append(intake - ul_v * frac)
        return g

    def macro_band_violation(self, x):
        """Two g(x) per macro band: under the floor, and over the
        ceiling. Both are HARD -- see MACRO_HARD_BANDS in PART 2F-6."""
        g = []
        for col, lo, hi, _label in getattr(self, "macro_band_list", []):
            intake = float(np.dot(x, self.col_arr[col]))
            g.append(lo - intake)
            g.append(intake - hi)
        return g

    def subgroup_violation(self, x):
        """g(x) = subgroup_total_grams - cap (<=0 feasible) for each subgroup."""
        x = np.asarray(x, float)
        return [float(x[idx].sum()) * 100.0 - cap_g
                for idx, cap_g in self.subgroup_groups]

    def count_dup_subgroups(self):
        """Number of subgroups BOTH present in this candidate pool AND
        scoped (has an explicit max-count entry) in cfg.duplicate_limit_
        subgroups, computed fresh from CURRENT cfg state -- not cached --
        so DietProblem always sizes n_ieq_constr correctly even if the
        dict was edited (e.g. interactively) after FoodModel was built."""
        limited = dict(getattr(self.cfg, "duplicate_limit_subgroups", {}))
        return sum(1 for idx, _cap_g in self.subgroup_groups
                   if self._subgroup_name_for(idx) in limited)

    def subgroup_duplicate_violation(self, x):
        """g(x) = (active foods in this subgroup) - max_count, but ONLY for
        subgroups listed in cfg.duplicate_limit_subgroups (a dict mapping
        subgroup name -> its own max distinct-food count). <=0 means the
        active count is within that subgroup's own limit. Subgroups NOT in
        the dict are skipped entirely here (no constraint emitted for
        them), so variety is fully unrestricted everywhere except the
        scoped subgroups -- e.g. two different Whole Grains can always be
        active together, while Poultry might be capped at 1 and Fatty Fish
        at 2, independently, per the dict's values."""
        x = np.asarray(x, float)
        limited = dict(getattr(self.cfg, "duplicate_limit_subgroups", {}))
        out = []
        for idx, _cap_g in self.subgroup_groups:
            sg_name = self._subgroup_name_for(idx)
            if sg_name in limited:
                max_count = float(limited[sg_name])
                out.append(float((x[idx] > 0).sum()) - max_count)
        return out

    def _subgroup_name_for(self, idx):
        """Subgroup name for a subgroup_groups index array (all entries in
        idx share the same subgroup by construction of subgroup_groups)."""
        if len(idx) == 0:
            return None
        return str(self.subgroup_arr[idx[0]])

    def nutrient_panel(self, x):
        """Daily totals of every tracked macro and micronutrient for plan x,
        paired with its floor (RDA / macro minimum) and UL ceiling (if any).
        Returns (macros, micros): lists of dicts."""
        x = np.asarray(x, float)
        ul_map = {col: ul for col, ul in self.ul_list}
        macros, micros = [], []
        for col, floor in self.soft_list:
            intake = float(np.dot(x, self.col_arr[col]))
            rec = {"name": col, "intake": intake, "floor": floor,
                   "ul": ul_map.get(col)}
            (macros if col in self.macro_cols else micros).append(rec)
        return macros, micros

    def watch_panel(self, x):
        """Daily totals for the seven nutrients tracked even when they carry
        no RDA floor: sodium, ALA, EPA, DHA, trans fat, saturated fat, and
        total sugars. These are "limit" or "target" nutrients the score
        equations use internally (inflammation, omega3_term) but that never
        appeared in nutrient_panel() because they have no soft floor. Returns
        a list of dicts: {name, intake, unit, ul, note}."""
        x = np.asarray(x, float)
        sod_ul = nc.micronutrient_ul(self.person).get("sodium_mg")
        rows_def = [
            ("Sodium",          nc.COLS.get("sodium"), "mg", sod_ul,
             "DRI UL shown for reference; not a hard optimizer constraint."),
            ("ALA (omega-3)",   nc.COLS.get("ala"),     "g",  None,
             f"target (AI) = {nc.K.get('ALA', float('nan')):.2f} g"),
            ("EPA (omega-3)",   nc.COLS.get("epa"),     "g",  None,
             "no individual EPA target; scored jointly as EPA+DHA"),
            ("DHA (omega-3)",   nc.COLS.get("dha"),     "g",  None,
             f"EPA+DHA combined target = {nc.K.get('EPA_DHA', float('nan')):.2f} g"),
            ("Trans fat",       nc.TRANS_COL,           "g",  None,
             "no DRI UL exists; lower is better (inflammation_score)."),
            ("Saturated fat",   nc.SATFAT_COL,          "g",  None,
             "no DRI UL exists; lower is better (inflammation_score)."),
            ("Total sugars",    nc.COLS.get("sugars"),  "g",  None,
             "total sugars (not just added); lower favors satiety/mood."),
        ]
        rows = []
        for name, col, unit, ul, note in rows_def:
            if col and col in self.col_arr:
                intake = float(np.dot(x, self.col_arr[col]))
            else:
                intake, note = 0.0, (note + " [column not found in dataset]")
            rows.append({"name": name, "intake": intake, "unit": unit,
                         "ul": ul, "note": note})
        return rows

    def adequacy(self, x):
        """Mean Adequacy Ratio (MAR) and % of floors met for plan x.
        NAR_i = min(intake_i / floor_i, 1); MAR = mean(NAR) * 100. Uses all
        RDA/macro floors. Returns (MAR_percent, percent_floors_met)."""
        x = np.asarray(x, float)
        nars = []
        for col, tgt in self.soft_list:
            if tgt and tgt > 0:
                nars.append(min(float(np.dot(x, self.col_arr[col])) / tgt, 1.0))
        if not nars:
            return 100.0, 100.0
        nars = np.asarray(nars)
        return float(100 * nars.mean()), float(100 * (nars >= 1.0).mean())

def active_objectives(o, target_kcal, cfg):
    """Active objectives as (name, value, sense) tuples.
    Protection has been REMOVED COMPLETELY from this file: the
    nutrient_protection_score() function, the o["Protection"] entry in
    raw_objectives(), and every diagnostic/report use of it (validate_plan,
    _corner_anchor, sensitivity_analysis, nutrient_sensitivity, the
    sensitivity CSVs/plots and SCORE_COLUMNS) are all gone. It is neither
    optimized nor computed nor reported anywhere.
    Inflammation is the single AHP-weighted composite score
    (transfat_score/addedsugar_score/satfat_score still exist individually
    and are still used by inflammation_score() under the hood; they are not
    exposed to the optimizer as separate axes).
    Full objective set (default): Mood, Hair, Muscle, Satiety,
        Inflammation, Energy_dev -> 6.
    If cfg.on_glp1_or_weightloss_drug is True, Satiety is DROPPED entirely
    (-> 5 objectives): GLP-1 receptor agonists and similar weight-loss drugs
    pharmacologically
    suppress appetite, so the Satiety score -- which models food volume/
    protein/fiber/energy-density driven fullness under NORMAL hunger
    signalling -- doesn't meaningfully apply; optimizing for it in that
    state doesn't reflect how the person will actually feel. satiety_score()
    itself is untouched and still computed/available for diagnostics; it
    is simply not part of the objective vector the optimizer searches on
    in this case. No other objective, K constant, or constraint changes.
    Each MAXIMIZED sub-score (Mood/Hair/Muscle/Satiety) is computed with its
    own AHP weights first."""
    rel_dev = abs(o["Energy_kcal"] - target_kcal) / max(target_kcal, 1e-9)
    band = cfg.energy_band_frac if cfg.energy_band_frac else 0.10
    K_ENERGY_DEV = band / 3.0
    energy_dev = rel_dev / (rel_dev + K_ENERGY_DEV)

    items = [(DISPLAY_NAME["Mood"], o["Mood"], "max"),
             (DISPLAY_NAME["Hair"], o["Hair"], "max"),
             (DISPLAY_NAME["Muscle"], o["Muscle"], "max")]
    if not (getattr(cfg, "on_glp1_or_weightloss_drug", False)
            and GLP1_DROP_SATIETY):
        items.append((DISPLAY_NAME["Satiety"], o["Satiety"], "max"))
    items.append((DISPLAY_NAME["Inflammation"], o["Inflammation"], "min"))
    items.append((DISPLAY_NAME["Energy_dev"], energy_dev, "min"))
    return items

GLP1_DROP_SATIETY: bool = False

def n_objectives(cfg):
    if getattr(cfg, "on_glp1_or_weightloss_drug", False) and GLP1_DROP_SATIETY:
        return 5
    return 6

def _min_vec(items):
    """(name,value,sense) list -> minimization vector (negate the maximises)."""
    return [(-v if s == "max" else v) for _, v, s in items]

class DietProblem(ElementwiseProblem):
    def __init__(self, fm: FoodModel, cfg: OptConfig):
        self.fm = fm
        self.cfg = cfg
        self.meal_mode = str(getattr(nc, "MEAL_AWARE_MODE", "off"))
        self.n_meal = nc.n_meal_constraints(self.meal_mode)
        self.n_band = 2 if cfg.energy_band_frac else 0
        self.n_subgroup = len(fm.subgroup_groups)
        self.n_dup = fm.count_dup_subgroups()
        self.n_wweia = 1 if globals().get("DISH_MODE", False) else 0
        self.n_sodium = 1 if globals().get("SODIUM_HARD_CONSTRAINT", False) else 0
        try:
            mark_csv_pool(fm)
        except Exception:
            fm._has_csv_rows = False
        super().__init__(
            n_var=fm.n,
            n_obj=n_objectives(cfg),
            n_ieq_constr=(len(fm.ul_list) + self.n_band + self.n_subgroup
                          + self.n_dup + self.n_wweia + self.n_sodium
                          + 2 * len(getattr(fm, "macro_band_list", []))
                          + self.n_meal),
            xl=fm.xl,
            xu=fm.xu,
        )

    def _evaluate(self, x, out, *args, **kwargs):
        fm, cfg = self.fm, self.cfg
        o = fm.raw_objectives(x)
        protein_short, macro_short, fatdairy_short, wholegrain_short = fm.boost_shortfall(x)
        penalty = (cfg.soft_weight * fm.soft_shortfall(x)
                   + nc.PROTEIN_BOOST_WEIGHT * protein_short
                   + nc.MACRO_BOOST_WEIGHT * macro_short
                   + nc.FATDAIRY_BOOST_WEIGHT * fatdairy_short
                   + nc.WHOLEGRAIN_BOOST_WEIGHT * wholegrain_short)

        try:
            _w = float(getattr(nc, "COMMONNESS_WEIGHT", 0.0))
            if _w > 0:
                penalty += _w * (1.0 - nc.plan_commonness(fm, x))
        except Exception:
            pass

        if self.meal_mode in ("soft", "full"):
            try:
                penalty += (nc.MEAL_PENALTY_WEIGHT
                            * nc.meal_soft_penalty(fm, x, self.meal_mode))
            except Exception:
                pass

        items = active_objectives(o, fm.target_kcal, cfg)
        F = [m + penalty for m in _min_vec(items)]
        out["F"] = np.array(F)

        g = list(fm.ul_violation(x))
        if self.n_band:
            band = cfg.energy_band_frac
            lo = fm.target_kcal * (1.0 - band)
            hi = fm.target_kcal * (1.0 + band)
            energy = o["Energy_kcal"]
            g.append(lo - energy)
            g.append(energy - hi)
        g.extend(fm.macro_band_violation(x))
        g.extend(fm.subgroup_violation(x))
        g.extend(fm.subgroup_duplicate_violation(x))
        if self.n_sodium:
            try:
                g.append(sodium_violation(fm, x))
            except Exception:
                g.append(0.0)

        if self.n_wweia:
            g.append(wweia_constraint_violation(fm, x))
        if self.n_meal:
            try:
                mg = nc.meal_constraints(fm, x, self.meal_mode)
            except Exception:
                mg = [0.0] * self.n_meal
            if len(mg) != self.n_meal:
                mg = (list(mg) + [0.0] * self.n_meal)[:self.n_meal]
            g.extend(mg)

        if len(g) != self.n_ieq_constr:
            raise RuntimeError(
                f"DietProblem produced {len(g)} constraints but declared "
                f"{self.n_ieq_constr}. pymoo reports this as an opaque "
                "reshape error; the real cause is a constraint added to "
                "_evaluate() without being counted in __init__.")
        out["G"] = np.array(g) if g else np.zeros(0)

class CardinalityRepair(Repair):
    def __init__(self, fm: FoodModel, cfg: OptConfig):
        super().__init__()
        self.fm = fm
        self.cfg = cfg
        self._sstep = _serving_step_x(fm)

    def _do(self, problem, X, random_state=None, **kwargs):
        _rs = random_state if random_state is not None else np.random.default_rng()
        X = np.atleast_2d(np.array(X, dtype=float))
        xl, xu = self.fm.xl, self.fm.xu
        _floor = getattr(self.fm, "min_serving_x", None)
        if _floor is None:
            lo_serv = np.where(xl > 0, xl, 0.10)
        else:
            lo_serv = np.where(xl > 0, np.maximum(xl, _floor), _floor)
        for r in range(X.shape[0]):
            x = np.clip(X[r], 0.0, xu)
            on = x > 0
            small = on & (x < lo_serv)
            x[small & (x >= 0.5 * lo_serv)] = lo_serv[small & (x >= 0.5 * lo_serv)]
            x[small & (x < 0.5 * lo_serv)] = 0.0
            active = np.where(x > 0)[0]

            dup_limited = dict(getattr(self.cfg, "duplicate_limit_subgroups", {}))
            if dup_limited:
                for idx, _cap_g in self.fm.subgroup_groups:
                    if len(idx) == 0:
                        continue
                    sg_name = str(self.fm.subgroup_arr[idx[0]])
                    if sg_name not in dup_limited:
                        continue
                    max_count = int(dup_limited[sg_name])
                    sub_active = idx[x[idx] > 0]
                    if len(sub_active) > max_count:
                        order = sub_active[np.argsort(x[sub_active])[::-1]]
                        keep = order[:max_count]
                        drop = order[max_count:]
                        x[drop] = 0.0
                active = np.where(x > 0)[0]

            if len(active) > self.cfg.max_foods:
                def _role_of(i):
                    sg = str(self.fm.subgroup_arr[i])
                    roles = nc.SUBGROUP_MEAL_ROLE.get(sg)
                    return roles[0] if roles else "Other"

                def _is_protected(i):
                    return str(self.fm.subgroup_arr[i]) in nc.SOFT_MIN_SUBGROUPS

                buckets = {}
                for i in active:
                    buckets.setdefault(_role_of(i), []).append(i)
                for grp in buckets.values():
                    grp.sort(key=lambda i: (not _is_protected(i), -x[i]))

                keep = []
                grp_names = sorted(buckets.keys())
                cursors = {g: 0 for g in grp_names}
                while len(keep) < self.cfg.max_foods:
                    progressed = False
                    for g in grp_names:
                        if len(keep) >= self.cfg.max_foods:
                            break
                        c = cursors[g]
                        if c < len(buckets[g]):
                            keep.append(buckets[g][c])
                            cursors[g] = c + 1
                            progressed = True
                    if not progressed:
                        break

                keep = np.array(keep, dtype=int)
                mask = np.ones(len(x), dtype=bool)
                mask[keep] = False
                x[mask] = 0.0
                active = keep

            if len(active) < self.cfg.min_foods:
                sub_counts = {}
                if dup_limited:
                    for i in active:
                        sg = str(self.fm.subgroup_arr[i])
                        if sg in dup_limited:
                            sub_counts[sg] = sub_counts.get(sg, 0) + 1
                off = np.where(x == 0)[0]
                need = self.cfg.min_foods - len(active)
                if need > 0 and len(off) > 0:
                    picked = []
                    pool = list(off)
                    _rs.shuffle(pool)
                    for i in pool:
                        if len(picked) >= need:
                            break
                        sg = str(self.fm.subgroup_arr[i])
                        if dup_limited and sg in dup_limited:
                            if sub_counts.get(sg, 0) >= int(dup_limited[sg]):
                                continue
                            sub_counts[sg] = sub_counts.get(sg, 0) + 1
                        picked.append(i)
                    if picked:
                        x[picked] = lo_serv[picked]
                    active = np.where(x > 0)[0]

            _band = self.cfg.energy_band_frac
            if _band:
                _tgt = self.fm.target_kcal
                _e = float(np.dot(x, self.fm.energy_arr))
                if _e > 0 and not (_tgt * (1.0 - _band) <= _e
                                   <= _tgt * (1.0 + _band)):
                    x = np.clip(x * (_tgt / _e), 0.0, xu)
                    active = np.where(x > 0)[0]

            for idx, cap_g in self.fm.subgroup_groups:
                if len(idx) == 0:
                    continue
                total_g = float(x[idx].sum()) * 100.0
                if total_g > cap_g:
                    x[idx] *= (cap_g / total_g) * (1.0 - 1e-9)

            grid = self.cfg.serving_grid_g
            sstep = getattr(self, "_sstep", None)
            has_serv = sstep is not None and np.any(~np.isnan(sstep))
            if grid or has_serv:
                gstep = (grid / 100.0) if grid else None
                if has_serv:
                    step_v = np.where(np.isnan(sstep),
                                      (gstep if gstep else np.nan), sstep)
                else:
                    step_v = np.full(len(x), gstep)
                active = np.where(x > 0)[0]
                active = active[~np.isnan(step_v[active])]
                if len(active):
                    step = step_v[active]
                    x[active] = np.round(x[active] / step) * step
                    zeroed = active[x[active] == 0]
                    if len(zeroed):
                        zs = step_v[zeroed]
                        needed = np.ceil(lo_serv[zeroed] / zs) * zs
                        x[zeroed] = needed

                    over = active[x[active] > xu[active]]
                    if len(over):
                        os_ = step_v[over]
                        room = np.floor(xu[over] / os_) * os_
                        x[over] = np.where(room > 0, room, x[over])

                    for idx, cap_g in self.fm.subgroup_groups:
                        if len(idx) == 0:
                            continue
                        total_g = float(x[idx].sum()) * 100.0
                        guard = 0
                        while total_g > cap_g + 1e-9 and guard < 10000:
                            guard += 1
                            sub_active = idx[x[idx] > 0]
                            if len(sub_active) == 0:
                                break
                            biggest = sub_active[np.argmax(x[sub_active])]
                            bstep = step_v[biggest]
                            if not np.isfinite(bstep) or bstep <= 0:
                                x[biggest] = 0.0
                                total_g = float(x[idx].sum()) * 100.0
                                continue
                            new_val = x[biggest] - bstep
                            if new_val < lo_serv[biggest] - 1e-12:
                                x[biggest] = 0.0
                            else:
                                x[biggest] = new_val
                            total_g = float(x[idx].sum()) * 100.0

            X[r] = np.clip(x, 0.0, xu)
        return X

class SparseDietSampling(Sampling):
    def __init__(self, fm, cfg):
        super().__init__()
        self.fm = fm
        self.cfg = cfg

    def _do(self, problem, n_samples, *args, random_state=None, **kwargs):
        fm, cfg = self.fm, self.cfg
        rng = random_state if random_state is not None else np.random.default_rng()
        lo = np.where(fm.xl > 0, fm.xl, 0.10)
        X = np.zeros((n_samples, fm.n))
        for r in range(n_samples):
            k = int(rng.integers(cfg.min_foods, cfg.max_foods + 1))
            idx = rng.choice(fm.n, size=min(k, fm.n), replace=False)
            X[r, idx] = rng.uniform(lo[idx],
                                    np.maximum(fm.xu[idx], lo[idx]))
            e = float(np.dot(X[r], fm.energy_arr))
            if e > 0:
                X[r] = np.clip(X[r] * (fm.target_kcal / e), 0.0, fm.xu)
        return X

CONVERGENCE_ARCHIVE_MAX: int = 300

class _ConvergenceCallback(Callback):
    """Records the current non-dominated front (clean min-vec) every
    cfg.hv_every generations, so we can plot hypervolume vs generation."""
    def __init__(self, fm, cfg):
        super().__init__()
        self.fm, self.cfg = fm, cfg
        self.gens, self.fronts = [], []
        self.feasible_frac = []
        self._archive = None

    def notify(self, algorithm):
        g = int(algorithm.n_gen or 0)
        if g == 1 or g % self.cfg.hv_every == 0 or g == self.cfg.n_gen:
            pop = algorithm.pop
            X = pop.get("X")
            try:
                cv = np.asarray(pop.get("CV")).reshape(-1)
                _all = np.atleast_2d(X)
                _ok = cv <= 1e-8
                self.feasible_frac.append(float(_ok.mean()) if len(cv) else 0.0)
                X = _all[_ok]
            except Exception:
                X = np.atleast_2d(X)
                self.feasible_frac.append(float("nan"))
            self.gens.append(g)
            if len(X) == 0:
                self.fronts.append(np.empty((0, n_objectives(self.cfg))))
                return
            try:
                Mn = _clean_min_matrix(self.fm, X, self.cfg)
                if self._archive is None or len(self._archive) == 0:
                    merged = Mn
                else:
                    merged = np.vstack([self._archive, Mn])
                nd = NonDominatedSorting().do(merged, only_non_dominated_front=True)
                self._archive = merged[nd]
                if len(self._archive) > CONVERGENCE_ARCHIVE_MAX:
                    keep = np.random.default_rng(0).choice(
                        len(self._archive), CONVERGENCE_ARCHIVE_MAX,
                        replace=False)
                    self._archive = self._archive[np.sort(keep)]
                self.fronts.append(self._archive.copy())
            except Exception:
                self.fronts.append(np.empty((0, n_objectives(self.cfg))))

def _scoring_fingerprint(fm) -> str:
    """Hash of everything that determines what a plan SCORES, as opposed to
    how it is searched for.

    This exists because the AHP nutrient weights live inline inside the score
    functions rather than in named constants, so editing a weight changes
    every objective value while leaving all OptConfig fields untouched. Hashing
    the SOURCE of the scoring functions catches any such edit automatically,
    including ones nobody remembers making. The person, their derived K
    constants and the resolved targets are folded in too: two people with the
    same OptConfig and the same candidate pool are still different problems,
    and before this was hashed one profile could silently resume another
    profile's checkpoints."""
    import inspect
    fns = [
        mood_score, hair_score, muscle_protection_score, satiety_score,
        inflammation_score, transfat_score, sodium_score, satfat_score,
        addedsugar_score, energy_density, omega3_term,
        complex_carbohydrates, sat, _sat_term, _inflam_penalty,
        build_k_constants, active_objectives,
    ]

    def _fn_identity(f):
        """Source text where available, else the compiled code object.

        inspect.getsource() raises OSError when a function was defined by
        pasting into a REPL rather than loaded from a file, which would make
        the fingerprint unusable in exactly the interactive setting this
        script is often run in. The bytecode fallback is not cosmetic: an
        inline AHP weight lives in co_consts, so editing 0.265209 to 0.30
        changes the constants tuple and therefore the hash, which is the
        property the fingerprint actually needs."""
        try:
            return inspect.getsource(f)
        except (OSError, TypeError):
            c = getattr(f, "__code__", None)
            if c is None:
                return repr(f)
            consts = tuple(x for x in c.co_consts
                           if isinstance(x, (int, float, str, bool, type(None))))
            return repr((f.__name__, c.co_names, consts, c.co_code))

    src = "\n".join(_fn_identity(f) for f in fns)

    p = fm.person
    person_fields = (
        p.sex, p.age, p.weight_kg, p.height_cm, p.activity,
        p.pregnant, p.trimester, p.lactating, p.lactation_stage,
        p.deficit, p.on_glp1_or_weightloss_drug,
    )
    parts = [
        src,
        str(INFLAMM_WEIGHTS),
        str(person_fields),
        f"{fm.target_kcal:.6f}",
        str(sorted((k, round(float(v), 9)) for k, v in (K or {}).items())),
        f"{K_M:.9f}|{K_N:.9f}|{K_O:.9f}|{K_SODIUM:.9f}",
        str(HAIR_SCORE_ACTIVE),
        str(fm.ul_list), str(fm.soft_list), str(fm.soft_weights),
        str(sorted(COLS.items())),
    ]
    return hashlib.sha256("|".join(parts).encode()).hexdigest()[:16]

def _cfg_signature(fm, cfg) -> str:
    """Short hash identifying 'this exact optimization problem', so
    checkpoint files from an OLD run (different generations, ref points,
    food set, objectives, etc.) are never mistaken for results of the
    CURRENT run and silently reused. Anything that changes what a seed's
    result MEANS should go in here -- which includes the SCORING, not just
    the search parameters: see _scoring_fingerprint()."""
    parts = [
        str(cfg.n_gen), str(cfg.n_ref_points), str(cfg.pop_size),
        str(cfg.min_foods), str(cfg.max_foods), str(cfg.soft_weight),
        str(cfg.energy_band_frac), str(cfg.on_glp1_or_weightloss_drug),
        str(cfg.serving_grid_g), str(cfg.sbx_eta), str(cfg.sbx_prob),
        str(cfg.pm_eta), str(fm.n),
        str(sorted(np.asarray(fm.cand_idx).tolist())),
        str(cfg.checkpoint_run_id or ""),
        _scoring_fingerprint(fm),
    ]
    return hashlib.sha256("|".join(parts).encode()).hexdigest()[:16]

def _checkpoint_paths(cfg, sig):
    if not cfg.checkpoint_enabled:
        return None, None
    root = _os.path.join(cfg.checkpoint_dir or "checkpoints", sig)
    _os.makedirs(root, exist_ok=True)
    return root, root

def _checkpoint_load_seed(root, seed):
    """Return a previously-saved seed result dict, or None if missing/
    unreadable (a partially-written file from a crash mid-save should never
    crash the resumed run -- just treat that seed as not-yet-done)."""
    if root is None:
        return None
    path = _os.path.join(root, f"seed_{seed}.pkl")
    if not _os.path.exists(path):
        return None
    try:
        with open(path, "rb") as f:
            return pickle.load(f)
    except Exception:
        return None

def _checkpoint_save_seed(root, seed, result):
    """Atomic-ish save: write to a temp file then rename, so a crash DURING
    the write never leaves a corrupt checkpoint file that _checkpoint_load_
    seed would then have to detect and discard."""
    if root is None:
        return
    path = _os.path.join(root, f"seed_{seed}.pkl")
    tmp = path + ".tmp"
    try:
        with open(tmp, "wb") as f:
            pickle.dump(result, f)
        _os.replace(tmp, path)
    except Exception as e:
        print(f"  WARNING: failed to checkpoint seed {seed}: {e!r}")

def _run_one_seed(fm, cfg, seed, ref_dirs, pop, termination):
    """Run NSGA-III for exactly ONE seed and return everything the caller
    needs to aggregate, as a dict. This is the single, shared definition of
    "what running one seed means" -- both the sequential loop and the
    parallel worker path below call this same function, so there is no risk
    of the two paths silently drifting apart and giving different results."""
    cb = _ConvergenceCallback(fm, cfg)
    algorithm = NSGA3(
        ref_dirs=ref_dirs,
        pop_size=pop,
        sampling=SparseDietSampling(fm, cfg),
        crossover=SBX(prob=cfg.sbx_prob, eta=cfg.sbx_eta),
        mutation=PM(eta=cfg.pm_eta,
                    prob_var=1.0 / max(cfg.max_foods, 1)),
        repair=CardinalityRepair(fm, cfg),
        eliminate_duplicates=True,
    )
    t_seed = time.perf_counter()
    res = minimize(DietProblem(fm, cfg), algorithm, termination,
                   seed=seed, callback=cb, verbose=False)
    dt = time.perf_counter() - t_seed

    X = hv = front = None
    if res.X is not None:
        X = np.atleast_2d(res.X)
        hv = _seed_hv(fm, X, cfg)
        front = _clean_min_matrix(fm, X, cfg)
    feas = None
    try:
        cv = np.asarray(res.pop.get("CV")).reshape(-1)
        feas = float((cv <= 1e-8).mean())
    except Exception:
        pass
    return dict(seed=seed, X=X, hv=hv, front=front, gens=cb.gens,
               fronts=cb.fronts, feasibility=feas, dt=dt,
               feasible_frac=getattr(cb, "feasible_frac", []))

_W_FM = _W_CFG = _W_REFDIRS = _W_POP = _W_TERM = None
_W_DISH_MODE_FLAGS = None

def _capture_mode_flags():
    """Flags a spawned worker cannot inherit and must be told."""
    return {"DISH_MODE": DISH_MODE,
            "SUBGROUP_CAPS_MUTED": SUBGROUP_CAPS_MUTED,
            "PREFER_WHOLE_STAPLE": PREFER_WHOLE_STAPLE,
            "APPLY_FDC_SUBSTITUTIONS": APPLY_FDC_SUBSTITUTIONS}

def _parallel_worker_init(fm, cfg, ref_dirs, pop, termination,
                          mode_flags=None):
    """Pool initializer: runs ONCE per worker process at startup (not once
    per seed). The env-var calls below are now a NO-OP SAFETY NET, not the
    real fix: the actual thread-limiting happens at the very top of this
    file (before numpy/pandas are ever imported), which is the only point
    where setting these vars reliably affects BLAS's internal thread pool.
    Setting them again here (after numpy is already loaded and BLAS is
    already initialized) has no effect in the vast majority of cases, but
    is kept as a harmless belt-and-suspenders call in case a future BLAS
    build reads these vars lazily. Re-runs configure_scoring() so this
    process's copy of the nc globals (K, COLS, TRANS_COL, SUGAR_COL,
    SATFAT_COL, HAIR_SCORE_ACTIVE) is correct, and stashes the heavy,
    seed-independent objects (fm, cfg, ref_dirs, pop, termination) so each
    per-seed task only has to ship a single integer."""
    import os
    os.environ.setdefault("OMP_NUM_THREADS", "1")
    os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
    os.environ.setdefault("MKL_NUM_THREADS", "1")
    global _W_FM, _W_CFG, _W_REFDIRS, _W_POP, _W_TERM
    _W_FM, _W_CFG, _W_REFDIRS, _W_POP, _W_TERM = fm, cfg, ref_dirs, pop, termination
    configure_scoring(fm.df, fm.person)
    if mode_flags:
        globals().update(mode_flags)

def _parallel_worker_run(seed):
    """Per-task entry point dispatched by the Pool: runs one seed using the
    worker-global state set up once by _parallel_worker_init."""
    return _run_one_seed(_W_FM, _W_CFG, seed, _W_REFDIRS, _W_POP, _W_TERM)

def _parallel_ping(i):
    """Trivial health-check task: proves a worker process actually started
    and can execute code (i.e. the Pool + initializer genuinely succeeded).
    Used to detect a silently-broken parallel pool -- e.g. worker functions
    defined in a Jupyter notebook's __main__ via `%run`, which 'spawn'
    (required on Windows) cannot resolve in a fresh child process -- BEFORE
    committing real, possibly very long, seed work to it. A broken pool then
    fails here, fast (seconds), with a clear message, instead of the caller
    hanging forever waiting for seed results that would never arrive."""
    import os
    return os.getpid()

def run_nsga3(fm: FoodModel, cfg: OptConfig):
    pop = cfg.pop_size or cfg.n_ref_points
    ref_dirs = get_reference_directions("energy", n_objectives(cfg),
                                        cfg.n_ref_points, seed=1)
    termination = get_termination("n_gen", cfg.n_gen)

    all_X = []
    per_seed_hv = []
    feas_traces = []
    seed_fronts = []
    feasibility = []
    convergence = []
    seed_times = []
    seeds = [cfg.base_seed + s for s in range(cfg.n_seeds)]
    t_start = time.perf_counter()

    sig = _cfg_signature(fm, cfg)
    ckpt_root, _ = _checkpoint_paths(cfg, sig)
    if cfg.checkpoint_enabled:
        print(f"  checkpointing ON  (dir: {ckpt_root})")

    results_by_seed = {}

    def _collect(r, from_checkpoint=False):
        results_by_seed[r["seed"]] = r
        n_sol = 0 if r["X"] is None else len(r["X"])
        tag = " [resumed from checkpoint]" if from_checkpoint else ""
        print(f"  seed {r['seed']:>3}: {n_sol} non-dominated solutions  "
              f"[{r['dt']:.1f}s]{tag}")

    def _finalise_collection():
        """Fold buffered per-seed results into the pooled arrays in ascending
        seed order, so the pooled front is byte-identical across re-runs."""
        for seed in sorted(results_by_seed):
            r = results_by_seed[seed]
            if r["X"] is not None:
                all_X.append(r["X"])
                per_seed_hv.append(r["hv"])
                seed_fronts.append(r["front"])
                convergence.append((r["gens"], r["fronts"]))
                if r.get("feasible_frac"):
                    feas_traces.append(r["feasible_frac"])
            if r["feasibility"] is not None:
                feasibility.append(r["feasibility"])
            seed_times.append(r["dt"])

    resumed_seeds, pending_seeds = [], []
    for seed in seeds:
        cached = _checkpoint_load_seed(ckpt_root, seed) if ckpt_root else None
        if cached is not None:
            resumed_seeds.append((seed, cached))
        else:
            pending_seeds.append(seed)
    if resumed_seeds:
        print(f"  resuming {len(resumed_seeds)}/{len(seeds)} seeds from "
              f"checkpoints, {len(pending_seeds)} left to run")
    for seed, cached in resumed_seeds:
        _collect(cached, from_checkpoint=True)

    seeds = pending_seeds

    def _run_sequential():
        for seed in seeds:
            r = _run_one_seed(fm, cfg, seed, ref_dirs, pop, termination)
            _checkpoint_save_seed(ckpt_root, seed, r)
            _collect(r)

    use_sequential = not (cfg.n_parallel and cfg.n_parallel > 1) or not seeds

    if not use_sequential:
        n_workers = min(cfg.n_parallel, len(seeds))
        print(f"  running {cfg.n_seeds} seeds across {n_workers} parallel "
              f"processes...")
        try:
            ctx = mp.get_context("fork")
        except ValueError:
            ctx = mp.get_context()

        poolx = None
        try:
            poolx = ctx.Pool(processes=n_workers, initializer=_parallel_worker_init,
                              initargs=(fm, cfg, ref_dirs, pop, termination,
                                        _capture_mode_flags()))
            for p in [poolx.apply_async(_parallel_ping, (i,))
                      for i in range(n_workers)]:
                p.get(timeout=60)
        except Exception as e:
            print(f"  WARNING: parallel worker pool failed its startup "
                  f"check ({e!r}).")
            print(f"  Falling back to SEQUENTIAL execution for all "
                  f"{cfg.n_seeds} seeds.")
            print(f"  (Common cause: running via `%run nutrition_diet_"
                  f"optimizer.py` in Jupyter on Windows. Fix: use "
                  f"`import nutrition_diet_optimizer as M; M.main()` "
                  f"instead -- this avoids the issue entirely.)")
            if poolx is not None:
                try:
                    poolx.terminate()
                    poolx.join()
                except Exception:
                    pass
            use_sequential = True
        else:
            with poolx:
                for r in poolx.imap(_parallel_worker_run, seeds):
                    _checkpoint_save_seed(ckpt_root, r["seed"], r)
                    _collect(r)

    if use_sequential:
        _run_sequential()

    _finalise_collection()

    total_time = time.perf_counter() - t_start

    if not all_X:
        raise RuntimeError("No feasible solutions found. Loosen bounds/ULs.")

    pooled = np.vstack(all_X)
    front_X, front_obj = _global_front(fm, pooled, cfg)

    _hv_lo = front_obj.min(axis=0)
    _hv_hi = front_obj.max(axis=0)
    per_seed_hv = [_seed_hv(fm, Xs, cfg, bounds=(_hv_lo, _hv_hi))
                   for Xs in all_X]

    globals()["_LAST_FEAS_TRACES"] = [
        type("_F", (), {"feasible_frac": t})() for t in feas_traces]
    fm.research = _research_metrics(per_seed_hv, seed_fronts, front_obj,
                                    feasibility, convergence, cfg)
    fm.research["total_time"] = total_time
    fm.research["seed_times"] = seed_times
    return front_X, front_obj, per_seed_hv

def _research_metrics(per_seed_hv, seed_fronts, ref_front, feasibility,
                      convergence, cfg):
    """IGD+ per seed (vs the pooled reference front), feasibility, and a
    normalised hypervolume-vs-generation curve per seed."""
    out = {"per_seed_hv": per_seed_hv, "feasibility": feasibility}

    lo, hi = ref_front.min(axis=0), ref_front.max(axis=0)
    span = np.where(hi - lo > 1e-12, hi - lo, 1.0)
    ref_n = (ref_front - lo) / span

    igd = IGDPlus(ref_n)
    out["igd_plus"] = [float(igd((sf - lo) / span)) for sf in seed_fronts]

    allsnap = [f for (_, fronts) in convergence for f in fronts if len(f)]
    curves = []
    if allsnap:
        stacked = np.vstack(allsnap)
        glo, ghi = stacked.min(axis=0), stacked.max(axis=0)
        gspan = np.where(ghi - glo > 1e-12, ghi - glo, 1.0)
        hv = HV(ref_point=np.ones(ref_front.shape[1]) * 1.1)
        for gens, fronts in convergence:
            ys = []
            for f in fronts:
                if len(f):
                    ys.append(float(hv((f - glo) / gspan)))
                else:
                    ys.append(0.0)
            curves.append((gens, ys))
    out["convergence"] = curves
    return out

def wilcoxon_compare(metric_a, metric_b, label_a="A", label_b="B", name="HV"):
    """Mann-Whitney U (Wilcoxon rank-sum) test between two configs' per-seed
    metric arrays. Call after running both versions, e.g.:
        wilcoxon_compare(hv7, hv5, '7-obj', '5-obj', 'HV')
    NOTE: do NOT compare raw HV across different objective counts; use this for
    same-dimension comparisons (or on IGD+/feasibility)."""
    from scipy.stats import mannwhitneyu
    a, b = np.asarray(metric_a, float), np.asarray(metric_b, float)
    u, p = mannwhitneyu(a, b, alternative="two-sided")
    print(f"\n{name}: {label_a} median {np.median(a):.4f} (IQR "
          f"{np.percentile(a,25):.4f}-{np.percentile(a,75):.4f})  vs  "
          f"{label_b} median {np.median(b):.4f} (IQR "
          f"{np.percentile(b,25):.4f}-{np.percentile(b,75):.4f})")
    print(f"Mann-Whitney U = {u:.1f}, p = {p:.4g}  -> "
          f"{'significant (p<0.05)' if p < 0.05 else 'not significant'}")
    return u, p

def _clean_min_matrix(fm: FoodModel, X, cfg):
    """Active-objective MINIMIZATION matrix WITHOUT the soft penalty (for
    ranking, HV and reporting)."""
    rows = []
    for x in X:
        o = fm.raw_objectives(x)
        items = active_objectives(o, fm.target_kcal, cfg)
        rows.append(_min_vec(items))
    return np.array(rows)

def _global_front(fm, X, cfg):
    M = _clean_min_matrix(fm, X, cfg)
    nd = NonDominatedSorting().do(M, only_non_dominated_front=True)
    return X[nd], M[nd]

def _seed_hv(fm, X, cfg, bounds=None):
    """Hypervolume of one seed's front.

    `bounds` is a (lo, hi) pair of COMMON normalisation vectors, normally
    taken from the pooled front over all seeds. Pass it whenever seed HVs
    are going to be compared with each other.

    Without it each seed is normalised against its OWN min and max, which
    stretches every front -- however narrow -- to fill [0,1]. A seed that
    found a small corner of the trade-off surface then scores like one that
    covered it, so the resulting mean and standard deviation across seeds
    measure nothing comparable. Self-normalisation is kept only as a
    fallback for the single-front case."""
    M = _clean_min_matrix(fm, X, cfg)
    if bounds is None:
        lo, hi = M.min(axis=0), M.max(axis=0)
    else:
        lo, hi = bounds
    span = np.where(hi - lo > 1e-12, hi - lo, 1.0)
    Mn = np.clip((M - lo) / span, 0.0, 1.1)
    return HV(ref_point=np.ones(M.shape[1]) * 1.1)(Mn)

def pick_recommended(front_obj, weights):
    """Equal/weighted normalised distance to the ideal point (smaller=better).
    front_obj is the clean MIN matrix. Returns index into the front."""
    lo, hi = front_obj.min(axis=0), front_obj.max(axis=0)
    span = np.where(hi - lo > 1e-12, hi - lo, 1.0)
    norm = (front_obj - lo) / span
    w = np.asarray(weights, dtype=float)
    if w.shape[0] != front_obj.shape[1]:
        w = np.ones(front_obj.shape[1])
    w = w / w.sum()
    score = (norm * w).sum(axis=1)

    best = np.flatnonzero(score <= score.min() + 1e-12)
    if len(best) == 1:
        return int(best[0])
    order = np.lexsort(front_obj[best].T[::-1])
    return int(best[order[0]])

def _random_feasible_diets(fm, cfg, n, rng):
    """Sample energy-matched, UL-feasible random diets respecting the food
    count (cardinality) and serving bounds. Baseline for 'does the optimizer
    actually help'."""
    band = cfg.energy_band_frac or 0.02
    lo, hi = fm.target_kcal * (1 - band), fm.target_kcal * (1 + band)
    out, tries, cap = [], 0, n * 30
    while len(out) < n and tries < cap:
        tries += 1
        k = int(rng.integers(cfg.min_foods, cfg.max_foods + 1))
        active = rng.choice(fm.n, size=min(k, fm.n), replace=False)
        x = np.zeros(fm.n)
        x[active] = rng.uniform(0.2, np.maximum(fm.xu[active], 0.2))
        e = float(np.dot(x, fm.energy_arr))
        if e <= 0:
            continue
        x = np.clip(x * (fm.target_kcal / e), 0.0, fm.xu)
        e2 = float(np.dot(x, fm.energy_arr))
        if not (lo <= e2 <= hi):
            continue
        if fm.ul_list and max(fm.ul_violation(x)) > 0:
            continue
        out.append(x)
    return out

def _corner_anchor(fm, front_X, rec_x):
    """For each score, show the front's plan that is best on ONLY that score
    (its single-objective 'corner') with its full profile -- demonstrating that
    optimizing one goal sacrifices the others, while the recommended plan stays
    balanced."""
    keys = ["Mood", "Hair", "Muscle", "Satiety", "Inflammation"]
    profiles = [fm.raw_objectives(x) for x in front_X]
    print(BOLD + "\n--- SINGLE-OBJECTIVE CORNERS (trade-off check) ---" + RESET)
    print("  Each row = the front's best plan for ONE goal; columns = its full scores.")
    print("  (Column codes: Mood/Hair/Musc/Saty/Unhl -> "
          + ", ".join(f"{_ABBREV[k]}={DISPLAY_NAME.get(k, k)}" for k in keys)
          + ")")
    print("  " + f"{'optimize ->':<14}"
          + "".join(f"{_ABBREV[k]:>8}" for k in keys))
    for k in keys:
        better_hi = (k != "Inflammation")
        vals = [p[k] for p in profiles]
        idx = int(np.argmax(vals) if better_hi else np.argmin(vals))
        row = profiles[idx]
        label = DISPLAY_NAME.get(k, k)
        print("  " + f"{label:<14}" + "".join(f"{row[kk]:>8.3f}" for kk in keys))
    rec = fm.raw_objectives(rec_x)
    print("  " + f"{'RECOMMENDED':<14}" + "".join(f"{rec[kk]:>8.3f}" for kk in keys))
    print("  (Single-goal corners spike one score and sag elsewhere; the "
          "recommended plan stays balanced.)")

def validate_plan(fm, cfg, rec_x):
    """Compare the recommended plan against a random feasible-diet baseline on
    the five scores + Mean Adequacy Ratio, and print where it ranks."""
    rng = np.random.default_rng(cfg.base_seed)
    rnd = _random_feasible_diets(fm, cfg, cfg.n_random, rng)
    print(BOLD + "\n--- DIET VALIDATION (recommended vs random feasible diet) ---" + RESET)
    if not rnd:
        print("  (could not sample feasible random diets to compare)")
        return
    keys = ["Mood", "Hair", "Muscle", "Satiety", "Inflammation"]
    rec_o = fm.raw_objectives(rec_x)
    rec_mar, rec_met = fm.adequacy(rec_x)
    R = {k: np.array([fm.raw_objectives(x)[k] for x in rnd]) for k in keys}
    Rmar = np.array([fm.adequacy(x)[0] for x in rnd])
    print(f"  Baseline = {len(rnd)} random feasible diets (energy-matched, UL-safe)")
    print(f"  {'Metric':<14}{'Recommended':>13}{'Random mean':>13}"
          f"{'Random best':>13}{'Percentile':>12}")

    def _row(name, val, arr, higher_better=True):
        best = arr.max() if higher_better else arr.min()
        pct = 100 * ((arr <= val).mean() if higher_better else (arr >= val).mean())
        print(f"  {name:<14}{val:>13.3f}{arr.mean():>13.3f}{best:>13.3f}"
              f"{pct:>11.0f}%")

    for k in keys:
        _row(DISPLAY_NAME.get(k, k), rec_o[k], R[k], higher_better=(k != "Inflammation"))
    _row("MAR (%)", rec_mar, Rmar, higher_better=True)
    print(f"  Recommended plan meets {rec_met:.0f}% of all RDA/macro floors.")
    print("  (Percentile = % of random diets the recommended plan beats.)")

REFERENCE_MAR_STANDARD = {
    "DASH": 96.0,
    "MIND": 93.1,
    "Mediterranean": 92.6,
}
REFERENCE_MAR_GLP1 = {
    "USDA MyPlate 1200": 81.7,
    "Mediterranean 1200": 81.0,
}

def default_reference_mar(cfg):
    """Pick the comparator set matching the run's energy regime."""
    if getattr(cfg, "on_glp1_or_weightloss_drug", False):
        return dict(REFERENCE_MAR_GLP1)
    return dict(REFERENCE_MAR_STANDARD)

DEFAULT_REFERENCE_MAR = REFERENCE_MAR_STANDARD

def front_wide_comparison(fm, cfg, front_X, references=None):
    """How the WHOLE Pareto front compares with published reference diets,
    rather than only the one plan the MCDM rule happens to select.

    Reporting a single selected plan against three reference patterns invites
    the obvious objection that the plan was chosen because it wins. Scoring
    every non-dominated plan and reporting the proportion that clears each
    reference answers that objection with the data already in hand: a claim
    about most of the front cannot be cherry-picking.

    `references` maps a label to a Mean Adequacy Ratio in percent, e.g.
    {"DASH": 96.0, "MIND": 93.1, "Mediterranean": 92.6}.
    """
    if references is None:
        references = default_reference_mar(cfg)
    mar = np.array([fm.adequacy(x)[0] for x in front_X], dtype=float)
    keys = ["Mood", "Hair", "Muscle", "Satiety", "Inflammation"]
    scores = {k: np.array([fm.raw_objectives(x)[k] for x in front_X], float)
              for k in keys}

    regime = ("GLP-1 / 1200 kcal" if getattr(cfg, "on_glp1_or_weightloss_drug",
              False) else "standard deficit")
    print(BOLD + "\n--- FRONT-WIDE COMPARISON (all non-dominated plans) ---" + RESET)
    print(f"  Pareto-optimal plans scored: {len(front_X)}")
    print(f"  Energy target: {fm.target_kcal:.0f} kcal  |  regime: {regime}")
    print(f"  Reference set: {', '.join(sorted(references)) or '(none)'}"
          f"   <- must have been scored at THIS energy target")
    print(f"  Mean Adequacy Ratio across the front: mean {mar.mean():.2f}% "
          f"+/- {mar.std(ddof=1) if len(mar) > 1 else 0.0:.2f} | "
          f"median {np.median(mar):.2f}% "
          f"(IQR {np.percentile(mar, 25):.2f}-{np.percentile(mar, 75):.2f}) | "
          f"range {mar.min():.2f}-{mar.max():.2f}")
    if references:
        print(f"  {'Reference diet':<18}{'its MAR':>10}{'front plans beating it':>26}")
        for label, ref in sorted(references.items(), key=lambda kv: -kv[1]):
            n_beat = int((mar > ref).sum())
            print(f"  {label:<18}{ref:>9.1f}%{n_beat:>15} / {len(mar)} "
                  f"({100.0 * n_beat / max(len(mar), 1):.1f}%)")
    print("  Per-objective spread across the front:")
    for k in keys:
        a = scores[k]
        print(f"    {DISPLAY_NAME.get(k, k):<34}mean {a.mean():.3f} "
              f"+/- {a.std(ddof=1) if len(a) > 1 else 0.0:.3f}   "
              f"range {a.min():.3f}-{a.max():.3f}")
    return {"mar": mar, "scores": scores, "references": dict(references),
            "regime": regime, "target_kcal": float(fm.target_kcal)}

def compare_rebuilt_to_front(front_result, rebuilt_mar, verbose=True):
    """Place the REBUILT plan inside the front's own MAR distribution.

    WHY THIS IS THE COMPARISON THAT MATTERS. The block above scores front_X --
    decision vectors as they leave NSGA-III. Every figure in it ("147 of 217
    beat DASH", "mean 96.44%") therefore describes plans as OPTIMIZED. The plan
    in the document is not one of them: substitutions have replaced foods,
    portions have been rescaled and meals rearranged, all of which move the
    nutrient vector. So the front statistics and the deliverable have never
    been the same object, and quoting the front's numbers for the issued plan
    overstates it by however much the rebuild cost.

    This reports the rebuilt plan's MAR against the SAME distribution and the
    SAME reference set, so the two are finally comparable:
      - where it falls in the front (percentile, plans it beats)
      - whether it still beats each reference diet

    The reference set is taken from the front result, so it is automatically
    the right one for the regime -- default_reference_mar() returns the GLP-1
    comparators (USDA MyPlate 1200, Mediterranean 1200) for a GLP-1 run and the
    standard set (DASH, MIND, Mediterranean) otherwise. Comparing a 1200 kcal
    rebuilt plan against DASH scored at 2053 kcal would be meaningless, which
    is why this must never carry its own hard-coded reference list.
    """
    mar = np.asarray(front_result.get("mar", []), dtype=float)
    refs = dict(front_result.get("references", {}))
    out = {"rebuilt_mar": float(rebuilt_mar), "n_front": int(len(mar)),
           "references": refs, "regime": front_result.get("regime")}
    if len(mar):
        out["front_mean"] = float(mar.mean())
        out["front_median"] = float(np.median(mar))
        out["percentile"] = float(100.0 * (mar < rebuilt_mar).mean())
        out["n_front_beaten"] = int((mar < rebuilt_mar).sum())
        out["vs_front_median"] = float(rebuilt_mar - np.median(mar))
    out["beats_reference"] = {k: bool(rebuilt_mar > v) for k, v in refs.items()}

    if verbose:
        print(BOLD + "\n--- REBUILT PLAN vs THE FRONT (as issued, not as "
              "optimized) ---" + RESET)
        print(f"  Regime: {front_result.get('regime', 'unknown')}  |  "
              f"reference set: {', '.join(sorted(refs)) or '(none)'}")
        print(f"  Rebuilt plan MAR: {rebuilt_mar:.2f}%")
        if len(mar):
            print(f"  Front (as optimized): mean {mar.mean():.2f}% | "
                  f"median {np.median(mar):.2f}% | "
                  f"range {mar.min():.2f}-{mar.max():.2f}")
            print(f"  The rebuilt plan beats {out['n_front_beaten']} / "
                  f"{len(mar)} front plans "
                  f"({out['percentile']:.1f}th percentile), and sits "
                  f"{out['vs_front_median']:+.2f} points from the front median.")
            if out["percentile"] < 25.0:
                print("  ! The rebuild moved this plan into the bottom quarter")
                print("    of the front it came from. The substitutions were")
                print("    made for safety and practicality, so this is a real")
                print("    trade -- but the front-wide claims do not describe")
                print("    this plan and must not be quoted for it.")
        if refs:
            print(f"  {'Reference diet':<22}{'its MAR':>10}{'rebuilt plan':>16}")
            for label, ref in sorted(refs.items(), key=lambda kv: -kv[1]):
                print(f"  {label:<22}{ref:>9.1f}%"
                      f"{('beats it' if rebuilt_mar > ref else 'does NOT'):>16}")
        print("  Report BOTH figures in the write-up. The gap between them is")
        print("  what safety and practicality constraints cost in adequacy")
        print("  terms, which is a result in itself rather than a caveat.")
    return out

def seed_statistics(fm, cfg, per_seed_hv):
    """Dispersion across the independent seeds, reported as mean +/- SD and
    median/IQR rather than as the single pooled number.

    Twenty-one runs summarised by one point estimate invites the question of
    what the other twenty looked like; this answers it. HV here is already
    normalised against common bounds (see run_nsga3), so the values are
    comparable across seeds."""
    res = getattr(fm, "research", {}) or {}
    hv = np.asarray(per_seed_hv, float)
    igd = np.asarray(res.get("igd_plus", []), float)
    feas = np.asarray(res.get("feasibility", []), float)

    print(BOLD + "\n--- SEED-LEVEL STATISTICS ---" + RESET)

    def _line(name, a, unit=""):
        if not len(a):
            return
        sd = a.std(ddof=1) if len(a) > 1 else 0.0
        print(f"  {name:<26} n={len(a):<4} mean {a.mean():.4f} +/- {sd:.4f}"
              f"{unit} | median {np.median(a):.4f} "
              f"(IQR {np.percentile(a, 25):.4f}-{np.percentile(a, 75):.4f})")

    _line("Hypervolume", hv)
    _line("IGD+ (vs pooled front)", igd)
    _line("Feasible final pop (%)", feas)
    if len(hv) > 1 and hv.mean() > 0:
        cv = 100.0 * hv.std(ddof=1) / hv.mean()
        print(f"  Hypervolume CV: {cv:.1f}%"
              + ("   (high: no single seed recovers the whole front, "
                 "which is why seeds are pooled)" if cv > 10 else ""))
    return {"hv": hv, "igd_plus": igd, "feasibility": feas}

def wilcoxon_vs_baseline(fm, cfg, front_X, n_random=None, metric="MAR"):
    """Wilcoxon rank-sum test: front plans vs random feasible plans.

    Answers the reviewer question the percentile table only gestures at --
    whether the optimised plans are drawn from a different distribution than
    plans that merely satisfy the same constraints, rather than sitting at
    the top of the same one."""
    from scipy.stats import mannwhitneyu
    n = n_random if n_random is not None else getattr(cfg, "n_random", 1000)
    rng = np.random.default_rng(cfg.base_seed)
    rnd = _random_feasible_diets(fm, cfg, n, rng)
    if not rnd:
        print("  (could not sample feasible random diets for the test)")
        return None

    if metric == "MAR":
        a = np.array([fm.adequacy(x)[0] for x in front_X], float)
        b = np.array([fm.adequacy(x)[0] for x in rnd], float)
    else:
        a = np.array([fm.raw_objectives(x)[metric] for x in front_X], float)
        b = np.array([fm.raw_objectives(x)[metric] for x in rnd], float)

    u, pv = mannwhitneyu(a, b, alternative="two-sided")
    rbc = 1.0 - (2.0 * u) / (len(a) * len(b))
    print(BOLD + f"\n--- {metric}: PARETO FRONT vs RANDOM FEASIBLE ---" + RESET)
    print(f"  front  n={len(a):<5} median {np.median(a):.3f} "
          f"(IQR {np.percentile(a,25):.3f}-{np.percentile(a,75):.3f})")
    print(f"  random n={len(b):<5} median {np.median(b):.3f} "
          f"(IQR {np.percentile(b,25):.3f}-{np.percentile(b,75):.3f})")
    print(f"  Mann-Whitney U = {u:.1f}, p = {pv:.4g}, rank-biserial "
          f"r = {abs(rbc):.3f}  -> "
          f"{'significant (p<0.05)' if pv < 0.05 else 'not significant'}")
    return {"u": float(u), "p": float(pv), "r": float(abs(rbc))}

def _score_terms(row):
    """Mirror of the four support-score equations as (label, weight, value)
    lists, using the REAL helpers/K on the daily row, so AHP weights can be
    perturbed without editing the score functions.

    These weights and term lists MUST track the score functions above. They
    previously did not: this mirror still carried the pre-audit nine-term
    Muscle/Mood/Hair and eight-term Satiety definitions, including vitamin D
    and vitamin C in Muscle, folate and complex carbohydrate in Mood, vitamin
    A and biotin in Hair, and healthy fats in Satiety -- every one of which
    the evidence audit removed. Any sensitivity result computed from the old
    mirror described a model that is no longer being optimised. The lists
    below are copied term-for-term from muscle_protection_score(),
    satiety_score(), mood_score() and hair_score(); _assert_mirror_matches()
    checks them numerically at run time so this cannot silently drift again."""
    s = lambda short, kk: nc.sat(nc.getv(row, short), nc.K[kk])
    om = nc.omega3_term(row)
    cc = nc.sat(nc.complex_carbohydrates(row), nc.K["ComplexCarbs"])
    ed = nc.energy_density(row)
    edt = nc.K_ENERGY_DENSITY / (nc.K_ENERGY_DENSITY + ed) if ed >= 0 else 0.0
    healthy = (nc.getv(row, "mufa") + nc.getv(row, "la") + nc.getv(row, "ala")
               + nc.getv(row, "epa") + nc.getv(row, "dha"))
    ht = healthy / (nc.K["HealthyFats"] + healthy) if (nc.K["HealthyFats"] + healthy) > 0 else 0.0
    return {
        "Muscle": [("protein", 0.265209, s("protein", "Protein")),
            ("iron", 0.155838, s("iron", "Iron")),
            ("carb", 0.140227, s("carb", "Carbs")),
            ("potassium", 0.115752, s("potassium", "Potassium")),
            ("leucine", 0.115752, s("leucine", "Leucine")),
            ("magnesium", 0.103611, s("magnesium", "Mg")),
            ("omega3", 0.103611, om)],
        "Satiety": [("energy_density", 0.492014, edt),
            ("protein", 0.306597, s("protein", "Protein")),
            ("fiber", 0.201389, s("fiber", "Fiber"))],
        "Mood": [("magnesium", 0.218576, s("magnesium", "Mg")),
            ("zinc", 0.198674, s("zinc", "Zinc")),
            ("vitamin_d", 0.150282, s("vitamin_d", "VitD")),
            ("omega3", 0.147197, om),
            ("iron", 0.142618, s("iron", "Iron")),
            ("selenium", 0.078280, s("selenium", "Selenium")),
            ("vitamin_b6", 0.064372, s("vitamin_b6", "VitB6"))],
        "Hair": [("iron", 0.351951, s("iron", "Iron")),
            ("protein", 0.300334, s("protein", "Protein")),
            ("zinc", 0.212137, s("zinc", "Zinc")),
            ("vitamin_d", 0.135578, s("vitamin_d", "VitD"))],
    }

def _assert_mirror_matches(row, tol=5e-4):
    """Recompute each support score from _score_terms() and compare with the
    real score function on the same row. Returns a list of human-readable
    mismatch strings (empty when the mirror is faithful).

    This is the guard that was missing: the mirror is a hand-copy of the
    score equations, so nothing but an explicit numerical check stops it
    drifting out of step with them again after a future re-weighting."""
    real = {
        "Muscle": muscle_protection_score(row),
        "Satiety": satiety_score(row),
        "Mood": mood_score(row),
        "Hair": hair_score(row),
    }
    problems = []
    for name, terms in _score_terms(row).items():
        if name == "Hair" and not globals().get("HAIR_SCORE_ACTIVE", False):
            continue
        mirrored = sum(w * v for _, w, v in terms)
        wsum = sum(w for _, w, _ in terms)
        if abs(wsum - 1.0) > 1e-3:
            problems.append(f"{name}: mirror weights sum to {wsum:.4f}, not 1")
        if abs(mirrored - real[name]) > tol:
            problems.append(f"{name}: mirror {mirrored:.4f} vs real "
                            f"{real[name]:.4f} (diff {mirrored-real[name]:+.4f})")
    return problems

def sensitivity_analysis(fm, cfg, rec_x, delta=0.2, out_prefix="sensitivity"):
    """Sensitivity analysis of the five score equations (fixed-plan only):
    perturb each K target (real equations) and each AHP weight (mirrored,
    renormalized) by +/-delta; record the change in each score on the
    recommended plan. Saves a CSV and a tornado plot."""
    keys = ["Mood", "Hair", "Muscle", "Satiety", "Inflammation"]
    row, _, _ = fm.daily(rec_x)
    base = {k: fm.raw_objectives(rec_x)[k] for k in keys}

    mism = _assert_mirror_matches(row, tol=5e-4)
    if mism:
        print(BOLD + "  WARNING: weight-mirror mismatch -- weight sensitivity "
              "results below describe a DIFFERENT model from the one being "
              "optimised. Fix _score_terms() before using them." + RESET)
        for m in mism:
            print(f"     {m}")

    records = []

    def _avg_abs(plus, minus):
        return {k: 0.5 * (abs(plus[k] - base[k]) + abs(minus[k] - base[k])) for k in keys}

    for kk in list(nc.K.keys()):
        orig = nc.K[kk]
        nc.K[kk] = orig * (1 + delta)
        plus = {k: fm.raw_objectives(rec_x)[k] for k in keys}
        nc.K[kk] = orig * (1 - delta)
        minus = {k: fm.raw_objectives(rec_x)[k] for k in keys}
        nc.K[kk] = orig
        records.append((f"K[{kk}]", "K-target", _avg_abs(plus, minus)))

    for gname in ["K_ENERGY_DENSITY", "OMEGA3_W_ALA", "OMEGA3_W_EPA_DHA"]:
        orig = getattr(nc, gname)
        setattr(nc, gname, orig * (1 + delta))
        plus = {k: fm.raw_objectives(rec_x)[k] for k in keys}
        setattr(nc, gname, orig * (1 - delta))
        minus = {k: fm.raw_objectives(rec_x)[k] for k in keys}
        setattr(nc, gname, orig)
        records.append((gname, "global", _avg_abs(plus, minus)))

    spec = _score_terms(row)

    def _mirror_score(sc, weights):
        tot = sum(weights)
        if tot <= 0:
            return 0.0
        return sum((w / tot) * t for (w, (_, _, t)) in zip(weights, spec[sc]))

    for sc in ["Muscle", "Satiety", "Mood", "Hair"]:
        terms = spec[sc]
        w0 = [w for _, w, _ in terms]
        for i, (label, _, _) in enumerate(terms):
            d = {k: 0.0 for k in keys}
            wp = list(w0); wp[i] = w0[i] * (1 + delta)
            wm = list(w0); wm[i] = w0[i] * (1 - delta)
            d[sc] = 0.5 * (abs(_mirror_score(sc, wp) - base[sc])
                           + abs(_mirror_score(sc, wm) - base[sc]))
            records.append((f"w[{DISPLAY_NAME.get(sc, sc)}:{label}]",
                             "AHP-weight", d))

    rows = []
    for name, ptype, d in records:
        total = sum(d.values())
        rows.append({"parameter": name, "type": ptype,
                     **{DISPLAY_NAME.get(k, k): round(d[k], 4) for k in keys},
                     "total_abs_delta": round(total, 4)})
    df = pd.DataFrame(rows).sort_values("total_abs_delta", ascending=False)
    df.to_csv(f"{out_prefix}_fixed.csv", index=False)

    print(BOLD + f"\n--- SENSITIVITY ANALYSIS (fixed plan, +/-{int(delta*100)}%) ---" + RESET)
    print("  Most influential parameters (avg |change| in score, summed over scores):")
    print(f"  {'parameter':<26}{'type':<12}{'total|delta|':>12}")
    for _, r in df.head(12).iterrows():
        print(f"  {r['parameter']:<26}{r['type']:<12}{r['total_abs_delta']:>12.4f}")
    print(f"  Full table -> {out_prefix}_fixed.csv")
    _save_tornado(df, out_prefix, delta)
    return df

def _save_tornado(df, out_prefix, delta):
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        top = df.head(14).iloc[::-1]
        colors = {"K-target": "#2E5496", "AHP-weight": "#C0504D", "global": "#4F8A3D"}
        fig, ax = plt.subplots(figsize=(8.5, 6))
        ax.barh(top["parameter"], top["total_abs_delta"],
                color=[colors.get(t, "0.5") for t in top["type"]])
        ax.set_xlabel(f"Total |change in scores|  (+/-{int(delta*100)}% perturbation)")
        ax.set_title("Score-equation sensitivity (tornado)")
        handles = [plt.Rectangle((0, 0), 1, 1, color=c) for c in colors.values()]
        ax.legend(handles, colors.keys(), loc="lower right", fontsize=9)
        ax.grid(axis="x", alpha=0.3)
        fig.tight_layout()
        fig.savefig(f"{out_prefix}_tornado.png", dpi=140, bbox_inches="tight")
        plt.close(fig)
        print(f"  Tornado plot -> {out_prefix}_tornado.png")
    except Exception as e:
        print(f"  (tornado plot skipped: {e})")

def build_meal_split(fm, x):
    """Arrange the recommended plan's active foods into the 5-meal template
    (Breakfast, A.M. Snack, Lunch, P.M. Snack, Dinner), grouped by meal
    role (Protein / Fruit-Veg / Whole Grain / Fat-Dairy) via
    nc.SUBGROUP_MEAL_ROLE and nc.ROLE_MEAL_SLOTS.

    Assignment rule (deliberately simple and transparent, not an
    optimization): within each role, foods are sorted by descending grams
    (largest servings first) and assigned WHOLE -- never split across
    meals -- to that role's meal slots in ROLE_MEAL_SLOTS priority order,
    cycling back to the start of the slot list if there are more foods
    than slots. This keeps each food's entire daily serving in exactly
    one meal, rather than fragmenting it into unrealistic partial amounts
    spread across the day.

    EXCEPTION: if a role has FEWER distinct foods than it has mandated
    slots (e.g. only one Fat/Dairy food selected all day, but Fat/Dairy is
    supposed to appear in Lunch, Dinner, AND Breakfast), the whole-serving
    rule above would leave some of those mandated meals showing nothing
    for that role. In that case only, each food's grams are split evenly
    across all of that role's slots instead, so every mandated meal gets
    a (smaller) nonzero share rather than being left empty. The total
    grams for that food across the day is unchanged either way -- this
    only affects how it's spread across meals in this display.

    Returns:
      grid: {meal: {role: [(food_name, grams), ...]}}
      unclassified: [(food_name, subgroup, grams), ...] -- active foods
        whose subgroup has no entry in SUBGROUP_MEAL_ROLE. Should always
        be empty in practice now: those subgroups (e.g. Refined Grains)
        are excluded from the candidate pool entirely in main(), before
        the optimizer ever runs, rather than being handled here after the
        fact -- see the candidate-pool filter next to `df_known` in
        main(). Kept here only as a defensive fallback.
    """
    active = np.where(x > 0)[0]
    subs = fm.subgroup_arr

    role_foods = {role: [] for role in nc.ROLE_MEAL_SLOTS}
    unclassified = []
    for i in active:
        grams = float(x[i]) * 100.0
        name = fm.names[i]
        sg = str(subs[i])
        roles = nc.SUBGROUP_MEAL_ROLE.get(sg)
        if not roles:
            unclassified.append((name, sg, grams))
            continue
        for role in roles:
            role_foods[role].append((name, grams, sg))

    grid = {meal: {role: [] for role in nc.ROLE_MEAL_SLOTS} for meal in nc.MEAL_SLOTS}
    for role, foods in role_foods.items():
        slots = nc.ROLE_MEAL_SLOTS[role]
        foods_sorted = sorted(foods, key=lambda t: -t[1])
        if foods_sorted and len(foods_sorted) < len(slots):
            n_slots = len(slots)
            n_foods = len(foods_sorted)
            max_repeats = nc.MAX_FOOD_REPEATS_PER_ROLE
            counts = [0] * n_foods
            slot_food_idx = [None] * n_slots
            i = 0
            for s in range(n_slots):
                tries = 0
                while tries < n_foods and counts[i % n_foods] >= max_repeats:
                    i += 1
                    tries += 1
                if tries < n_foods:
                    idx = i % n_foods
                    slot_food_idx[s] = idx
                    counts[idx] += 1
                    i += 1
            for s, meal in enumerate(slots):
                idx = slot_food_idx[s]
                if idx is None:
                    continue
                name, grams, _sg = foods_sorted[idx]
                share = grams / counts[idx]
                grid[meal][role].append((name, share))
            continue

        if role == "Fat/Dairy":
            pool = list(foods_sorted)
            filled = {}
            for meal in slots:
                preferred = nc.FATDAIRY_SLOT_SUBGROUP_PREFERENCE.get(meal, [])
                for idx, (name, grams, sg) in enumerate(pool):
                    if sg in preferred:
                        filled[meal] = (name, grams)
                        pool.pop(idx)
                        break
            for meal in slots:
                if meal not in filled and pool:
                    name, grams, _sg = pool.pop(0)
                    filled[meal] = (name, grams)
            for meal, (name, grams) in filled.items():
                grid[meal][role].append((name, grams))
            for j, (name, grams, _sg) in enumerate(pool):
                meal = slots[j % len(slots)]
                grid[meal][role].append((name, grams))
            continue

        for j, (name, grams, _sg) in enumerate(foods_sorted):
            meal = slots[j % len(slots)]
            grid[meal][role].append((name, grams))

    return grid, unclassified

def print_meal_split(fm, cfg, x):
    """Print the Diet Plan Split section and save it to CSV."""
    grid, unclassified = build_meal_split(fm, x)
    role_cols = ["Protein", "Fruit/Veg", "Whole Grain", "Fat/Dairy"]

    print(BOLD + "\n--- DIET PLAN SPLIT (5 meals, heuristic post-hoc arrangement) ---" + RESET)
    print("  The optimizer scores/selects foods for the WHOLE DAY as a single flat")
    print("  list -- it has no meal-slot concept. This split is a readability layer")
    print("  applied AFTER optimization: each food's full daily serving is assigned")
    print("  whole (never fragmented) to one meal, largest servings first, cycling")
    print("  through that role's meal-slot priority order (main meals get first pick).")

    col_w = 32
    print(f"\n  {'Meal':<12}" + "".join(f"{r:<{col_w}}" for r in role_cols))
    print("  " + "-" * (12 + col_w * len(role_cols)))
    csv_rows = []
    for meal in nc.MEAL_SLOTS:
        line = f"  {meal:<12}"
        for role in role_cols:
            items = grid[meal][role]
            cell = (", ".join(f"{name[:18]} ({grams:.0f}g)" for name, grams in items)
                    if items else "-")
            display = cell if len(cell) <= col_w - 2 else cell[:col_w - 5] + "..."
            line += f"{display:<{col_w}}"
            csv_rows.append({"meal": meal, "role": role,
                             "foods": "; ".join(f"{n} ({g:.0f}g)" for n, g in items)})
        print(line)

    pd.DataFrame(csv_rows).to_csv(cfg.meal_split_csv, index=False)
    print(f"\n  Saved: {cfg.meal_split_csv}")

def report(fm: FoodModel, cfg: OptConfig, front_X, front_obj, per_seed_hv):
    n = len(front_X)
    print("\n" + "=" * 72)
    print("RESULTS")
    print("=" * 72)
    print(f"Pareto-optimal plans found (pooled over {cfg.n_seeds} seeds): {n}")
    if per_seed_hv:
        print(f"Hypervolume (normalised, ref=1.1): "
              f"mean {np.mean(per_seed_hv):.4f} +/- {np.std(per_seed_hv):.4f} "
              f"over {len(per_seed_hv)} seeds")

    R = getattr(fm, "research", None)
    if R:
        def _mi(a):
            a = np.asarray(a, float)
            return (f"mean {a.mean():.4f} +/- {a.std():.4f} | median {np.median(a):.4f} "
                    f"(IQR {np.percentile(a,25):.4f}-{np.percentile(a,75):.4f})")
        print("\n--- RESEARCH-GRADE METRICS (across seeds) ---")
        if R.get("per_seed_hv"):
            print(f"Hypervolume : {_mi(R['per_seed_hv'])}")
        if R.get("igd_plus"):
            print(f"IGD+ (vs pooled front; lower=better): {_mi(R['igd_plus'])}")
        if R.get("feasibility"):
            fa = np.asarray(R["feasibility"], float) * 100
            print(f"Feasible final-population fraction: mean {fa.mean():.1f}% "
                  f"+/- {fa.std():.1f}% (all hard ULs + energy band)")
        if R.get("total_time") is not None:
            tt = R["total_time"]; st = R.get("seed_times") or []
            mm, ss = divmod(int(tt), 60)
            per = f", {np.mean(st):.1f}s/seed avg" if st else ""
            print(f"Runtime: {tt:.1f}s ({mm}m {ss}s) for {cfg.n_seeds} seeds"
                  f"{per}")
        if R.get("convergence"):
            _save_convergence(R["convergence"], cfg)
            print(f"Convergence plots saved: {cfg.conv_png}, {cfg.conv_rate_png}")
        print("Note: HV is not comparable across different objective "
              "counts; use wilcoxon_compare() on same-dimension runs.")

    sample = active_objectives(fm.raw_objectives(front_X[0]), fm.target_kcal, cfg)
    score_names = [nm for nm, _, _ in sample
                   if nm != DISPLAY_NAME["Energy_dev"]]
    maximise = [nm for nm, _, s in sample if s == "max"]

    human = []
    for x in front_X:
        o = fm.raw_objectives(x)
        items = dict((nm, v) for nm, v, _ in
                     active_objectives(o, fm.target_kcal, cfg))
        row = [items[nm] for nm in score_names]
        row += [o["Energy_kcal"], abs(o["Energy_kcal"] - fm.target_kcal)]
        human.append(row)
    cols = score_names + ["Energy_kcal", "|kcal-target|"]
    front_df = pd.DataFrame(human, columns=cols)
    front_df.to_csv(cfg.front_csv, index=False)

    rec = pick_recommended(front_obj, cfg.mcdm_weights)

    print("\n--- PARETO FRONT (each row is one trade-off plan) ---")
    print(f"(target energy = {fm.target_kcal} kcal; "
          f"maximise {'/'.join(maximise)}; "
          f"minimise {DISPLAY_NAME['Inflammation']} & |kcal-target|; "
          f"objective set = {n_objectives(cfg)})")
    with pd.option_context("display.float_format", lambda v: f"{v:.3f}",
                           "display.width", 200, "display.max_rows", None):
        for i in range(n):
            cells = " | ".join(
                f"{c}={front_df.iloc[i][c]:.3f}" if c != "Energy_kcal"
                else f"{c}={front_df.iloc[i][c]:.0f}" for c in cols)
            if i == rec:
                print(BOLD + ">>> " + cells + "   [RECOMMENDED]" + RESET)
            else:
                print("    " + cells)

    print("\n--- OBJECTIVE OVERLAP (correlation over the Pareto set) ---")
    ov_cols = score_names + ["Energy_kcal"]
    corr = front_df[ov_cols].corr()
    with pd.option_context("display.float_format", lambda v: f"{v:+.2f}",
                           "display.width", 200):
        print(corr.to_string())
    m = len(ov_cols)
    flagged = []
    for a in range(m):
        for b in range(a + 1, m):
            r = corr.iloc[a, b]
            if abs(r) > 0.9:
                flagged.append((ov_cols[a], ov_cols[b], r))
    if flagged:
        print("  Highly overlapping pairs (|r|>0.9) -- candidates to merge:")
        for a, b, r in flagged:
            print(f"    {a} <-> {b}: r={r:+.2f}")
    else:
        print(f"  No pair exceeds |r|>0.9; all {m} objectives stay distinct.")

    print("\n" + BOLD + "=" * 72)
    print("RECOMMENDED DIET PLAN (balanced compromise)")
    print("=" * 72 + RESET)
    x = front_X[rec]
    active = np.where(x > 0)[0]

    _cand = fm.df.iloc[fm.cand_idx]
    _units = (_cand["servings_unit"].tolist()
              if "servings_unit" in _cand.columns else [None] * len(_cand))
    _srcs = (_cand["source_file"].tolist()
             if "source_file" in _cand.columns else [None] * len(_cand))
    _sg = (pd.to_numeric(_cand[SERVING_G_COL], errors="coerce").tolist()
           if SERVING_G_COL in _cand.columns else [None] * len(_cand))

    def _portion(grams, unit, serving_g):
        """Render the amount in the unit the food is actually dosed in."""
        if serving_g and not pd.isna(serving_g) and serving_g > 0:
            n = grams / serving_g
            label = "serving" if (unit is None or pd.isna(unit)) else str(unit)
            return f"{n:.2f} x {label}"
        if unit is None or pd.isna(unit):
            return ""
        return f"({unit})"

    plan_rows = []
    for i in active:
        grams = x[i] * 100.0
        unit, sgv = _units[i], _sg[i]
        plan_rows.append((
            fm.names[i],
            round(grams, 0),
            _portion(grams, unit, sgv),
            "" if (unit is None or pd.isna(unit)) else str(unit),
            "" if (sgv is None or pd.isna(sgv)) else round(float(sgv), 1),
            "" if (_srcs[i] is None or pd.isna(_srcs[i])) else str(_srcs[i]),
        ))
    plan_rows.sort(key=lambda t: -t[1])
    print(BOLD + f"{'Food':<45}{'grams/day':>12}  {'portion':<24}" + RESET)
    for name, grams, portion, _u, _sgv, _src in plan_rows:
        print(f"{name[:44]:<45}{grams:>12.0f}  {portion[:24]:<24}")
    pd.DataFrame(plan_rows,
                 columns=["food", "grams_per_day", "portion",
                          "servings_unit", "serving_g", "source_file"]).to_csv(
        cfg.plan_csv, index=False)
    pd.DataFrame(fm.watch_panel(x)).to_csv(cfg.watch_csv, index=False)

    o = fm.raw_objectives(x)
    items = active_objectives(o, fm.target_kcal, cfg)
    print(BOLD + "\nScores for this plan:" + RESET)
    skip = (DISPLAY_NAME["Inflammation"], DISPLAY_NAME["Energy_dev"])
    score_str = " | ".join(f"{nm} {v:.3f}" for nm, v, s in items
                           if nm not in skip)
    print(f"  {score_str}")
    print(f"  {DISPLAY_NAME['Inflammation']} {o['Inflammation']:.3f} (lower better; "
          f"= AHP blend of TransFat {o['TransFat']:.3f}, "
          f"AddedSugar {o['AddedSugar']:.3f}, SatFat {o['SatFat']:.3f}) | "
          f"Energy {o['Energy_kcal']:.0f} kcal "
          f"(target {fm.target_kcal}, off by {abs(o['Energy_kcal']-fm.target_kcal):.0f})")

    print(BOLD + "\nConstraint check (recommended plan):" + RESET)
    g = fm.ul_violation(x)
    worst = max(g) if g else -1
    print(f"  Hard ULs: {'ALL OK' if worst <= 0 else 'VIOLATION'} "
          f"(max intake-UL = {worst:.2f}; <=0 is safe)")
    print(f"  Soft minimums: mean shortfall "
          f"{fm.soft_shortfall(x)*100:.1f}% below RDA/macro targets "
          f"(0% = all minimums met)")
    sg_g = fm.subgroup_violation(x)
    worst_sg = max(sg_g) if sg_g else -1
    print(f"  Subgroup gram caps: {'ALL OK' if worst_sg <= 0 else 'VIOLATION'} "
          f"(max total-cap = {worst_sg:.1f} g; <=0 is safe)")
    dup_g = fm.subgroup_duplicate_violation(x)
    worst_dup = max(dup_g) if dup_g else -1
    dup_cfg = dict(getattr(cfg, "duplicate_limit_subgroups", {}))
    n_scoped = len(dup_cfg)
    print(f"  Max-foods-per-subgroup: {'ALL OK' if worst_dup <= 0 else 'VIOLATION'} "
          f"(scoped to {n_scoped} subgroups, each with its own max count "
          f"{dict(dup_cfg) if n_scoped <= 8 else '(see cfg)'}; "
          f"max active-count-over-limit = {worst_dup:.0f}; <=0 is safe; "
          f"unscoped subgroups allow unlimited distinct foods)")
    if cfg.energy_band_frac:
        b = cfg.energy_band_frac
        lo = fm.target_kcal * (1 - b); hi = fm.target_kcal * (1 + b)
        e = o["Energy_kcal"]
        print(f"  Hard energy band: {lo:.0f}-{hi:.0f} kcal "
              f"(target {fm.target_kcal} +/-{b*100:.0f}%)  -> plan {e:.0f} kcal "
              f"{'OK' if lo <= e <= hi else 'OUT OF BAND'}")

    macros, micros = fm.nutrient_panel(x)

    def _nline(r):
        nm, val, fl, ul = r["name"], r["intake"], r["floor"], r["ul"]
        nm = (nm[:37] + "..") if len(nm) > 39 else nm
        pct = f"{val/fl*100:4.0f}% of target" if fl else ""
        ultxt = f", UL {ul:g}" if ul is not None else ""
        flag = ""
        if fl and val < fl:
            flag = "  <- below target"
        if ul is not None and val > ul:
            flag = "  !! ABOVE UL"
        return (f"    {nm:<40} {val:10.2f}   (target {fl:g}{ultxt})  "
                f"{pct}{flag}")

    print(BOLD + "\n--- NUTRITION OF RECOMMENDED PLAN (daily totals vs targets) ---" + RESET)
    print(f"  Energy: {o['Energy_kcal']:.0f} kcal  (target {fm.target_kcal} +/-{(cfg.energy_band_frac or 0)*100:.0f}%)")
    print("  Macronutrients (target = calorie-deficit minimum):")
    for r in macros:
        print(_nline(r))
    row_x, _, _ = fm.daily(x)
    cc = nc.complex_carbohydrates(row_x)
    cc_t = nc.K.get("ComplexCarbs")
    cc_pct = f"{cc/cc_t*100:4.0f}% of target" if cc_t else ""
    cc_flag = "  <- below target" if (cc_t and cc < cc_t) else ""
    src = "from data" if nc.COLS.get("complex_carbs") else "carb - sugars"
    print(f"    {'Complex carbohydrates ('+src+')':<40} {cc:10.2f}   "
          f"(target {cc_t:g})  {cc_pct}{cc_flag}")
    print("  Micronutrients (target = RDA/AI floor; UL = upper limit):")
    for r in micros:
        print(_nline(r))

    print("  Watch-list (no RDA floor; tracked for limiting/targeting):")
    for w in fm.watch_panel(x):
        ul_str = f"  UL {w['ul']:g}{w['unit']}" if w['ul'] else ""
        flag = " <- OVER UL" if (w['ul'] and w['intake'] > w['ul']) else ""
        print(f"    {w['name']:<18} {w['intake']:10.3f} {w['unit']:<3}{ul_str}{flag}"
              f"   ({w['note']})")

    if cfg.nutrient_sens:
        _report_nutrient_sensitivity(fm, x, cfg)

    if cfg.validate:
        validate_plan(fm, cfg, x)
        seed_statistics(fm, cfg, per_seed_hv)
        front_wide_comparison(fm, cfg, front_X)
        wilcoxon_vs_baseline(fm, cfg, front_X, metric="MAR")
        _corner_anchor(fm, front_X, x)

    try:
        srcs = fm.df.get("pool_source")
        if srcs is not None and (srcs.astype(str) == POOL_SOURCE_CSV).any():
            render_hybrid_7day(fm, cfg, front_X, front_obj)
    except Exception as e:
        print(f"  (hybrid plan skipped: {type(e).__name__}: {e})")

    report_unmeasurable_nutrients(fm.df)
    um = getattr(fm, "unmeasured_cols", [])
    cov = getattr(fm, "nutrient_coverage", {})
    if um:
        print("\n  Below "
              f"{MIN_NUTRIENT_COVERAGE:.0%} pool coverage -- NOT scored, "
              "NOT counted in MAR:")
        for c in sorted(um):
            print(f"    {c:<34}{100*cov.get(c, 0.0):5.1f}% of foods carry "
                  "a value")
        print("    These are UNKNOWN, not deficient. Summing blanks as zero "
              "would report\n    a deficiency that is an artifact of column "
              "coverage.")
    thin = {c: v for c, v in cov.items()
            if MIN_NUTRIENT_COVERAGE <= v < 0.90 and c not in um}
    if thin:
        print("\n  Scored but on partial coverage -- read these with "
              "caution:")
        for c, v in sorted(thin.items()):
            print(f"    {c:<34}{100*v:5.1f}%")
    if EXCLUDED_NUTRIENTS:
        print("\n  Excluded from this pipeline entirely: "
              + ", ".join(sorted(EXCLUDED_NUTRIENTS))
              + ".\n    Plans from this pool are neither adequate nor "
                "deficient in these --\n    the question is not addressed. "
                "State this in the limitations.")
    if globals().get("DISH_MODE", False):
        report_wweia_status(fm, x)
        report_clinical_status(fm, x)
        if getattr(fm, "_has_csv_rows", False):
            report_hybrid_slots(fm, x)
            report_nova(fm, x)
    print_meal_split(fm, cfg, x)

    _save_pcp(front_df[ov_cols], rec, cfg)
    print(f"\nSaved: {cfg.front_csv}, {cfg.plan_csv}, {cfg.pcp_png}, "
          f"{cfg.meal_split_csv}")

def _save_pcp(front7, rec, cfg):
    """Custom parallel-coordinates plot with non-overlapping axis text:
    column name (bottom, rotated), min value (just under each axis), max value
    (just above each axis)."""
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        cols = list(front7.columns)
        F = front7.to_numpy(dtype=float)
        n, m = F.shape
        mins, maxs = F.min(axis=0), F.max(axis=0)
        span = np.where(maxs - mins > 1e-12, maxs - mins, 1.0)
        Fn = (F - mins) / span
        x = np.arange(m)

        fig, ax = plt.subplots(figsize=(max(8.5, 1.8 * m), 5.6))
        for i in range(n):
            if i != rec:
                ax.plot(x, Fn[i], color="0.72", alpha=0.35, lw=0.8, zorder=1)
        ax.plot(x, Fn[rec], color="crimson", lw=2.6, zorder=4, label="recommended")

        for xi in x:
            ax.axvline(xi, color="0.55", lw=0.9, zorder=2)
            ax.text(xi, 1.035, f"{maxs[xi]:.3g}", ha="center", va="bottom",
                    fontsize=8, color="0.30")
            ax.text(xi, -0.035, f"{mins[xi]:.3g}", ha="center", va="top",
                    fontsize=8, color="0.30")

        ax.set_xticks(x)
        ax.set_xticklabels(cols, rotation=28, ha="right", fontsize=9)
        ax.tick_params(axis="x", pad=20)
        ax.set_yticks([])
        ax.set_ylim(-0.16, 1.12)
        ax.set_xlim(-0.4, m - 0.6)
        ax.set_title("Pareto front (parallel coordinates)", fontsize=12, pad=12)
        ax.legend(loc="upper right", fontsize=9, framealpha=0.9)
        for s in ("top", "right", "left", "bottom"):
            ax.spines[s].set_visible(False)
        fig.tight_layout()
        fig.savefig(cfg.pcp_png, dpi=140, bbox_inches="tight")
        plt.close(fig)
    except Exception as e:
        print(f"  (PCP plot skipped: {e})")

def sweep_operator_config(fm, cfg, settings=None, n_gen=120, n_seeds=4,
                          verbose=True):
    """Compare operator settings cheaply, so the choice comes from data.

    The default sbx_eta/pm_eta were lowered from 30/40 to 15/20 on the theory
    that the run's four flat-low seeds were failing to escape their starting
    basin. That is a plausible reading of the convergence trace and it is still
    only a reading. This runs the candidate settings head to head at low
    n_gen/n_seeds -- minutes, not hours -- and reports what actually happens.

    WHAT TO LOOK AT, and it is not only the mean. The whole argument for lower
    eta is that it should lift the WORST seeds and narrow the spread. A setting
    that improves the mean while leaving min unchanged has not addressed the
    problem this was meant to fix; a setting that lifts min at a small cost to
    max probably has.

    Short runs favour settings that converge fast, which biases against
    exploration -- so treat a sweep result as a tiebreaker, not a verdict, and
    confirm anything surprising at full n_gen before committing to it.
    """
    if settings is None:
        settings = [
            {"label": "lowered (15/20) - current", "sbx_eta": 15.0, "pm_eta": 20.0},
            {"label": "previous (30/40)",          "sbx_eta": 30.0, "pm_eta": 40.0},
            {"label": "wider (10/15)",             "sbx_eta": 10.0, "pm_eta": 15.0},
            {"label": "pymoo stock (15/20, SBX 0.9)", "sbx_eta": 15.0,
             "pm_eta": 20.0, "sbx_prob": 0.9},
        ]
    import copy
    out = []
    for st in settings:
        c = copy.deepcopy(cfg)
        c.n_gen, c.n_seeds = int(n_gen), int(n_seeds)
        c.checkpoint_enabled = False
        for k, v in st.items():
            if k != "label":
                setattr(c, k, v)
        try:
            _, _, per_seed_hv = run_nsga3(fm, c)
            hv = np.asarray(per_seed_hv, float)
            out.append({"label": st["label"], "mean": float(hv.mean()),
                        "min": float(hv.min()), "max": float(hv.max()),
                        "spread": float(hv.max() - hv.min())})
        except Exception as exc:
            out.append({"label": st["label"], "error":
                        f"{type(exc).__name__}: {exc}"})

    if verbose:
        print(BOLD + f"\n--- OPERATOR SWEEP ({n_gen} gens x {n_seeds} seeds "
              f"per setting) ---" + RESET)
        print(f"  {'setting':<30}{'mean HV':>10}{'min':>9}{'max':>9}{'spread':>9}")
        for r in out:
            if "error" in r:
                print(f"  {r['label']:<30}  {r['error']}")
                continue
            print(f"  {r['label']:<30}{r['mean']:>10.3f}{r['min']:>9.3f}"
                  f"{r['max']:>9.3f}{r['spread']:>9.3f}")
        ok = [r for r in out if "error" not in r]
        if ok:
            best_min = max(ok, key=lambda r: r["min"])
            best_mean = max(ok, key=lambda r: r["mean"])
            print(f"\n  Best WORST-seed (the thing lower eta is meant to fix): "
                  f"{best_min['label']}")
            print(f"  Best mean:                                          "
                  f"{best_mean['label']}")
            if best_min["label"] != best_mean["label"]:
                print("  These disagree. Prefer the best worst-seed if you are")
                print("  pooling the front across seeds, since a pooled front")
                print("  gains more from lifting the failures than from")
                print("  polishing the winner.")
    return out

MIN_SEEDS_FOR_STALL_ANALYSIS: int = 6
MIN_GENS_FOR_STALL_ANALYSIS: int = 500

def report_feasibility(callbacks, verbose=True):
    """Feasible fraction of the population over the run, across seeds.

    WHAT IT TELLS YOU, and it is the question the HV curve cannot answer.

    A low feasible fraction means the search spends most of its effort
    generating plans that violate a hard constraint and are discarded. That
    looks exactly like slow convergence on an HV plot, but no amount of extra
    generations or operator tuning fixes it -- the constraint set is the
    bottleneck, and the lever is which constraints are that tight.

    Rough reading of the final-generation figure:
      > 50%   constraints are not the limiting factor; tune operators or run
              longer.
      10-50%  workable but wasteful; worth checking which band is binding.
      < 10%   the feasible region is the problem. More generations will not
              help much.
    """
    fracs = []
    for cb in callbacks or []:
        ff = getattr(cb, "feasible_frac", None)
        if ff:
            fracs.append(np.asarray(ff, float))
    if not fracs:
        return {}
    n = min(len(a) for a in fracs)
    arr = np.vstack([a[:n] for a in fracs])
    early, late = float(np.nanmean(arr[:, 0])), float(np.nanmean(arr[:, -1]))
    out = {"early": early, "late": late, "per_gen_mean": np.nanmean(arr, 0)}
    if verbose:
        print(BOLD + "\n--- CONSTRAINT FEASIBILITY ---" + RESET)
        print(f"  Feasible fraction of the population: "
              f"{early:.1%} at the first sample -> {late:.1%} at the end")
        if late < 0.10:
            print("  ! Under 10%. The feasible region -- not the search -- is")
            print("    the bottleneck. More generations buys very little here.")
            print("    The tightest constraints are the place to look:")
            print(f"      MACRO_HARD_BANDS protein {MACRO_HARD_BANDS['protein']}"
                  f" is a {100*(MACRO_HARD_BANDS['protein'][1]-1):.0f}% window,")
            print(f"      energy band +/-{100*OptConfig().energy_band_frac:.0f}%,"
                  f" plus subgroup gram caps and micronutrient ULs at "
                  f"{UL_SAFETY_FRAC:.0%}.")
            print("    Widening ONE of those is a clinical decision, not a")
            print("    tuning decision -- take it to a dietitian rather than")
            print("    loosening it to make a graph look better.")
        elif late < 0.50:
            print("  Workable but wasteful: a large share of each generation is")
            print("  discarded. Worth identifying which band binds most often.")
        else:
            print("  Constraints are not the limiting factor. Convergence speed")
            print("  is down to the operators and the generation budget.")
    return out

def analyse_seed_stalls(convergence, stall_frac=0.02, tail_frac=0.25,
                        low_frac=0.60, verbose=True):
    """How many seeds stopped improving, and would restarting them pay?

    A seed counts as DEAD WEIGHT only when BOTH are true:
      1. it went essentially nowhere in the last `tail_frac` of the run
         (gained under `stall_frac` of its own final value), AND
      2. it finished well below the field -- under `low_frac` of the best
         seed's final HV.

    BOTH conditions are needed, and the first alone is actively misleading. A
    seed that converged near the top of the field is also flat at the end --
    that is what converged MEANS. Testing flatness alone labelled the single
    BEST seed in a 21-seed run (final HV 1.318, the highest of all of them) as
    stalled, and would have restarted it. Flat near the ceiling is success;
    flat near the floor is the waste worth reclaiming.

    Both thresholds are judgement calls, and the reason to measure rather than
    eyeball is that the plot makes stalling look worse than it is: faint grey
    lines that sit low are visually obvious, while a line that climbs slowly
    but steadily looks flat at that scale. One trace in a real run climbed
    sharply around generation 4000 after appearing flat for a long stretch --
    a restart rule tuned too eagerly would have killed it.

    Returns a dict; the verdict is deliberately conservative, because adding
    restart logic complicates the methods chapter and should only happen if
    the waste is real.
    """
    curves = [(np.asarray(g, float), np.asarray(y, float))
              for g, y in convergence if g is not None and len(g) > 2]
    if not curves:
        return {}

    _n_seeds = len(curves)
    _n_gen = float(max(g[-1] for g, _ in curves))
    _too_small = _n_seeds < MIN_SEEDS_FOR_STALL_ANALYSIS or \
        _n_gen < MIN_GENS_FOR_STALL_ANALYSIS
    if _too_small:
        if verbose:
            print(BOLD + "\n--- SEED STALL ANALYSIS: NOT RUN ---" + RESET)
            print(f"  This run has {_n_seeds} seed(s) over {_n_gen:.0f} "
                  f"generations. The analysis needs at least "
                  f"{MIN_SEEDS_FOR_STALL_ANALYSIS} seeds and "
                  f"{MIN_GENS_FOR_STALL_ANALYSIS} generations to mean anything.")
            print("  WHY: 'stalled' means a seed stopped improving and will not")
            print("  recover. Over a short run nothing has converged yet, so a")
            print("  flat tail is just a seed that has not started climbing --")
            print("  indistinguishable from one that is finished. And with two")
            print("  seeds there is no field to be 'low' relative to.")
            print("  Re-run the full configuration to get a usable answer.")
        return {"n_seeds": _n_seeds, "n_gen": _n_gen,
                "skipped": True, "reason": "sample too small"}

    rows, stalled = [], 0
    for i, (g, y) in enumerate(curves):
        n = len(y)
        cut = max(1, int(n * (1.0 - tail_frac)))
        final = float(y[-1])
        tail_gain = final - float(y[cut])
        rel = tail_gain / final if final > 0 else 0.0
        is_flat = rel < stall_frac
        is_stalled = is_flat
        idx = int(np.argmax(y >= 0.99 * final)) if final > 0 else n - 1
        rows.append({"seed": i, "final_hv": final,
                     "tail_gain": tail_gain, "tail_gain_pct": 100.0 * rel,
                     "effectively_done_at_gen": float(g[idx]),
                     "stalled": is_stalled})

    finals = np.array([r["final_hv"] for r in rows], float)
    best = float(finals.max()) if len(finals) else 0.0
    spread = float(finals.max() - finals.min())
    stalled = 0
    for r in rows:
        r["low"] = bool(best > 0 and r["final_hv"] < low_frac * best)
        r["stalled"] = bool(r["stalled"] and r["low"])
        stalled += int(r["stalled"])
    out = {"n_seeds": len(rows), "n_stalled": stalled,
           "stalled_pct": 100.0 * stalled / len(rows),
           "final_hv_min": float(finals.min()), "final_hv_max": float(finals.max()),
           "final_hv_spread": spread, "rows": rows}

    if verbose:
        print(BOLD + "\n--- SEED STALL ANALYSIS ---" + RESET)
        print(f"  Seeds: {len(rows)}   final HV {finals.min():.3f}-"
              f"{finals.max():.3f}  (spread {spread:.3f})")
        print(f"  DEAD WEIGHT (flat over the last {tail_frac:.0%} of the run "
              f"AND finished under {low_frac:.0%} of the best seed): "
              f"{stalled}/{len(rows)} ({out['stalled_pct']:.0f}%)")
        print(f"  Seeds that are merely flat at the end are NOT counted: a")
        print(f"  converged seed is flat because it has arrived, not because")
        print(f"  it is stuck.")
        print(f"  {'seed':>5}{'final HV':>11}{'tail gain':>12}"
              f"{'done by gen':>14}   status")
        for r in sorted(rows, key=lambda z: z["final_hv"]):
            print(f"  {r['seed']:>5}{r['final_hv']:>11.3f}"
                  f"{r['tail_gain_pct']:>11.1f}%"
                  f"{r['effectively_done_at_gen']:>14.0f}   "
                  f"{'DEAD WEIGHT' if r['stalled'] else ('converged high' if r['tail_gain_pct'] < stall_frac * 100 else 'still improving')}")
        print("\n  Verdict:")
        if out["stalled_pct"] >= 30.0:
            print(f"    {stalled} of {len(rows)} seeds are dead weight. Restart-"
                  f"on-stall would convert that compute into more attempts,")
            print("    and with a final-HV spread of "
                  f"{spread:.3f} more attempts is the lever that matters.")
        elif out["stalled_pct"] >= 15.0:
            print("    Borderline. Some waste, but not enough that restart")
            print("    logic obviously pays for the added complexity in the")
            print("    methods chapter. Judgement call.")
        else:
            print(f"    Only {stalled} of {len(rows)} stalled -- restart logic")
            print("    is NOT worth the complexity. If HV is still climbing at")
            print("    the end, more generations is the simpler lever; if the")
            print("    spread is large, more SEEDS is.")
    return out

def _save_convergence(convergence, cfg):
    """Hypervolume-vs-generation curve: one faint line per seed + bold mean."""
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        fig, ax = plt.subplots(figsize=(7.5, 4.6))
        all_curves = []
        for gens, ys in convergence:
            if gens:
                ax.plot(gens, ys, color="0.72", alpha=0.35, linewidth=1)
                all_curves.append((np.asarray(gens), np.asarray(ys, float)))
        if all_curves:
            grid = all_curves[0][0]
            stack = [np.interp(grid, g, y) for g, y in all_curves]
            mean = np.nanmean(np.vstack(stack), axis=0)
            ax.plot(grid, mean, color="crimson", linewidth=2.5, label="mean")
        ax.set_xlabel("Generation", fontsize=10)
        ax.set_ylabel("Hypervolume (normalised)", fontsize=10)
        ax.set_title("Convergence: hypervolume vs generation", fontsize=12, pad=10)
        ax.margins(x=0.02)
        ax.set_ylim(bottom=0)
        ax.legend(loc="lower right", fontsize=9, framealpha=0.9)
        ax.grid(alpha=0.3)
        fig.tight_layout()
        fig.savefig(cfg.conv_png, dpi=140, bbox_inches="tight")
        plt.close(fig)

        try:
            _rows = []
            for _i, (_g, _y) in enumerate(convergence):
                for _gg, _yy in zip(_g or [], _y or []):
                    _rows.append({"seed": _i, "generation": _gg,
                                  "front_size": int(len(_yy))})
            if _rows:
                pd.DataFrame(_rows).to_csv(cfg.conv_csv, index=False)
                print(f"  Convergence traces saved: {cfg.conv_csv}")
        except Exception as _e:
            print(f"  (convergence CSV skipped: {_e})")

        analyse_seed_stalls(convergence)
        try:
            report_feasibility(globals().get("_LAST_FEAS_TRACES") or [])
        except Exception:
            pass

        if all_curves and len(grid) > 2:
            mg = np.asarray(grid, float)
            dgen = np.diff(mg)
            dgen[dgen == 0] = 1.0
            rate = np.diff(mean) / dgen
            xr = mg[1:]
            w = min(15, len(rate) if len(rate) % 2 else len(rate) - 1)
            w = max(3, w)
            if w % 2 == 0:
                w += 1
            kern = np.ones(w) / w
            rate_s = np.convolve(rate, kern, mode="same")
            fig2, ax2 = plt.subplots(figsize=(7.5, 4.6))
            ax2.plot(xr, rate, color="0.72", linewidth=1, alpha=0.7,
                     label="per-generation \u0394HV")
            ax2.plot(xr, rate_s, color="crimson", linewidth=2.5,
                     label=f"smoothed (w={w})")
            ax2.axhline(0.0, color="black", linewidth=0.8, linestyle="--", alpha=0.6)
            ax2.set_xlabel("Generation", fontsize=10)
            ax2.set_ylabel("HV improvement rate  (\u0394HV / generation)", fontsize=10)
            ax2.set_title("Convergence: hypervolume improvement rate vs generation",
                          fontsize=12, pad=10)
            ax2.margins(x=0.02)
            ax2.set_ylim(bottom=0)
            ax2.legend(loc="upper right", fontsize=9, framealpha=0.9)
            ax2.grid(alpha=0.3)
            fig2.tight_layout()
            fig2.savefig(cfg.conv_rate_png, dpi=140, bbox_inches="tight")
            plt.close(fig2)
    except Exception as e:
        print(f"  (convergence plot skipped: {e})")

def nutrient_sensitivity(fm, x, pct=0.10):
    """Local one-at-a-time (OAT) sensitivity of the five health-domain scores to
    a +pct change in each nutrient's whole-day total, evaluated at plan x.

    For each nutrient j we form the perturbed plan total a_j -> a_j*(1+pct),
    leave all other nutrients unchanged, and recompute every score
    S_d = sum_j w_dj * a_j/(K_dj + a_j). The reported delta is
    S_d(perturbed) - S_d(baseline). Because the scores are Michaelis-Menten,
    a nutrient already far above its half-saturation K barely moves the score
    (saturated), while one near or below K moves it the most.

    Returns (base_scores, rows): base_scores is {ScoreName: value}; rows is a
    list of dicts sorted by total absolute score movement (most influential
    nutrient first)."""
    base_row, _, _ = fm.daily(x)
    fns = [
        ("Mood", nc.mood_score), ("Hair", nc.hair_score),
        ("Muscle", nc.muscle_protection_score), ("Satiety", nc.satiety_score),
        ("Inflammation", nc.inflammation_score),
    ]
    base = {name: float(fn(base_row)) for name, fn in fns}

    col_label = {}
    for name, col in nc.COLS.items():
        if col and col in base_row:
            col_label.setdefault(col, name)
    for c in (nc.TRANS_COL, nc.SUGAR_COL, nc.SATFAT_COL):
        if c and c in base_row:
            col_label.setdefault(c, c)

    rows = []
    for col, label in col_label.items():
        baseval = float(base_row.get(col, 0.0))
        pert = dict(base_row)
        pert[col] = baseval * (1.0 + pct)
        deltas = {name: round(float(fn(pert)) - base[name], 5) for name, fn in fns}
        total = round(sum(abs(v) for v in deltas.values()), 5)
        if total > 0:
            rows.append({"nutrient": label, "column": col, "baseline": baseval,
                         **deltas, "total_abs_move": total})
    rows.sort(key=lambda r: r["total_abs_move"], reverse=True)
    return base, rows

def _report_nutrient_sensitivity(fm, x, cfg):
    """Print, CSV, and a tornado chart for the +pct nutrient sensitivity."""
    pct = cfg.nutrient_sens_pct
    base, rows = nutrient_sensitivity(fm, x, pct)
    if not rows:
        return
    print(BOLD + f"\n--- NUTRIENT SENSITIVITY  (+{pct*100:.0f}% one nutrient at a "
          f"time -> change in each score) ---" + RESET)
    print("  Baseline scores: " + ", ".join(
        f"{DISPLAY_NAME.get(k, k)} {v:.4f}" for k, v in base.items()))
    print("  Higher |delta| = the score is more sensitive to that nutrient "
          "(it sits near/below its K; saturated nutrients barely move).")
    print("  (Column codes: dMood=" + DISPLAY_NAME["Mood"] + ", dHair="
          + DISPLAY_NAME["Hair"] + ", dMuscle=" + DISPLAY_NAME["Muscle"]
          + ", dSatiety=" + DISPLAY_NAME["Satiety"]
          + ", dUnhealthy="
          + DISPLAY_NAME["Inflammation"] + ")")
    print(f"  {'nutrient':<16}{'dMood':>9}{'dHair':>9}{'dMuscle':>9}"
          f"{'dSatiety':>9}{'dUnhealthy':>11}")
    for r in rows[:20]:
        print(f"  {r['nutrient']:<16}{r['Mood']:>9.4f}{r['Hair']:>9.4f}"
              f"{r['Muscle']:>9.4f}{r['Satiety']:>9.4f}"
              f"{r['Inflammation']:>11.4f}")

    try:
        import csv
        with open(cfg.nutrient_sens_csv, "w", newline="") as f:
            w = csv.writer(f)
            w.writerow(["nutrient", "column", "baseline_total", "pct_increase",
                        f"d_{DISPLAY_NAME['Mood']}", f"d_{DISPLAY_NAME['Hair']}",
                        f"d_{DISPLAY_NAME['Muscle']}", f"d_{DISPLAY_NAME['Satiety']}",
                        f"d_{DISPLAY_NAME['Inflammation']}",
                        "total_abs_move"])
            for r in rows:
                w.writerow([r["nutrient"], r["column"], f"{r['baseline']:.5f}",
                            pct, r["Mood"], r["Hair"], r["Muscle"], r["Satiety"],
                            r["Inflammation"], r["total_abs_move"]])
        print(f"  Saved: {cfg.nutrient_sens_csv}")
    except Exception as e:
        print(f"  (sensitivity CSV skipped: {e})")

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        top = rows[:15][::-1]
        labels = [r["nutrient"] for r in top]
        vals = [r["total_abs_move"] for r in top]
        fig, ax = plt.subplots(figsize=(7.5, max(3.5, 0.42 * len(top) + 1)))
        ax.barh(labels, vals, color="#2C7FB8")
        ax.set_xlabel(f"Total |\u0394 score| for a +{pct*100:.0f}% nutrient increase")
        ax.set_title("Nutrient sensitivity of the health-domain scores", pad=10)
        ax.grid(axis="x", alpha=0.3)
        fig.tight_layout()
        fig.savefig(cfg.nutrient_sens_png, dpi=140, bbox_inches="tight")
        plt.close(fig)
        print(f"  Saved: {cfg.nutrient_sens_png}")
    except Exception as e:
        print(f"  (sensitivity plot skipped: {e})")

def _serving_step_x(fm: FoodModel):
    """Per-food size of one ladder step, expressed in x units (100 g).

    Returns an array where serving-basis foods hold serving_g*0.25/100 and
    mass-basis foods hold NaN. x is kept in 100 g units throughout the
    optimizer -- every objective, cap and energy calculation already speaks
    that language -- so the serving ladder is imposed as an allowed-value
    lattice on x rather than by introducing a second variable type. The two
    are mathematically equivalent; this way nothing downstream has to know.
    """
    cand = fm.df.iloc[fm.cand_idx]
    if "dose_basis" not in cand.columns:
        return np.full(fm.n, np.nan)
    g = pd.to_numeric(cand[SERVING_G_COL], errors="coerce").to_numpy(float)
    is_serv = (cand["dose_basis"].to_numpy() == "serving")
    step = np.where(is_serv, g * SERVING_LADDER_STEP / 100.0, np.nan)
    return step

def _apply_serving_caps(fm: FoodModel):
    """Clamp serving-basis foods to at most MAX_SERVINGS.

    The subgroup gram cap and the 2-serving ceiling are BOTH honoured: the
    tighter of the two wins. "Never exceed 2 servings" is a ceiling, so it
    cannot be used to raise a food above a nutritional cap that was already
    stricter.
    """
    step = _serving_step_x(fm)
    serv = ~np.isnan(step)
    if not serv.any():
        return
    max_x = step[serv] * (MAX_SERVINGS / SERVING_LADDER_STEP)
    tightened = int((fm.xu[serv] > max_x).sum())
    loosened = int((fm.xu[serv] < max_x).sum())
    fm.xu[serv] = np.minimum(fm.xu[serv], max_x)
    print(f"  -> serving ladder: {int(serv.sum())} food(s) capped at "
          f"{MAX_SERVINGS:g} servings "
          f"({tightened} tightened by the ladder, "
          f"{loosened} already tighter via their subgroup cap).")

def gather_bounds(fm: FoodModel):
    print("\nServing limits (grams/day). Minimum is 0; set the maximums below.")
    default_lo = 0.0
    fm.xl = np.full(fm.n, default_lo / 100.0)

    subs = fm.df.iloc[fm.cand_idx]["Food_Subgroup"].astype(str).to_numpy()

    use_ul = input(
        "  Use per-subgroup upper limits scaled to your calorie target? "
        "[Y/n]: ").strip().lower()
    if use_ul != "n":
        caps, factor = nc.subgroup_serving_caps(fm.target_kcal)
        gh = input("    Fallback MAX grams for any subgroup without a defined "
                   "limit (e.g. \"Unknown\") [10]: ").strip()
        fallback = float(gh) if gh else 10.0
        default_hi = fallback
        fm.xu = np.array([caps.get(s, fallback) / 100.0 for s in subs])
        print(f"  -> applied subgroup upper limits, scaled by "
              f"{fm.target_kcal:.0f}/{nc.UL_REF_KCAL:.0f} = {factor:.2f}")
        for sg in sorted(set(subs)):
            cap_g = caps.get(sg, fallback)
            tag = "" if sg in caps else "  (fallback)"
            print(f"       {sg:<24} \u2264 {cap_g:5.0f} g/day{tag}")

        fm.unknown_subgroup_fallback_g = fallback
        fm.subgroup_groups = [
            (np.where(subs == sg)[0], float(caps.get(sg, fallback)))
            for sg in np.unique(subs)
        ]
    else:
        gh = input("  Global default MAX grams [10]: ").strip()
        default_hi = float(gh) if gh else 10.0
        fm.xu = np.full(fm.n, default_hi / 100.0)

        fm.unknown_subgroup_fallback_g = default_hi
        fm.subgroup_groups = [
            (np.where(subs == sg)[0], default_hi)
            for sg in np.unique(subs)
        ]

    def _parse(raw):
        lo, hi = (float(v) for v in raw.replace(" ", "").split(","))
        return lo / 100.0, hi / 100.0

    mode = input("  Override serving limits by [s]ubgroup, by [f]ood, or "
                 "[n]one? [n]: ").strip().lower()

    if mode == "s":
        uniq = sorted(set(subs))
        disp = [f"{sg}  ({int((subs == sg).sum())} foods)" for sg in uniq]
        chosen = nc.select_multiple(
            uniq, "\n  Select subgroup(s) to override [numbers/names/all]: ",
            display=disp)
        for sg in chosen:
            raw = input(f"    {sg}  min,max g "
                        f"[{default_lo:.0f},{default_hi:.0f}]: ").strip()
            if not raw:
                continue
            try:
                lo, hi = _parse(raw)
                mask = (subs == sg)
                fm.xl[mask], fm.xu[mask] = lo, hi
                print(f"      -> {int(mask.sum())} foods in '{sg}' set to "
                      f"{lo*100:.0f}-{hi*100:.0f} g")
            except ValueError:
                print("      ! couldn't parse; keeping defaults.")

    elif mode == "f":
        for i, name in enumerate(fm.names):
            raw = input(f"    [{i}] {name[:40]} ({subs[i]}) min,max g "
                        f"[{default_lo:.0f},{default_hi:.0f}]: ").strip()
            if not raw:
                continue
            try:
                fm.xl[i], fm.xu[i] = _parse(raw)
            except ValueError:
                print("      ! couldn't parse; keeping defaults.")

    _apply_serving_caps(fm)

    if hasattr(nc, "apply_food_specific_caps"):
        nc.apply_food_specific_caps(fm)

    if hasattr(nc, "apply_minimum_servings"):
        nc.apply_minimum_servings(fm)

    if hasattr(nc, "describe_macro_bands"):
        nc.describe_macro_bands(fm)
    if hasattr(nc, "check_band_feasibility"):
        nc.check_band_feasibility(fm)

    print("\nMax distinct foods allowed per subgroup (only subgroups listed "
          "here are limited; anything not listed stays unrestricted).")
    cur = dict(fm.cfg.duplicate_limit_subgroups)
    present = sorted(set(subs))
    scoped_present = [sg for sg in present if sg in cur]
    if scoped_present:
        print("  Currently scoped subgroups (present in your candidate pool):")
        for sg in scoped_present:
            print(f"    {sg:<24} max = {cur[sg]}")
    edit = input("  Edit these limits, or add a new subgroup to scope? "
                 "[Y/n]: ").strip().lower()
    if edit != "n":
        uniq = present
        disp = [f"{sg}"
                + (f"  (currently max={cur[sg]})" if sg in cur else "  (unrestricted)")
                for sg in uniq]
        chosen = nc.select_multiple(
            uniq, "\n  Select subgroup(s) to set/change a max-food limit for "
                 "[numbers/names/all]: ", display=disp)
        for sg in chosen:
            raw = input(f"    {sg}  max distinct foods "
                        f"[{cur.get(sg, 'unrestricted')}] "
                        f"(Enter = 0 / unrestricted, or type a number): ").strip()
            if raw == "":
                raw = "0"
            try:
                n = int(raw)
                if n <= 0:
                    cur.pop(sg, None)
                    print(f"      -> '{sg}' set to UNRESTRICTED (limit removed)")
                else:
                    cur[sg] = n
                    print(f"      -> '{sg}' max distinct foods = {n}")
            except ValueError:
                print("      ! couldn't parse; keeping current setting.")
        fm.cfg.duplicate_limit_subgroups = cur
        print(f"  -> {len(cur)} subgroup(s) now scoped for a max-foods limit; "
              f"everything else remains unrestricted.")

_REQUIRED_COLS = [
    "description",
    "Energy (Atwater Specific Factors) (KCAL)",
    "Protein (G)",
    "Total lipid (fat) (G)",
    "Carbohydrate, by difference (G)",
]

def _normalize_headers(df: pd.DataFrame) -> pd.DataFrame:
    """Collapse newlines/repeated whitespace in column names.

    Nutrient headers like "Carbohydrate, by difference (G)" contain commas,
    so they get quoted on export and can come back with embedded line
    breaks depending on how the file was written. Two files that describe
    the same nutrient would then fail to align on a plain concat. Normalise
    before doing anything else.
    """
    df = df.copy()
    df.columns = [re.sub(r"\s+", " ", str(c)).strip() for c in df.columns]
    return df

SERVING_LADDER_STEP = 0.25
MAX_SERVINGS = 2.0
SERVING_LADDER = [round(k * SERVING_LADDER_STEP, 2)
                  for k in range(int(MAX_SERVINGS / SERVING_LADDER_STEP) + 1)]

SERVING_G_COL = "serving_g"

def _attach_serving_weights(df: pd.DataFrame, weights_path) -> pd.DataFrame:
    """Join gram-per-serving weights onto the pool by food_code.

    The weights file is derived from the published INDB, which reports every
    recipe BOTH per 100 g and per unit serving. Dividing the two gives that
    recipe's exact serving weight:

        serving_g = unit_serving_energy_kcal / energy_kcal * 100

    This is an identity, not an estimate -- recomputing it from protein,
    carbohydrate and fat independently reproduces the same number for
    931/931 rows where all four are present. So "1 tea cup" is that
    recipe's own tea cup, not a generic assumption about tea cups.
    """
    if weights_path is None or str(weights_path).strip() == "":
        return df
    if not _os.path.exists(str(weights_path)):
        raise FileNotFoundError(
            f"Serving-weights file not found: {weights_path}\n"
            f"  Current directory: {_os.getcwd()}\n"
            f"  Either give the full path, or press Enter at that prompt to "
            f"dose every food in grams deliberately.")
    w = _normalize_headers(pd.read_csv(str(weights_path), low_memory=False))
    if "food_code" not in w.columns or SERVING_G_COL not in w.columns:
        print(f"  WARNING: {_os.path.basename(str(weights_path))} lacks "
              f"'food_code'/'{SERVING_G_COL}'; serving weights not applied.")
        return df
    w = w[["food_code", SERVING_G_COL]].dropna(subset=["food_code"])
    w = w.drop_duplicates(subset=["food_code"])

    if "food_code" not in df.columns:
        print("  WARNING: pool has no 'food_code'; serving weights not applied.")
        return df

    before = df[SERVING_G_COL].notna().sum() if SERVING_G_COL in df.columns else 0
    if SERVING_G_COL in df.columns:
        df = df.drop(columns=[SERVING_G_COL])
    df = df.merge(w, on="food_code", how="left")
    got = int(df[SERVING_G_COL].notna().sum())
    print(f"  Serving weights: matched {got} of {len(df)} pool rows "
          f"(was {before}).")
    return df

def _assign_basis(df: pd.DataFrame) -> pd.DataFrame:
    """Tag every row 'serving' or 'mass' and report the split."""
    if SERVING_G_COL not in df.columns:
        df[SERVING_G_COL] = np.nan
    g = pd.to_numeric(df[SERVING_G_COL], errors="coerce")
    ok = g.notna() & (g > 0) & (g <= 2000)
    df[SERVING_G_COL] = g.where(ok)
    df["dose_basis"] = np.where(ok, "serving", "mass")

    n_s = int(ok.sum())
    print(f"\n  Dosing basis: {n_s} food(s) on the serving ladder "
          f"({SERVING_LADDER[1]}-{MAX_SERVINGS} servings, step "
          f"{SERVING_LADDER_STEP}), {len(df) - n_s} in grams.")
    if n_s == 0 and "food_code" in df.columns and df["food_code"].notna().any():
        print("    WARNING: no food in the pool has a serving weight, yet the "
              "pool contains food_code values. If you meant to dose the "
              "recipe foods in servings, the weights file was skipped or "
              "did not match -- plans will show '(bowl)' instead of "
              "'0.75 x bowl'.")
    bad = g.notna() & ~ok
    if bad.any():
        print(f"    {int(bad.sum())} row(s) had an unusable serving weight "
              f"and fall back to gram dosing.")
    return df

def load_food_data(paths) -> pd.DataFrame:
    """Read and vertically merge one or more per-100 g food csv files.

    Returns a single frame with a contiguous RangeIndex (main() maps
    pool rows back to positional indices, so the index must be clean),
    plus two bookkeeping columns:
        source_file    - which input file each row came from
        orig_fdc_id    - the row's id in its own source file
    `fdc_id` itself is re-issued as a globally unique integer so ids
    from different files can never collide.
    """
    frames = []
    for p in paths:
        p = (clean_input_path(p) if "clean_input_path" in globals()
             else str(p).strip().strip('"').strip("'"))
        if not p:
            continue
        if not _os.path.exists(p):
            raise FileNotFoundError(
                describe_missing_path(p)
                if "describe_missing_path" in globals()
                else f"No such file: {p}")

        d = _normalize_headers(pd.read_csv(p, low_memory=False))

        missing = [c for c in _REQUIRED_COLS if c not in d.columns]
        if missing:
            raise ValueError(
                f"{_os.path.basename(p)} is missing required column(s): "
                f"{missing}\nColumns found: {sorted(d.columns.tolist())}")

        d["source_file"] = _os.path.basename(p)
        d["orig_fdc_id"] = d["fdc_id"] if "fdc_id" in d.columns else pd.NA
        if "servings_unit" not in d.columns:
            d["servings_unit"] = pd.NA

        print(f"  Loaded {len(d):>5} rows x {d.shape[1]:>3} cols  from "
              f"{_os.path.basename(p)}")
        frames.append(d)

    if not frames:
        raise ValueError("No input files given.")

    if len(frames) > 1:
        common = set(frames[0].columns)
        union = set(frames[0].columns)
        for f in frames[1:]:
            common &= set(f.columns)
            union |= set(f.columns)
        partial = sorted(union - common)
        if partial:
            print(f"\n  NOTE: {len(partial)} column(s) are not present in "
                  f"every file and will be NaN where absent:")
            for c in partial:
                have = [f["source_file"].iloc[0] for f in frames
                        if c in f.columns]
                print(f"    {c}  (only in: {', '.join(have)})")

    df = pd.concat(frames, ignore_index=True, sort=False)

    key = df["description"].astype(str).str.strip().str.lower()
    dup = key.duplicated(keep="first")
    if dup.any():
        print(f"\n  Dropping {int(dup.sum())} duplicate description(s) "
              f"(kept first occurrence):")
        for nm in df.loc[dup, "description"].head(10):
            print(f"    {nm}")
        if int(dup.sum()) > 10:
            print(f"    ... and {int(dup.sum()) - 10} more")
        df = df[~dup]

    df = df.reset_index(drop=True)
    df["fdc_id"] = np.arange(1, len(df) + 1, dtype=np.int64)

    print(f"\n  Merged pool: {len(df)} unique foods from "
          f"{len(frames)} file(s).")
    return df

def _report_pool_coverage(df: pd.DataFrame) -> None:
    """Print, per source file, how many rows survive classification.

    Three outcomes are reported separately, because they mean different
    things and only one of them is a defect:

      pool     - classified into a subgroup that has a meal role; usable.
      no-role  - classified, but into a subgroup with no entry in
                 SUBGROUP_MEAL_ROLE (currently "Refined Grains"). These are
                 excluded on NUTRITIONAL grounds, deliberately.
      unclass  - the classifier did not recognise the name at all. This is
                 the defect bucket. A file with a high unclass share is a
                 data/classifier problem, and any result computed from that
                 pool is drawn from a silently truncated candidate set.
    """
    print("\n  Classifier coverage by source file:")
    print(f"    {'file':<40}{'rows':>6}{'pool':>7}{'no-role':>9}"
          f"{'unclass':>9}{'unclass%':>10}")
    for src, g in df.groupby("source_file", sort=False):
        unclass = int((g["Food_Type"] == "Unknown").sum())
        known = g[g["Food_Type"] != "Unknown"]
        norole = int((~known["Food_Subgroup"].isin(
            nc.SUBGROUP_MEAL_ROLE.keys())).sum())
        pool = len(known) - norole
        pct = (unclass / len(g) * 100.0) if len(g) else 0.0
        print(f"    {str(src)[:39]:<40}{len(g):>6}{pool:>7}{norole:>9}"
              f"{unclass:>9}{pct:>9.1f}%")
        if pct > 40.0:
            print(f"      ^ WARNING: {pct:.0f}% of this file is "
                  f"unclassified. Check classify_food() covers its naming "
                  f"style before treating the pool as representative.")

def retry_failed_recipes(result, food_db, column_map, gemini_api_key,
                         output_dir="output", verbose=True):
    """Regenerate ONLY the meals that fell back to the template.

    Recipe generation is the one part of this pipeline that depends on an
    external service, so it is the one part that can fail for reasons nothing
    in the run controls -- a timeout, a rate limit, a transient outage. When it
    does, the plan itself is unaffected: foods, portions and meal assignments
    are all computed locally and are already correct. Only the cooking text is
    missing.

    Re-running the WHOLE pipeline to recover that text would re-run the
    optimizer, which is hours of compute for a network blip -- and would also
    produce a different plan if anything else has changed. This regenerates the
    affected meals against the plan already in `result` and leaves everything
    else exactly as it was.
    """
    recipes = dict(result.get("recipes") or {})
    failed = [k for k, v in recipes.items() if not v.get("used_gemini")]
    if not failed:
        if verbose:
            print("  No templated recipes to retry -- every meal has a full "
                  "recipe.")
        return result
    if verbose:
        print(f"  Retrying {len(failed)} templated recipe(s): "
              f"{', '.join(failed)}")

    split = result.get("rebuilt_meal_split")
    meal_col = _cfg(column_map, "meal_col")
    fixed = 0
    for meal in failed:
        rows = split[split[meal_col].astype(str) == meal] if split is not None \
            else None
        if rows is None or rows.empty:
            continue
        try:
            new = build_recipe(meal, rows, food_db, column_map, gemini_api_key)
            if new.get("used_gemini"):
                recipes[meal] = new
                fixed += 1
            elif verbose:
                print(f"    {meal}: still failing -- "
                      f"{new.get('fallback_reason') or 'unknown'}")
        except Exception as exc:
            if verbose:
                print(f"    {meal}: {type(exc).__name__}: {exc}")
    result["recipes"] = recipes
    if verbose:
        print(f"  Recovered {fixed} of {len(failed)}.")
        if fixed:
            print("  Re-run write_docx() to refresh the document, or call this "
                  "before the document is written.")
    return result

PRACTICAL_MAX_FOODS_PER_DAY: int = 20
HANDWRITTEN_PLAN_FOODS_TYPICAL: int = 16

def score_plan_quality(result, cfg=None, person=None, verbose=True):
    """Score a plan on the four axes a dietitian reviewer actually uses.

    WHY THIS EXISTS. Thirteen separate guards now run over a plan, each added
    after a specific failure had already reached a document: the 9,308 mg
    sodium, the whelk and salt cod, the six-item plates, the dessert in the
    dinner slot. Each one reports into a long console log, and a warning in a
    long log is how every one of those reached a reader in the first place.

    What was never in the code is the REVIEWER'S QUESTION -- "is this plan any
    good, and on which axis is it weak?" This computes that from the guards
    that already exist, on the same four axes and the same 0-10 scale used in
    review, so the answer arrives before the plan is sent rather than after.

    IT IS A SCREEN, NOT A DIETITIAN. It catches the failure classes that have
    actually occurred here. It cannot judge whether a plan suits a particular
    patient, and a 9/10 is a reason to review rather than a reason to skip
    reviewing.
    """
    def clamp(v):
        return max(0.0, min(10.0, v))

    notes = {"Nutritional Adequacy": [], "Practicality": [],
             "Safety": [], "Overall Acceptability": []}
    score = {k: 10.0 for k in notes}

    split = result.get("rebuilt_meal_split")
    cmap = result.get("column_map") or {}
    meal_col = _cfg(cmap, "meal_col") or "meal"
    summary = result.get("nutrition_summary")

    adeq = result.get("adequacy") or {}
    if adeq.get("mar_after") is not None:
        mar = float(adeq["mar_after"])
        score["Nutritional Adequacy"] -= max(0.0, (95.0 - mar) * 0.4)
        notes["Nutritional Adequacy"].append(f"MAR as issued {mar:.1f}%")
    nc_tbl = result.get("nutrient_change")
    if nc_tbl is not None and not nc_tbl.empty:
        crossed = nc_tbl[nc_tbl["crossed_below_rda"] | nc_tbl["crossed_over_ul"]]
        if not crossed.empty:
            score["Nutritional Adequacy"] -= 1.5 * len(crossed)
            notes["Nutritional Adequacy"].append(
                f"{len(crossed)} nutrient(s) crossed a reference limit during "
                f"the rebuild")

    micro = result.get("micronutrient_summary")
    try:
        if micro is not None and not micro.empty:
            na = micro[micro["nutrient"].astype(str).str.lower()
                       .str.contains("sodium", na=False)]
            if not na.empty:
                v = float(na.iloc[0]["day_total"])
                if v > MAX_SODIUM_MG_PER_DAY:
                    over = v / MAX_SODIUM_MG_PER_DAY
                    score["Safety"] -= min(8.0, 4.0 * over)
                    notes["Safety"].append(
                        f"sodium {v:,.0f} mg vs {MAX_SODIUM_MG_PER_DAY:,.0f}")
            over_ul = micro[micro["over_ul"]] if "over_ul" in micro else None
            if over_ul is not None and not over_ul.empty:
                score["Safety"] -= 2.0 * len(over_ul)
                notes["Safety"].append(f"{len(over_ul)} nutrient(s) over UL")
    except Exception:
        pass
    if person is None or not getattr(person, "weight_kg", None):
        score["Safety"] -= 2.0
        notes["Safety"].append("no client profile attached")

    flagged = 0
    if split is not None and not split.empty:
        fc = _cfg(cmap, "food_col") or "food"
        for nm in split[fc].astype(str):
            if _classify_flag(nm)[0]:
                flagged += 1
        if flagged:
            score["Practicality"] -= 1.5 * flagged
            notes["Practicality"].append(
                f"{flagged} food(s) still flagged unsafe/impractical")
        for meal, grp in split.groupby(split[meal_col].astype(str)):
            if len(grp) > EXCHANGE_MAX_ITEMS_PER_MEAL:
                score["Practicality"] -= 1.0
                notes["Practicality"].append(f"{meal}: {len(grp)} items")
    if split is not None and not split.empty:
        fc2 = _cfg(cmap, "food_col") or "food"
        n_distinct = split[fc2].astype(str).nunique()
        if n_distinct > PRACTICAL_MAX_FOODS_PER_DAY:
            score["Practicality"] -= 0.5 * (n_distinct - PRACTICAL_MAX_FOODS_PER_DAY)
            notes["Practicality"].append(
                f"{n_distinct} distinct foods for one day, above the "
                f"{PRACTICAL_MAX_FOODS_PER_DAY}-food design budget")
        elif n_distinct > HANDWRITTEN_PLAN_FOODS_TYPICAL:
            notes["Practicality"].append(
                f"{n_distinct} distinct foods (within budget; a hand-written "
                f"plan typically uses {HANDWRITTEN_PLAN_FOODS_TYPICAL} or "
                f"fewer -- worth a glance at the shopping list)")
        else:
            notes["Practicality"].append(f"{n_distinct} distinct foods")

    dups = result.get("day_level_duplicates") or []
    if dups:
        score["Practicality"] -= 1.0 * len(dups)
        notes["Practicality"].append(
            f"{len(dups)} ingredient(s) repeated across meals")
    recipes = result.get("recipes") or {}
    missing = [k for k, v in recipes.items() if not v.get("used_gemini")]
    if missing:
        score["Practicality"] -= 1.2 * len(missing)
        notes["Practicality"].append(f"{len(missing)} meal(s) without a recipe")

    bad_plates = []
    if split is not None and not split.empty and "Food_Subgroup" in split.columns:
        for meal, grp in split.groupby(split[meal_col].astype(str)):
            sgs = grp["Food_Subgroup"].tolist()
            probs = meal_archetype_problems(meal, sgs)
            _, clash = meal_compatibility(sgs)
            if probs or clash:
                bad_plates.append(meal)
        if bad_plates:
            score["Overall Acceptability"] -= 2.0 * len(bad_plates)
            notes["Overall Acceptability"].append(
                f"plate problems in: {', '.join(bad_plates)}")
        main_fail = [mm for mm in bad_plates
                     if MEAL_ARCHETYPES.get(mm, (False,))[0]]
        if main_fail:
            score["Overall Acceptability"] = min(
                score["Overall Acceptability"], 4.0)
            notes["Overall Acceptability"].append(
                f"main meal(s) that do not read as that meal: "
                f"{', '.join(main_fail)} -- capped at 4/10 regardless of "
                f"nutrient quality")
    score["Overall Acceptability"] = min(
        score["Overall Acceptability"],
        min(score["Nutritional Adequacy"], score["Practicality"],
            score["Safety"]) + 1.0)

    for k in score:
        score[k] = round(clamp(score[k]), 1)

    if verbose:
        print(BOLD + "\n=== PLAN QUALITY (self-assessment) ===" + RESET)
        for k in ("Nutritional Adequacy", "Practicality", "Safety",
                  "Overall Acceptability"):
            bar = "#" * int(round(score[k])) + "." * (10 - int(round(score[k])))
            print(f"  {k:<24}{score[k]:>5}/10  [{bar}]")
            for n_ in notes[k]:
                print(f"      - {n_}")
        weakest = min(score, key=lambda z: score[z])
        print(f"\n  Weakest axis: {weakest} ({score[weakest]}/10)")
        print("  This is a SCREEN for failures seen before, not a dietitian's")
        print("  review. A high score means nothing obvious is wrong, not that")
        print("  the plan suits this patient.")
    return {"scores": score, "notes": notes}

def plan_signoff_checklist(result, cfg=None, person=None, previous_target=None,
                           verbose=True):
    """Release gate: is this plan fit to hand to a client?

    Every item here corresponds to a failure that actually reached a document
    in this project -- 9,308 mg sodium, a plan of whelk and salt cod, six
    unrelated items on one plate, five recipes shipped as bare ingredient
    lists. Each was individually detected somewhere in the output, and each
    still reached the reader, because a warning buried in a long console log is
    not a gate.

    Returns a dict with `ready` False if anything blocking failed. The point is
    that a plan with a FAILED line should not be presented as final, whatever
    else is good about it.
    """
    cmap = result.get("column_map") or {}

    checks = []

    def add(name, ok, blocking, detail=""):
        checks.append({"check": name, "pass": bool(ok),
                       "blocking": bool(blocking), "detail": detail})

    has_profile = person is not None and getattr(person, "weight_kg", None)
    add("Client profile attached", bool(has_profile), True,
        "" if has_profile else "No profile: a calorie target cannot be "
                               "justified for anyone specific without one.")

    tgt = getattr(cfg, "target_kcal", None) or result.get("target_kcal")
    if previous_target and tgt and abs(float(previous_target) - float(tgt)) > 1:
        add("Target change recorded", True, False,
            f"Target updated: {float(previous_target):,.0f} -> "
            f"{float(tgt):,.0f} kcal (profile updated).")

    add("Accessibility filter applied",
        bool(globals().get("PREFILTER_POOL_BY_FLAGS", False)), True)

    micro = result.get("micronutrient_summary")
    na = None
    try:
        if micro is not None and not micro.empty:
            r = micro[micro["nutrient"].astype(str).str.lower()
                      .str.contains("sodium", na=False)]
            na = float(r.iloc[0]["day_total"]) if not r.empty else None
    except Exception:
        na = None
    if na is not None:
        add("Sodium within CDRR", na <= MAX_SODIUM_MG_PER_DAY, True,
            f"{na:,.0f} mg against {MAX_SODIUM_MG_PER_DAY:,.0f} mg")
    else:
        add("Sodium within CDRR", False, False, "not measurable from this result")

    recipes = result.get("recipes") or {}
    missing = [k for k, v in recipes.items() if not v.get("used_gemini")]
    add("All recipes model-written", not missing, False,
        "" if not missing else
        f"{len(missing)} meal(s) on the template fallback: "
        f"{', '.join(missing)}. Cookable as written; run "
        f"retry_failed_recipes() for the fuller card.")
    stepless = [k for k, v in recipes.items() if not (v.get("steps") or [])]
    add("Every meal has cooking steps", not stepless, True,
        "" if not stepless else f"no steps at all for: {', '.join(stepless)}")

    undercooked = [k for k, v in recipes.items()
                   if v.get("undercooked_ingredient")]
    add("Dry pulses and grains cooked adequately", not undercooked, True,
        "" if not undercooked else
        f"{', '.join(undercooked)}: the model recipe undercooked a dry "
        f"ingredient and was replaced by the templated card.")

    implausible: List[str] = []
    for k, v in recipes.items():
        names_k = [str(i.get("name")) for i in (v.get("ingredients") or [])]
        if not names_k:
            continue
        ok_p, probs_p = validate_prep_plausibility(v, names_k)
        if not ok_p:
            implausible.append(f"{k}: {probs_p[0]}")
    add("No prepared food soaked or cooked from raw", not implausible, True,
        "" if not implausible else " | ".join(implausible))

    unrecognisable: List[str] = []
    for k, v in recipes.items():
        names_k = [str(i.get("name")) for i in (v.get("ingredients") or [])]
        unrecognisable.extend(standalone_edibility_problems(k, names_k))
    add("Every meal is recognisable as food", not unrecognisable, True,
        "" if not unrecognisable else " | ".join(unrecognisable))

    split_chk = result.get("rebuilt_meal_split")
    if split_chk is not None and not split_chk.empty:
        cm_chk = result.get("column_map") or {}
        f_chk = _cfg(cm_chk, "food_col") or "food"
        g_chk = _cfg(cm_chk, "grams_col") or "grams"
        m_chk = _cfg(cm_chk, "meal_col") or "meal"
        oversized, misplaced_sweets = [], []
        for _, rr in split_chk.iterrows():
            nm = str(rr.get(f_chk))
            gv = pd.to_numeric(rr.get(g_chk), errors="coerce")
            gv = float(gv) if pd.notna(gv) else 0.0
            cap = culinary_herb_cap_g(nm)
            if cap is not None and gv > cap + 0.5:
                oversized.append(f"{nm} at {gv:.0f} g (cap {cap:.0f} g)")
            if is_dessert_or_sweet(nm):
                slot = MEAL_NAME_ALIASES.get(
                    str(rr.get(m_chk)).strip().lower(), "")
                if slot and slot != "snack":
                    misplaced_sweets.append(f"{nm} in {rr.get(m_chk)}")
        add("Herbs at culinary quantities", not oversized, True,
            "" if not oversized else "; ".join(oversized))
        add("No dessert in a main meal", not misplaced_sweets, True,
            "" if not misplaced_sweets else "; ".join(misplaced_sweets))

    bad_meals = []
    split = result.get("rebuilt_meal_split")
    if split is not None and not split.empty and cfg is not None:
        try:
            mc = _cfg(result.get("column_map", {}), "meal_col") or "meal"
            sgc = "Food_Subgroup"
            if sgc in split.columns:
                for meal, grp in split.groupby(split[mc].astype(str)):
                    _, bad = meal_compatibility(grp[sgc].tolist())
                    if bad:
                        bad_meals.append(meal)
        except Exception:
            pass
    add("Meal coherence check", not bad_meals, False,
        "" if not bad_meals else f"flavour clash in: {', '.join(bad_meals)}")

    if split is not None and not split.empty:
        fc2 = _cfg(cmap, "food_col") or "food"
        n_distinct = split[fc2].astype(str).nunique()
        add("Shopping list is a realistic size",
            n_distinct <= PRACTICAL_MAX_FOODS_PER_DAY, False,
            "" if n_distinct <= HANDWRITTEN_PLAN_FOODS_TYPICAL else
            (f"{n_distinct} distinct foods for one day, above the "
             f"{PRACTICAL_MAX_FOODS_PER_DAY}-food design budget"
             if n_distinct > PRACTICAL_MAX_FOODS_PER_DAY else
             f"{n_distinct} distinct foods; a hand-written plan typically "
             f"uses {HANDWRITTEN_PLAN_FOODS_TYPICAL} or fewer"))

    dups = result.get("day_level_duplicates") or []
    add("No repeated ingredient across meals", not dups, False,
        "" if not dups else
        "; ".join(" / ".join(d["foods"]) for d in dups[:3]))

    blocking_fail = [c for c in checks if c["blocking"] and not c["pass"]]
    ready = not blocking_fail

    if verbose:
        print(BOLD + "\n=== PLAN SIGN-OFF CHECKLIST ===" + RESET)
        for c in checks:
            mark = "PASS" if c["pass"] else ("FAIL" if c["blocking"] else "warn")
            print(f"  [{mark}] {c['check']}"
                  + (f" -- {c['detail']}" if c["detail"] else ""))
        print()
        if ready:
            print("  READY: no blocking item failed.")
        else:
            print(f"  NOT READY: {len(blocking_fail)} blocking item(s) failed. "
                  f"Do not present this as a final plan.")
            print("  A warning inside a long log is not a gate -- this is.")
    return {"ready": ready, "checks": checks}

def reproducibility_report(cfg, verbose=True):
    """State exactly which parts of a run are reproducible, and which are not.

    Written because "results should be reproducible" is a requirement with
    THREE different answers in this pipeline, and reporting one number for all
    of them would be wrong.

    1. THE OPTIMIZATION IS FULLY REPRODUCIBLE. Every seed is passed explicitly
       to pymoo's minimize(), and pymoo 0.6.2 threads its seeded Generator into
       SparseDietSampling and CardinalityRepair as random_state (verified, not
       assumed). Both operators fall back to an unseeded Generator only if
       called outside pymoo, which never happens in a run. Same inputs + same
       cfg => identical front.

    2. THE REBUILD STAGE IS REPRODUCIBLE EXCEPT FOR RECIPE TEXT. Substitution,
       portion rescaling, meal shifts, consolidation and energy reconciliation
       are all deterministic. The RECIPES are generated by an external LLM and
       are NOT reproducible -- the same plan will produce different wording on
       different days, and the model behind the API can change without notice.

    3. THE FOOD DATABASE IS AN INPUT, NOT A CONSTANT. A different FDC export,
       or a different pool filter, changes everything downstream. Reproducing a
       result requires the same CSV, not just the same code.

    WHAT TO RECORD IN THE THESIS so a reader can reproduce a run: the config
    signature below, the food CSV (with its version or download date), the
    package versions, and the checkpoint directory if one was used.
    """
    import platform
    try:
        import pymoo, numpy, pandas
        vers = (f"python {platform.python_version()}, pymoo {pymoo.__version__}, "
                f"numpy {numpy.__version__}, pandas {pandas.__version__}")
    except Exception:
        vers = f"python {platform.python_version()}"
    info = {
        "base_seed": getattr(cfg, "base_seed", None),
        "n_seeds": cfg.n_seeds,
        "n_gen": cfg.n_gen,
        "n_ref_points": cfg.n_ref_points,
        "pop_size": cfg.pop_size or cfg.n_ref_points,
        "sbx_eta": cfg.sbx_eta, "sbx_prob": cfg.sbx_prob, "pm_eta": cfg.pm_eta,
        "serving_grid_g": cfg.serving_grid_g,
        "min_foods": cfg.min_foods, "max_foods": cfg.max_foods,
        "energy_band_frac": cfg.energy_band_frac,
        "versions": vers,
    }
    if verbose:
        print(BOLD + "\n--- REPRODUCIBILITY ---" + RESET)
        print("  Optimization : FULLY REPRODUCIBLE. Seeds are passed to pymoo "
              "explicitly and")
        print("                 threaded into the custom sampling and repair "
              "operators.")
        print("                 Same CSV + same settings below => identical "
              "front.")
        print("  Rebuild      : deterministic, EXCEPT recipe TEXT (external "
              "LLM). The food")
        print("                 choices, portions and meal assignments repeat; "
              "the wording")
        print("                 does not, and the model behind the API can "
              "change.")
        print("  Food data    : an INPUT. Record the CSV version/date -- the "
              "same code on a")
        print("                 different export gives a different answer, "
              "correctly.")
        print("\n  Settings to record alongside any reported result:")
        for k, v in info.items():
            if k != "versions":
                print(f"    {k:<20}{v}")
        print(f"    {'versions':<20}{vers}")
        print("\n  To reproduce a specific plan rather than the whole front,")
        print("  record the seed AND the front index -- the MCDM pick depends")
        print("  on cfg.mcdm_weights, so that must be recorded too.")
    return info

LAST_FM = None
LAST_CFG = None
LAST_FRONT_X = None
LAST_FRONT_OBJ = None

OFFER_DISH_POOL: bool = False

def main():
    print("=" * 72)
    print("NSGA-III DIET OPTIMIZER (research grade)")
    print("=" * 72)

    print("\nIf you've changed the scoring code since your last run, old "
          "checkpoints on disk will NOT reflect that change unless you "
          "start fresh here.")
    ck_in = input("Use previous checkpoints if found for this exact run "
                  "config? [Y/n]: ").strip().lower()
    if ck_in == "n":
        _checkpoint_run_id = f"fresh_{int(time.time())}"
        print("  -> ignoring any existing checkpoints; this run will start "
              "fresh (old checkpoint files are left on disk, untouched, "
              "under their original run id).\n")
    else:
        _checkpoint_run_id = None
        print("  -> will resume from matching checkpoints if any are found.\n")

    person = nc.get_person_from_input()
    nc.print_report(person)

    if OFFER_DISH_POOL:
        print("\nWhich food pool?")
        print("  1  Indian ingredients  -- IFCT / INDB csv files (the original)")
        print("  2  USDA FNDDS dishes   -- the five 2021-2023 Excel workbooks")
        pool_choice = input("Choice [1/2]: ").strip()
    else:
        pool_choice = "1"
        print("\nFood pool: ingredient CSV (the dish pool is retired).")

    rebuild_gemini_key = ""
    if pool_choice != "2":
        rebuild_gemini_key = prompt_gemini_api_key()

    if pool_choice == "2":
        df = load_fndds_and_prepare()
        if prompt_extra_csv():
            df = merge_pools(df, load_extra_ingredient_csv())
        else:
            df["pool_source"] = POOL_SOURCE_DISH
        df = _assign_basis(df)
    else:
        disable_dish_mode()
        print("\nEnter CSV path(s), comma-separated for multiple files.")
        print("  e.g.  india_foods_aligned.csv, indb_aligned_no_added_sugar.csv")
        print("  All files must be per-100 g composition tables.")
        print("  This must be a FILE, not a folder.")
        raw_in = input("CSV path(s) [Enter = india_foods_aligned.csv, "
                       "indb_aligned_no_added_sugar.csv]: ").strip()
        if not raw_in:
            raw_in = "india_foods_aligned.csv, indb_aligned_no_added_sugar.csv"
        csv_paths = [p for p in (s.strip() for s in raw_in.split(",")) if p]
        if not csv_paths:
            print("\nNo CSV path given.")
            return
        for p in csv_paths:
            if _os.path.isdir(p):
                print(f"\n  {p}\n  is a FOLDER, not a csv file. Give the "
                      "full path to the .csv itself,\n  or choose 2 above "
                      "if you meant the FNDDS Excel workbooks.")
                return
        print()
        df = load_food_data(csv_paths)

        wpath = input(
            "Serving-weights CSV (food_code, serving_g) "
            "[Enter to skip, all foods dosed in grams]: ").strip().strip('"').strip("'")
        if wpath:
            df = _attach_serving_weights(df, wpath)
        else:
            print("  No serving-weights file given -- EVERY food will be dosed "
                  "in grams and the 0.25-2 serving ladder will NOT apply.")
        df = _assign_basis(df)

    desc_col = next(c for c in ["description", "food_description", "food_name"]
                     if c in df.columns)

    is_babyfood = df[desc_col].astype(str).str.strip().str.lower().str.startswith("babyfood")
    if is_babyfood.any():
        print(f"  Excluding {int(is_babyfood.sum())} Babyfood/infant-labeled "
              f"row(s) from the candidate pool (not appropriate for adult "
              f"diet plans).")
    df = df[~is_babyfood].copy()

    _KNOWN_CORRUPTED_FDC_IDS = {173459}
    if "fdc_id" in df.columns:
        is_corrupted = df["fdc_id"].isin(_KNOWN_CORRUPTED_FDC_IDS)
        if is_corrupted.any():
            print(f"  Excluding {int(is_corrupted.sum())} row(s) with "
                  f"confirmed-corrupted nutrient data (see "
                  f"_KNOWN_CORRUPTED_FDC_IDS).")
        df = df[~is_corrupted].copy()

    df[["Food_Type", "Food_Subgroup"]] = (
        df[desc_col].apply(nc.classify_food).apply(pd.Series))

    if hasattr(nc, "nutrient_sanity_audit"):
        nc.nutrient_sanity_audit(df, desc_col)
    if hasattr(nc, "apply_nutrient_corrections"):
        df = nc.apply_nutrient_corrections(df)

    if hasattr(nc, "refine_fish_subgroup_by_fat"):
        df = nc.refine_fish_subgroup_by_fat(df)

    if hasattr(nc, "apply_cultural_and_sourcing_filters"):
        df = nc.apply_cultural_and_sourcing_filters(df, desc_col)

    if hasattr(nc, "prompt_for_allergen_exclusions"):
        _allergens = nc.prompt_for_allergen_exclusions()
        if _allergens:
            df = nc.filter_pool_for_allergens(df, _allergens, desc_col)

    if hasattr(nc, "attach_functional_scores"):
        df = nc.attach_functional_scores(df, desc_col)

    if "source_file" in df.columns and df["source_file"].nunique() >= 1:
        _report_pool_coverage(df)

    if hasattr(nc, "pool_diagnostic_report"):
        nc.pool_diagnostic_report(df, desc_col)

    configure_scoring(df, person)

    df_known = df[df["Food_Type"] != "Unknown"].copy()

    _no_role_mask = ~df_known["Food_Subgroup"].isin(nc.SUBGROUP_MEAL_ROLE.keys())
    if _no_role_mask.any():
        _dropped_subs = sorted(df_known.loc[_no_role_mask, "Food_Subgroup"].unique())
        print(f"  Excluding {int(_no_role_mask.sum())} food(s) from the candidate "
              f"pool -- subgroup(s) with no meal-role mapping: {_dropped_subs}.")
        df_known = df_known[~_no_role_mask].copy()

    types = sorted(df_known["Food_Type"].dropna().unique())
    print("\nAvailable Food Types:")
    sel_types = nc.select_multiple(types,
                                   "\nSelect Food Type(s) [numbers/names/all]: ")
    pool = df_known[df_known["Food_Type"].isin(sel_types)]
    subs = sorted(pool["Food_Subgroup"].dropna().unique())
    print("\nAvailable Subgroups:")
    sel_subs = nc.select_multiple(subs,
                                  "\nSelect Subgroup(s) [numbers/names/all]: ")
    pool = pool[pool["Food_Subgroup"].isin(sel_subs)]

    if PREFILTER_NOVA and "nova_group" in dir(nc):
        try:
            _nova = pool[desc_col].astype(str).map(lambda z: nc.nova_group(z))
            _too_processed = _nova > NOVA_MAX
            if _too_processed.any():
                _kept = pool[~_too_processed]
                print(f"\n  NOVA FILTER: removing {int(_too_processed.sum())} "
                      f"food(s) above NOVA {NOVA_MAX} from the candidate pool.")
                for _nm in pool.loc[_too_processed, desc_col].head(6):
                    print(f"    {str(_nm)[:66]}")
                if len(_kept) >= max(PREFILTER_MIN_POOL, 5):
                    pool = _kept
                else:
                    print(f"    NOT APPLIED: only {len(_kept)} foods would "
                          f"remain (need >= {PREFILTER_MIN_POOL}).")
        except Exception as _e:
            print(f"  (NOVA filter skipped: {type(_e).__name__}: {_e})")

    if PREFILTER_CONDIMENTS:
        try:
            _sc = "Food_Subgroup"
            _sgs = (pool[_sc].astype(str) if _sc in pool.columns
                    else pd.Series([""] * len(pool), index=pool.index))
            _cond = pd.Series(
                [nc.is_condiment(a, b) for a, b in
                 zip(pool[desc_col].astype(str), _sgs)], index=pool.index)
            if _cond.any():
                _kept = pool[~_cond]
                print(f"\n  CONDIMENT FILTER: removing {int(_cond.sum())} "
                      f"seasoning/garnish row(s) from the candidate pool.")
                for _nm in pool.loc[_cond, desc_col].head(6):
                    print(f"    {str(_nm)[:66]}")
                if len(_kept) >= max(PREFILTER_MIN_POOL, 5):
                    pool = _kept
        except Exception as _e:
            print(f"  (condiment filter skipped: {type(_e).__name__}: {_e})")

    if PREFILTER_POOL_BY_FLAGS and hasattr(nc, "_classify_flag"):
      try:
        _flags = pool[desc_col].astype(str).map(lambda n: nc._classify_flag(n))
        _cat = _flags.map(lambda t: t[0])
        _drop = _cat.isin(PREFILTER_DROP_CATEGORIES)
        if _drop.any():
            _by_key: Dict[str, int] = {}
            for _c, _k, _ in _flags[_drop]:
                _by_key[f"{_c}/{_k}"] = _by_key.get(f"{_c}/{_k}", 0) + 1
            print(f"\n  PRE-FILTER: removing {int(_drop.sum())} food(s) from the "
                  f"candidate pool before optimization.")
            for _k in sorted(_by_key, key=lambda z: -_by_key[z])[:12]:
                print(f"    {_by_key[_k]:>5}  {_k}")
            print("    These are the foods PART S would otherwise have had to")
            print("    substitute AFTER the fact. Removing them here is why the")
            print("    adjustments log should now be short.")
            _kept = pool[~_drop]
            if len(_kept) >= max(PREFILTER_MIN_POOL, 5):
                pool = _kept
            else:
                print(f"    NOT APPLIED: only {len(_kept)} foods would remain "
                      f"(need >= {PREFILTER_MIN_POOL}). Keeping the full pool "
                      f"and leaving the repairs to PART S.")
      except Exception as _e:
        print(f"  (flag pre-filter skipped: {type(_e).__name__}: {_e})")

    cand_idx = np.array([df.index.get_loc(ix) for ix in pool.index])
    if len(cand_idx) < 5:
        print(f"\nOnly {len(cand_idx)} candidate foods; need >= 5. Widen "
              f"the selection.")
        return

    print(f"\nCandidate foods: {len(cand_idx)}")
    cfg = OptConfig()
    cfg.on_glp1_or_weightloss_drug = person.on_glp1_or_weightloss_drug
    cfg.checkpoint_run_id = _checkpoint_run_id
    print(f"  Detected physical cores: {_detect_physical_cores()}  "
          f"-> n_parallel = {cfg.n_parallel} worker process(es) "
          f"(BLAS threads per process are pinned to 1; see top of file)")
    grid_in = input("Serving grid in grams (e.g. 25)  [Enter = 5]: ").strip()
    cfg.serving_grid_g = float(grid_in) if grid_in else 5.0
    fm = FoodModel(df=df, cand_idx=cand_idx, person=person, cfg=cfg)
    gather_bounds(fm)

    q = input(f"\n[Enter] research run (n_gen={cfg.n_gen}, seeds={cfg.n_seeds}; "
              f"research grade, slow)   [2] quick trial (n_gen=80, seeds=2): ").strip()
    if q == "2":
        cfg.n_gen, cfg.n_seeds = 80, 2
        print("  -> quick trial mode.")
    else:
        print(f"  -> research-grade run (n_gen={cfg.n_gen}, seeds={cfg.n_seeds}).")

    print(f"\nRunning NSGA-III: pop={cfg.pop_size or cfg.n_ref_points}, "
          f"n_gen={cfg.n_gen}, seeds={cfg.n_seeds}, "
          f"objectives={n_objectives(cfg)}, hard ULs={len(fm.ul_list)}, "
          f"soft minimums={len(fm.soft_list)} ...")
    front_X, front_obj, hv = run_nsga3(fm, cfg)
    report(fm, cfg, front_X, front_obj, hv)

    if pool_choice != "2":
        run_post_optimization_rebuild(fm, cfg, front_X, front_obj,
                                      gemini_api_key=rebuild_gemini_key)

    import os
    outdir = os.path.abspath(os.getcwd())
    print(f"\nAll output files saved in: {outdir}")
    for f in (cfg.front_csv, cfg.plan_csv, cfg.pcp_png, cfg.conv_png, cfg.meal_split_csv):
        full = os.path.join(outdir, f)
        print(f"  {'[OK]' if os.path.exists(full) else '[missing]'} {f}")

    if input("\nAlso run sensitivity analysis of the score equations "
             "(perturb K targets & AHP weights)? [y/N]: ").strip().lower() == "y":
        rec = pick_recommended(front_obj, [1] * n_objectives(cfg))
        sensitivity_analysis(fm, cfg, front_X[rec])

    reproducibility_report(cfg)

    if input("\nAlso sweep the crossover/mutation settings "
             "(short runs, compares sbx_eta/pm_eta)? [y/N]: ").strip().lower() == "y":
        sweep_operator_config(fm, cfg)

    globals()["LAST_FM"], globals()["LAST_CFG"] = fm, cfg
    globals()["LAST_FRONT_X"], globals()["LAST_FRONT_OBJ"] = front_X, front_obj
    return fm, cfg

