def _name_level_pair(na, nb):
    """Name-level override (classic dish or avoidance), or None.

    Identical control flow to PART 2F. The only change is that both names
    pass through `_f2_normalise` first, so USDA structural tokens
    ("meat only", "large or small curd", "coconut meat") cannot be read as
    food identities.
    """
    a, b = _f2_normalise(na), _f2_normalise(nb)
    for ra, rb, sc, why, trad in _F_AVOID_C:
        if trad and not HONOUR_TRADITIONAL_AVOIDANCE:
            continue
        if (ra.search(a) and rb.search(b)) or (ra.search(b) and rb.search(a)):
            return sc, why
    for ra, rb, sc, why in _F_CLASSIC_C:
        if (ra.search(a) and rb.search(b)) or (ra.search(b) and rb.search(a)):
            return sc, why
    return None

_F_BREAKFAST_UP = set(_F_BREAKFAST_UP) | _F_PULSE
_F_SNACK_UP = set(_F_SNACK_UP) | _F_PULSE

