DEFAULT_MIN_SERVING_G = 20.0
for _s in list(SUBGROUP_MEAL_ROLE):
    if " + " in _s:
        MIN_SERVING_G.setdefault(_s, 80)

def apply_minimum_servings(fm, verbose=True):
    """Set fm.min_serving_x (in 100 g units) from MIN_SERVING_G.

    Clamped to fm.xu so a floor can never exceed a food's own ceiling --
    otherwise a food with a tight per-food cap (amaranth seed at 25 g)
    would become unusable.
    """
    if not hasattr(fm, "xu"):
        return fm
    subs = [str(s) for s in fm.subgroup_arr]
    floor = np.array([MIN_SERVING_G.get(s, DEFAULT_MIN_SERVING_G)
                      for s in subs], dtype=float) / 100.0
    fm.min_serving_x = np.minimum(floor, fm.xu)
    if verbose:
        n_raised = int((fm.min_serving_x > 0.10 + 1e-9).sum())
        print(f"\n  Minimum servings set for {len(subs)} foods "
              f"({n_raised} above the old flat 10 g floor).")
    return fm

