def detect_pool_locale(df: Any, desc_col: str = "description") -> str:
    """Guess whether this pool is US or Indian from how its foods are named.

    Cheap and boring on purpose: count naming markers. Getting it wrong in
    either direction is visible immediately in the exclusion report, which is
    printed, so an operator can override with POOL_LOCALE rather than having
    to debug a silent misclassification.
    """
    try:
        if desc_col not in df.columns:
            return "IN"
        names = df[desc_col].astype(str).str.lower()
        us = sum(int(names.str.contains(p, regex=True, na=False).sum())
                 for p in _US_POOL_MARKERS)
        ind = sum(int(names.str.contains(p, regex=True, na=False).sum())
                  for p in _IN_POOL_MARKERS)
        return "US" if us > ind else "IN"
    except Exception:
        return "IN"

