def _slot_allows(sg, meal, role):
    """True if subgroup `sg` may occupy this (meal, role) cell."""
    allowed = MEAL_ROLE_SUBGROUP_FILTER.get((meal, role))
    return allowed is None or sg in allowed

ROLE_MEAL_SLOTS = {
    role: [m for m in MEAL_SLOTS if role in MEAL_REQUIRED_ROLES[m]]
    for role in MEAL_ROLE_COLUMNS
}

def _remap_meal_roles():
    """Rename the 'Whole Grain' role to 'Carbs' and widen its membership."""
    for sg, roles in list(SUBGROUP_MEAL_ROLE.items()):
        SUBGROUP_MEAL_ROLE[sg] = [CARB_ROLE if r == "Whole Grain" else r
                                  for r in roles]

    if "Starchy Roots & Tubers" in SUBGROUP_MEAL_ROLE:
        SUBGROUP_MEAL_ROLE["Starchy Roots & Tubers"] = [CARB_ROLE]

    for sub in list(SUBGROUP_MEAL_ROLE):
        if sub.endswith(" + Grain"):
            SUBGROUP_MEAL_ROLE[sub] = ["Protein", CARB_ROLE]

    if INDIAN_EXT_CONFIG.get("refined_grains_as_carbs"):
        SUBGROUP_MEAL_ROLE["Refined Grains"] = [CARB_ROLE]

INDIAN_EXT_CONFIG.setdefault("refined_grains_as_carbs", True)
_remap_meal_roles()

