def build_fndds_pool(paths=None, verbose=True):
    """Assemble the FNDDS dish pool in this optimizer's column schema.

    Returns a DataFrame carrying 'description', 'Food_Subgroup',
    'Serving_g', every nutrient FNDDS publishes renamed to the schema
    names, and the WWEIA category kept for reporting.
    """
    paths = paths or FNDDS_PATHS
    if not paths:
        raise ValueError("Call prompt_fndds_paths() first.")

    foods = _read_fndds(paths["foods"],
                        ["Food code", "Main food description",
                         "WWEIA Category number"])
    nut = _read_fndds(paths["nutrients"],
                      ["Food code", "Energy (kcal)"])
    ing = _read_fndds(paths["ingredients"],
                      ["Food code", "Main food description",
                       "Ingredient description", "Ingredient weight (g)"])
    por = _read_fndds(paths["portions"],
                      ["Food code", "Portion description",
                       "Portion weight (g)"])

    flow = []

    def _stage(name, n, note=""):
        flow.append((name, int(n), note))

    pool = foods.drop_duplicates("Food code").copy()
    pool["description"] = pool["Main food description"].astype(str)
    _stage("Foods and Beverages (master list)", len(pool),
           "every food code USDA publishes")

    nut = nut.rename(columns=FNDDS_COLUMN_MAP)
    nut = nut.drop(columns=[c for c in ("Main food description",
                                        "WWEIA Category number",
                                        "WWEIA Category description")
                            if c in nut.columns])
    pool = pool.merge(nut, on="Food code", how="left")
    _stage("+ Nutrient Values joined", len(pool),
           f"{len([c for c in FNDDS_COLUMN_MAP.values() if c in pool.columns])}"
           " nutrients attached")

    energy_col = "Energy (KCAL)"
    if energy_col in pool.columns:
        orphans = pool[pd.to_numeric(pool[energy_col],
                                     errors="coerce").isna()]
        if len(orphans):
            if verbose:
                print(f"\n  {len(orphans)} food code(s) in Foods and "
                      "Beverages have NO nutrient row")
                print("  and are dropped (cannot be scored):")
                for r in orphans.head(5).itertuples():
                    print(f"      {int(r._1)}  {str(r.description)[:50]}")
            pool = pool[~pool.index.isin(orphans.index)].reset_index(drop=True)
            _stage("- dropped: no nutrient row", len(pool),
                   ", ".join(str(d)[:28] for d in
                             orphans["description"].head(3)))

    por = por[pd.to_numeric(por["Portion weight (g)"],
                            errors="coerce").fillna(0) > 0]
    serv = por.groupby("Food code")["Portion weight (g)"].median()
    pool[SERVING_G_COL] = pool["Food code"].map(serv)
    n_noserv = int(pool[SERVING_G_COL].isna().sum())
    pool[SERVING_G_COL] = pool[SERVING_G_COL].fillna(100.0)

    pool["food_code"] = pool["Food code"]
    pool["orig_fdc_id"] = pool["Food code"]
    pool["source_file"] = "FNDDS 2021-2023"
    if "Energy (KCAL)" in pool.columns:
        pool["Energy (Atwater Specific Factors) (KCAL)"] = pool["Energy (KCAL)"]

    _stage("+ Portions and Weights joined", len(pool),
           f"serving sizes; {n_noserv} defaulted to 100 g")

    cls = classify_dishes_by_ingredients(ing, verbose=verbose)
    pool = pool.merge(cls[["Food code", "Food_Subgroup", "anchor_fraction",
                           "resolved_mass"]], on="Food code", how="left")
    pool["Food_Subgroup"] = pool["Food_Subgroup"].fillna("Unknown")

    _stage("+ FNDDS Ingredients joined", len(pool),
           "classified by recipe, not by name")
    derive_composite_role_fractions(cls, verbose=verbose)
    n_before = len(pool)
    pool = apply_dish_pool_filters(pool, verbose=verbose)
    pool = apply_clinical_pool_filters(pool, verbose=verbose)
    _stage("- dish pool filters", len(pool),
           f"{n_before - len(pool)} removed: infant, raw, niche, cat 9999")

    if verbose:
        print(BOLD + "\n--- HOW THE POOL WAS BUILT ---" + RESET)
        print("  Foods and Beverages is the MASTER list. Every other workbook")
        print("  is joined onto it by food code; Ingredient Nutrient Values")
        print("  attaches to the recipes by ingredient code, one level down.")
        print()
        prev = None
        for name, n, note in flow:
            delta = "" if prev is None else f"{n - prev:+d}"
            print(f"    {name:<38}{n:>7}{delta:>8}")
            if note:
                print(f"        {note}")
            prev = n
        print(f"\n    {'INTO NSGA-III':<38}{len(pool):>7}")
        mapped = [c for c in FNDDS_COLUMN_MAP.values() if c in pool.columns]
        print(f"\n  Pool built: {len(pool)} dishes, {len(mapped)} nutrients "
              "mapped to the schema.")
        print("  Serving weights from measured household portions; "
              f"{n_noserv} dishes had\n  none and default to 100 g.")
        print("  ABSENT from FNDDS and therefore scoring as zero:")
        print("    " + ", ".join(FNDDS_ABSENT_NUTRIENTS[:3]) + ",")
        print("    " + ", ".join(FNDDS_ABSENT_NUTRIENTS[3:]) + ".")
        print("    Requested from FoodData Central except IODINE, which is "
              "excluded\n    entirely (PART L, EXCLUDED_NUTRIENTS). Leucine, "
              "trans fat, added sugar\n    and manganese are well covered "
              "there; molybdenum and biotin are not,\n    and anything "
              f"below {MIN_NUTRIENT_COVERAGE:.0%} pool coverage is reported "
              "as UNKNOWN rather\n    than scored as a deficiency.")
    return pool

def load_fndds_and_prepare(folder=None, api_key=None, ask_key=True,
                           verbose=True):
    """One call: paths -> API key -> dish mode -> pool. Entry point for a run.

    The key prompt comes BEFORE the pool build so a rejected key is caught
    in two seconds rather than after several minutes of Excel parsing.
    Pass ask_key=False for an unattended run.
    """
    prompt_fndds_paths(folder=folder, verbose=verbose)
    if ask_key and not (api_key or USDA_FDC_API_KEY):
        prompt_usda_api_key(verbose=verbose)
    enable_dish_mode(verbose=verbose)
    pool = build_fndds_pool(verbose=verbose)
    return fetch_missing_nutrients_via_fdc(pool, api_key=api_key,
                                           verbose=verbose)

