MAX_SINGLE_FOOD_RDA_SHARE = 1.0

def single_food_concentration_violation(fm, x):
    """Excess where one food supplies too much of one micronutrient floor.

    Returned in units of "floors exceeded" so it is commensurate with the
    other PART M terms. Vectorised over foods per nutrient; the loop is over
    the ~25 soft floors, not the 5,000 foods.
    """
    x = np.asarray(x, dtype=float)
    macro = getattr(fm, "macro_cols", set())
    v = 0.0
    for col, floor in fm.soft_list:
        if not floor or floor <= 0 or col in macro:
            continue
        contrib = x * fm.col_arr[col]
        cap = MAX_SINGLE_FOOD_RDA_SHARE * floor
        over = contrib - cap
        over = over[over > 0]
        if over.size:
            v += float(over.sum() / floor)
    return v

