def _identity_arr(fm):
    """One food-identity token per candidate, cached. '' means unmatched
    and therefore never a duplicate."""
    a = getattr(fm, "_ident_arr", None)
    if a is None:
        d = fm.df.iloc[fm.cand_idx]["description"].astype(str).str.lower()
        out = []
        for s in d:
            hit = ""
            for kw in FOOD_IDENTITY_KEYWORDS:
                if kw in s:
                    hit = kw
                    break
            out.append(hit)
        a = np.array(out, dtype=object)
        fm._ident_arr = a
    return a

MAX_SODIUM_MG_PER_DAY = 2300.0
MIN_SODIUM_MG_PER_DAY = 1500.0

SODIUM_HARD_CONSTRAINT = True
SODIUM_SOFT_WEIGHT = 1.0

SODIUM_TARGET_MG_PER_DAY = 1800.0

def _sodium_col_name(fm):
    """The sodium column in this FoodModel, or None. Cached on the model."""
    got = getattr(fm, "_na_col_cache", "unset")
    if got != "unset":
        return got
    col = None
    for cand in globals().get("SODIUM_COL_CANDIDATES", ()) or ():
        if cand in getattr(fm, "col_arr", {}):
            col = cand
            break
    try:
        fm._na_col_cache = col
    except Exception:
        pass
    return col

def sodium_violation(fm, x):
    """Sodium outside the AI-CDRR band, in units of 'one whole CDRR'.

    Two-sided on purpose. Sodium is physiologically essential, so a ceiling
    alone would let a calorie-restricted optimizer drive it toward zero.
    """
    na = _sodium_arr(fm)
    if na is None:
        return 0.0
    na_mg = float(np.dot(np.asarray(x, float), na))
    if na_mg > MAX_SODIUM_MG_PER_DAY:
        return (na_mg - MAX_SODIUM_MG_PER_DAY) / MAX_SODIUM_MG_PER_DAY
    if na_mg < MIN_SODIUM_MG_PER_DAY:
        return (MIN_SODIUM_MG_PER_DAY - na_mg) / MIN_SODIUM_MG_PER_DAY
    return 0.0
SODIUM_COL_CANDIDATES = ["Sodium, Na (MG)", "Sodium (MG)", "Sodium (mg)"]

def _sodium_arr(fm):
    """Sodium per candidate per 100 g unit, cached. None if unavailable.

    The cache sentinel is a missing ATTRIBUTE, not a sentinel VALUE: an
    earlier version used the string "unset" and compared it with `==`,
    which raises once the cache holds a numpy array ("truth value of an
    array with more than one element is ambiguous").
    """
    if not hasattr(fm, "_na_arr"):
        col = _resolve_col(fm.df, SODIUM_COL_CANDIDATES)
        fm._na_arr = (np.nan_to_num(
            pd.to_numeric(fm.df.iloc[fm.cand_idx][col],
                          errors="coerce").to_numpy(float))
            if col else None)
    return fm._na_arr

MIN_DISH_PORTION_G = 25.0

RAW_DISH_PATTERNS = (r"\braw\b", r"\bsashimi\b", r"\bceviche\b",
                     r"\btartare\b", r"\blomi\b", r"\bunheated\b")
RAW_ALLOWED_CATEGORIES = {6402, 6404, 6406, 6407, 6408, 6410, 6412, 6413,
                          6414, 6416, 6418, 6420, 6422, 6430, 6432, 6489,
                          6802, 6804, 6806, 6808, 6814, 6816}

_WWEIA_NUM_COL = "WWEIA Category number"

def apply_dish_pool_filters(df, cooked_only=True, verbose=True):
    """Drop dishes that should not be in an adult day pool at all.

    Runs BEFORE the optimizer, so excluded dishes are never decision
    variables. Returns the filtered frame.
    """
    if _WWEIA_NUM_COL not in df.columns:
        if verbose:
            print("\n  ! No WWEIA category column; dish filters skipped.")
        return df
    n0 = len(df)
    cat = pd.to_numeric(df[_WWEIA_NUM_COL], errors="coerce")

    desc_l = df["description"].astype(str).str.lower()
    drop_infant = cat.isin(WWEIA_EXCLUDE_INFANT)
    drop_free = cat.isin(WWEIA_EXCLUDE_FREE_MASS)
    drop_unspec = (cat.isin(WWEIA_EXCLUDE_UNSPECIFIED)
                   | desc_l.str.contains("as ingredient", na=False))
    drop_niche = desc_l.str.contains("|".join(NICHE_SPECIES_PATTERNS),
                                     regex=True, na=False)
    keep = ~(drop_infant | drop_free | drop_unspec | drop_niche)

    drop_raw = pd.Series(False, index=df.index)
    if cooked_only:
        desc = df["description"].astype(str).str.lower()
        pat = "|".join(RAW_DISH_PATTERNS)
        drop_raw = desc.str.contains(pat, regex=True, na=False) & \
            ~cat.isin(RAW_ALLOWED_CATEGORIES)
        keep &= ~drop_raw

    out = df[keep].reset_index(drop=True)
    if verbose:
        print(f"\n  Dish pool filters:")
        print(f"    infant/toddler foods removed      {int(drop_infant.sum()):>5}")
        print(f"    water & diet drinks removed       {int(drop_free.sum()):>5}")
        print(f"    unspecified / 'as ingredient'     {int(drop_unspec.sum()):>5}"
              "   (cat 9999: no buyable food)")
        print(f"    niche species removed             {int(drop_niche.sum()):>5}"
              "   (carp, mullet, game meats)")
        if cooked_only:
            print(f"    raw/uncooked dishes removed       {int(drop_raw.sum()):>5}"
                  "   (fresh produce categories exempt)")
        print(f"    pool: {n0} -> {len(out)} dishes")
    return out

UNITS_HINT = {"iodine": "UG", "manganese": "MG", "molybdenum": "UG",
              "biotin": "UG", "pantothenic_acid": "MG", "leucine": "G",
              "chromium": "UG", "fluoride": "MG"}

def report_unmeasurable_nutrients(df, verbose=True):
    """List every nutrient the optimizer scores that this dataset cannot
    supply, and say so out loud.

    Nutrients whose column does not resolve never enter fm.soft_list, so
    they simply VANISH from the nutrition printout. Earlier runs on the
    Indian pool listed iodine, manganese, molybdenum and biotin; the FNDDS
    runs did not, and the difference looked like a formatting change rather
    than four nutrients no longer being tracked at all. A silent
    disappearance is the dangerous kind: it reads as "no problem found"
    when it means "not looked at". Iodine matters most here -- it has been
    a recurring shortfall in this pipeline and FNDDS cannot measure it.

    Returns the list of unresolved nutrient keys.
    """
    missing = []
    for key, cands in COL_CANDIDATES.items():
        if _resolve_col(df, cands) is None:
            missing.append(key)
    if verbose and missing:
        print(BOLD + "\n--- NUTRIENTS NOT PRESENT IN THIS DATASET ---" + RESET)
        print("  These are scored by the optimizer but ABSENT from the food")
        print("  table, so they contribute ZERO to every plan and do not")
        print("  appear in the panel above. Their status is UNKNOWN, not ok:")
        for k in sorted(missing):
            print(f"    {k:<24} ({UNITS_HINT.get(k, '?')})")
        if "iodine" in missing:
            print("\n  ! IODINE cannot be verified from this dataset. It has")
            print("    been a recurring shortfall in this pipeline, so a plan")
            print("    built here must NOT be read as iodine-adequate.")
        fdc_keys = {"leucine": "Leucine (G)",
                    "trans": "Fatty acids, total trans (G)",
                    "added_sugar": "Sugars, added (G)",
                    "iodine": "Iodine, I (UG)",
                    "manganese": "Manganese, Mn (MG)",
                    "molybdenum": "Molybdenum, Mo (UG)",
                    "pantothenic": "Pantothenic acid (MG)",
                    "biotin": "Biotin (UG)"}
        sparse = {"iodine", "molybdenum", "biotin"}
        never = {"complex_carbs", "gi_value", "gi_category"}
        good = [k for k in missing if k in fdc_keys and k not in sparse]
        thin = [k for k in missing if k in sparse]
        derived = [k for k in missing if k in never]
        if good:
            print("\n  FETCHABLE from FoodData Central, good coverage: "
                  + ", ".join(sorted(good)))
        if thin:
            print("  REQUESTED from FoodData Central but SPARSELY MEASURED "
                  "there: "
                  + ", ".join(sorted(thin)))
            print("    USDA has never run a broad analysis for these, so a "
                  "successful\n    fetch may still return blanks. Check "
                  "fdc_resolved_mass.")
        if derived:
            print("  NOT IN ANY FOOD DATABASE: " + ", ".join(sorted(derived)))
            print("    complex_carbs is derived from other columns; glycemic "
                  "index is not\n    a USDA nutrient at all and would need a "
                  "separate GI table.")
        if not USDA_FDC_API_KEY:
            print("\n  No API key set, so none of the fetchable ones were "
                  "requested.\n  Run prompt_usda_api_key(), then "
                  "fetch_missing_nutrients_via_fdc().")
    elif verbose:
        print("\n  All scored nutrients are present in this dataset.")
    return missing

def _wweia_arr(fm):
    """WWEIA category number per candidate, cached on fm."""
    a = getattr(fm, "_wweia_arr", None)
    if a is None:
        a = pd.to_numeric(fm.df.iloc[fm.cand_idx][_WWEIA_NUM_COL],
                          errors="coerce").fillna(-1).astype(int).to_numpy()
        fm._wweia_arr = a
    return a

def _name_stem_arr(fm):
    """First NAME_STEM_WORDS words of each candidate's description, cached.

    The stem is what makes two near-identical products collide: both
    strawberry milks reduce to "strawberry milk" even though FNDDS files
    them under different categories.
    """
    a = getattr(fm, "_stem_arr", None)
    if a is None:
        d = fm.df.iloc[fm.cand_idx]["description"].astype(str).str.lower()
        d = d.str.replace(r"[^a-z0-9 ]", " ", regex=True)
        a = (d.str.split().str[:NAME_STEM_WORDS].str.join(" ")).to_numpy()
        fm._stem_arr = a
    return a

def _serving_g_arr(fm):
    """Grams per serving per candidate, cached on fm."""
    a = getattr(fm, "_serv_arr", None)
    if a is None:
        a = pd.to_numeric(fm.df.iloc[fm.cand_idx][SERVING_G_COL],
                          errors="coerce").fillna(100.0).to_numpy()
        fm._serv_arr = a
    return a

def wweia_constraint_violation(fm, x):
    """Total constraint violation from the WWEIA rules, in servings.

    Returns 0.0 when the day satisfies all of them. Positive values are
    summed excesses and shortfalls, so the constraint machinery can treat
    this the same way it treats subgroup_violation.

    Four rules, all evaluated on the day as a whole rather than food by
    food -- which is the whole point, since the tea problem was three
    separate foods each individually reasonable.
    """
    x = np.asarray(x, dtype=float)
    cats = _wweia_arr(fm)
    serv_g = _serving_g_arr(fm)
    grams = x * 100.0
    servings = np.divide(grams, serv_g, out=np.zeros_like(grams),
                         where=serv_g > 0)
    v = 0.0

    active = grams > 1e-9

    for cat_no, cap in WWEIA_MAX_SERVINGS.items():
        got = float(servings[cats == cat_no].sum())
        if got > cap:
            v += got - cap

    for cat_no, cap_g in WWEIA_MAX_GRAMS.items():
        got = float(grams[cats == cat_no].sum())
        if got > cap_g:
            v += (got - cap_g) / 100.0

    cereal = float(servings[np.isin(cats, list(WWEIA_CEREAL_GROUP))].sum())
    if cereal > MAX_CEREAL_SERVINGS_PER_DAY:
        v += cereal - MAX_CEREAL_SERVINGS_PER_DAY

    lo_v, hi_v = WWEIA_VEGETABLE_RANGE
    veg_g = float(grams[(cats >= lo_v) & (cats <= hi_v)].sum())
    if veg_g > MAX_VEGETABLE_G_PER_DAY:
        v += (veg_g - MAX_VEGETABLE_G_PER_DAY) / 100.0
    total_g = float(grams.sum())
    if total_g > MAX_TOTAL_FOOD_G_PER_DAY:
        v += (total_g - MAX_TOTAL_FOOD_G_PER_DAY) / 100.0

    v += single_food_concentration_violation(fm, x)
    v += clinical_violation(fm, x)
    v += csv_subgroup_cap_violation(fm, x)
    if getattr(fm, "_has_csv_rows", False):
        v += hybrid_slot_violation(fm, x)
        v += processing_violation(fm, x)

    if SODIUM_HARD_CONSTRAINT:
        v += sodium_violation(fm, x)

    if active.any():
        cnt = {}
        for c in cats[active]:
            cnt[c] = cnt.get(c, 0) + 1
        v += float(sum(max(0, n - MAX_DISHES_PER_CATEGORY)
                       for n in cnt.values()))
        stems = _name_stem_arr(fm)
        scnt = {}
        for s in stems[active]:
            scnt[s] = scnt.get(s, 0) + 1
        v += float(sum(max(0, n - MAX_DISHES_PER_NAME_STEM)
                       for n in scnt.values()))
        idents = _identity_arr(fm)
        icnt = {}
        for s in idents[active]:
            if s:
                icnt[s] = icnt.get(s, 0) + 1
        v += float(sum(max(0, n - MAX_DISHES_PER_FOOD_IDENTITY)
                       for n in icnt.values()))

    unit = np.isin(cats, list(WWEIA_UNITARY)) & (grams > 1e-9)
    if unit.any():
        s = servings[unit]
        v += float(np.where(s < 1.0, 1.0 - s,
                            np.abs(s - np.round(s))).sum())

    main_mask = np.isin(cats, list(WWEIA_MAIN_DISH))
    n_mains = int((grams[main_mask] > MIN_DISH_PORTION_G).sum())
    if n_mains < MIN_MAIN_DISHES_PER_DAY:
        v += float(MIN_MAIN_DISHES_PER_DAY - n_mains)

    staple = float(servings[np.isin(cats, list(WWEIA_STAPLE))].sum())
    if staple < MIN_STAPLE_SERVINGS_PER_DAY:
        v += MIN_STAPLE_SERVINGS_PER_DAY - staple

    token = (grams > 1e-9) & (grams < MIN_DISH_PORTION_G)
    v += float(((MIN_DISH_PORTION_G - grams[token]) / MIN_DISH_PORTION_G).sum())
    return v

def report_wweia_status(fm, x, verbose=True):
    """Print which WWEIA rules the recommended plan meets, and which it
    does not. Called from report() so a violated plan says so on its face
    rather than being read as clean."""
    x = np.asarray(x, dtype=float)
    cats, serv_g = _wweia_arr(fm), _serving_g_arr(fm)
    grams = x * 100.0
    servings = np.divide(grams, serv_g, out=np.zeros_like(grams),
                         where=serv_g > 0)
    lines = []
    for cat_no, cap in sorted(WWEIA_MAX_SERVINGS.items()):
        got = float(servings[cats == cat_no].sum())
        if got > 1e-6:
            n = int((grams[cats == cat_no] > 1e-9).sum())
            ok = got <= cap + 1e-6
            lines.append(f"    cat {cat_no}: {got:.2f} servings across {n} "
                         f"dish(es), cap {cap:.1f}  {'ok' if ok else 'OVER'}")
    for cat_no, cap_g in sorted(WWEIA_MAX_GRAMS.items()):
        got_g = float(grams[cats == cat_no].sum())
        if got_g > 1e-6:
            ok = got_g <= cap_g + 1e-6
            lines.append(f"    cat {cat_no}: {got_g:.0f} g, cap {cap_g:.0f} g"
                         f"  {'ok' if ok else 'OVER'}")
    main_mask = np.isin(cats, list(WWEIA_MAIN_DISH))
    n_mains = int((grams[main_mask] > MIN_DISH_PORTION_G).sum())
    staple = float(servings[np.isin(cats, list(WWEIA_STAPLE))].sum())
    token = int(((grams > 1e-9) & (grams < MIN_DISH_PORTION_G)).sum())
    cereal = float(servings[np.isin(cats, list(WWEIA_CEREAL_GROUP))].sum())
    lo_v, hi_v = WWEIA_VEGETABLE_RANGE
    veg_g = float(grams[(cats >= lo_v) & (cats <= hi_v)].sum())
    total_g = float(grams.sum())
    act = grams > 1e-9
    stems = _name_stem_arr(fm)
    dup_cat = sum(max(0, list(cats[act]).count(c) - MAX_DISHES_PER_CATEGORY)
                  for c in set(cats[act]))
    dup_stem = sum(max(0, list(stems[act]).count(s) - MAX_DISHES_PER_NAME_STEM)
                   for s in set(stems[act]))
    if verbose:
        print("\n  WWEIA plausibility check:")
        for ln in lines:
            print(ln)
        print(f"    cereal servings (all cereal cats): {cereal:.2f} "
              f"(cap {MAX_CEREAL_SERVINGS_PER_DAY:.1f})"
              f"  {'ok' if cereal <= MAX_CEREAL_SERVINGS_PER_DAY + 1e-6 else 'OVER'}")
        print(f"    vegetables: {veg_g:.0f} g "
              f"(cap {MAX_VEGETABLE_G_PER_DAY:.0f})"
              f"  {'ok' if veg_g <= MAX_VEGETABLE_G_PER_DAY + 1e-6 else 'OVER'}")
        print(f"    total food mass: {total_g:.0f} g "
              f"(cap {MAX_TOTAL_FOOD_G_PER_DAY:.0f})"
              f"  {'ok' if total_g <= MAX_TOTAL_FOOD_G_PER_DAY + 1e-6 else 'OVER'}")
        idents = _identity_arr(fm)
        dup_id = sum(max(0, list(idents[act]).count(s)
                         - MAX_DISHES_PER_FOOD_IDENTITY)
                     for s in set(idents[act]) if s)
        print(f"    duplicate dishes: {dup_cat} by category, {dup_stem} by "
              f"name, {dup_id} by food"
              f"  {'ok' if dup_cat + dup_stem + dup_id == 0 else 'DUPLICATES'}")
        if dup_id:
            for s in sorted(set(idents[act])):
                if s and list(idents[act]).count(s) > 1:
                    names = [str(fm.names[j])[:34] for j in np.where(act)[0]
                             if idents[j] == s]
                    print(f"        '{s}' x{len(names)}: " + "; ".join(names))
        u = np.isin(cats, list(WWEIA_UNITARY)) & (grams > 1e-9)
        frac = [(str(fm.names[j])[:34], servings[j]) for j in np.where(u)[0]
                if abs(servings[j] - round(servings[j])) > 1e-6
                or servings[j] < 1.0]
        print(f"    unitary dishes at part-servings: {len(frac)}"
              f"  {'ok' if not frac else 'FRACTIONAL UNITS'}")
        for nm, sv in frac:
            print(f"        {nm:<36}{sv:.2f} servings")
        conc = single_food_concentration_violation(fm, x)
        print(f"    single-food micro concentration: {conc:.2f}"
              f"  {'ok' if conc <= 1e-6 else 'ONE FOOD DOMINATES A NUTRIENT'}")
        if conc > 1e-6:
            macro = getattr(fm, "macro_cols", set())
            for col, floor in fm.soft_list:
                if not floor or floor <= 0 or col in macro:
                    continue
                contrib = x * fm.col_arr[col]
                j = int(np.argmax(contrib))
                if contrib[j] > MAX_SINGLE_FOOD_RDA_SHARE * floor:
                    print(f"        {col[:30]:<32} "
                          f"{100*contrib[j]/floor:5.0f}% of floor from "
                          f"{str(fm.names[j])[:30]}")
        print(f"    main dishes: {n_mains} (need {MIN_MAIN_DISHES_PER_DAY})"
              f"  {'ok' if n_mains >= MIN_MAIN_DISHES_PER_DAY else 'SHORT'}")
        print(f"    staple servings: {staple:.2f} "
              f"(need {MIN_STAPLE_SERVINGS_PER_DAY:.1f})"
              f"  {'ok' if staple >= MIN_STAPLE_SERVINGS_PER_DAY else 'SHORT'}")
        print(f"    portions under {MIN_DISH_PORTION_G:.0f} g: {token}"
              f"  {'ok' if token == 0 else 'TOKEN PORTIONS'}")
        na = _sodium_arr(fm)
        if na is not None:
            na_mg = float(np.dot(x, na))
            verdict = ("ok" if MIN_SODIUM_MG_PER_DAY <= na_mg
                       <= MAX_SODIUM_MG_PER_DAY
                       else ("OVER CDRR" if na_mg > MAX_SODIUM_MG_PER_DAY
                             else "BELOW AI"))
            mode = "hard" if SODIUM_HARD_CONSTRAINT else "soft"
            print(f"    sodium: {na_mg:.0f} mg "
                  f"(AI {MIN_SODIUM_MG_PER_DAY:.0f} - "
                  f"CDRR {MAX_SODIUM_MG_PER_DAY:.0f})  {verdict}"
                  f"   [{mode} constraint]")
            if not SODIUM_HARD_CONSTRAINT and na_mg > MAX_SODIUM_MG_PER_DAY:
                print("        Soft, so the plan is still FEASIBLE while "
                      "exceeding the CDRR.\n        Report the figure; do "
                      "not read 'feasible' as 'within guidance'.")
            if na_mg > MAX_SODIUM_MG_PER_DAY:
                order = np.argsort(-(x * na))[:3]
                for j in order:
                    if x[j] * na[j] > 1:
                        print(f"        {str(fm.names[j])[:34]:<36}"
                              f"{x[j]*na[j]:6.0f} mg")
    return {"mains": n_mains, "staple": staple, "token": token}

