APPLY_FDC_SUBSTITUTIONS = False

def propose_fdc_substitutions(paths=None, top_n=40, out_csv=None,
                              verbose=True):
    """Suggest donor ingredients for the unreachable codes, by mass.

    SUGGESTIONS ONLY. Nothing here is applied. Token similarity is weak on
    food names -- it will propose "Crackers, milk" for "Milk, NFS" -- so
    every row needs a human decision before it goes into
    FDC_INGREDIENT_SUBSTITUTIONS. The value of this function is the
    RANKING: it tells you which codes are worth the effort, because the
    mass column is what decides whether a mapping changes anything.
    """
    import re as _re
    paths = paths or FNDDS_PATHS
    ing = _read_fndds(paths["ingredients"],
                      ["Food code", "Ingredient code", "Ingredient description",
                       "Ingredient weight (g)"])
    inv = _read_fndds(paths["ing_nutrients"],
                      ["Ingredient code", "Ingredient description", "FDC ID"])
    mp = inv[["Ingredient code", "Ingredient description", "FDC ID"]].dropna()
    mp = mp.drop_duplicates("Ingredient code")
    reachable = set(mp["Ingredient code"])

    stop = {"nfs", "ns", "as", "in", "to", "part", "ingredient", "ingredients",
            "recipes", "food", "or", "and", "a", "with", "no", "not", "eaten"}

    def toks(s):
        return {t for t in _re.split(r"[^a-z0-9]+", str(s).lower())
                if t and t not in stop}

    donors = [(int(c), str(d), toks(d))
              for c, d in zip(mp["Ingredient code"],
                              mp["Ingredient description"])]
    ing["_w"] = pd.to_numeric(ing["Ingredient weight (g)"],
                              errors="coerce").fillna(0.0)
    total = float(ing["_w"].sum()) or 1.0
    miss = ing[~ing["Ingredient code"].isin(reachable)]
    rank = (miss.groupby(["Ingredient code", "Ingredient description"])["_w"]
            .sum().sort_values(ascending=False).reset_index())
    rank.columns = ["code", "desc", "mass"]

    rows = []
    for _, r in rank.head(top_n).iterrows():
        q = toks(r["desc"])
        best = (0.0, None, None)
        for c, d, t in donors:
            if not t or not q:
                continue
            s = len(q & t) / len(q | t)
            if s > best[0]:
                best = (s, c, d)
        rows.append({"code": int(r["code"]), "desc": r["desc"],
                     "pct_of_recipe_mass": round(100.0 * r["mass"] / total, 3),
                     "already_mapped": int(r["code"]) in
                     FDC_INGREDIENT_SUBSTITUTIONS,
                     "suggested_donor_code": best[1],
                     "suggested_donor": best[2],
                     "similarity": round(best[0], 2)})
    out = pd.DataFrame(rows)
    if out_csv:
        out.to_csv(out_csv, index=False)
    if verbose:
        done = out[out["already_mapped"]]["pct_of_recipe_mass"].sum()
        left = out[~out["already_mapped"]]["pct_of_recipe_mass"].sum()
        print(f"\n  Unreachable ingredient mass in the top {top_n} codes: "
              f"{done + left:.1f}% of all recipe mass")
        print(f"    already mapped in PART N: {done:.1f}%")
        print(f"    still unmapped:           {left:.1f}%")
        print("  Suggestions are NOT applied. Review, then add to "
              "FDC_INGREDIENT_SUBSTITUTIONS.")
        if out_csv:
            print(f"  Written: {out_csv}")
    return out

FDC_MATCH_THRESHOLD = 1.0
SEARCH_ABORT_AFTER = 5
FDC_SEARCH_CACHE = "fdc_search_matches.csv"
FDC_DATATYPE_RANK = {"Foundation": 0, "SR Legacy": 1, "Survey (FNDDS)": 2,
                     "Branded": 3}

def _norm_desc(s):
    """Lowercase, punctuation to spaces, collapse whitespace. Nothing else."""
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ",
                                      str(s).lower())).strip()

def _fdc_search(query, key, page_size=50, timeout=30):
    """One FDC search call. Returns [(fdcId, description, dataType), ...].

    Tries GET first and falls back to POST with a JSON body. FDC documents
    both, but which one a given deployment accepts has changed between
    releases, and a GET that 4xxs on every query looks identical to a bad
    key unless the fallback is tried. Raises the LAST error with its status
    code attached so the caller can report something diagnosable.
    """
    import json
    import urllib.error
    import urllib.parse
    import urllib.request
    last = None

    try:
        url = (f"{USDA_FDC_BASE}/foods/search?api_key={key}"
               f"&query={urllib.parse.quote(query)}"
               f"&pageSize={int(page_size)}")
        with urllib.request.urlopen(url, timeout=timeout) as r:
            payload = json.loads(r.read().decode("utf-8"))
        return _fdc_search_rows(payload)
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = re.sub(r"\s+", " ", e.read().decode("utf-8", "replace"))[:160]
        except Exception:
            pass
        last = ("GET", e.code, body)
    except Exception as e:
        last = ("GET", None, f"{type(e).__name__}: {e}")

    try:
        body_json = json.dumps({"query": query,
                                "pageSize": int(page_size)}).encode("utf-8")
        req = urllib.request.Request(
            f"{USDA_FDC_BASE}/foods/search?api_key={key}", data=body_json,
            headers={"Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(req, timeout=timeout) as r:
            payload = json.loads(r.read().decode("utf-8"))
        return _fdc_search_rows(payload)
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = re.sub(r"\s+", " ", e.read().decode("utf-8", "replace"))[:160]
        except Exception:
            pass
        last = ("POST", e.code, body)
    except Exception as e:
        last = ("POST", None, f"{type(e).__name__}: {e}")

    raise FdcSearchError(f"{last[0]} HTTP {last[1]}: {last[2]}",
                         status=last[1])

def _fdc_search_rows(payload):
    return [(f.get("fdcId"), f.get("description", ""), f.get("dataType", ""))
            for f in ((payload or {}).get("foods") or []) if f.get("fdcId")]

class FdcSearchError(RuntimeError):
    def __init__(self, msg, status=None):
        super().__init__(msg)
        self.status = status

def resolve_unreachable_by_search(paths=None, api_key=None,
                                  threshold=None, cache_csv=None,
                                  max_codes=None, verbose=True):
    """Find FDC IDs for unreachable ingredient codes by exact description.

    Returns {ingredient_code: fdc_id} for codes whose description matched a
    FoodData Central entry at or above `threshold` (default 1.0, exact).

    Results are cached, including the MISSES -- a code that has no exact
    match will never acquire one, so re-querying it every run wastes quota
    for a guaranteed negative.
    """
    key = api_key or USDA_FDC_API_KEY
    threshold = FDC_MATCH_THRESHOLD if threshold is None else threshold
    cache_csv = cache_csv or FDC_SEARCH_CACHE
    if not key:
        if verbose:
            print("\n  ! No USDA API key; exact-match resolution skipped.")
        return {}

    paths = paths or FNDDS_PATHS
    ing = _read_fndds(paths["ingredients"],
                      ["Ingredient code", "Ingredient description",
                       "Ingredient weight (g)"])
    inv = _read_fndds(paths["ing_nutrients"], ["Ingredient code", "FDC ID"])
    ing["_w"] = pd.to_numeric(ing["Ingredient weight (g)"],
                              errors="coerce").fillna(0.0)
    reachable = set(inv[["Ingredient code", "FDC ID"]].dropna()
                    ["Ingredient code"])
    miss = ing[~ing["Ingredient code"].isin(reachable)]
    rank = (miss.groupby(["Ingredient code", "Ingredient description"])["_w"]
            .sum().sort_values(ascending=False).reset_index())
    total_mass = float(ing["_w"].sum()) or 1.0

    done = {}
    if os.path.isfile(cache_csv):
        c = pd.read_csv(cache_csv)
        for r in c.itertuples():
            done[int(r.ingredient_code)] = (
                int(r.fdc_id) if pd.notna(r.fdc_id) and r.fdc_id != "" else None,
                float(r.score), str(r.matched_description))
        if verbose:
            print(f"\n  Exact-match cache: {len(done)} codes already searched "
                  f"({cache_csv}).")

    todo = [r for r in rank.itertuples() if int(r._1) not in done]
    if max_codes:
        todo = todo[:max_codes]
    if verbose:
        print(f"  Codes to search: {len(todo)} of {len(rank)} unreachable. "
              "One request each.")

    import time
    fails, first_fail, mapping_hits = 0, None, 0
    for i, r in enumerate(todo):
        code, desc = int(r._1), str(r._2)
        want = _norm_desc(desc)
        best = (None, 0.0, "")
        try:
            for fid, cand, dtype in _fdc_search(desc, key):
                if _norm_desc(cand) == want:
                    rankv = FDC_DATATYPE_RANK.get(dtype, 9)
                    if best[0] is None or rankv < best[1]:
                        best = (int(fid), float(rankv), cand)
            best = (best[0], 1.0 if best[0] is not None else 0.0, best[2])
        except Exception as e:
            fails += 1
            first_fail = first_fail or str(e)
            if fails >= SEARCH_ABORT_AFTER and not mapping_hits:
                if verbose:
                    print(f"\n    ! ABORTED after {fails} consecutive "
                          "failures. Nothing was searched.")
                    print(f"      {first_fail}")
                    print("      Every query failed the same way, so this is "
                          "the endpoint or the\n      key, not the "
                          "descriptions. Nothing was written to the cache,\n"
                          "      so fixing the cause and re-running loses "
                          "no quota.")
                return {}
            best = (None, 0.0, "")
        else:
            fails = 0
            if best[0] is not None:
                mapping_hits += 1
        done[code] = best
        if verbose and i % 25 == 0:
            print(f"    {i}/{len(todo)}   matched so far: {mapping_hits}")
        time.sleep(0.2)

    pd.DataFrame([{"ingredient_code": c, "fdc_id": v[0] if v[0] else "",
                   "score": v[1], "matched_description": v[2]}
                  for c, v in done.items()]).to_csv(cache_csv, index=False)

    mapping = {c: v[0] for c, v in done.items()
               if v[0] is not None and v[1] >= threshold}
    if verbose:
        got_mass = float(rank[rank["Ingredient code"].isin(mapping)]
                         ["_w"].sum()) if len(rank) else 0.0
        miss_mass = float(rank["_w"].sum())
        print(f"\n  Exact matches found: {len(mapping)} of {len(rank)} "
              f"unreachable codes.")
        print(f"    recipe mass recovered: "
              f"{100.0*got_mass/total_mass:.2f}% of the "
              f"{100.0*miss_mass/total_mass:.1f}% that was unreachable.")
        print("    Every one of these is FDC's own entry for that exact "
              "description --\n    a measurement, not a substitution. Codes "
              "with no exact match stay\n    unresolved and keep showing in "
              "fdc_resolved_mass.")
        if len(mapping) < len(rank) * 0.2:
            print("\n    The low yield is structural, not a bug: most "
                  "unreachable codes are\n    FNDDS aggregates ('Milk, NFS', "
                  "'Beef as ingredient in recipes').\n    Those strings name "
                  "a category, so no FDC entry can carry them.")
    return mapping

def substituted_code_map(inv_df, verbose=True):
    """ingredient code -> FDC ID, with PART N substitutions folded in.

    Returns (mapping, n_substituted). Codes with a real FDC ID keep it;
    codes in FDC_INGREDIENT_SUBSTITUTIONS borrow their donor's.
    """
    mp = inv_df[["Ingredient code", "FDC ID"]].dropna()
    code_to_fdc = mp.groupby("Ingredient code")["FDC ID"].min().astype(int)
    out = dict(code_to_fdc)
    n = 0
    if APPLY_FDC_SUBSTITUTIONS:
        for code, (donor, _why) in FDC_INGREDIENT_SUBSTITUTIONS.items():
            if code in out:
                continue
            if donor in code_to_fdc:
                out[code] = int(code_to_fdc[donor])
                n += 1
            elif donor in set(mp["FDC ID"].astype(int)):
                out[code] = int(donor)
                n += 1
    if verbose and n:
        print(f"  PART N: {n} unreachable ingredient codes given a "
              "representative donor.")
        print("    These are STATED ASSUMPTIONS, not measurements -- see "
              "FDC_INGREDIENT_SUBSTITUTIONS\n    for the reasoning behind "
              "each, and cite them as substitutions.")
    return out, n

