def meal_prevalence(cat_no, meal):
    row = WWEIA_MEAL_PREVALENCE.get(int(cat_no))
    return 1.0 if row is None else float(row.get(meal, 1.0))

def meal_placement_allowed(cat_no, meal):
    """False where WWEIA shows the category is effectively never eaten."""
    return meal_prevalence(cat_no, meal) > MEAL_PREVALENCE_BAN

EXOTIC_SPECIES_PATTERNS = (
    r"\bturtle\b", r"\bfrog\b", r"\balligator\b", r"\bsnake\b",
    r"\biguana\b", r"\bsquirrel\b", r"\bopossum\b", r"\braccoon\b",
    r"\bmuskrat\b", r"\bbeaver\b", r"\bbear\b", r"\bmoose\b",
    r"\bcaribou\b", r"\bantelope\b", r"\bwhale\b", r"\bseal\b",
    r"\bvenison\b", r"\bdeer\b", r"\bboar\b", r"\bemu\b", r"\bostrich\b",
    r"\bpheasant\b", r"\bquail\b", r"\bescargot\b", r"\bsnails?\b",
    r"\bcaviar\b", r"\broe\b", r"\btripe\b", r"\bbrain\b",
    r"\bkidney,\b", r"\btongue\b", r"\bgizzard\b", r"\bsweetbread\b",
)
WWEIA_ORGAN_MEAT = {2006}

WWEIA_ADDED_FAT = {8002, 8004, 8010, 8012}
WWEIA_FAT_EQUIVALENT = {2804}
MIN_ADDED_FAT_G_PER_DAY = 15.0

WWEIA_FISH = {2402, 2404}
MAX_FISH_SERVINGS_PER_WEEK = 4.0
FISH_SERVING_G = 113.0
MAX_FISH_G_PER_DAY = MAX_FISH_SERVINGS_PER_WEEK * FISH_SERVING_G / 7.0

HIGH_MERCURY_PATTERNS = (
    r"\bswordfish\b", r"\bshark\b", r"\bking mackerel\b", r"\btilefish\b",
    r"\bmarlin\b", r"\borange roughy\b", r"\bbigeye\b", r"\btuna, fresh\b",
    r"\bbass\b", r"\bgrouper\b", r"\bhalibut\b", r"\bsablefish\b",
    r"\bchilean\b", r"\bsea bass\b",
)

MIN_DISH_PORTION_G_STRICT = 50.0
MIN_DISH_PORTION_SERVING_FRAC = 0.5
MAX_ITEMS_PER_DAY = 12
MAX_ITEMS_PER_DAY_CSV = 24

def max_items_per_day(fm):
    return (MAX_ITEMS_PER_DAY_CSV if getattr(fm, "_has_csv_rows", False)
            else MAX_ITEMS_PER_DAY)

def _pattern_mask(desc_series, patterns):
    return desc_series.str.contains("|".join(patterns), regex=True, na=False)

def apply_clinical_pool_filters(df, verbose=True):
    """Drop exotic species and organ meats from the dish pool."""
    if "description" not in df.columns:
        return df
    n0 = len(df)
    low = df["description"].astype(str).str.lower()
    cat = pd.to_numeric(df.get(_WWEIA_NUM_COL), errors="coerce")
    drop_exotic = _pattern_mask(low, EXOTIC_SPECIES_PATTERNS)
    drop_organ = cat.isin(WWEIA_ORGAN_MEAT) if cat is not None else False
    keep = ~(drop_exotic | drop_organ)
    out = df[keep].reset_index(drop=True)
    if verbose:
        print(f"    exotic / game / wild species     {int(drop_exotic.sum()):>5}"
              "   (turtle, venison, frog, offal...)")
        print(f"    organ meat category              "
              f"{int(np.sum(drop_organ)) if cat is not None else 0:>5}")
        print(f"    pool: {n0} -> {len(out)} after clinical filters")
    return out

def clinical_violation(fm, x):
    """Added fat, fish frequency, portion realism, item count.

    Returned in commensurate units so it can be summed with the other PART M
    terms: fractions of a floor, or servings.
    """
    x = np.asarray(x, dtype=float)
    cats = _wweia_arr(fm)
    serv_g = _serving_g_arr(fm)
    grams = x * 100.0
    active = grams > 1e-9
    v = 0.0

    fat_mask = np.isin(cats, list(WWEIA_ADDED_FAT | WWEIA_FAT_EQUIVALENT))
    fat_g = float(grams[fat_mask].sum())
    if fat_g < MIN_ADDED_FAT_G_PER_DAY:
        v += (MIN_ADDED_FAT_G_PER_DAY - fat_g) / MIN_ADDED_FAT_G_PER_DAY

    fish_g = float(grams[np.isin(cats, list(WWEIA_FISH))].sum())
    if fish_g > MAX_FISH_G_PER_DAY:
        v += (fish_g - MAX_FISH_G_PER_DAY) / MAX_FISH_G_PER_DAY
    hi = _high_mercury_arr(fm)
    hi_g = float(grams[hi].sum())
    if hi_g > 0:
        v += hi_g / MAX_FISH_G_PER_DAY

    floor = np.maximum(MIN_DISH_PORTION_G_STRICT,
                       MIN_DISH_PORTION_SERVING_FRAC * serv_g)
    token = active & (grams < floor)
    if token.any():
        v += float(((floor[token] - grams[token]) / floor[token]).sum())

    n_items = int(active.sum())
    cap = max_items_per_day(fm)
    if n_items > cap:
        v += float(n_items - cap)
    return v

def _high_mercury_arr(fm):
    """Boolean per candidate: high-mercury or species-ambiguous fish."""
    if not hasattr(fm, "_hg_arr"):
        low = fm.df.iloc[fm.cand_idx]["description"].astype(str).str.lower()
        fm._hg_arr = _pattern_mask(low, HIGH_MERCURY_PATTERNS).to_numpy()
    return fm._hg_arr

def report_clinical_status(fm, x, verbose=True):
    x = np.asarray(x, dtype=float)
    cats, serv_g = _wweia_arr(fm), _serving_g_arr(fm)
    grams = x * 100.0
    active = grams > 1e-9
    fat_g = float(grams[np.isin(cats, list(WWEIA_ADDED_FAT
                                           | WWEIA_FAT_EQUIVALENT))].sum())
    fish_g = float(grams[np.isin(cats, list(WWEIA_FISH))].sum())
    hi_g = float(grams[_high_mercury_arr(fm)].sum())
    floor = np.maximum(MIN_DISH_PORTION_G_STRICT,
                       MIN_DISH_PORTION_SERVING_FRAC * serv_g)
    token = int((active & (grams < floor)).sum())
    if verbose:
        print("\n  Clinical review checks (PART Q):")
        print(f"    added fat: {fat_g:.0f} g (floor "
              f"{MIN_ADDED_FAT_G_PER_DAY:.0f}, oil/nuts/seeds only)"
              f"  {'ok' if fat_g >= MIN_ADDED_FAT_G_PER_DAY else 'NO ADDED FAT'}")
        print(f"    fish: {fish_g:.0f} g/day (cap {MAX_FISH_G_PER_DAY:.0f} "
              f"= {MAX_FISH_SERVINGS_PER_WEEK:.0f} servings/week)"
              f"  {'ok' if fish_g <= MAX_FISH_G_PER_DAY else 'OVER'}")
        if hi_g > 0:
            names = [str(fm.names[j])[:34] for j in
                     np.where(_high_mercury_arr(fm) & active)[0]]
            print(f"    ! high-mercury or species-ambiguous: {hi_g:.0f} g")
            for nm in names:
                print(f"        {nm}")
        print(f"    portions below 50 g / half a serving: {token}"
              f"  {'ok' if token == 0 else 'TOKEN PORTIONS'}")
        cap = max_items_per_day(fm)
        print(f"    distinct items: {int(active.sum())} (cap {cap})"
              f"  {'ok' if active.sum() <= cap else 'TOO MANY'}")

EXTRA_CSV_PATH = None
POOL_SOURCE_DISH = "FNDDS dish"
POOL_SOURCE_CSV = "CSV ingredient"

