def prompt_extra_csv(path=None):
    """Ask for an optional ingredient CSV to merge with the dish pool."""
    global EXTRA_CSV_PATH
    if path is None:
        print("\n" + BOLD + "--- Optional: extra ingredient CSV ---" + RESET)
        print("  A per-100 g composition table of single INGREDIENTS, merged")
        print("  with the FNDDS dishes. Enter to skip (dishes only).")
        path = _clean_path(input("  CSV path [Enter to skip]: "))
    if not path:
        EXTRA_CSV_PATH = None
        return None
    if not os.path.isfile(path):
        print(f"  Not a file: {path}. Skipping.")
        EXTRA_CSV_PATH = None
        return None
    EXTRA_CSV_PATH = path
    return path

def load_extra_ingredient_csv(path=None, verbose=True):
    """Read the ingredient CSV and align it to the pool schema.

    Reports every column it could NOT align rather than filling gaps. A
    nutrient absent here becomes NaN for these rows, which the coverage
    check in FoodModel then accounts for -- an ingredient with no selenium
    value must not be scored as zero selenium.
    """
    path = path or EXTRA_CSV_PATH
    if not path:
        return None
    df = _normalize_headers(pd.read_csv(path, low_memory=False))
    if "description" not in df.columns:
        for alt in ("Main food description", "food", "name", "Food"):
            if alt in df.columns:
                df["description"] = df[alt]
                break
    if "description" not in df.columns:
        raise ValueError(f"{os.path.basename(path)}: no 'description' column.")

    CSV_ALIASES = {
        "Folate, DFE (UG)": "Folate, total (UG)",
        "Sodium (mg)": "Sodium, Na (MG)",
        "Fatty acids, total trans": "Fatty acids, total trans (G)",
        "Sugars, added": "Sugars, added (G)",
        "Added Sugars (g)": "Sugars, added (G)",
        "Fatty acids, total monounsaturated (G)": "MUFA (G)",
        "Energy (Atwater Specific Factors) (KCAL)": "Energy (KCAL)",
    }
    renamed = []
    for src_c, dst_c in CSV_ALIASES.items():
        if src_c in df.columns and dst_c not in df.columns:
            df[dst_c] = df[src_c]
            renamed.append(f"{src_c} -> {dst_c}")
    if verbose and renamed:
        print("\n  CSV columns aliased onto the dish schema:")
        for r in renamed:
            print(f"    {r}")
        print("    Without this each half populates a different column and "
              "the merged\n    pool shows ~50% coverage for a nutrient both "
              "halves actually carry.")

    if "Food_Subgroup" not in df.columns:
        df["Food_Subgroup"] = [classify_food(d)[1]
                               for d in df["description"].astype(str)]
    df["pool_source"] = POOL_SOURCE_CSV
    if _WWEIA_NUM_COL not in df.columns:
        df[_WWEIA_NUM_COL] = -1

    if verbose:
        need = [c for c in FNDDS_COLUMN_MAP.values()]
        have = [c for c in need if c in df.columns]
        missing = [c for c in need if c not in df.columns]
        unk = int((df["Food_Subgroup"].astype(str) == "Unknown").sum())
        print(f"\n  Ingredient CSV: {len(df)} rows, "
              f"{len(have)} of {len(need)} schema nutrients present.")
        if missing:
            print("    NOT in the CSV (NaN for these rows, never zero): "
                  + ", ".join(m[:28] for m in missing[:6])
                  + (" ..." if len(missing) > 6 else ""))
        print(f"    unclassified subgroup: {unk} rows")
        thin = []
        for c in df.columns:
            v = pd.to_numeric(df[c], errors="coerce")
            if v.notna().mean() > 0.95 and (v.fillna(0) != 0).mean() < 0.10:
                thin.append((c, 100 * (v.fillna(0) != 0).mean()))
        if thin:
            print("\n    ! ZERO-FILLED columns -- present for every row, "
                  "non-zero for almost none:")
            for c, pct in sorted(thin, key=lambda t: t[1])[:10]:
                print(f"        {c[:36]:<38}{pct:5.1f}% non-zero")
            print("      These read as complete data and are not. The "
                  "coverage check keeps\n      them out of scoring, so they "
                  "report as UNKNOWN, not as deficiencies.")
        mapped = df["Food_Subgroup"].astype(str).isin(SUBGROUP_TO_RULE_GROUP)
        print(f"    rows reached by PART Q rules via subgroup: "
              f"{int(mapped.sum())} of {len(df)}")
        print("    The rest are governed by the mass, duplicate, "
              "concentration and\n    sodium rules, which do not need a "
              "category, but NOT by the\n    category-specific caps.")
    return df

def merge_pools(dish_pool, csv_pool, verbose=True):
    """Concatenate the two pools, keeping provenance and column union."""
    if csv_pool is None or csv_pool.empty:
        dish_pool["pool_source"] = POOL_SOURCE_DISH
        return dish_pool
    dish_pool = dish_pool.copy()
    dish_pool["pool_source"] = POOL_SOURCE_DISH
    out = pd.concat([dish_pool, csv_pool], ignore_index=True, sort=False)

    if SERVING_G_COL in out.columns:
        out[SERVING_G_COL] = pd.to_numeric(out[SERVING_G_COL],
                                           errors="coerce").fillna(100.0)
    for c in ("food_code", "orig_fdc_id"):
        if c not in out.columns:
            out[c] = np.nan
    if verbose:
        print(f"\n  MIXED POOL: {int((out['pool_source']==POOL_SOURCE_DISH).sum())}"
              f" dishes + {int((out['pool_source']==POOL_SOURCE_CSV).sum())}"
              f" ingredients = {len(out)} decision variables.")
        print("    Provenance is kept in `pool_source`, so any result can be")
        print("    split by it. Report the split -- a plan built mostly from")
        print("    one side is a different claim from a genuinely mixed one.")
    return out.reset_index(drop=True)

def mark_csv_pool(fm):
    """Flag whether the pool contains CSV ingredient rows.

    Set once on the model rather than read per evaluation: the slot
    constraint runs inside every _evaluate() call and a DataFrame lookup
    there would dominate the runtime.
    """
    s = fm.df.get("pool_source")
    fm._has_csv_rows = bool(s is not None
                            and (s.astype(str) == POOL_SOURCE_CSV).any())
    return fm._has_csv_rows

def _source_arr(fm):
    """Boolean per candidate: True where the row came from the CSV."""
    if not hasattr(fm, "_src_arr"):
        s = fm.df.iloc[fm.cand_idx].get("pool_source")
        fm._src_arr = (np.array([str(v) == POOL_SOURCE_CSV for v in s])
                       if s is not None
                       else np.zeros(len(fm.cand_idx), dtype=bool))
    return fm._src_arr

def _rule_group_arr(fm):
    """PART Q rule group per candidate, derived from subgroup for CSV rows.

    Lets an ingredient satisfy the added-fat floor and count against the
    fish cap, which it otherwise could not: those rules key on WWEIA
    category and a CSV ingredient has none.
    """
    if not hasattr(fm, "_rulegrp_arr"):
        sg = fm.df.iloc[fm.cand_idx].get("Food_Subgroup")
        fm._rulegrp_arr = np.array(
            [SUBGROUP_TO_RULE_GROUP.get(str(v), "") for v in sg]
            if sg is not None else [""] * len(fm.cand_idx), dtype=object)
    return fm._rulegrp_arr

def csv_subgroup_cap_violation(fm, x, target_kcal=None):
    """Re-apply SUBGROUP_UL_2500 to CSV rows only.

    The caps are muted globally in dish mode because they are statements
    about ingredients. In a mixed pool the CSV rows ARE ingredients, so the
    mute exempts precisely the rows the caps were written for. This puts
    them back, for those rows only.
    """
    x = np.asarray(x, dtype=float)
    is_csv = _source_arr(fm)
    if not is_csv.any():
        return 0.0
    grams = x * 100.0
    sg = fm.df.iloc[fm.cand_idx]["Food_Subgroup"].astype(str).to_numpy()
    factor = (target_kcal or getattr(fm, "target_kcal", None)
              or UL_REF_KCAL) / UL_REF_KCAL
    v = 0.0
    for subgroup, ul in SUBGROUP_UL_2500.items():
        cap = ul * factor
        got = float(grams[is_csv & (sg == subgroup)].sum())
        if got > cap > 0:
            v += (got - cap) / cap
    return v

