def hybrid_slot_demand():
    """{slot: how many distinct foods the day's structure requires}."""
    demand = {}
    for row in HYBRID_STRUCTURE:
        for s in row[2]:
            demand[s] = demand.get(s, 0) + 1
    return demand

def _slot_eligible_arr(fm):
    """{slot: boolean mask over candidates}, cached."""
    if not hasattr(fm, "_slot_masks"):
        sg = fm.df.iloc[fm.cand_idx]["Food_Subgroup"].astype(str).to_numpy()
        fm._slot_masks = {slot: np.isin(sg, list(subs))
                          for slot, subs in HYBRID_SLOT_SUBGROUPS.items()}
    return fm._slot_masks

def hybrid_slot_violation(fm, x):
    """Shortfall in distinct eligible foods per slot, summed over slots.

    Counted in "missing foods", so one empty fruit slot costs 1.0 and is
    commensurate with the other structural terms.
    """
    if not HYBRID_ENFORCE_SLOTS:
        return 0.0
    x = np.asarray(x, float)
    grams = x * 100.0
    masks = _slot_eligible_arr(fm)
    v = 0.0
    for slot, need in hybrid_slot_demand().items():
        floor = HYBRID_SLOT_MIN_G.get(slot, HYBRID_SLOT_MIN_G_DEFAULT)
        have = int(np.count_nonzero(masks.get(slot, False) & (grams >= floor)))
        if have < need:
            v += float(need - have)
    return v

def report_hybrid_slots(fm, x, verbose=True):
    x = np.asarray(x, float)
    grams = x * 100.0
    masks = _slot_eligible_arr(fm)
    rows = []
    for slot, need in hybrid_slot_demand().items():
        floor = HYBRID_SLOT_MIN_G.get(slot, HYBRID_SLOT_MIN_G_DEFAULT)
        have = int(np.count_nonzero(masks.get(slot, False) & (grams >= floor)))
        pool = int(np.count_nonzero(masks.get(slot, False)))
        rows.append((slot, have, need, pool))
    if verbose:
        print("\n  Hybrid slot coverage (distinct foods, >= slot minimum):")
        print(f"    {'slot':<16}{'have':>6}{'need':>6}{'in pool':>9}")
        for slot, have, need, pool in rows:
            flag = "" if have >= need else "   SHORT"
            print(f"    {slot:<16}{have:>6}{need:>6}{pool:>9}{flag}")
        if any(p == 0 for _, _, _, p in rows):
            print("    A slot with 0 in pool cannot ever be filled -- that is "
                  "a subgroup\n    naming mismatch, not an optimizer failure. "
                  "Check HYBRID_SLOT_SUBGROUPS\n    against the pool's actual "
                  "Food_Subgroup values.")

def _hybrid_pick_days(front_X, front_obj, n_days=HYBRID_DAYS):
    """Choose n_days distinct plans from the Pareto front.

    Spread across the front rather than taking the first n rows, so the
    week varies instead of repeating near-identical solutions. Chosen by
    greedy maximum-distance in objective space, starting from the plan
    closest to the front's centroid.
    """
    X = np.asarray(front_X, float)
    F = np.asarray(front_obj, float)
    if len(X) <= n_days:
        return list(range(len(X)))
    Fn = (F - F.min(0)) / np.maximum(F.max(0) - F.min(0), 1e-12)
    picked = [int(np.argmin(((Fn - Fn.mean(0)) ** 2).sum(1)))]
    while len(picked) < n_days:
        d = np.min(((Fn[:, None, :] - Fn[None, picked, :]) ** 2).sum(-1),
                   axis=1)
        d[picked] = -1
        picked.append(int(np.argmax(d)))
    return picked

def build_hybrid_day(fm, x, target_kcal=None):
    """Arrange one plan's foods into the published slot structure.

    Returns [(meal, kcal, protein_g, [(slot, food, grams, kcal, prot)])].

    Foods are assigned to the slot they are eligible for, largest first,
    within each meal's energy share. A food with no eligible slot is
    returned under "Unslotted" rather than dropped -- the structure is a
    presentation of what the optimizer chose, and silently discarding part
    of the plan would misreport the nutrition totals shown beneath it.
    """
    x = np.asarray(x, float)
    energy = np.asarray(fm.energy_arr, float)
    sub = fm.df.iloc[fm.cand_idx]["Food_Subgroup"].astype(str).to_numpy()
    prot_col = _resolve_col(fm.df, COL_CANDIDATES.get("protein", []))
    prot = (np.nan_to_num(pd.to_numeric(
        fm.df.iloc[fm.cand_idx][prot_col], errors="coerce").to_numpy(float))
        if prot_col else np.zeros(len(x)))

    items = [{"i": i, "g": float(x[i] * 100.0),
              "kcal": float(x[i] * energy[i]),
              "prot": float(x[i] * prot[i]),
              "sg": sub[i], "name": str(fm.names[i])}
             for i in np.where(x > 1e-9)[0]]
    items.sort(key=lambda t: (-t["kcal"], t["name"]))

    total = sum(t["kcal"] for t in items) or 1.0
    used, out = set(), []
    for meal, share, slots, cite, _desc in HYBRID_STRUCTURE:
        budget = total * share
        spent, rows = 0.0, []
        for slot in slots:
            ok = HYBRID_SLOT_SUBGROUPS.get(slot, set())
            cand = [t for t in items if t["i"] not in used and t["sg"] in ok]
            if not cand:
                rows.append((slot, "-- no eligible food in plan --",
                             0.0, 0.0, 0.0))
                continue
            tgt = max(budget - spent, 1.0) / max(
                len(slots) - len(rows), 1)
            pick = min(cand, key=lambda t: (abs(t["kcal"] - tgt), t["name"]))
            used.add(pick["i"])
            spent += pick["kcal"]
            rows.append((slot, pick["name"], pick["g"], pick["kcal"],
                         pick["prot"]))
        out.append((meal, cite, spent,
                    sum(r[4] for r in rows), rows))

    leftover = [t for t in items if t["i"] not in used]
    if leftover:
        out.append(("Unslotted", "no published slot matches these subgroups",
                    sum(t["kcal"] for t in leftover),
                    sum(t["prot"] for t in leftover),
                    [("-", t["name"], t["g"], t["kcal"], t["prot"])
                     for t in leftover]))
    return out

def _hybrid_day_stats(fm, x):
    """kcal, protein g, fibre g for one plan."""
    x = np.asarray(x, float)
    kcal = float(np.dot(x, np.asarray(fm.energy_arr, float)))

    def _sum(keys):
        col = _resolve_col(fm.df, COL_CANDIDATES.get(keys, []))
        if not col:
            return 0.0
        a = np.nan_to_num(pd.to_numeric(fm.df.iloc[fm.cand_idx][col],
                                        errors="coerce").to_numpy(float))
        return float(np.dot(x, a))

    return kcal, _sum("protein"), _sum("fiber")

def render_hybrid_7day(fm, cfg, front_X, front_obj, out_path=None,
                       verbose=True, recommended_x=None):
    """Write the 7-day hybrid plan, matching the template's layout.

    Adds what the template does not have: per-day MACRO and MICRO tables,
    and scaling to the person's energy target instead of a fixed 2,000 kcal.
    """
    target = float(getattr(fm, "target_kcal", 0) or HYBRID_REFERENCE_KCAL)
    idx = _hybrid_pick_days(front_X, front_obj)
    L = []
    L.append(f"# Hybrid 5-Meal Structure \u2014 {len(idx)}-Day Plan "
             f"(~{target:,.0f} kcal)\n")
    L.append("Every meal is an instance of a published structure; only the "
             "foods rotate.\n")
    L.append("| Meal | Governing structure | Slots that must be filled |")
    L.append("|---|---|---|")
    for meal, _share, _slots, cite, desc in HYBRID_STRUCTURE:
        L.append(f"| {meal} | {cite} | {desc} |")
    L.append("")
    L.append("Quantities per day follow the USDA Healthy U.S.-Style Pattern "
             "@2,000 kcal and NHLBI DASH @2,000 kcal.")
    L.append("Protein is distributed evenly across main meals per Mamerow "
             "et al., *J Nutr* 2014;144:876\u201380.")
    L.append("")
    L.append(f"**Quantities are each day's own optimizer output, not a scaled "
             f"template.** The {HYBRID_REFERENCE_KCAL:,.0f} kcal reference "
             f"pattern supplies the meal energy SHARES and slot composition "
             f"(ratios, which carry over unchanged); the gram amounts come "
             f"from NSGA-III and already meet this person's "
             f"{target:,.0f} kcal target directly.")
    L.append("")
    L.append("**Why these tables will not match the console printout.** The "
             "console reports the ONE recommended plan. Each day below is a "
             "DIFFERENT plan drawn from the Pareto front, chosen by maximum "
             "spread in objective space so the week varies. Different plans "
             "have different foods, so different nutrient totals -- a "
             "mismatch between this report and the console is expected and "
             "is not an error in either. The day matching the recommended "
             "plan, if one is shown, is marked below.")
    L.append("")
    L.append("Foods are whatever NSGA-III selected, arranged into the "
             "slots. A slot reading *no eligible food* means the optimizer "
             "chose nothing that qualifies \u2014 nothing is inserted to "
             "fill a gap, because that would make the nutrient tables below "
             "stop describing the food above them.")

    for d, k in enumerate(idx, start=1):
        x = np.asarray(front_X[k], float)
        day = build_hybrid_day(fm, x)
        kcal, protein, fibre = _hybrid_day_stats(fm, x)
        label = (HYBRID_DAY_LABELS[d - 1]
                 if d <= len(HYBRID_DAY_LABELS) else f"Variant {d}")
        if recommended_x is not None and np.allclose(
                x, np.asarray(recommended_x, float), rtol=1e-9, atol=1e-9):
            label += " \u2014 **this is the recommended plan (matches console)**"
        L.append(f"\n---\n\n## Day {d} \u2014 {label} \u00b7 "
                 f"{kcal:,.0f} kcal \u00b7 {protein:.0f} g protein "
                 f"\u00b7 {fibre:.0f} g fibre\n")
        for meal, cite, mk, mp, rows in day:
            L.append(f"**{meal}** \u2014 {mk:,.0f} kcal, {mp:.0f} g protein"
                     f"  \n*{cite}*\n")
            L.append("| Slot | Food | kcal | Protein |")
            L.append("|---|---|---:|---:|")
            for slot, name, g, kc, pr in rows:
                food = (f"{name[:52]}, {g:,.0f} g" if g > 0 else name)
                L.append(f"| {slot} | {food} | {kc:,.0f} | {pr:.1f} g |")
            L.append("")

        macros, micros = fm.nutrient_panel(x)
        L.append(f"### Day {d} macronutrients\n")
        L.append("| Nutrient | Intake | Target | % |")
        L.append("|---|---:|---:|---:|")
        for r in macros:
            pct = 100.0 * r["intake"] / r["floor"] if r.get("floor") else 0.0
            L.append(f"| {r['name']} | {r['intake']:,.1f} | "
                     f"{r['floor']:,.1f} | {pct:.0f}% |")
        L.append("")
        L.append(f"### Day {d} micronutrients\n")
        L.append("| Nutrient | Intake | RDA | % | UL |")
        L.append("|---|---:|---:|---:|---:|")
        for r in sorted(micros, key=lambda r: r["name"]):
            pct = 100.0 * r["intake"] / r["floor"] if r.get("floor") else 0.0
            ul = f"{r['ul']:,.0f}" if r.get("ul") else "\u2014"
            L.append(f"| {r['name']} | {r['intake']:,.2f} | "
                     f"{r['floor']:,.2f} | {pct:.0f}% | {ul} |")
        L.append("")
        um = getattr(fm, "unmeasured_cols", [])
        if um:
            L.append(f"*Not scored \u2014 below {MIN_NUTRIENT_COVERAGE:.0%} "
                     "pool coverage, so UNKNOWN rather than deficient: "
                     + ", ".join(sorted(um)) + "*\n")

    L.append("\n---\n")
    L.append("## Swaps that preserve the structure\n")
    L.append("| Slot | Interchangeable options |")
    L.append("|---|---|")
    for slot, subs in HYBRID_SLOT_SUBGROUPS.items():
        L.append(f"| {slot} | " + " \u00b7 ".join(sorted(subs)) + " |")
    L.append("")
    L.append("Swap **within a row only**. Swapping across rows breaks the "
             "plate proportions the structure is built on. The options "
             "listed are the food SUBGROUPS each slot accepts in this "
             "pool, not a dietitian's shortlist.\n")
    L.append("## Prep notes\n")
    L.append("- Batch-cook two grains and one legume on one day; both keep "
             "4\u20135 days refrigerated.")
    L.append("- Roast a tray of mixed vegetables covering two subgroups at "
             "once.")
    L.append("- Portion yogurt, nuts and cut vegetables in advance \u2014 "
             "the snack slots are where structure breaks down first.")
    L.append("- Cook without added salt and season at the table. Rinse "
             "canned legumes. Salted cooking, cured meats or standard "
             "canned goods add 1,000+ mg sodium quickly.\n")
    L.append("### Caveat\n")
    L.append("General nutrition information, not individualised advice. "
             f"The {HYBRID_REFERENCE_KCAL:,.0f} kcal structure is a "
             "reference level scaled here to a computed target; actual "
             "needs depend on age, sex, body size and activity. Nutrient "
             "values are database figures scaled to the stated portions "
             "\u2014 brand, cut and preparation shift them, sodium most of "
             "all. Anyone pregnant or breastfeeding, or managing diabetes, "
             "kidney disease, hypertension or food allergies, should have "
             "this reviewed by a registered dietitian nutritionist.\n")

    out_path = out_path or "hybrid_7day_plan.md"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(L))
    if verbose:
        print(f"\n  Hybrid {len(idx)}-day plan written: {out_path}")
        print(f"    template {HYBRID_REFERENCE_KCAL:,.0f} kcal -> "
              f"{target:,.0f} kcal "
              f"(x{(target / HYBRID_REFERENCE_KCAL) if HYBRID_REFERENCE_KCAL else 0:.2f}); "
              f"per-day macros and "
              "micros included.")
    return out_path

NOVA_PREFERENCE_ACTIVE = True
NOVA_PENALTY = {1: 0.0, 2: 0.15, 3: 0.45, 4: 1.0}
NOVA_WEIGHT = 0.6

_NOVA4_PATTERNS = (
    r"\bcandy\b", r"\bcandies\b", r"\bcookie", r"\bcracker", r"\bchips\b",
    r"\bsnack", r"\bsoda\b", r"\bcola\b", r"\bsoft drink", r"\bfruit roll",
    r"\bpastry\b", r"\bcake\b", r"\bpie,\b", r"\bdoughnut", r"\bicing\b",
    r"\bfrosting\b", r"\bmargarine\b", r"\bimitation\b", r"\bformulated\b",
    r"\bmeal replacement\b", r"\bnutrition(al)? bar\b", r"\bprotein bar\b",
    r"\bready-to-heat\b", r"\bready-to-eat\b", r"\bmicrowave\b",
    r"\binstant\b", r"\bfrozen (dinner|entree|meal|pizza)\b",
    r"\bhot dog\b", r"\bfrankfurter\b", r"\bluncheon meat\b",
    r"\bchicken nugget", r"\bfish stick", r"\bbreakfast bar\b",
    r"\bsweetened\b", r"\bflavored drink\b", r"\bdrink mix\b",
    r"\binfant formula\b", r"\bturnover\b", r"\bpop.?tart", r"\btoaster\b",
)
_NOVA3_PATTERNS = (
    r"\bcanned\b", r"\bin brine\b", r"\bin syrup\b", r"\bsalted\b",
    r"\bsmoked\b", r"\bcured\b", r"\bpickled\b", r"\bbread\b", r"\bcheese\b",
    r"\bham\b", r"\bbacon\b", r"\bsausage\b", r"\btortillas?\b", r"\bbagel\b",
    r"\bmuffins?\b", r"\bjuice, canned\b", r"\bdried, sulfured\b",
)
_NOVA2_PATTERNS = (
    r"^oil,", r"^butter,", r"^sugars?,", r"^salt,", r"^vinegar",
    r"^lard\b", r"^shortening\b", r"^honey\b", r"^syrups?,", r"^ghee\b",
    r"^cream, fluid\b", r"^starch,", r"^gelatin",
)
_NOVA1_PATTERNS = (
    r"\braw\b", r"\bfresh\b", r"\buncooked\b",
    r"\bcooked, boiled, drained, without salt\b",
    r"\bcooked, without salt\b", r"\bdried\b(?!.*sulfured)",
    r"\bwhole, raw\b",
)
_BRAND_PATTERN = r"\b[A-Z]{3,}[A-Z ]{2,}\b"

def nova_group(desc):
    """Assign a NOVA group (1-4) from a food description string."""
    s = str(desc)
    low = s.lower()

    def hit(pats):
        return any(re.search(p, low) for p in pats)

    if hit(_NOVA4_PATTERNS):
        g = 4
    elif hit(_NOVA2_PATTERNS):
        g = 2
    elif hit(_NOVA3_PATTERNS):
        g = 3
    elif hit(_NOVA1_PATTERNS):
        g = 1
    else:
        g = 3
    if g < 4 and re.search(_BRAND_PATTERN, s):
        g = min(4, g + 1)
    return g

def nova_arr(fm):
    """NOVA group per candidate, cached."""
    if not hasattr(fm, "_nova_arr"):
        d = fm.df.iloc[fm.cand_idx]["description"].astype(str)
        fm._nova_arr = np.array([nova_group(v) for v in d], dtype=int)
    return fm._nova_arr

def processing_violation(fm, x):
    """Mass-weighted processing penalty, 0 when the plan is all NOVA 1.

    Normalised by total plan mass, so it measures the plan's processing
    PROFILE rather than its size -- a 2,500 g whole-food day should not
    score worse than a 400 g ultra-processed one.
    """
    if not NOVA_PREFERENCE_ACTIVE:
        return 0.0
    x = np.asarray(x, float)
    grams = x * 100.0
    total = float(grams.sum())
    if total <= 0:
        return 0.0
    nv = nova_arr(fm)
    pen = np.array([NOVA_PENALTY.get(int(g), 1.0) for g in nv])
    return NOVA_WEIGHT * float(np.dot(grams, pen) / total)

def report_nova(fm, x, verbose=True):
    x = np.asarray(x, float)
    grams = x * 100.0
    nv = nova_arr(fm)
    total = float(grams.sum()) or 1.0
    if verbose:
        print("\n  Processing profile (NOVA, Monteiro et al. 2019):")
        labels = {1: "1 whole / minimally processed",
                  2: "2 culinary ingredients",
                  3: "3 processed",
                  4: "4 ultra-processed"}
        for g in (1, 2, 3, 4):
            mass = float(grams[nv == g].sum())
            n = int(np.count_nonzero((nv == g) & (grams > 1e-9)))
            print(f"    {labels[g]:<32}{n:>4} foods{mass:>8.0f} g"
                  f"{100*mass/total:>7.1f}%")
        upf = 100 * float(grams[nv == 4].sum()) / total
        print(f"    penalty term: {processing_violation(fm, x):.3f} "
              "(0 = entirely whole foods)")
        if upf > 30:
            print(f"    ! {upf:.0f}% of plan mass is ultra-processed. The "
                  "slot structure is\n      satisfied; the food filling it "
                  "is not what the structure assumes.")
        print("    Groups are assigned from the DESCRIPTION only, not an "
              "ingredient list,\n    so this approximates NOVA rather than "
              "implementing it. Preference,\n    not filter: nothing is "
              "excluded on this basis.")

if __name__ == "__main__":
    main()

import difflib
