from typing import Any, Dict, List, Optional, Sequence, Tuple

import pandas as pd

NUTRIENT_BASIS_G: float = 100.0

TOLERANCE_PCT: float = 0.05

LOW_CONFIDENCE_SIMILARITY: float = 0.60

SIMILARITY_METRIC: str = "cosine"

TOP_N_SUBSTITUTES: int = 3

SUBSTITUTE_SEARCH_DEPTH: int = 15

ENERGY_DENSITY_WEIGHT: float = 0.45

PROTECT_NUTRIENT_FLOORS: bool = True

NUTRIENT_RETENTION_MIN: float = 0.80

NO_FLOOR_NUTRIENTS: Tuple[str, ...] = (
    "sugar", "sodium", "salt", "saturated", "trans", "cholesterol",
    "energy", "kcal", "calorie", "alcohol", "caffeine",
)

SEL_W_FLOOR: float = 1.00
SEL_W_DAY_KCAL: float = 1.60
SEL_W_MEAL_BAND: float = 0.50
SEL_W_CLAMP: float = 0.70
SEL_W_LIMIT: float = 0.60
SEL_W_DRIFT: float = 0.30
SEL_W_SODIUM_FORM: float = 0.20

LIMIT_NUTRIENT_MAX_RATIO: float = 1.25

SODIUM_MG_PER_1000KCAL_LIMIT: float = 1150.0

FOOD_FAMILY_LIMITS = {
    "seafood": (("Fatty Fish", "Lean Fish", "Tuna", "Seafood"), 2),
    "red meat": (("Beef", "Mutton/Lamb", "Pork", "Game"), 2),
    "dairy": (("Milk", "Yogurt", "Cheese", "Paneer", "Cream"), 3),
}

def check_food_family_repetition(subgroups, verbose=True):
    """Count items per FOOD FAMILY across subgroups and flag over-represented ones.

    REPORTED, not enforced. Turning this into a hard constraint means adding
    rows to the problem's inequality vector and re-deriving n_ieq_constr, which
    is a change to the optimizer core; this reports the same information
    without that risk. If it fires often, promoting it to a constraint is the
    follow-up.
    """
    subs = [str(x).strip() for x in subgroups]
    out = []
    for label, (members, cap) in FOOD_FAMILY_LIMITS.items():
        n = sum(1 for x in subs if x in members)
        if n > cap:
            out.append({"family": label, "count": n, "cap": cap})
    if verbose and out:
        print(BOLD + "\n--- REPETITION ACROSS FOOD FAMILIES ---" + RESET)
        for r in out:
            print(f"  ! {r['count']} separate {r['family']} items in one day "
                  f"(cap {r['cap']}). Per-subgroup duplicate limits do not "
                  f"catch this: each subgroup holds one item and the family "
                  f"holds {r['count']}.")
    return out

def check_sodium_density(sodium_mg, kcal, verbose=True):
    """Sodium per 1000 kcal against the CDRR-equivalent density."""
    if not kcal or kcal <= 0:
        return {}
    dens = 1000.0 * float(sodium_mg or 0.0) / float(kcal)
    over = dens > SODIUM_MG_PER_1000KCAL_LIMIT
    if verbose:
        print(BOLD + "\n--- SODIUM DENSITY ---" + RESET)
        print(f"  {sodium_mg:,.0f} mg over {kcal:,.0f} kcal = "
              f"{dens:,.0f} mg/1000 kcal "
              f"(reference {SODIUM_MG_PER_1000KCAL_LIMIT:,.0f})")
        if over:
            print("  ! Above the reference DENSITY even if the absolute total")
            print("    looks acceptable. At a reduced energy target the same")
            print("    sodium arrives in less food, so density is the figure")
            print("    that compares across energy levels.")
    return {"sodium_mg": float(sodium_mg or 0.0), "kcal": float(kcal),
            "mg_per_1000kcal": dens, "over_reference": bool(over)}

def _is_limit_nutrient(nutrient_name: str) -> bool:
    """True for nutrients where an INCREASE is the harm (sodium, sat fat...)."""
    n = _norm(nutrient_name)
    return any(_contains(n, kw) for kw in
               ("sodium", "salt", "saturated", "trans", "cholesterol", "sugar"))

def _limit_penalty(
    day_totals: Dict[str, float],
    baseline: Dict[str, float],
) -> float:
    """Weighted overshoot of limit nutrients above their tolerated multiple."""
    pen = 0.0
    for c, base in baseline.items():
        if base <= 0.0 or not _is_limit_nutrient(c):
            continue
        ceiling = base * LIMIT_NUTRIENT_MAX_RATIO
        amt = day_totals.get(c, 0.0)
        if amt > ceiling:
            pen += (amt - ceiling) / ceiling
    return pen

LOW_SODIUM_FORM_HINTS = ("no salt added", "unsalted", "low sodium",
                         "reduced sodium", "fresh", "frozen", "raw",
                         "rinsed", "drained")
HIGH_SODIUM_FORM_HINTS = ("canned", "brine", "pickled", "cured", "smoked",
                          "salted", "in salt", "packed in oil")

def _sodium_form_penalty(food_name: Any) -> float:
    """0.0 for a low-sodium form, 1.0 for a clearly salted one, else 0.5."""
    n = _norm(food_name)
    if any(_contains(n, k) for k in LOW_SODIUM_FORM_HINTS):
        return 0.0
    if any(_contains(n, k) for k in HIGH_SODIUM_FORM_HINTS):
        return 1.0
    return 0.5

def _floorable(nutrient_name: str) -> bool:
    """False for nutrients where a retention floor is the wrong direction."""
    n = _norm(nutrient_name)
    return not any(_contains(n, kw) for kw in NO_FLOOR_NUTRIENTS)

FLOOR_PRIORITY_WEIGHTS: Dict[str, float] = {
    "protein": 3.0,
    "vitamin d": 2.0,
    "folate": 2.0,
    "vitamin b-12": 1.5,
    "iron": 1.5,
    "calcium": 1.5,
    "zinc": 1.5,
}

PORTION_SEARCH_STEPS: int = 25

def _floor_weight(nutrient_name: str) -> float:
    """Priority weight for a nutrient's floor. Unlisted nutrients weigh 1.0."""
    n = _norm(nutrient_name)
    for key, w in FLOOR_PRIORITY_WEIGHTS.items():
        if _contains(n, key):
            return float(w)
    return 1.0

