TOKEN_PORTION_MIN_G: float = 15.0

RESCALE_MIN_GRAMS: float = 1.0
RESCALE_MAX_GRAMS: float = 250.0

USE_SERVING_PRIORS: bool = True
SERVING_PRIOR_MIN_MULT: float = 0.5
SERVING_PRIOR_MAX_MULT: float = 2.5

def portion_bounds_for(food_db, column_map, db_pos, fallback_grams=None):
    """(min_g, max_g) for one food, from its own serving prior when available.

    Falls back to the flat RESCALE_MIN_GRAMS/RESCALE_MAX_GRAMS bounds when the
    food has no serving weight on file -- a missing prior must widen the band,
    never narrow it, or a sparse serving column would silently constrain the
    plan more than a full one.
    """
    lo, hi = float(RESCALE_MIN_GRAMS), float(RESCALE_MAX_GRAMS)
    if not USE_SERVING_PRIORS:
        return lo, hi
    try:
        col = SERVING_G_COL
        db = food_db.reset_index(drop=True)
        if col not in db.columns or db_pos is None:
            return lo, hi
        v = pd.to_numeric(db.iloc[int(db_pos)].get(col), errors="coerce")
        if pd.isna(v) or float(v) <= 0:
            return lo, hi
        serv = float(v)
        return (max(lo, serv * SERVING_PRIOR_MIN_MULT),
                min(hi, serv * SERVING_PRIOR_MAX_MULT))
    except Exception:
        return lo, hi

