def _is_branded_name(name: Any) -> bool:
    """True if PART 2H/2I's brand detectors recognise a proprietor in `name`.

    Thin wrapper so IMPRACTICAL_RULES can reuse the pool builder's detector
    rather than carrying a second, divergent copy. Guarded because those
    helpers live in an earlier part of the module and this one must keep
    working if that part is ever removed.
    """
    raw = str(name or "")
    letters = [ch for ch in raw if ch.isalpha()]

    words = [w for w in re.findall(r"[A-Za-z][A-Za-z.&'\-]*", raw)
             if any(ch.isalpha() for ch in w)]
    if letters and words:
        all_upper = all(ch.isupper() for ch in letters)
        _minor = {"or", "in", "and", "with", "of", "the", "for", "to", "a"}
        all_title = all(
            w.lower() in _minor
            or (w[0].isupper() and not any(ch.isupper() for ch in w[1:]))
            for w in words)
        if all_upper or all_title:
            return bool(re.search(r"\b[A-Za-z][A-Za-z.&\-]*'[Ss]\b", raw))

    try:
        tok = _looks_branded(name)
        if tok and str(tok).strip().strip(".,").upper() in _RP_CAPS_OK:
            tok = None
        return bool(tok or _caps_brand_token(name))
    except Exception:
        return False

