def _scrub_secret(text: Any, secret: str) -> str:
    """
    Remove an API key from any string before it is logged, printed or stored.

    Called on every exception message that could conceivably echo a request URL,
    header or payload. Never let a raw key reach a log line, a docx, or a CSV.
    """
    s = str(text)
    if secret:
        s = s.replace(secret, "***REDACTED***")
        if len(secret) > 8:
            s = s.replace(secret[:8], "***REDACTED***")
    s = re.sub(r"AIza[0-9A-Za-z\-_]{10,}", "***REDACTED***", s)
    s = re.sub(r"(?i)(api[_-]?key\s*[=:]\s*)\S+", r"\1***REDACTED***", s)
    return s

@functools.lru_cache(maxsize=200_000)
def _norm_cached(text: str) -> str:
    s = text.lower().strip()
    s = re.sub(r"[^a-z0-9%\s]", " ", s)
    s = re.sub(r"\s+", " ", s)
    return s

def _norm(text: Any) -> str:
    """
    Lowercase, collapse punctuation/whitespace. Used for all keyword matching.

    Memoized: find_substitute() normalises every one of the ~7,000 food_db names
    on each call, and _classify_flag() does the same again. Without the cache a
    plan with 30 flagged foods spends most of its runtime re-normalising the same
    strings. Cache is on the hashable str path only.
    """
    if isinstance(text, str):
        return _norm_cached(text)
    s = str(text).lower().strip()
    s = re.sub(r"[^a-z0-9%\s]", " ", s)
    s = re.sub(r"\s+", " ", s)
    return s

@functools.lru_cache(maxsize=50_000)
def _kw_pattern(needle_norm: str):
    """Compiled word-boundary pattern for a normalised keyword, plural-tolerant.

    THE PLURAL GAP. The boundary assertions below are essential (see _contains),
    but on their own they also mean `peanut` does not match "Peanuts, all types,
    raw" and `oyster` does not match "Oysters, eastern, raw". FDC and IFCT
    pluralise inconsistently -- "Peanuts", "Sardines", "Sprouts" -- so a rule
    author writing the singular silently covers less than they think, and the
    gap is invisible because the rule looks correct.

    This is why the raw-seafood rules appeared to work while raw peanuts slipped
    through two review passes: "fish", "salmon" and "tuna" happen to be their
    own plurals, so those keywords were never affected and the defect looked
    like a missing rule rather than a matcher limitation.

    An optional trailing s / es / ies is therefore accepted. This WIDENS every
    existing rule table, which is the intent -- but it means a keyword whose
    plural is an unrelated word would now over-match. None in the current tables
    are (checked: bran/brans, germ/germs, seal/seals, pea/peas all stay within
    the rule's meaning), and irregular plurals like leaf/leaves are simply not
    caught, which is no worse than before.
    """
    stem = re.escape(needle_norm)
    if needle_norm.endswith("y"):
        stem = re.escape(needle_norm[:-1]) + "(?:y|ies)"
    return re.compile(rf"(?<!\w){stem}(?:e?s)?(?!\w)")

def _contains(haystack_norm: str, needle: str) -> bool:
    """
    Word-boundary keyword test on already-normalised text.

    Boundaries are essential, not cosmetic. Plain substring matching flags
    "Interstate Brands Corp, Wonder Hamburger Rolls" as a milling by-product
    because "bran" sits inside "brands", and clears "Cornmeal, degermed" as
    containing "germ" when degermed means the germ was removed. Both confirmed
    against the FDC pool.
    """
    return bool(_kw_pattern(_norm(needle)).search(haystack_norm))

def _canonical_meal(meal_name: Any) -> str:
    """
    Map an arbitrary meal label onto a canonical type.

    "Mid-Morning Snack" -> "snack", "Supper" -> "dinner". Anything unrecognised
    returns "" which means the module expresses no opinion about it - unknown
    meals are never used as shift targets and their contents are never flagged
    as misplaced.
    """
    n = _norm(meal_name)
    if not n:
        return ""
    for alias, canon in MEAL_NAME_ALIASES.items():
        if _norm(alias) in n:
            return canon
    for canon in CANONICAL_MEALS:
        if canon in n:
            return canon
    return ""

def _cfg(column_map: Dict[str, Any], key: str, default: Any = None) -> Any:
    return (column_map or {}).get(key, default)

def _require_columns(df: pd.DataFrame, cols: Sequence[str], where: str) -> None:
    missing = [c for c in cols if c and c not in df.columns]
    if missing:
        raise KeyError(
            f"{where} is missing required column(s): {missing}. "
            f"Available columns: {list(df.columns)}. "
            f"Fix the mapping in `column_map`."
        )

def _match_rules(food_name: Any, rules: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """
    Return the first rule that fires, or None.

    A rule fires when EVERY term in its `all` list is present (if it has one),
    AND at least one term from EACH group in its `all_any` list of lists (if it
    has one), AND at least one term in its `any` list is present (if it has
    one), AND no term in its `none` list is present.

    `all` exists because some hazards are a conjunction, not a phrase. Raw egg
    is "egg" AND "raw" in any word order - matching the literal phrase "egg,
    raw" misses "Egg, whole, raw, fresh", while matching the loose phrase "raw
    white" catches "Grapefruit, raw, white". Both confirmed against the FDC
    pool.

    `all_any` exists because `all` cannot express a conjunction of disjunctions,
    and a whole CLASS of impracticality is exactly that shape: a FORM word AND a
    FOOD word, where either side has many synonyms. "Dried egg white flakes" and
    "Buttermilk, dried" are the same defect - (dried|dry|powder|flakes) AND
    (egg|milk|buttermilk|...) - but writing that with `any` alone flags every
    fresh egg, and writing it with `all` alone needs one rule per word pair.
    Both of those foods survived two full review passes because the rule table
    could not say this until now.

    `none` stops obvious false positives - "bran flakes" is a breakfast cereal,
    not a milling by-product; "beef, cooked" is not raw beef.
    """
    n = _norm(food_name)
    for rule in rules:
        pred = rule.get("predicate")
        if pred is not None:
            try:
                fired = bool(pred(food_name))
            except Exception:
                fired = False
            if fired and not any(_contains(n, kw) for kw in rule.get("none", [])):
                return rule
        all_terms = rule.get("all", [])
        if all_terms and not all(_contains(n, kw) for kw in all_terms):
            continue
        all_any_groups = rule.get("all_any", [])
        if all_any_groups and not all(
            any(_contains(n, kw) for kw in group) for group in all_any_groups
        ):
            continue
        any_terms = rule.get("any", [])
        if any_terms and not any(_contains(n, kw) for kw in any_terms):
            continue
        if not all_terms and not any_terms and not all_any_groups:
            continue
        if any(_contains(n, kw) for kw in rule.get("none", [])):
            continue
        return rule
    return None

@functools.lru_cache(maxsize=100_000)
def _classify_flag_cached(food_name: str) -> Tuple[str, str, str]:
    return _classify_flag_impl(food_name)

def _classify_flag(food_name: Any) -> Tuple[str, str, str]:
    """
    Classify a food name as UNSAFE, IMPRACTICAL, or unflagged.

    UNSAFE is evaluated first: a food that is both unsafe and impractical is a
    safety problem before it is a convenience problem.

    Returns (category, reason_key, why) - all "" when the food is fine.

    Memoized. NOTE FOR EDITORS: if you change UNSAFE_RULES or IMPRACTICAL_RULES
    at runtime (rather than editing this file), call
    _classify_flag_cached.cache_clear() afterwards or the old verdicts persist.
    """
    if isinstance(food_name, str):
        return _classify_flag_cached(food_name)
    return _classify_flag_impl(food_name)

def _rule_why(food_name: Any, rule: Dict[str, Any]) -> str:
    """The rationale for THIS food under THIS rule.

    A rule that covers several mechanisms cannot explain itself with one
    sentence. `raw_nuts_legumes_sprouts` covers Salmonella on nuts, seed-borne
    pathogens on sprouts and phytohaemagglutinin in beans - and a review caught
    it telling a reader that raw CHICKPEAS were swapped out because "raw kidney
    beans contain phytohaemagglutinin". True sentence, wrong food, and it
    quietly teaches the reader to distrust the other reasons too.

    `why_by_term` maps a trigger term to the mechanism that term implies. The
    first matching entry wins; rules without one keep their single `why`.
    """
    by_term = rule.get("why_by_term")
    if by_term:
        n = _norm(food_name)
        for term, why in by_term.items():
            if _contains(n, term):
                return why
    return rule.get("why", "")

def _classify_flag_impl(food_name: Any) -> Tuple[str, str, str]:
    """Uncached implementation of _classify_flag."""
    hit = _match_rules(food_name, UNSAFE_RULES)
    if hit:
        return "UNSAFE", hit["key"], _rule_why(food_name, hit)
    hit = _match_rules(food_name, IMPRACTICAL_RULES)
    if hit:
        return "IMPRACTICAL", hit["key"], _rule_why(food_name, hit)
    return "", "", ""

def _infer_role(food_name: Any) -> Tuple[str, Dict[str, Any]]:
    """
    Infer a food's meal role from its name using MEAL_ROLE_RULES.

    Rules are scanned in dict order and the FIRST hit wins, so order the dict
    from most specific to most general when editing. Returns ("", {}) when no
    rule matches, which means "no opinion".
    """
    n = _norm(food_name)

    if is_dessert_or_sweet(food_name):
        return "dessert_or_sweet", MEAL_ROLE_RULES["dessert_or_sweet"]

    for role, spec in MEAL_ROLE_RULES.items():
        if any(_contains(n, kw) for kw in spec["keywords"]):
            return role, spec
    return "", {}

def _build_db_index(food_db: pd.DataFrame, column_map: Dict[str, Any]) -> Dict[str, int]:
    """Map normalised food name -> positional index in food_db (first wins)."""
    db_food_col = _cfg(column_map, "db_food_col") or _cfg(column_map, "food_col")
    index: Dict[str, int] = {}
    for pos, name in enumerate(food_db[db_food_col].tolist()):
        key = _norm(name)
        if key and key not in index:
            index[key] = pos
    return index

def _lookup_nutrients(
    food_name: Any,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    db_index: Optional[Dict[str, int]] = None,
) -> Tuple[float, float, bool]:
    """
    Return (kcal_per_basis, protein_per_basis, found) for a food name.

    Exact normalised match only. No fuzzy fallback here on purpose: silently
    matching "chicken breast" to "chicken breast, fried" would misstate energy.
    Unmatched foods return (0.0, 0.0, False) and are reported to the caller.
    """
    kcal_col = _cfg(column_map, "kcal_col")
    protein_col = _cfg(column_map, "protein_col")
    db_index = db_index if db_index is not None else _build_db_index(food_db, column_map)

    pos = db_index.get(_norm(food_name))
    if pos is None:
        return 0.0, 0.0, False

    row = food_db.iloc[pos]
    kcal = pd.to_numeric(row.get(kcal_col), errors="coerce")
    protein = pd.to_numeric(row.get(protein_col), errors="coerce") if protein_col else 0.0
    return (
        float(kcal) if pd.notna(kcal) else 0.0,
        float(protein) if pd.notna(protein) else 0.0,
        True,
    )

def _attach_row_nutrients(
    meal_split: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
) -> Tuple[pd.DataFrame, List[str]]:
    """
    Attach per-row kcal and protein to the meal split.

    If column_map["meal_kcal_col"] is given, that value is trusted verbatim
    (your optimizer already computed it). Otherwise kcal is derived from food_db
    scaled by grams / nutrient_basis_g.

    Returns (dataframe_with_nutrient_cols, names_not_found_in_food_db).
    """
    df = meal_split.copy()
    food_col = _cfg(column_map, "food_col")
    grams_col = _cfg(column_map, "grams_col")
    meal_kcal_col = _cfg(column_map, "meal_kcal_col")
    basis = float(_cfg(column_map, "nutrient_basis_g", NUTRIENT_BASIS_G) or NUTRIENT_BASIS_G)

    db_index = _build_db_index(food_db, column_map)
    kcals, proteins, missing = [], [], []

    for _, row in df.iterrows():
        grams = pd.to_numeric(row.get(grams_col), errors="coerce")
        grams = float(grams) if pd.notna(grams) else 0.0
        k_basis, p_basis, found = _lookup_nutrients(row[food_col], food_db, column_map, db_index)
        if not found:
            missing.append(str(row[food_col]))

        if meal_kcal_col and meal_kcal_col in df.columns:
            v = pd.to_numeric(row.get(meal_kcal_col), errors="coerce")
            if pd.notna(v):
                kcals.append(float(v))
            else:
                kcals.append(k_basis * grams / basis if basis else 0.0)
        else:
            kcals.append(k_basis * grams / basis if basis else 0.0)
        proteins.append(p_basis * grams / basis if basis else 0.0)

    df[ROW_KCAL_COL] = kcals
    df[ROW_PROTEIN_COL] = proteins
    return df, sorted(set(missing))

def derive_meal_kcal_bands(
    meal_split: pd.DataFrame,
    column_map: Dict[str, Any],
    food_db: Optional[pd.DataFrame] = None,
    tolerance_pct: float = TOLERANCE_PCT,
) -> Dict[str, Tuple[float, float]]:
    """
    Fallback band derivation: +/- tolerance_pct around each meal's current kcal.

    Used only when the optimizer does not expose explicit bands. Because the
    bands are derived from the plan itself, every meal starts perfectly in band
    and the shift logic still has a real constraint to respect.
    """
    meal_col = _cfg(column_map, "meal_col")
    df = meal_split
    if ROW_KCAL_COL not in df.columns:
        if food_db is None:
            raise ValueError("derive_meal_kcal_bands needs food_db to compute kcal.")
        df, _ = _attach_row_nutrients(df, food_db, column_map)

    bands: Dict[str, Tuple[float, float]] = {}
    for meal, grp in df.groupby(meal_col, sort=False):
        total = float(grp[ROW_KCAL_COL].sum())
        bands[str(meal)] = (total * (1.0 - tolerance_pct), total * (1.0 + tolerance_pct))
    return bands

def flag_foods(meal_split: pd.DataFrame, column_map: Dict[str, Any]) -> pd.DataFrame:
    """
    Flag foods needing SUBSTITUTION.

    Adds three columns:
      flag_category   - "UNSAFE", "IMPRACTICAL", or "" (fine as-is)
      flag_reason_key - the rule key that fired, e.g. "raw_egg"
      flag_why        - the rule's plain-English rationale, for the audit log

    Pure and side-effect free: returns a copy, changes no portion, moves nothing.
    """
    food_col = _cfg(column_map, "food_col")
    _require_columns(meal_split, [food_col], "meal_split")

    df = meal_split.copy()
    cats, keys, whys = [], [], []
    for name in df[food_col]:
        cat, key, why = _classify_flag(name)
        cats.append(cat)
        keys.append(key)
        whys.append(why)
    df["flag_category"] = cats
    df["flag_reason_key"] = keys
    df["flag_why"] = whys
    return df

def _resolve_nutrient_cols(food_db: pd.DataFrame, column_map: Dict[str, Any]) -> List[str]:
    """
    Decide which food_db columns define 'nutritionally similar'.

    Explicit column_map["nutrient_cols"] always wins. Otherwise numeric columns
    whose names look like nutrients are auto-selected, and kcal/protein are
    always forced in so energy and protein always drive the match.
    """
    explicit = _cfg(column_map, "nutrient_cols")
    kcal_col = _cfg(column_map, "kcal_col")
    protein_col = _cfg(column_map, "protein_col")

    if explicit:
        cols = [c for c in explicit if c in food_db.columns]
    else:
        cols = []
        for c in food_db.columns:
            if not pd.api.types.is_numeric_dtype(food_db[c]):
                continue
            cl = str(c).lower()
            if any(h in cl for h in DEFAULT_NUTRIENT_HINTS):
                cols.append(c)

    for forced in (kcal_col, protein_col):
        if forced and forced in food_db.columns and forced not in cols:
            cols.append(forced)
    return cols

def _scaled_matrix(food_db: pd.DataFrame, nutrient_cols: List[str]) -> pd.DataFrame:
    """
    Max-scale each nutrient column into [0, 1].

    Scaling keeps every component non-negative, so cosine similarity also lands
    in [0, 1] and LOW_CONFIDENCE_SIMILARITY = 0.60 means what it looks like.
    Without scaling, kcal (hundreds) would swamp zinc (single digits).
    """
    m = food_db[nutrient_cols].apply(pd.to_numeric, errors="coerce").fillna(0.0).abs()
    denom = m.max(axis=0).replace(0.0, 1.0)
    return m.divide(denom, axis=1)

def find_substitute(
    food_row: pd.Series,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    exclude_flagged: Sequence[str] = (),
) -> List[Dict[str, Any]]:
    """
    Find the closest nutritional matches to `food_row` FROM food_db ONLY.

    NO FOOD INVENTION: every candidate returned is an actual row of food_db.
    Nothing is generated, guessed, or recalled from general knowledge.

    Candidates are filtered to the same broad food group when a group column is
    available (a 'similar' food from a different group is usually a bad swap on
    the plate even when the nutrient vector agrees). If that leaves fewer than
    MIN_CANDIDATES_IN_GROUP options, the search relaxes to the whole database
    and sets group_relaxed=True on each result so the report can say so.

    Excluded from consideration: the food itself, any name in `exclude_flagged`,
    and - importantly - any candidate that would itself trip the UNSAFE or
    IMPRACTICAL rules. Replacing raw salmon with raw tuna is not a fix.

    Returns up to TOP_N_SUBSTITUTES dicts:
        {"food_name", "score", "group", "group_relaxed", "db_index"}
    sorted best-first. Returns [] when nothing acceptable exists.
    """
    food_col = _cfg(column_map, "food_col")
    db_food_col = _cfg(column_map, "db_food_col") or food_col
    group_col = _cfg(column_map, "group_col")

    original_name = str(food_row[food_col])
    nutrient_cols = _resolve_nutrient_cols(food_db, column_map)
    if not nutrient_cols:
        return []

    db = food_db.reset_index(drop=True)
    scaled = _scaled_matrix(db, nutrient_cols)

    db_index = _build_db_index(db, column_map)
    pos = db_index.get(_norm(original_name))
    if pos is None:
        return []
    target_vec = scaled.iloc[pos]

    banned = {_norm(original_name)} | {_norm(x) for x in exclude_flagged}
    names_norm = db[db_food_col].map(_norm)

    eligible = ~names_norm.isin(banned)

    self_flagged = db[db_food_col].map(lambda n: bool(_classify_flag(n)[0]))
    eligible &= ~self_flagged

    group_relaxed = False
    if group_col and group_col in db.columns:
        target_group = db.iloc[pos].get(group_col)
        if pd.notna(target_group):
            in_group = eligible & (db[group_col] == target_group)
            if int(in_group.sum()) >= MIN_CANDIDATES_IN_GROUP:
                eligible = in_group
            else:
                group_relaxed = True

    cand_idx = list(db.index[eligible])
    if not cand_idx:
        return []

    cand = scaled.loc[cand_idx]
    if SIMILARITY_METRIC == "euclidean":
        dist = ((cand - target_vec) ** 2).sum(axis=1) ** 0.5
        scores = 1.0 / (1.0 + dist)
    else:
        num = cand.mul(target_vec, axis=1).sum(axis=1)
        den = ((cand ** 2).sum(axis=1) ** 0.5) * float((target_vec ** 2).sum() ** 0.5)
        scores = (num / den.replace(0.0, pd.NA)).fillna(0.0)

    top = scores.sort_values(ascending=False).head(
        max(int(SUBSTITUTE_SEARCH_DEPTH), int(TOP_N_SUBSTITUTES)))

    kcal_col_db = _cfg(column_map, "kcal_col")
    if ENERGY_DENSITY_WEIGHT > 0.0 and kcal_col_db and kcal_col_db in db.columns:
        dens = pd.to_numeric(db[kcal_col_db], errors="coerce")
        target_dens = float(dens.iloc[pos]) if pd.notna(dens.iloc[pos]) else 0.0
        if target_dens > 0.0:
            adj = {}
            for idx, sc in top.items():
                d = dens.get(idx)
                if pd.isna(d) or float(d) <= 0.0:
                    adj[idx] = float(sc)
                    continue
                ratio = min(float(d), target_dens) / max(float(d), target_dens)
                adj[idx] = float(sc) * (1.0 - ENERGY_DENSITY_WEIGHT * (1.0 - ratio))
            top = pd.Series(adj).sort_values(ascending=False)

    out: List[Dict[str, Any]] = []
    for idx, score in top.items():
        out.append({
            "food_name": str(db.at[idx, db_food_col]),
            "score": float(score),
            "group": (str(db.at[idx, group_col])
                      if group_col and group_col in db.columns else ""),
            "group_relaxed": group_relaxed,
            "db_index": int(idx),
        })
    return out

def build_reason(
    flag_category: str,
    original_food: str,
    replacement_food: str,
    why: str = "",
    score: float = 0.0,
    grams: float = 0.0,
) -> str:
    """
    Render the human-readable justification for a substitution.

    Wording lives in REASON_TEMPLATES so the clinical voice can be edited in one
    place. `why` is the rule rationale so the reader sees the actual mechanism,
    not just a category label.
    """
    key = flag_category if replacement_food else "NO_SUBSTITUTE"
    template = REASON_TEMPLATES.get(key, REASON_TEMPLATES["NO_SUBSTITUTE"])
    return template.format(
        original=original_food,
        replacement=replacement_food,
        category=flag_category,
        why=(why or "no rationale recorded"),
        score=score,
        grams=grams,
    )

def apply_substitutions(meal_split: pd.DataFrame, log_rows: List[Dict[str, Any]]) -> pd.DataFrame:
    """
    Write accepted substitutions into the meal split.

    PORTIONS ARE PRESERVED EXACTLY - only the food name changes. This module
    never re-optimizes grams; the optimizer's portion decision stands.

    Matching is by ROW_ID_COL, so duplicate food names in different meals cannot
    be confused with one another.
    """
    df = meal_split.copy()
    for entry in log_rows:
        if not entry.get("substitution_applied"):
            continue
        rid = entry.get("row_id")
        col = entry["_food_col"]
        mask = df[ROW_ID_COL] == rid
        if mask.any():
            df.loc[mask, col] = entry["replacement_food"]
            if entry.get("portion_rescaled") and entry.get("_grams_col"):
                gcol = entry["_grams_col"]
                if gcol in df.columns:
                    df[gcol] = df[gcol].astype(float)
                    df.loc[mask, gcol] = float(entry["grams_rescaled"])
    return df

def flag_misplaced_foods(meal_split: pd.DataFrame, column_map: Dict[str, Any]) -> pd.DataFrame:
    """
    Flag foods that are nutritionally fine but sitting in an odd meal.

    A row is flagged only when BOTH are true:
      * its role is inferable from MEAL_ROLE_RULES, and
      * the canonical type of its current meal is not in that role's meal list.

    Foods with no inferable role, and foods in meals whose name does not map to
    a canonical type, are never flagged - the module has no opinion there and
    silence must not be read as approval.

    Adds: misplaced (bool), misplaced_role, misplaced_why, misplaced_targets
    (preference-ordered list of canonical meal types this food would suit).
    """
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    _require_columns(meal_split, [food_col, meal_col], "meal_split")

    df = meal_split.copy()
    flags, roles, whys, targets = [], [], [], []

    for _, row in df.iterrows():
        role, spec = _infer_role(row[food_col])
        current_canon = _canonical_meal(row[meal_col])
        if not role or not current_canon:
            flags.append(False); roles.append(role); whys.append(""); targets.append([])
            continue
        if current_canon in spec["meals"]:
            flags.append(False); roles.append(role); whys.append(""); targets.append([])
            continue
        flags.append(True)
        roles.append(role)
        whys.append(spec["why"])
        targets.append(list(spec["meals"]))

    df["misplaced"] = flags
    df["misplaced_role"] = roles
    df["misplaced_why"] = whys
    df["misplaced_targets"] = targets
    return df

def find_valid_shift(
    food_row: pd.Series,
    current_meal: str,
    target_meal_candidates: Sequence[str],
    current_meal_kcal: Dict[str, float],
    meal_kcal_bands: Dict[str, Tuple[float, float]],
    column_map: Dict[str, Any],
    blocked_reasons_out: Optional[List[str]] = None,
) -> Optional[str]:
    """
    Return the first target meal that can accept this food WITHOUT breaking any
    calorie band, or None if no candidate works.

    HARD CONSTRAINT. For each candidate, in preference order, both must hold:
      * origin  meal kcal MINUS this food stays within the origin's band, and
      * target  meal kcal PLUS  this food stays within the target's band.

    A shift that would push either meal outside its band is refused outright -
    the bands are the optimizer's own guarantee and this module has no mandate
    to renegotiate them for the sake of a cosmetic improvement.

    `current_meal_kcal` must be the LIVE running totals, so that when shifts are
    processed one at a time each check sees the effect of the previous shift.

    `blocked_reasons_out`, if provided, collects a human-readable reason per
    rejected candidate (the return type stays str | None as specified).
    """
    kcal = float(food_row[ROW_KCAL_COL])
    reasons = blocked_reasons_out if blocked_reasons_out is not None else []

    origin_band = meal_kcal_bands.get(current_meal)
    if origin_band is None:
        reasons.append(f"no calorie band is defined for '{current_meal}', so the "
                       f"shift cannot be verified")
        return None
    o_min, o_max = float(origin_band[0]), float(origin_band[1])
    origin_after = float(current_meal_kcal.get(current_meal, 0.0)) - kcal

    if origin_after < o_min:
        reasons.append(
            f"removing {kcal:.0f} kcal would drop {current_meal} to "
            f"{origin_after:.0f} kcal, below its band minimum of {o_min:.0f} kcal "
            f"(short by {o_min - origin_after:.0f} kcal)"
        )
        return None
    if origin_after > o_max:
        reasons.append(
            f"{current_meal} is already above its band maximum of {o_max:.0f} kcal"
        )
        return None

    for target in target_meal_candidates:
        if target == current_meal:
            continue
        band = meal_kcal_bands.get(target)
        if band is None:
            reasons.append(f"no calorie band is defined for '{target}'")
            continue
        t_min, t_max = float(band[0]), float(band[1])
        target_after = float(current_meal_kcal.get(target, 0.0)) + kcal
        if target_after > t_max:
            reasons.append(
                f"would exceed {target}'s kcal band by "
                f"{target_after - t_max:.0f} kcal "
                f"({target_after:.0f} vs max {t_max:.0f})"
            )
            continue
        if target_after < t_min:
            reasons.append(
                f"{target} would still sit {t_min - target_after:.0f} kcal below "
                f"its band minimum of {t_min:.0f} kcal"
            )
            continue
        return target

    return None

def apply_meal_shifts(meal_split: pd.DataFrame, shift_log_rows: List[Dict[str, Any]]) -> pd.DataFrame:
    """
    Move rows into their new meal for every APPLIED shift in the log.

    The band arithmetic already happened one shift at a time in
    _plan_meal_shifts(), which re-derives both meals' running kcal totals after
    each decision - so by the time we get here the approved set is jointly
    consistent and can be written in one pass. Blocked entries are ignored.
    """
    df = meal_split.copy()
    for entry in shift_log_rows:
        if not entry.get("shift_applied"):
            continue
        mask = df[ROW_ID_COL] == entry.get("row_id")
        if mask.any():
            df.loc[mask, entry["_meal_col"]] = entry["target_meal"]
    return df

def _consolidate_duplicates(
    meal_split: pd.DataFrame,
    column_map: Dict[str, Any],
) -> Tuple[pd.DataFrame, List[str]]:
    """
    Sum grams for identical foods appearing more than once within the same meal.

    Totals are unaffected - this is a presentation fix, not a re-optimization.
    It matters because substitutions and shifts can both land a food next to a
    copy of itself. Returns (dataframe, human-readable descriptions of merges).
    """
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    grams_col = _cfg(column_map, "grams_col")

    key = meal_split[meal_col].astype(str) + "||" + meal_split[food_col].astype(str)
    dupes = key[key.duplicated(keep=False)]
    if dupes.empty:
        return meal_split, []

    merged_desc: List[str] = []
    keep_idx: List[Any] = []
    df = meal_split.copy()
    for k in dupes.unique():
        rows = df[key == k]
        total = float(pd.to_numeric(rows[grams_col], errors="coerce").fillna(0).sum())
        first = rows.index[0]
        df.loc[first, grams_col] = total
        keep_idx.extend(rows.index[1:])
        meal, food = k.split("||", 1)
        merged_desc.append(
            f"'{food}' appeared {len(rows)} times in {meal} after adjustments; "
            f"the lines were combined into a single {total:.0f} g portion "
            f"(total grams unchanged)."
        )
    df = df.drop(index=keep_idx)
    return df.reset_index(drop=True), merged_desc

def _plan_meal_swaps(
    meal_split: pd.DataFrame,
    blocked: List[Dict[str, Any]],
    running: Dict[str, float],
    meal_kcal_bands: Dict[str, Tuple[float, float]],
    column_map: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """
    Rescue shifts that a SINGLE move cannot make, by exchanging two foods.

    THE DEADLOCK THIS EXISTS FOR. A review found one A.M. Snack holding three
    separate protein mains - roasted chicken, canned tuna and almond butter -
    while the Lunch beside it was an apple and a glass of milk. Every one of
    those three shifts had been correctly blocked, each with the same true
    reason: removing that item would drop the snack below its calorie floor.
    Each decision was right and the outcome was absurd.

    The reason a single move cannot escape it is arithmetic. Moving X out of a
    meal that is already near its floor always breaks the floor, no matter which
    X you pick, so an item-at-a-time planner has no legal move available and
    correctly reports that. A SWAP does not have that problem: X leaves and Y
    arrives in the same step, so the origin's total moves by the DIFFERENCE
    rather than by the whole of X. Where that difference is small, both meals
    can stay in band and the misplaced food still gets where it belongs.

    Only the food being rescued has to be misplaced. Its counterpart is an
    ordinary food moving the other way, which is why the swap is checked against
    both bands rather than assumed safe.

    Returns extra log entries. Never re-decides an already-applied shift.
    """
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    out: List[Dict[str, Any]] = []
    if not blocked:
        return out

    moved_rows: set = set()

    for entry in blocked:
        rid = entry.get("row_id")
        if rid in moved_rows:
            continue
        src = str(entry.get("original_meal") or "")
        targets = [t for t in (entry.get("_target_names") or []) if t and t != src]
        if not targets:
            continue

        rows = meal_split[meal_split[ROW_ID_COL] == rid]
        if rows.empty:
            continue
        out_kcal = float(rows.iloc[0][ROW_KCAL_COL])

        s_band = meal_kcal_bands.get(src)
        if not s_band:
            continue

        def _partner_suits_meal(pname: str, dest_meal: str) -> bool:
            """Would this food be a defensible thing to find in dest_meal?

            Deliberately permissive: it rejects only what is clearly wrong,
            because an exchange that cannot find a partner leaves the
            ORIGINAL misplacement in place, and a wrong-ish partner is
            usually better than a wrong main. It rejects two things:
            ingredient-only foods anywhere, and foods whose inferred role
            excludes the destination slot.
            """
            if is_ingredient_not_a_dish(pname):
                return False
            role, spec = _infer_role(pname)
            allowed = (spec or {}).get("meals") or []
            if not role or not allowed:
                return True
            slot = MEAL_NAME_ALIASES.get(str(dest_meal).strip().lower(), "")
            if not slot:
                return True
            return slot in allowed

        best_swap = None
        for tgt in targets:
            t_band = meal_kcal_bands.get(tgt)
            if not t_band:
                continue
            partners = meal_split[
                (meal_split[meal_col].astype(str) == tgt)
                & (~meal_split[ROW_ID_COL].isin(moved_rows))
            ]
            for _, p in partners.iterrows():
                p_name = str(p[food_col])

                if not _partner_suits_meal(p_name, src):
                    continue

                in_kcal = float(p[ROW_KCAL_COL])
                s_after = running.get(src, 0.0) - out_kcal + in_kcal
                t_after = running.get(tgt, 0.0) - in_kcal + out_kcal
                if not (s_band[0] <= s_after <= s_band[1]):
                    continue
                if not (t_band[0] <= t_after <= t_band[1]):
                    continue
                cost = (abs(s_after - sum(s_band) / 2.0)
                        + abs(t_after - sum(t_band) / 2.0))
                if best_swap is None or cost < best_swap[0]:
                    best_swap = (cost, tgt, p, s_after, t_after, in_kcal)

        if best_swap is None:
            continue

        _, tgt, partner, s_after, t_after, in_kcal = best_swap
        entry["shift_applied"] = True
        entry["target_meal"] = tgt
        entry["blocked_reason"] = ""
        entry["resolved_by_swap"] = True
        entry["reason"] = (
            entry.get("reason", "")
            + f" A single move was blocked by {src}'s calorie floor, so this "
              f"was resolved as an EXCHANGE with "
              f"'{str(partner[food_col])}' moving the other way."
        )
        out.append({
            "type": "MEAL SHIFT",
            "row_id": partner[ROW_ID_COL],
            "food": str(partner[food_col]),
            "original_meal": tgt,
            "target_meal": src,
            "kcal_moved": round(in_kcal, 1),
            "reason": (
                f"Counterpart of the exchange that moved "
                f"'{entry['food']}' out of {src}. Moved to keep both meals "
                f"inside their calorie bands; it was not itself misplaced."
            ),
            "shift_applied": True,
            "blocked_reason": "",
            "resolved_by_swap": True,
            "_meal_col": meal_col,
        })
        running[src], running[tgt] = s_after, t_after
        moved_rows.add(rid)
        moved_rows.add(partner[ROW_ID_COL])

    return out

def _plan_meal_shifts(
    meal_split: pd.DataFrame,
    meal_kcal_bands: Dict[str, Tuple[float, float]],
    column_map: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """
    Decide which flagged-misplaced foods can actually move.

    Shifts are evaluated ONE AT A TIME against live running kcal totals: after
    each approval the origin and destination totals are updated, so the next
    decision sees the true state. Approving them in bulk against stale totals
    could collectively break a band even though each looked fine alone.

    Larger-kcal items are considered first - they are the ones most likely to be
    blocked, and letting small items move first would consume the headroom they
    need.
    """
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")

    running: Dict[str, float] = (
        meal_split.groupby(meal_col)[ROW_KCAL_COL].sum().astype(float).to_dict()
    )
    by_canon: Dict[str, List[str]] = {}
    for meal in meal_split[meal_col].astype(str).unique():
        canon = _canonical_meal(meal)
        if canon:
            by_canon.setdefault(canon, []).append(meal)

    candidates = meal_split[meal_split["misplaced"]].copy()
    candidates = candidates.sort_values(ROW_KCAL_COL, ascending=False)

    log: List[Dict[str, Any]] = []
    for _, row in candidates.iterrows():
        current_meal = str(row[meal_col])
        target_names: List[str] = []
        for canon in row["misplaced_targets"]:
            for actual in by_canon.get(canon, []):
                if actual != current_meal and actual not in target_names:
                    target_names.append(actual)

        reasons: List[str] = []
        chosen = find_valid_shift(
            food_row=row,
            current_meal=current_meal,
            target_meal_candidates=target_names,
            current_meal_kcal=running,
            meal_kcal_bands=meal_kcal_bands,
            column_map=column_map,
            blocked_reasons_out=reasons,
        )

        entry: Dict[str, Any] = {
            "type": "MEAL SHIFT",
            "row_id": row[ROW_ID_COL],
            "food": str(row[food_col]),
            "original_meal": current_meal,
            "target_meal": chosen or "",
            "kcal_moved": round(float(row[ROW_KCAL_COL]), 1),
            "reason": (
                f"Role '{row['misplaced_role']}': {row['misplaced_why']} "
                f"Currently placed in {current_meal}."
            ),
            "shift_applied": bool(chosen),
            "blocked_reason": "" if chosen else (
                "; ".join(reasons) if reasons
                else "no candidate meal of a suitable type exists in this plan"
            ),
            "resolved_by_swap": False,
            "_meal_col": meal_col,
            "_target_names": list(target_names),
        }
        log.append(entry)

        if chosen:
            running[current_meal] = running.get(current_meal, 0.0) - float(row[ROW_KCAL_COL])
            running[chosen] = running.get(chosen, 0.0) + float(row[ROW_KCAL_COL])

    log.extend(_plan_meal_swaps(
        meal_split=meal_split,
        blocked=[e for e in log if not e["shift_applied"]],
        running=running,
        meal_kcal_bands=meal_kcal_bands,
        column_map=column_map,
    ))
    return log

def summarize_micronutrients(
    rebuilt_meal_split: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    person: Any = None,
) -> pd.DataFrame:
    """
    Day-total micronutrients for the REBUILT plan, against RDA and UL.

    WHY THIS EXISTS. summarize_nutrition() reports kcal and protein only, so
    after a rebuild there was no way to confirm that substitutions had not
    moved iodine, zinc or any other watch-item -- a reviewer noted exactly that
    gap. Substitutions swap whole foods and rescale portions, both of which
    move micronutrients around far more than they move energy, so the rebuild
    is precisely when these need re-checking rather than being assumed
    unchanged from the optimizer's run.

    DISPLAY AND VERIFICATION ONLY. Nothing here feeds back into portioning, and
    a UL exceedance is REPORTED, not corrected -- correcting it would mean
    re-optimizing, which this module does not do.

    Columns are matched by the RDA_AI key names against food_db's columns, so a
    nutrient absent from the database is simply absent from the table rather
    than reported as zero. Returns an empty frame when nothing can be matched.
    """
    df = rebuilt_meal_split
    grams_col = _cfg(column_map, "grams_col")
    food_col = _cfg(column_map, "food_col")
    db_food_col = _cfg(column_map, "db_food_col") or food_col
    basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0

    try:
        rda = micronutrient_rda(person) if person is not None else {}
        ul = micronutrient_ul(person) if person is not None else {}
    except Exception:
        rda, ul = {}, {}

    db_idx = _build_db_index(food_db.reset_index(drop=True), column_map)
    db = food_db.reset_index(drop=True)

    keys = [k for k in (rda.keys() or []) if k in db.columns] or [
        c for c in db.columns
        if c not in (db_food_col,) and pd.api.types.is_numeric_dtype(db[c])
    ]
    if not keys:
        return pd.DataFrame()

    totals: Dict[str, float] = {k: 0.0 for k in keys}
    for _, row in df.iterrows():
        pos = db_idx.get(_norm(row.get(food_col)))
        if pos is None:
            continue
        g = pd.to_numeric(row.get(grams_col), errors="coerce")
        g = float(g) if pd.notna(g) else 0.0
        for k in keys:
            v = pd.to_numeric(db.iloc[pos].get(k), errors="coerce")
            if pd.notna(v):
                totals[k] += float(v) * g / basis

    out: List[Dict[str, Any]] = []
    for k in keys:
        r, u = rda.get(k), ul.get(k)
        amt = totals[k]
        out.append({
            "nutrient": k,
            "day_total": round(amt, 2),
            "rda": r,
            "pct_rda": round(100.0 * amt / r, 1) if r else None,
            "ul": u,
            "pct_ul": round(100.0 * amt / u, 1) if u else None,
            "below_rda": bool(r and amt < r),
            "over_ul": bool(u and amt > u),
        })
    return pd.DataFrame(out)

def summarize_nutrition(
    rebuilt_meal_split: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    meal_kcal_bands: Optional[Dict[str, Tuple[float, float]]] = None,
) -> pd.DataFrame:
    """
    Per-meal and daily kcal/protein, computed AFTER substitutions and shifts.

    DISPLAY AND VERIFICATION ONLY - nothing here feeds back into portioning.

    Each meal is checked against its band. Shifts are already band-checked, so
    an out-of-band meal here should only ever come from a substitution's kcal
    delta (the replacement food's energy density differing from the original).

    Returns one row per meal plus a TOTAL row, with columns:
      meal | kcal | protein_g | band_min | band_max | in_band
    """
    meal_col = _cfg(column_map, "meal_col")
    df = rebuilt_meal_split
    if ROW_KCAL_COL not in df.columns:
        df, _ = _attach_row_nutrients(df, food_db, column_map)

    rows: List[Dict[str, Any]] = []
    for meal, grp in df.groupby(meal_col, sort=False):
        kcal = float(grp[ROW_KCAL_COL].sum())
        protein = float(grp[ROW_PROTEIN_COL].sum())
        band = (meal_kcal_bands or {}).get(str(meal))
        rows.append({
            "meal": str(meal),
            "kcal": round(kcal, 1),
            "protein_g": round(protein, 1),
            "band_min": round(float(band[0]), 1) if band else None,
            "band_max": round(float(band[1]), 1) if band else None,
            "in_band": (bool(band[0] <= kcal <= band[1]) if band else None),
        })

    rows.append({
        "meal": "TOTAL (day)",
        "kcal": round(float(df[ROW_KCAL_COL].sum()), 1),
        "protein_g": round(float(df[ROW_PROTEIN_COL].sum()), 1),
        "band_min": None, "band_max": None, "in_band": None,
    })
    return pd.DataFrame(rows)

COOKING_FORM_OVERRIDES: List[Dict[str, Any]] = [
    {
        "keywords": ["canned", "tinned", "cooked", "precooked", "pre cooked",
                     "ready to eat", "roasted", "boiled", "steamed", "smoked",
                     "cured", "pasteurized", "pasteurised"],
        "not": ["for cooking", "to be cooked", "uncooked", "raw",
                "dry roasted", "oil roasted"],
        "method": "reheat only",
        "note": "Already cooked. Warm through if serving hot, or use straight "
                "from the tin or pack. Do NOT cook it again and do NOT wait "
                "for a raw-to-cooked doneness cue.",
    },
    {
        "keywords": ["raisin", "sultana", "currant", "apricot", "date", "fig",
                     "prune", "cranberry", "dried fruit", "dried mango"],
        "not": ["juice", "paste", "syrup", "fresh", "raw", "canned",
                "frozen", "cooked"],
        "method": "serve as-is",
        "note": "Eaten dried, as it comes. No cooking or soaking needed.",
    },
    {
        "keywords": ["dried", "dry", "dehydrated", "powder", "powdered",
                     "flakes", "granules", "instant", "milk solids"],
        "not": ["drained", "drained solids", "fruit", "raisin", "apricot",
                "date", "fig", "prune", "cranberry", "canned",
                "dry roasted", "dry heat", "dry curd", "raw", "fresh"],
        "method": "rehydrate",
        "note": "Already dehydrated. Reconstitute in the measured liquid "
                "already in this meal; do not cook further and do not judge it "
                "by the doneness of the fresh form.",
    },
]

def _form_override(haystack: str) -> Optional[Dict[str, str]]:
    """First matching form override for a normalised name+category, or None."""
    for rule in COOKING_FORM_OVERRIDES:
        if not any(_contains(haystack, kw) for kw in rule["keywords"]):
            continue
        if any(_contains(haystack, kw) for kw in rule.get("not", [])):
            continue
        return {"method": rule["method"], "note": rule["note"]}
    return None

def assign_cooking_method(food_name: str, category: str = "") -> Dict[str, str]:
    """
    Assign a preparation method to a food ALREADY in the plan.

    Never introduces a food. Note that the notes deliberately avoid instructions
    like "fry in oil" or "season to taste" - oil and salt would be invented
    ingredients, which this module forbids.

    FORM IS CHECKED BEFORE FOOD. A canned, dried or otherwise pre-prepared item
    takes its method from its form, not from its species - see
    COOKING_FORM_OVERRIDES. Without that ordering the table instructs the cook
    to cook already-cooked food and to look for doneness cues that cannot occur.

    `category` (from food_db, if you mapped category_col) is searched alongside
    the name so a well-categorised DB improves the match. Unmatched foods get
    DEFAULT_COOKING_METHOD rather than a guess.
    """
    haystack = f"{_norm(food_name)} {_norm(category)}"

    spec = dry_prep_requirement(food_name)
    if spec:
        bits = []
        if float(spec["soak_hours"]) > 0:
            bits.append(f"Soak in cold water about "
                        f"{int(spec['soak_hours'])} h (start the night "
                        f"before), then drain and discard the water.")
        if float(spec["hard_boil_min"]) > 0:
            bits.append(f"Boil hard for a full "
                        f"{int(spec['hard_boil_min'])} min, then reduce to a "
                        f"simmer.")
        bits.append(f"Cook {spec['typical_cook_min']}; never less than "
                    f"{int(spec['min_cook_min'])} min.")
        bits.append(spec["safety"])
        return {"method": spec["method"], "note": " ".join(bits)}

    if is_ready_to_eat(food_name) and not _form_override(haystack):
        form = food_prep_form(food_name)
        if form == "quick_dry":
            return {"method": "rehydrate briefly",
                    "note": "Dehydrated but fast. Reconstitute in the "
                            "measured liquid already in this meal, a few "
                            "minutes at most. Do NOT soak it for hours."}
        return {"method": "use as bought",
                "note": "Already cooked, canned, cultured or milled. Drain "
                        "and rinse if it came in liquid, then warm through "
                        "briefly if the dish is hot. Do NOT soak it and do "
                        "NOT cook it from raw."}

    override = _form_override(haystack)
    if override:
        return override

    for rule in FOOD_CATEGORY_COOKING_RULES:
        if any(_contains(haystack, kw) for kw in rule["keywords"]):
            need = rule.get("requires_form")
            if need and food_prep_form(food_name) not in need:
                continue
            return {"method": rule["method"], "note": rule["note"]}
    return dict(DEFAULT_COOKING_METHOD)

GEMINI_PROMPT_TEMPLATE = """You are a registered dietitian writing a single, \
practical, fully detailed recipe card for one meal of a prescribed diet plan. \
The person cooking it may be an inexperienced cook following it exactly, with \
nothing else in the kitchen.

MEAL: {meal_name}
TARGET FOR THIS MEAL: approximately {kcal:.0f} kcal and {protein:.1f} g protein.

INGREDIENTS AVAILABLE (this is the complete and only list):
{ingredient_block}
{prep_form_block}{mandatory_prep_block}
ABSOLUTE RULES - a response that breaks any of these is discarded:
1. Use ONLY the ingredients listed above. Do not add, suggest, or imply any \
additional ingredient, seasoning, garnish, or side - including common staples \
like salt, oil, butter, water, stock, herbs, spices, sugar, or lemon - unless it \
is already present in the ingredient list provided.
2. Do not rename the ingredients. Reproduce each name exactly as written above.
3. Do not change any gram amount. The amounts are fixed and already optimized.
4. Do not contradict the assigned cooking method for any ingredient.
5. Do not mention any ingredient in the steps that is not in the list above.
6. Do not recommend serving it "with" anything.

HOW TO SPEND THE DETAIL. The rules above cap WHAT may appear; they do not cap \
HOW MUCH you say about it. Write the detail into the PROCESS, never into the \
ingredient list:
- Give every step a heat level, a pan or vessel, and a time or a time range.
- Give every step a SENSORY DONENESS CUE - what it looks, smells or feels like \
when it is ready - because timings vary by equipment.
- State the gram amount inside the step itself the first time an ingredient \
enters, using the exact amount given above.
- Say what to do while something cooks, so the steps run in a workable order.
- ONE PAN OR ONE POT WHERE POSSIBLE. Write the method so the meal can be made in a single skillet or a single saucepan, sequencing the steps so items that need the pan first go first and later items join them. Only call for a second vessel when the dish genuinely cannot be made otherwise, and say why.
- COMMON EQUIPMENT ONLY: a skillet, a saucepan, a baking tray, a bowl, a sieve, a knife and a board. Do not call for a blender, food processor, thermometer, mandoline, sous-vide, air fryer or any specialty tool.
- If a canned ingredient is listed, say to DRAIN AND RINSE IT under cold running water for about 30 seconds and drain again. This removes a large part of the packing sodium and is the single most useful thing a cook can do about salt when salt itself cannot be adjusted.
- Name the equipment needed, and give a realistic total time and a yield.
- Flag the one mistake most likely to ruin this particular dish.
- Say how to store leftovers and how to reheat them, or say it must be eaten \
fresh.
- Do NOT pad with adjectives or restaurant language. Every added sentence must \
tell the cook something they would otherwise have to guess.

WATER AND COOKING LIQUID. Rule 1 forbids adding ingredients, and that has been \
misread as forbidding the MENTION of water, producing sentences like "fill a pot \
with enough liquid extracted or available from the canned ingredients or use dry \
rehydration techniques". That is not required and is worse than saying nothing.

Water for boiling, steaming, soaking or rehydrating is not an ingredient - it \
carries no energy and no nutrients, none of it is being counted, and every \
kitchen has it. Say plainly "bring a pot of water to the boil" or "cover with \
warm water and leave for 10 minutes" whenever that is what the step needs.

What rule 1 actually forbids is water that becomes part of what is eaten in a way \
that changes the dish - stock, broth, brine, juice, milk or any flavoured liquid \
not in the list above. Do not add those. If a step needs a flavourful liquid and \
none is listed, use plain water and say so directly rather than writing around it.

Return ONLY a JSON object, with no prose before or after it and no markdown code \
fences, in exactly this shape:
{{
  "title": "short name for the dish",
  "yield_note": "what this makes, e.g. one serving, about 350 g plated",
  "total_time": "e.g. 25 minutes, 10 active",
  "equipment": ["pan or tool needed", "..."],
  "ingredients": [{{"name": "exact name from the list", "amount": "e.g. 120 g", \
"prep_note": "how it is cut, drained, soaked or brought to temperature"}}],
  "steps": [
    {{"instruction": "what to do, with the gram amount and the heat level", \
"duration": "e.g. 4-5 minutes", "cue": "how you know it is ready"}}
  ],
  "common_mistake": "the single error most likely to ruin this dish",
  "storage": "how to keep and reheat it, or that it must be eaten fresh",
  "approx_note": "one sentence noting the figures are approximate"
}}"""

RECIPE_PROSE_FIELDS: Tuple[str, ...] = (
    "steps", "equipment", "common_mistake", "storage",
    "yield_note", "total_time", "title",
)

def _model_accepts_sampling_params(model: str) -> bool:
    """
    True if this model still accepts temperature/top_p/top_k.

    Google deprecated those parameters on the Gemini 3.6+ Flash line; sending
    them to a model that rejects them would fail every recipe call and silently
    drop the whole run to templated fallbacks. So we only send GEMINI_TEMPERATURE
    to model families known to accept it.
    """
    m = (model or "").lower()
    return any(m.startswith(p) for p in GEMINI_SAMPLING_PARAM_MODEL_PREFIXES)

def _gemini_generation_config(model: str) -> Dict[str, Any]:
    """Build the generation config appropriate to the target model."""
    cfg: Dict[str, Any] = {}
    if GEMINI_FORCE_JSON_MIME:
        cfg["response_mime_type"] = "application/json"
    if _model_accepts_sampling_params(model):
        cfg["temperature"] = GEMINI_TEMPERATURE
    return cfg

class _GeminiError(RuntimeError):
    """Gemini failure carrying a `kind` so the caller can react sensibly.

    kind is one of:
      "auth"  - the key is rejected. Retrying and trying other models are both
                pointless; fail fast so a five-meal run does not spend 30
                seconds re-proving the same thing.
      "model" - this model name is not available to this key. Retrying is
                pointless, but ANOTHER MODEL may well work -> move on.
      "rate"  - quota/rate limited. Retrying after a backoff is exactly right.
      "other" - network, timeout, parse. Retry, then give up.
    """

    def __init__(self, kind: str, message: str):
        super().__init__(message)
        self.kind = kind

_GEMINI_WORKING_MODEL: Optional[str] = None

GEMINI_MODEL_CANDIDATES_LIVE: List[str] = []

def _classify_gemini_error(status: Optional[int], message: str) -> str:
    """Map an HTTP status / error text onto a _GeminiError kind."""
    m = (message or "").lower()
    if status in (401, 403) or "api key not valid" in m or "permission denied" in m \
            or "unauthenticated" in m or "api_key_invalid" in m:
        return "auth"
    if status == 404 or "not found" in m or "is not supported" in m \
            or "unsupported" in m or "does not exist" in m:
        return "model"
    if status == 429 or "quota" in m or "rate limit" in m or "resource_exhausted" in m:
        return "rate"
    if status in (500, 502, 503, 504) or "unavailable" in m \
            or "high demand" in m or "overloaded" in m \
            or "timed out" in m or "timeout" in m or "read timed out" in m \
            or "connection" in m:
        return "transient"
    if status == 400 and ("model" in m or "unknown name" in m):
        return "model"
    return "other"

def _gemini_once(prompt: str, gemini_api_key: str, model: str,
                 timeout: Optional[float] = None) -> str:
    """One attempt against one model. Raises _GeminiError, returns text.

    Tries the google-genai SDK, then plain REST. IMPORTANT: the REST path is
    reached whenever the SDK path does not produce text - not only when the SDK
    is missing. The previous version only fell through on ImportError, so an
    installed-but-failing SDK meant REST was never attempted at all.
    """
    cfg = _gemini_generation_config(model)
    timeout = GEMINI_TIMEOUT_S if timeout is None else float(timeout)
    sdk_err = ""

    try:
        from google import genai

        try:
            client = genai.Client(
                api_key=gemini_api_key,
                http_options={"timeout": int(timeout * 1000)},
            )
        except TypeError:
            client = genai.Client(api_key=gemini_api_key)
        resp = client.models.generate_content(
            model=model, contents=prompt, config=cfg,
        )
        text = getattr(resp, "text", None)
        if text and text.strip():
            return text
        sdk_err = "SDK returned an empty response"
    except ImportError:
        sdk_err = "google-genai not installed"
    except Exception as exc:
        msg = _scrub_secret(exc, gemini_api_key)
        status = getattr(getattr(exc, "response", None), "status_code", None) \
            or getattr(exc, "code", None)
        kind = _classify_gemini_error(status if isinstance(status, int) else None, msg)
        if kind == "auth":
            raise _GeminiError("auth", f"SDK: {msg[:200]}")
        sdk_err = f"SDK: {msg[:160]}"

    try:
        import requests
    except ImportError:
        raise _GeminiError(
            "other",
            f"neither google-genai nor requests is installed ({sdk_err}). "
            f"Install one: pip install google-genai",
        )

    payload: Dict[str, Any] = {
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
    }
    gen_cfg: Dict[str, Any] = {}
    if "response_mime_type" in cfg:
        gen_cfg["responseMimeType"] = cfg["response_mime_type"]
    if "temperature" in cfg:
        gen_cfg["temperature"] = cfg["temperature"]
    if gen_cfg:
        payload["generationConfig"] = gen_cfg

    try:
        r = requests.post(
            GEMINI_REST_ENDPOINT.format(model=model),
            headers={
                "Content-Type": "application/json",
                "x-goog-api-key": gemini_api_key,
            },
            json=payload,
            timeout=timeout,
        )
    except Exception as exc:
        raise _GeminiError("other", _scrub_secret(exc, gemini_api_key)[:200])

    if r.status_code != 200:
        body = " ".join(_scrub_secret(r.text, gemini_api_key).split())[:400]
        raise _GeminiError(
            _classify_gemini_error(r.status_code, body),
            f"HTTP {r.status_code}: {body}",
        )

    try:
        data = r.json()
    except Exception:
        raise _GeminiError("other", "response was not JSON")

    cand = (data.get("candidates") or [{}])[0]
    parts = cand.get("content", {}).get("parts", [])
    text = "".join(p.get("text", "") for p in parts if isinstance(p, dict))
    if not text.strip():
        reason = cand.get("finishReason") or data.get("promptFeedback", {}).get(
            "blockReason") or "no text parts"
        raise _GeminiError("other", f"empty response (finishReason={reason})")
    return text

def _call_gemini(prompt: str, gemini_api_key: str,
                 model: Optional[str] = None,
                 max_attempts: Optional[int] = None,
                 timeout: Optional[float] = None,
                 deadline: Optional[float] = None) -> str:
    """Send one prompt to Gemini and return the raw text response.

    Client is constructed HERE, per call - never at import time - so importing
    this file never touches the network and never needs a key.

    Walks GEMINI_MODEL_CANDIDATES until one works, because a key that cannot
    reach the newest Flash model can usually still reach an older one, and a
    hard-coded model name turns that into a total failure. The first model that
    succeeds is remembered for the rest of the run.

    Retry policy is driven by the error kind: rate limits back off and retry,
    model errors move to the next candidate immediately, auth errors abort.
    Every message is scrubbed of the key before it is raised.
    """
    global _GEMINI_WORKING_MODEL
    if not gemini_api_key:
        raise ValueError("No Gemini API key supplied.")

    max_attempts = GEMINI_MAX_ATTEMPTS if max_attempts is None else int(max_attempts)
    out_of_time = (lambda: deadline is not None
                   and time.monotonic() >= deadline)

    if model:
        candidates = [model]
    elif _GEMINI_WORKING_MODEL:
        candidates = [_GEMINI_WORKING_MODEL]
    elif GEMINI_MODEL_CANDIDATES_LIVE:
        candidates = list(GEMINI_MODEL_CANDIDATES_LIVE)
    else:
        candidates = list(GEMINI_MODEL_CANDIDATES)

    errors: List[str] = []
    for cand_model in candidates:
        if out_of_time():
            errors.append("time budget for this check was exhausted")
            break
        for attempt in range(1, max_attempts + 1):
            try:
                text = _gemini_once(prompt, gemini_api_key, cand_model, timeout)
                _GEMINI_WORKING_MODEL = cand_model
                return text
            except _GeminiError as exc:
                if exc.kind == "auth":
                    raise RuntimeError(
                        f"Gemini rejected the API key ({exc}). Check the key "
                        f"and that the Generative Language API is enabled."
                    )
                errors.append(f"{cand_model}: {exc}")
                hint = re.search(r"use models/([A-Za-z0-9.\-]+)", str(exc))
                if hint and hint.group(1) not in candidates:
                    candidates.append(hint.group(1))
                if exc.kind == "model":
                    break
                if attempt < max_attempts and not out_of_time():
                    delay = GEMINI_BACKOFF_BASE_S ** attempt
                    if exc.kind in ("transient", "rate"):
                        delay = min(GEMINI_TRANSIENT_MAX_BACKOFF_S,
                                    delay * GEMINI_TRANSIENT_BACKOFF_MULT)
                    time.sleep(delay)
                elif out_of_time():
                    break

    raise RuntimeError("Gemini call failed. " + " | ".join(errors[-3:]))

def discover_gemini_models(gemini_api_key: str,
                           timeout: Optional[float] = None) -> List[str]:
    """Ask the API which models this key can actually use for generateContent.

    Why this exists: GEMINI_MODEL_CANDIDATES is a guess frozen at the time this
    file was written, and Google retires model names. When that happens every
    candidate 404s and recipe generation drops to zero with a working key -
    exactly the failure this replaced. Discovery makes the stale-name problem
    self-correcting.

    Returns model names best-first: Flash models first (fast and cheap, which
    is what a five-recipe run wants), then anything else that can generate
    content. Returns [] if the listing cannot be fetched, in which case the
    caller falls back to the hard-coded candidates.
    """
    if not gemini_api_key:
        return []
    try:
        import requests
    except ImportError:
        return []

    try:
        r = requests.post if False else requests.get(
            GEMINI_LIST_ENDPOINT,
            headers={"x-goog-api-key": gemini_api_key},
            timeout=timeout or GEMINI_PREFLIGHT_TIMEOUT_S,
        )
        if r.status_code != 200:
            return []
        data = r.json()
    except Exception:
        return []

    usable: List[str] = []
    for entry in (data.get("models") or []):
        name = str(entry.get("name", ""))
        if name.startswith("models/"):
            name = name[len("models/"):]
        if not name:
            continue
        methods = entry.get("supportedGenerationMethods") or []
        if "generateContent" not in methods:
            continue
        low = name.lower()
        if any(bad in low for bad in GEMINI_MODEL_EXCLUDE):
            continue
        usable.append(name)

    flash = [m for m in usable if "flash" in m.lower()]
    rest = [m for m in usable if "flash" not in m.lower()]
    return flash + rest

def check_gemini_access(gemini_api_key: str,
                        verbose: bool = True) -> Tuple[bool, str]:
    """Probe the key ONCE, under a hard time budget. Returns (ok, message).

    Worth doing up front: without it the first sign of a bad key or an
    unavailable model is "Recipes via Gemini: 0" at the very end of a long run.

    But a check must be quick or it is worse than no check. This runs ONE
    attempt per model with GEMINI_PREFLIGHT_TIMEOUT_S, under an overall
    GEMINI_PREFLIGHT_MAX_WAIT_S ceiling - the full retry policy would take
    minutes of silence at a prompt. `verbose` prints which model is being
    tried, so a slow network looks like progress rather than a freeze.
    """
    if not gemini_api_key:
        return False, "no key supplied"

    probe = 'Return exactly this JSON and nothing else: {"ok": true}'
    deadline = time.monotonic() + GEMINI_PREFLIGHT_MAX_WAIT_S

    models = ([_GEMINI_WORKING_MODEL] if _GEMINI_WORKING_MODEL
              else list(GEMINI_MODEL_CANDIDATES))

    if not _GEMINI_WORKING_MODEL:
        if verbose:
            print(" (listing models)", end="", flush=True)
        found = discover_gemini_models(
            gemini_api_key, timeout=min(GEMINI_PREFLIGHT_TIMEOUT_S,
                                        max(1.0, deadline - time.monotonic())))
        if found:
            models = found + [m for m in GEMINI_MODEL_CANDIDATES if m not in found]
            global GEMINI_MODEL_CANDIDATES_LIVE
            GEMINI_MODEL_CANDIDATES_LIVE = list(models)

    last = "no response"
    for m in models:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return False, (f"timed out after {GEMINI_PREFLIGHT_MAX_WAIT_S:.0f}s "
                           f"(last: {last}). The run will continue without it.")
        if verbose:
            print(f"\r  checking the key ... trying {m}".ljust(60),
                  end="", flush=True)
        try:
            _call_gemini(
                probe, gemini_api_key, model=m,
                max_attempts=1,
                timeout=min(GEMINI_PREFLIGHT_TIMEOUT_S, remaining),
                deadline=deadline,
            )
            winner = _GEMINI_WORKING_MODEL or m
            _set_working_model(winner)
            return True, f"working (model: {winner})"
        except Exception as exc:
            last = _scrub_secret(exc, gemini_api_key)[:200]
            if "rejected the API key" in last:
                return False, last
    return False, last

def _set_working_model(model: str) -> None:
    """Record the model that answered, so recipe calls skip the probing."""
    global _GEMINI_WORKING_MODEL
    _GEMINI_WORKING_MODEL = model

def _strip_fences(text: str) -> str:
    """Remove ```json ... ``` wrappers and any stray prose around the object."""
    t = (text or "").strip()
    t = re.sub(r"^```(?:json)?\s*", "", t)
    t = re.sub(r"\s*```$", "", t).strip()
    start, end = t.find("{"), t.rfind("}")
    if start != -1 and end != -1 and end > start:
        t = t[start:end + 1]
    return t

def _ingredient_matches_any(name: str, originals_norm: Sequence[str]) -> bool:
    """
    Decide whether a returned ingredient name traces back to an input ingredient.

    Three levels, loosest last:
      1. exact normalised equality,
      2. containment either way (>= 4 chars) - handles "Chicken breast, roasted"
         vs "chicken breast",
      3. difflib ratio >= INGREDIENT_MATCH_CUTOFF - handles minor rewording.

    Deliberately not looser than that: a genuinely different food must fail.
    """
    n = _norm(name)
    if not n:
        return False
    if n in originals_norm:
        return True
    for orig in originals_norm:
        if len(n) >= 4 and len(orig) >= 4 and (n in orig or orig in n):
            return True
        if difflib.SequenceMatcher(None, n, orig).ratio() >= INGREDIENT_MATCH_CUTOFF:
            return True
    return False

def _flatten_steps(steps: Any) -> List[str]:
    """Normalise the richer step schema down to a list of plain strings.

    The prompt now asks for each step as an object with instruction/duration/
    cue. Everything downstream of the parse -- the validator's staple scan,
    the .docx renderer, any consumer of result["recipes"] -- was written
    against a list of strings, and the validator is the safety gate, so it
    must never be handed a shape it was not written for. Flattening here, ONCE,
    before validation, means the gate keeps working unchanged and the model can
    still return either shape.

    A dict step becomes "instruction (duration) - cue"; a bare string passes
    through; anything else is stringified rather than dropped, because a step
    silently discarded is a step the staple scan never reads.
    """
    out: List[str] = []
    for s in (steps or []):
        if isinstance(s, dict):
            text = str(s.get("instruction") or s.get("step") or "").strip()
            dur = str(s.get("duration") or "").strip()
            cue = str(s.get("cue") or s.get("doneness") or "").strip()
            if dur:
                text = f"{text} ({dur})" if text else dur
            if cue:
                text = f"{text} - {cue}" if text else cue
            if text:
                out.append(text)
        else:
            text = str(s).strip()
            if text:
                out.append(text)
    return out

def _recipe_prose_blob(recipe_dict: Dict[str, Any]) -> str:
    """Every free-text field of a recipe, concatenated, for the staple scan."""
    parts: List[str] = []
    for field in RECIPE_PROSE_FIELDS:
        val = recipe_dict.get(field)
        if val is None:
            continue
        if field == "steps":
            parts.extend(_flatten_steps(val))
        elif isinstance(val, (list, tuple)):
            parts.extend(str(v) for v in val)
        else:
            parts.append(str(val))
    for item in (recipe_dict.get("ingredients") or []):
        if isinstance(item, dict) and item.get("prep_note"):
            parts.append(str(item["prep_note"]))
    return " ".join(parts)

def validate_no_invented_ingredients(
    recipe_dict: Dict[str, Any],
    original_ingredient_names: Sequence[str],
) -> bool:
    """
    Reject any recipe that introduces a food not supplied in the prompt.

    THIS IS NOT OPTIONAL. It runs immediately after every Gemini response is
    parsed and before the recipe is accepted anywhere. LLMs habitually add "a
    pinch of salt", "a drizzle of olive oil", or a garnish; against the project's
    no-food-invention constraint that is a correctness failure, not a nicety.

    Two checks:
      1. Every name in the returned "ingredients" must fuzzy-match an input name.
      2. If CHECK_STEPS_FOR_STAPLES, no staple from STAPLE_WATCHLIST may appear
         in the steps unless it was an input ingredient. Matching is word-
         boundary based, so "boil" does not fire the "oil" rule.

    Returns True if the recipe is clean, False if it must be discarded in favour
    of the templated fallback.
    """
    if not isinstance(recipe_dict, dict):
        return False

    originals_norm = [_norm(n) for n in original_ingredient_names if str(n).strip()]
    if not originals_norm:
        return False

    ingredients = recipe_dict.get("ingredients")
    if not isinstance(ingredients, list) or not ingredients:
        return False

    for item in ingredients:
        name = item.get("name", "") if isinstance(item, dict) else str(item)
        if not _ingredient_matches_any(name, originals_norm):
            return False

    if CHECK_STEPS_FOR_STAPLES:
        blob = _norm(_recipe_prose_blob(recipe_dict))
        allowed_blob = " ".join(originals_norm)
        for staple in STAPLE_WATCHLIST:
            st = _norm(staple)
            if re.search(rf"\b{re.escape(st)}\b", allowed_blob):
                continue
            if re.search(rf"\b{re.escape(st)}\b", blob):
                return False

    return True

def _rank_minutes(ing: Dict[str, Any]) -> float:
    """Minutes of cooking this one ingredient implies, 0 if none."""
    spec = dry_prep_requirement(ing.get("name"))
    if spec:
        return float(spec["min_cook_min"])
    return _duration_minutes(ing.get("note", ""))

def _templated_recipe(
    meal_name: str,
    ingredients: List[Dict[str, Any]],
    kcal: float,
    protein: float,
    note: str = "",
) -> Dict[str, Any]:
    """
    Deterministic fallback recipe, assembled purely from the assigned cooking
    methods. Uses no model, invents nothing, and always succeeds - which is what
    makes an empty or broken API key a non-event rather than a failure.
    """
    names = [i["name"] for i in ingredients]

    prep_first: List[str] = []
    for name in names:
        spec = dry_prep_requirement(name)
        if not spec:
            continue
        if float(spec["soak_hours"]) > 0:
            prep_first.append(
                f"THE NIGHT BEFORE -- put the {name} in a bowl, cover with "
                f"cold water to at least three times its depth, and leave "
                f"about {int(spec['soak_hours'])} hours. Drain and discard "
                f"the soaking water before cooking.")
        if float(spec["hard_boil_min"]) > 0:
            prep_first.append(
                f"Cover the drained {name} with fresh water, bring to a full "
                f"rolling boil and hold it there for {int(spec['hard_boil_min'])} "
                f"minutes. {spec['safety']}")
        prep_first.append(
            f"Reduce to a simmer and cook the {name} for "
            f"{spec['typical_cook_min']}, topping up with hot water so it "
            f"stays covered. It is ready when a piece crushes easily against "
            f"the roof of the mouth -- go by that, not by the clock.")

    def _rank(ing: Dict[str, Any]) -> float:
        """Longest cook time first, so the steps run in a workable order."""
        spec = dry_prep_requirement(ing["name"])
        if spec:
            return 10000.0 + float(spec["min_cook_min"])
        return _duration_minutes(ing.get("note", ""))

    ordered = sorted(ingredients, key=_rank, reverse=True)

    steps: List[str] = list(prep_first)
    for ing in ordered:
        if dry_prep_requirement(ing["name"]):
            continue
        steps.append(
            f"{ing['method'].capitalize()}: {ing['name']} ({ing['amount']}). "
            f"{ing.get('note', '')}".strip())
    steps.append("Combine the prepared items and serve as one meal.")
    steps.append("Add nothing that is not listed above.")

    total_g = sum(
        float(re.sub(r"[^\d.]", "", str(i["amount"])) or 0.0) for i in ingredients
    )
    longest = max([_rank_minutes(i) for i in ingredients] or [0.0])
    soak = any(needs_overnight_soak(i["name"]) for i in ingredients)
    if longest > 0:
        total_time = f"about {longest:.0f} minutes of cooking"
        if soak:
            total_time += ", plus an overnight soak started the day before"
    else:
        total_time = "overnight soak required" if soak else ""

    return {
        "title": f"{meal_name} plate",
        "yield_note": (f"One serving, about {total_g:.0f} g plated."
                       if total_g > 0 else "One serving."),
        "total_time": total_time,
        "equipment": [],
        "ingredients": [
            {"name": i["name"], "amount": i["amount"], "prep_note": i["note"]}
            for i in ingredients
        ],
        "steps": steps,
        "steps_detailed": [],
        "prep_ahead": prep_ahead_lines([i["name"] for i in ingredients]),
        "common_mistake": (
            "Under-cooking the soaked pulse or grain. It is done when a piece "
            "crushes easily, which may be well past the stated time if the "
            "batch is old."
            if any(dry_prep_requirement(i["name"]) for i in ingredients)
            else "Overcooking the protein. Take it off the heat as soon as it "
                 "is done; it carries on cooking in its own heat."
        ),
        "storage": ("Best eaten fresh. Anything kept over should be cooled "
                    "quickly, refrigerated in a covered container and eaten "
                    "within 24 hours, reheated until steaming hot throughout."),
        "approx_note": (
            f"Approximately {kcal:.0f} kcal and {protein:.1f} g protein for this meal; "
            f"figures are estimates from the food database. This card was "
            f"assembled from the assigned cooking methods and the published "
            f"preparation times for the dry ingredients, without model output, "
            f"so it states only what those two sources support."
        ),
        "used_gemini": False,
        "gemini_added_ingredient": False,
        "undercooked_ingredient": False,
        "fallback_reason": note or "templated recipe used",
    }

def build_recipe(
    meal_name: str,
    meal_foods_df: pd.DataFrame,
    cooking_methods: Dict[str, Dict[str, str]],
    kcal: float,
    protein: float,
    gemini_api_key: str = "",
    column_map: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Build one recipe from the FINAL meal composition (post-substitution,
    post-shift).

    Flow:
      a) no key -> straight to the templated fallback, no network call;
      b) otherwise build the structured prompt from this meal's exact foods,
         grams and assigned cooking methods;
      c) call Gemini, strip fences, parse JSON;
      d) run validate_no_invented_ingredients() - reject on failure;
      e) ANY exception at all falls back to the template.

    The returned dict always carries used_gemini and gemini_added_ingredient so
    the report can say exactly which meals were model-written and which were not.
    The API key never appears in the returned dict or in fallback_reason.
    """
    column_map = column_map or {}
    food_col = _cfg(column_map, "food_col")
    grams_col = _cfg(column_map, "grams_col")

    ingredients: List[Dict[str, Any]] = []
    for _, row in meal_foods_df.iterrows():
        name = str(row[food_col])
        grams = pd.to_numeric(row.get(grams_col), errors="coerce")
        grams = float(grams) if pd.notna(grams) else 0.0
        cm = cooking_methods.get(name, dict(DEFAULT_COOKING_METHOD))
        ingredients.append({
            "name": name,
            "amount": f"{grams:.0f} g",
            "method": cm["method"],
            "note": cm["note"],
        })

    original_names = [i["name"] for i in ingredients]

    if not gemini_api_key:
        return _templated_recipe(
            meal_name, ingredients, kcal, protein,
            note="no Gemini API key supplied for this run",
        )

    ingredient_block = "\n".join(
        f"- {i['name']} | {i['amount']} | assigned cooking method: "
        f"{i['method']} ({i['note']})"
        for i in ingredients
    )
    prep_block = mandatory_prep_block(original_names)
    form_block = prep_form_block(original_names)
    prompt = GEMINI_PROMPT_TEMPLATE.format(
        meal_name=meal_name,
        kcal=kcal,
        protein=protein,
        ingredient_block=ingredient_block,
        prep_form_block=("\n" + form_block if form_block else ""),
        mandatory_prep_block=("\n" + prep_block if prep_block else ""),
    )

    try:
        raw = _call_gemini(prompt, gemini_api_key)
        parsed = json.loads(_strip_fences(raw))

        if not validate_no_invented_ingredients(parsed, original_names):
            corrected = None
            for _try in range(RECIPE_INVENTION_RETRIES):
                try:
                    fix_prompt = (
                        prompt
                        + "\n\nYOUR PREVIOUS RESPONSE WAS REJECTED. It used an "
                          "ingredient that is not in the list above, or wrote "
                          "an ingredient name differently from the list. Both "
                          "are forbidden.\n"
                          "Write the recipe again using ONLY these exact "
                          "names, copied character for character:\n"
                        + "\n".join(f"  - {n}" for n in original_names)
                        + "\nDo not add salt, oil, butter, stock, herbs, "
                          "spices, garnishes or a side. Plain water for "
                          "boiling or soaking is allowed and is not an "
                          "ingredient. Return ONLY the JSON object."
                    )
                    raw2 = _call_gemini(fix_prompt, gemini_api_key)
                    cand = json.loads(_strip_fences(raw2))
                    if validate_no_invented_ingredients(cand, original_names):
                        corrected = cand
                        break
                except Exception:
                    break
            if corrected is None:
                fb = _templated_recipe(
                    meal_name, ingredients, kcal, protein,
                    note=(f"Gemini introduced an ingredient not in this meal, "
                          f"or altered a name; discarded after "
                          f"{RECIPE_INVENTION_RETRIES} corrective retry(ies)"),
                )
                fb["gemini_added_ingredient"] = True
                return fb
            parsed = corrected

        ok_cook, cook_problems = validate_cooking_adequacy(
            parsed, original_names)
        ok_form, form_problems = validate_prep_plausibility(
            parsed, original_names)
        ok_cook = ok_cook and ok_form
        cook_problems = cook_problems + form_problems
        if not ok_cook:
            corrected = None
            for _try in range(RECIPE_INVENTION_RETRIES):
                try:
                    fix_prompt = (
                        prompt
                        + "\n\nYOUR PREVIOUS RESPONSE WAS REJECTED ON FOOD "
                          "SAFETY AND COOKING GROUNDS. These are the "
                          "problems:\n"
                        + "\n".join(f"  - {p}" for p in cook_problems)
                        + "\n\nWrite the recipe again with the full "
                          "preparation and cooking times stated above, using "
                          "ONLY the listed ingredients. If a step has to "
                          "start the night before, make it step 1 and label "
                          "it clearly. Do not shorten any time. Return ONLY "
                          "the JSON object."
                    )
                    raw3 = _call_gemini(fix_prompt, gemini_api_key)
                    cand = json.loads(_strip_fences(raw3))
                    if (validate_no_invented_ingredients(cand, original_names)
                            and validate_cooking_adequacy(
                                cand, original_names)[0]
                            and validate_prep_plausibility(
                                cand, original_names)[0]):
                        corrected = cand
                        break
                except Exception:
                    break
            if corrected is None:
                fb = _templated_recipe(
                    meal_name, ingredients, kcal, protein,
                    note=("Gemini gave an ingredient the wrong preparation "
                          "for the form it is sold in (" +
                          "; ".join(cook_problems)[:300] +
                          f"); discarded after {RECIPE_INVENTION_RETRIES} "
                          f"corrective retry(ies)"),
                )
                fb["undercooked_ingredient"] = True
                return fb
            parsed = corrected

        by_name = {_norm(i["name"]): i for i in ingredients}
        clean_ings = []
        for item in (parsed.get("ingredients") or []):
            nm = item.get("name", "") if isinstance(item, dict) else str(item)
            src = by_name.get(_norm(nm))
            clean_ings.append({
                "name": nm,
                "amount": src["amount"] if src else item.get("amount", ""),
                "prep_note": (item.get("prep_note", "") if isinstance(item, dict) else ""),
            })

        raw_steps = parsed.get("steps") or []
        detailed = [s for s in raw_steps if isinstance(s, dict)]
        equipment = parsed.get("equipment") or []
        if isinstance(equipment, str):
            equipment = [equipment]

        return {
            "title": str(parsed.get("title") or f"{meal_name} plate"),
            "yield_note": str(parsed.get("yield_note") or ""),
            "total_time": str(parsed.get("total_time") or ""),
            "equipment": [str(e) for e in equipment],
            "ingredients": clean_ings,
            "steps": _flatten_steps(raw_steps),
            "steps_detailed": detailed,
            "common_mistake": str(parsed.get("common_mistake") or ""),
            "storage": str(parsed.get("storage") or ""),
            "approx_note": str(parsed.get("approx_note") or ""),
            "prep_ahead": prep_ahead_lines(original_names),
            "used_gemini": True,
            "gemini_added_ingredient": False,
            "undercooked_ingredient": False,
            "fallback_reason": "",
        }

    except Exception as exc:
        return _templated_recipe(
            meal_name, ingredients, kcal, protein,
            note=f"Gemini unavailable or response unusable: "
                 f"{_scrub_secret(exc, gemini_api_key)[:200]}",
        )

def write_csv(adjustments_log: pd.DataFrame, output_dir: str) -> str:
    """Write the adjustments log to CSV for auditability. Returns the path."""
    os.makedirs(output_dir, exist_ok=True)
    path = os.path.join(output_dir, "adjustments_log.csv")
    adjustments_log.to_csv(path, index=False)
    return path

VEGETABLE_ADJACENT_SUBGROUPS = frozenset({
    "Starchy Roots & Tubers", "Herbs & Aromatics",
    "Meat + Vegetable", "Egg + Vegetable", "Seafood + Vegetable",
})

def _peas_count_as_vegetable(food_name: Any) -> bool:
    """Green peas are a vegetable; dried split peas are a pulse.

    One subgroup, two foods, and the difference is form -- which is exactly
    what food_prep_form() was built to tell apart.
    """
    return food_prep_form(food_name) in ("fresh", "unknown")

SUBGROUP_FLOOR_MEMBERS = {
    "Vegetables": set(VEGETABLE_SUBGROUPS) | {"Peas"},
    "Fruits": set(FRUIT_SUBGROUPS),
    "Whole Grains": set(WHOLE_GRAIN_SUBGROUPS),
    "Legumes": {"Beans", "Legumes", "Peas", "Soy Products"},
    "Healthy Fats": {"Nuts", "Seeds", "Healthy Fats", "Vegetable Oil"},
}

def diagnose_subgroup_gap(
    split,
    food_db,
    column_map,
    floor_label: str = "Vegetables",
    floor_g: Optional[float] = None,
) -> Dict[str, Any]:
    """Explain a food-group near-miss instead of just reporting the number.

    Written because "Vegetables 340 g / 350 g - 97% BELOW FLOOR" appeared
    twice in a row and told nobody anything actionable. The same line is
    consistent with three completely different situations -- the pool has no
    vegetables left to add, the plan has vegetables the tally is not
    counting, or the search simply never tried -- and a reviewer cannot tell
    which from the number alone.

    Returns a dict with the counted total, the adjacent grams the floor
    deliberately excludes, and the cheapest foods already in the pool that
    would close the gap.
    """
    out: Dict[str, Any] = {
        "label": floor_label, "counted_g": 0.0, "floor_g": floor_g,
        "adjacent_g": {}, "in_plan": [], "candidates": [], "verdict": "",
    }
    try:
        f_col = _cfg(column_map, "food_col") or "food"
        g_col = _cfg(column_map, "grams_col") or "grams"
        sub_col = _cfg(column_map, "subgroup_col") or "Food_Subgroup"

        counted = 0.0
        for _, r in split.iterrows():
            nm = str(r.get(f_col))
            gv = pd.to_numeric(r.get(g_col), errors="coerce")
            gv = float(gv) if pd.notna(gv) else 0.0
            sg = str(r.get(sub_col) or classify_food(nm)[1]).strip()
            if _subgroup_in_floor_group(sg, floor_label, nm):
                counted += gv
                out["in_plan"].append((nm, gv, sg))
            elif sg in VEGETABLE_ADJACENT_SUBGROUPS and floor_label == "Vegetables":
                out["adjacent_g"][sg] = out["adjacent_g"].get(sg, 0.0) + gv
        out["counted_g"] = counted

        if floor_g is None or counted >= floor_g:
            out["verdict"] = "met"
            return out
        gap = floor_g - counted

        f_name = _cfg(column_map, "food_col") or "food"
        kcal_c = _cfg(column_map, "energy_col") or "Energy"
        seen = {str(n).lower() for n, _, _ in out["in_plan"]}
        cands = []
        for _, r in food_db.iterrows():
            nm = str(r.get(f_name))
            if nm.lower() in seen:
                continue
            sg = str(r.get(sub_col) or classify_food(nm)[1]).strip()
            if not _subgroup_in_floor_group(sg, floor_label, nm):
                continue
            kc = pd.to_numeric(r.get(kcal_c), errors="coerce")
            if pd.isna(kc):
                continue
            cands.append((float(kc) * gap / 100.0, nm, sg))
        cands.sort()
        out["candidates"] = cands[:8]

        if not cands:
            out["verdict"] = (
                f"POOL EXHAUSTED: nothing left in the pool counts toward "
                f"{floor_label}. The floor cannot be met from this pool at "
                f"any calorie level; widen the Food Type/Subgroup selection.")
        else:
            cheapest = cands[0]
            out["verdict"] = (
                f"REACHABLE: {gap:.0f} g short. The cheapest close is "
                f"{cheapest[1]} at {gap:.0f} g for about {cheapest[0]:.0f} "
                f"kcal. A gap this small and this cheap being missed twice "
                f"running points at search pressure, not at the pool -- see "
                f"SUBGROUP_FLOOR_BOOST.")
        if out["adjacent_g"]:
            adj = ", ".join(f"{k} {v:.0f} g" for k, v in out["adjacent_g"].items())
            out["verdict"] += (
                f" NOTE: the plan also contains {adj}, which this floor "
                f"deliberately excludes; the shortfall is against the "
                f"narrower definition, not against total plant food.")
    except Exception as exc:
        out["verdict"] = f"diagnostic failed: {type(exc).__name__}: {exc}"
    return out

def _subgroup_in_floor_group(subgroup: str, floor_label: str,
                             food_name: Any = None) -> bool:
    """True if this Food_Subgroup counts toward that subgroup-total floor.

    `food_name` is optional and only consulted where the subgroup alone is
    not decisive -- currently just Peas, where the fresh form is a vegetable
    and the dried form is a pulse.
    """
    members = SUBGROUP_FLOOR_MEMBERS.get(floor_label)
    if members is not None:
        sg = str(subgroup).strip()
        if (sg == "Peas" and floor_label == "Vegetables"
                and food_name is not None):
            return _peas_count_as_vegetable(food_name)
        return sg in members
    return str(subgroup).strip() == floor_label

def summarize_adequacy(
    before_split: pd.DataFrame,
    after_split: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    soft_targets: Optional[Dict[str, float]] = None,
    reference_mar: Optional[Dict[str, float]] = None,
    front_result: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Mean Adequacy Ratio for the plan BEFORE and AFTER the rebuild.

    WHY THIS MATTERS MORE THAN IT LOOKS. The front-wide comparison scores
    fm.adequacy(x) over front_X -- decision vectors straight out of NSGA-III.
    Every MAR in that table, and every "N of 163 plans beat DASH" claim built
    on it, therefore describes the plan AS OPTIMIZED.

    That is not the plan anyone eats. Between the optimizer and the document,
    substitutions replace foods for safety and practicality, portions are
    rescaled, and meals are rearranged. Each of those changes the nutrient
    vector, so it changes MAR -- and nothing recomputed it. A run can report
    96.5% adequacy and beating DASH while the plan actually issued sits well
    below both, because the number was measured on a plan that no longer
    exists by the time the document is printed.

    This closes that gap by scoring the rebuilt plan on the SAME formula --
    NAR_i = min(intake_i / floor_i, 1), MAR = mean(NAR) -- so the two numbers
    are directly comparable and the reference-diet comparison can be repeated
    against what the patient is actually given.

    `soft_targets` is fm.soft_list as a dict; without it there are no floors to
    score against and this returns an empty result rather than a guess.
    """
    if not soft_targets:
        return {}

    def _totals(df: pd.DataFrame) -> Dict[str, float]:
        idx = _build_db_index(food_db.reset_index(drop=True), column_map)
        db = food_db.reset_index(drop=True)
        basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
        fcol, gcol = _cfg(column_map, "food_col"), _cfg(column_map, "grams_col")
        out = {c: 0.0 for c in soft_targets}
        sub_col = _cfg(column_map, "group_col") or "Food_Subgroup"
        subgroup_floors = {c: c.split(" (g,")[0].strip()
                           for c in soft_targets if "(g, subgroup total)" in c}
        for _, r in df.iterrows():
            pos = idx.get(_norm(r.get(fcol)))
            if pos is None:
                continue
            g = pd.to_numeric(r.get(gcol), errors="coerce")
            g = float(g) if pd.notna(g) else 0.0
            for c in soft_targets:
                if c in db.columns:
                    v = pd.to_numeric(db.iloc[pos].get(c), errors="coerce")
                    if pd.notna(v):
                        out[c] += float(v) * g / basis
            if subgroup_floors and sub_col in db.columns:
                sg = str(db.iloc[pos].get(sub_col) or "").strip()
                for c, label in subgroup_floors.items():
                    if _subgroup_in_floor_group(sg, label):
                        out[c] += g
        return out

    def _mar(totals: Dict[str, float]) -> Tuple[float, float, List[str]]:
        nars, short = [], []
        for col, tgt in soft_targets.items():
            if not tgt or float(tgt) <= 0:
                continue
            nar = min(totals.get(col, 0.0) / float(tgt), 1.0)
            nars.append(nar)
            if nar < 1.0:
                short.append(col)
        if not nars:
            return 100.0, 100.0, []
        arr = np.asarray(nars, dtype=float)
        return (float(100 * arr.mean()),
                float(100 * (arr >= 1.0).mean()),
                short)

    before_tot, after_tot = _totals(before_split), _totals(after_split)
    b_mar, b_met, _ = _mar(before_tot)
    a_mar, a_met, a_short = _mar(after_tot)

    subgroup_cov = []
    for col, tgt in soft_targets.items():
        if "(g, subgroup total)" not in col or not tgt or tgt <= 0:
            continue
        got = after_tot.get(col, 0.0)
        subgroup_cov.append({
            "group": col.split(" (g,")[0].strip(),
            "grams": round(got, 1), "floor_g": round(float(tgt), 1),
            "pct_of_floor": round(100.0 * got / float(tgt), 1),
            "met": bool(got >= float(tgt)),
        })
    subgroup_cov.sort(key=lambda r: r["pct_of_floor"])
    refs = dict(reference_mar or {})
    return {
        "mar_before": round(b_mar, 2),
        "mar_after": round(a_mar, 2),
        "mar_delta": round(a_mar - b_mar, 2),
        "floors_met_before_pct": round(b_met, 1),
        "floors_met_after_pct": round(a_met, 1),
        "floors_short_after": a_short,
        "reference_mar": refs,
        "subgroup_coverage": subgroup_cov,
        "beats_reference_after": {k: bool(a_mar > v) for k, v in refs.items()},
        "beats_reference_before": {k: bool(b_mar > v) for k, v in refs.items()},
    }

def summarize_nutrient_change(
    before_split: pd.DataFrame,
    after_split: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    person: Any = None,
) -> pd.DataFrame:
    """
    Day totals BEFORE and AFTER substitution, for every scored nutrient.

    The point of this table is that it is the only place the cost of the
    rebuild is visible as a number. The per-meal summary shows the final plan
    and the adjustments log shows what was swapped, but neither says what the
    swapping DID to the day. A run can hold energy exactly on target and still
    have moved a third of the protein, and until both columns sit side by side
    that is invisible.

    Both columns are computed by the SAME code path over the same nutrient
    list, so a difference between them is a real difference in the food and
    never an artefact of two different summing methods.

    Returns nutrient | before | after | change | pct_change | rda | ul |
    crossed_below_rda | crossed_over_ul, sorted with the largest relative
    movements first. `crossed_*` flags the cases that matter most: a nutrient
    that was fine before the rebuild and is not fine after it.
    """
    def _totals(df: pd.DataFrame) -> Dict[str, float]:
        idx = _build_db_index(food_db.reset_index(drop=True), column_map)
        db = food_db.reset_index(drop=True)
        cols = _resolve_nutrient_cols(food_db, column_map)
        basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
        fcol = _cfg(column_map, "food_col")
        gcol = _cfg(column_map, "grams_col")
        out = {c: 0.0 for c in cols}
        for _, r in df.iterrows():
            pos = idx.get(_norm(r.get(fcol)))
            if pos is None:
                continue
            g = pd.to_numeric(r.get(gcol), errors="coerce")
            g = float(g) if pd.notna(g) else 0.0
            for c in cols:
                v = pd.to_numeric(db.iloc[pos].get(c), errors="coerce")
                if pd.notna(v):
                    out[c] += float(v) * g / basis
        return out

    try:
        rda = micronutrient_rda(person) if person is not None else {}
        ul = micronutrient_ul(person) if person is not None else {}
    except Exception:
        rda, ul = {}, {}

    b, a = _totals(before_split), _totals(after_split)
    rows: List[Dict[str, Any]] = []
    for c in b:
        bv, av = b[c], a.get(c, 0.0)
        r_, u_ = rda.get(c), ul.get(c)
        rows.append({
            "nutrient": c,
            "before": round(bv, 2),
            "after": round(av, 2),
            "change": round(av - bv, 2),
            "pct_change": round(100.0 * (av - bv) / bv, 1) if abs(bv) > 1e-9 else None,
            "rda": r_,
            "ul": u_,
            "crossed_below_rda": bool(r_ and bv >= r_ > av),
            "crossed_over_ul": bool(u_ and bv <= u_ < av),
        })
    df = pd.DataFrame(rows)
    if df.empty:
        return df
    return df.reindex(
        df["pct_change"].abs().fillna(0.0).sort_values(ascending=False).index
    ).reset_index(drop=True)

SHOPPING_AISLES = [
    ("Fresh produce", set(VEGETABLE_SUBGROUPS) | set(FRUIT_SUBGROUPS)),
    ("Meat, fish and eggs", {"Poultry", "Beef", "Mutton/Lamb", "Pork", "Game",
                             "Fatty Fish", "Lean Fish", "Tuna", "Seafood",
                             "Eggs"}),
    ("Dairy", {"Milk", "Yogurt", "Cheese", "Paneer", "Cream", "Plant Milk"}),
    ("Grains and pulses", set(WHOLE_GRAIN_SUBGROUPS) | {"Refined Grains",
                                                        "Beans", "Legumes",
                                                        "Peas", "Soy Products"}),
    ("Nuts, seeds and oils", {"Nuts", "Seeds", "Healthy Fats",
                              "Vegetable Oil"}),
]

def build_shopping_list(split, food_db, column_map):
    """One consolidated shopping list, grouped by supermarket aisle.

    THE PRACTICALITY GAP NOTHING ELSE CLOSED. Every version of this document
    listed foods meal by meal, so an ingredient used in two meals appeared
    twice at two weights and the reader had to add them up. A plan is only as
    practical as the shop that precedes it, and no amount of nutrient accuracy
    survives a list you cannot take to a shop.

    Quantities are summed across the day and rounded UP to something buyable --
    nobody buys 137 g of anything.
    """
    fcol = _cfg(column_map, "food_col")
    gcol = _cfg(column_map, "grams_col")
    scol = _cfg(column_map, "group_col") or "Food_Subgroup"
    idx = _build_db_index(food_db.reset_index(drop=True), column_map)
    db = food_db.reset_index(drop=True)

    totals: Dict[str, float] = {}
    subs: Dict[str, str] = {}
    for _, r in split.iterrows():
        nm = str(r.get(fcol))
        g = pd.to_numeric(r.get(gcol), errors="coerce")
        totals[nm] = totals.get(nm, 0.0) + (float(g) if pd.notna(g) else 0.0)
        pos = idx.get(_norm(nm))
        subs[nm] = str(db.iloc[pos].get(scol)).strip() if pos is not None else ""

    def _buyable(g, name=""):
        if culinary_herb_cap_g(name) is not None:
            return (f"1 small bunch or packet (about {g:.0f} g is used -- "
                    f"the rest keeps in the fridge)")
        if g < 25:
            return f"{max(5, int(round(g / 5.0) * 5)):d} g"
        if g < 100:
            return f"{int(np.ceil(g / 10.0) * 10):d} g"
        return f"{int(np.ceil(g / 50.0) * 50):d} g"

    aisles = []
    placed = set()
    for label, members in SHOPPING_AISLES:
        items = [(nm, totals[nm]) for nm in sorted(totals)
                 if subs.get(nm) in members]
        if items:
            aisles.append((label, [(nm, _buyable(g, nm)) for nm, g in items]))
            placed.update(nm for nm, _ in items)
    other = [(nm, _buyable(totals[nm], nm)) for nm in sorted(totals)
             if nm not in placed]
    if other:
        aisles.append(("Other", other))
    return aisles

MAJOR_ALLERGENS: Dict[str, str] = {
    "milk": r"\b(milk|cheese|yogh?urt|butter(?!,?\s*(peanut|almond|nut|seed|cocoa|shea))|"
            r"cream|curd|whey|casein|ghee|paneer|custard|ice\s+cream)\b",
    "egg": r"\b(egg|eggs|albumen|mayonnaise|meringue|omelet)\b",
    "fish": r"\b(fish|salmon|tuna|cod|snapper|trout|mackerel|sardine|anchovy|"
            r"herring|halibut|haddock|tilapia|catfish|bass|perch|pollock|"
            r"lingcod|sole|flounder|surimi|caviar|roe)\b",
    "crustacean shellfish": r"\b(shrimp|prawn|crab|lobster|crayfish|crawfish|langoustine)\b",
    "mollusc shellfish": r"\b(clam|oyster|mussel|scallop|squid|octopus|snail|abalone|mollusk|mollusc)\b",
    "tree nuts": r"\b(almond|walnut|cashew|pecan|pistachio|hazelnut|filbert|"
                 r"macadamia|brazil\s+nut|pine\s+nut|chestnut)\b",
    "peanuts": r"\b(peanut|groundnut|arachis)\b",
    "wheat / gluten": r"\b(wheat|flour(?!,?\s*(corn|rice|soy|almond|coconut|chickpea|cottonseed))|"
                      r"bread|pasta|noodle|semolina|durum|spelt|farro|couscous|"
                      r"bulgur|seitan|barley|rye|malt)\b",
    "soy": r"\b(soy|soya|soybean|tofu|tempeh|edamame|miso|natto|curd\s+cheese)\b",
    "sesame": r"\b(sesame|tahini|benne|gingelly|til\b)\b",
}
_ALLERGEN_C = {k: re.compile(v, re.I) for k, v in MAJOR_ALLERGENS.items()}

_NUT_SEED_BUTTER_RE = re.compile(
    r"\b(peanut|almond|cashew|hazelnut|pecan|walnut|macadamia|pistachio|"
    r"sunflower|pumpkin\s*seed|sesame|soy|coconut|cocoa|shea|nut|seed)"
    r"[\s-]*butters?\b", re.I)

ALLERGEN_EXCLUSION_EXTRA: Dict[str, str] = {
    "milk": r"\b(lactose|dairy|ghee|kefir|quark|ricotta|mascarpone|"
            r"custard|ice\s*cream|condensed|evaporated|malted\s+milk)\b",
    "egg": r"\b(ovalbumin|lysozyme|meringue|frittata|quiche|"
           r"eggnog|aioli|hollandaise)\b",
    "fish": r"\b(worcestershire|fish\s*sauce|nuoc\s*mam|bonito|dashi|"
            r"caesar\s+dressing|fish\s*oil|cod\s*liver)\b",
    "crustacean shellfish": r"\b(shellfish|seafood|bisque|surimi|krill)\b",
    "mollusc shellfish": r"\b(shellfish|seafood|calamari|escargot)\b",
    "tree nuts": r"\b(marzipan|praline|nougat|nutella|gianduja|frangipane|"
                 r"nut\s*(oil|butter|paste|flour|milk))\b",
    "peanuts": r"\b(satay|goober|monkey\s+nut|peanut\s*(oil|flour|butter))\b",
    "wheat / gluten": r"\b(gluten|seitan|farina|einkorn|emmer|kamut|"
                      r"matzo|panko|roux|orzo|vital\s+wheat)\b",
    "soy": r"\b(edamame|shoyu|tamari|okara|yuba|textured\s+vegetable)\b",
    "sesame": r"\b(halvah|halva|hummus|za'?atar|gomashio|benne)\b",
}

def prompt_for_allergen_exclusions(
    interactive: bool = True,
) -> List[str]:
    """Ask which allergens to exclude from the pool. Returns the list chosen.

    Deliberately a numbered multi-select rather than free text. A client
    typing "nuts" could mean tree nuts, peanuts, or both, and a screen that
    guesses wrong on that question is worse than no screen -- so the choice is
    made from a fixed list where every option maps to a known pattern.

    Set CLIENT_ALLERGENS in globals to skip the prompt entirely, for batch
    runs and for reproducible thesis experiments.
    """
    preset = globals().get("CLIENT_ALLERGENS")
    if preset is not None:
        return [a for a in preset if a in MAJOR_ALLERGENS]
    if not interactive:
        return []

    keys = list(MAJOR_ALLERGENS)
    print("\n=== Allergy and intolerance screen ===")
    print("  Foods containing anything you select are removed from the pool")
    print("  BEFORE optimisation, so the plan is built to be balanced without")
    print("  them rather than having them cut out afterwards.")
    for i, k in enumerate(keys, 1):
        print(f"    {i:>2}. {k}")
    print("     0. none - no exclusions")
    raw = input("  Enter numbers separated by commas [0]: ").strip()
    if not raw or raw == "0":
        print("  No allergen exclusions applied.")
        return []

    chosen: List[str] = []
    for tok in raw.replace(" ", "").split(","):
        if not tok:
            continue
        try:
            n_ = int(tok)
        except ValueError:
            print(f"  Ignored '{tok}' - not a number.")
            continue
        if 1 <= n_ <= len(keys):
            if keys[n_ - 1] not in chosen:
                chosen.append(keys[n_ - 1])
        else:
            print(f"  Ignored '{tok}' - out of range.")
    if chosen:
        print(f"  Excluding: {', '.join(chosen)}")
    return chosen

def filter_pool_for_allergens(df, allergens: Sequence[str],
                              desc_col: str = "description",
                              verbose: bool = True):
    """Remove every food containing a selected allergen from the pool.

    Reports what went and, more importantly, WHAT IS LEFT for the food groups
    the removal hits hardest. Excluding fish and tree nuts from a plan with a
    high protein floor and an LA floor is a real constraint, and a screen that
    silently narrows the pool without saying so sets the optimizer up to fail
    for reasons nobody can see afterwards.
    """
    if not allergens or desc_col not in df.columns:
        return df
    names = df[desc_col].astype(str)
    mask = pd.Series(False, index=df.index)
    per: Dict[str, int] = {}
    for a in allergens:
        rx = MAJOR_ALLERGENS.get(a)
        if not rx:
            continue
        _rx = re.compile(rx, re.I)
        hit = names.map(lambda s_: bool(_rx.search(s_)))
        extra = ALLERGEN_EXCLUSION_EXTRA.get(a)
        if extra:
            _rx2 = re.compile(extra, re.I)
            hit = hit | names.map(lambda s_: bool(_rx2.search(s_)))
        per[a] = int(hit.sum())
        mask = mask | hit

    kept = df.loc[~mask].copy()
    if verbose:
        print(f"\n  Allergen screen: removed {int(mask.sum()):,} of "
              f"{len(df):,} foods, {len(kept):,} remain.")
        for a, n_ in per.items():
            print(f"    {a:<22} {n_:>5} removed")
        try:
            for grp, need in (("protein", ("Poultry", "Beef", "Pork",
                                           "Fatty Fish", "Lean Fish", "Eggs",
                                           "Legumes", "Soy Products")),
                              ("healthy fat", ("Nuts", "Seeds",
                                               "Healthy Fats",
                                               "Vegetable Oil"))):
                left = sum(1 for n_ in kept[desc_col].astype(str)
                           if classify_food(n_)[1] in need)
                flag = "  <-- THIN" if left < 15 else ""
                print(f"    {left:>5} {grp} foods remain{flag}")
        except Exception:
            pass
    return kept

def detect_allergens(food_names: Sequence[str]) -> Dict[str, List[str]]:
    """Which major allergens are present, and which foods carry each.

    Returns {allergen: [foods]}. Empty when the plan is clean, which is worth
    stating explicitly in the document rather than leaving as silence.
    """
    found: Dict[str, List[str]] = {}
    for name in food_names:
        text = str(name or "")
        milk_text = _NUT_SEED_BUTTER_RE.sub(" ", text)
        for allergen, rx in _ALLERGEN_C.items():
            probe = milk_text if allergen == "milk" else text
            if rx.search(probe):
                found.setdefault(allergen, []).append(text)
    return {k: sorted(set(v)) for k, v in sorted(found.items())}

SULFITE_RE = re.compile(r"\b(sulfured|sulphured|sulfite|sulphite|"
                        r"dried\s+(apricot|apple|peach|pear|raisin|fruit))\b", re.I)
ADDED_SUGAR_RE = re.compile(
    r"\b(added\s+sugar|heavy\s+syrup|light\s+syrup|syrup\s+pack|sweetened|"
    r"sugared|candied|glazed|honey[\s-]roasted|crystalli[sz]ed|"
    r"in\s+syrup|with\s+sugar|honey|glucose|sucrose|corn\s+syrup)\b", re.I)
HIGH_MERCURY_RE = re.compile(
    r"\b(shark|swordfish|king\s+mackerel|tilefish|marlin|orange\s+roughy|"
    r"bigeye\s+tuna|ahi)\b", re.I)
MODERATE_MERCURY_RE = re.compile(
    r"\b(albacore|yellowfin|tuna,?\s*(canned|white)|halibut|sea\s+bass|"
    r"grouper|snapper|mahi|bluefish|monkfish)\b", re.I)
RAW_RISK_RE = re.compile(
    r"\b(raw\s+(egg|eggs|milk|oyster|fish|sprout)|unpasteuri[sz]ed|"
    r"sprouts?,\s*raw|sashimi|ceviche|tartare|soft[\s-]?boiled\s+egg|"
    r"runny\s+egg)\b", re.I)
HIGH_VIT_K_RE = re.compile(
    r"\b(kale|collard|turnip\s+greens|mustard\s+greens|spinach|swiss\s+chard|"
    r"beet\s+greens|broccoli\s+raab|rapini|parsley|brussels\s+sprouts?|"
    r"broccoli|cabbage|watercress|natto)\b", re.I)

def clinical_safety_flags(
    food_names: Sequence[str],
    nutrients: Optional[Dict[str, float]] = None,
) -> List[Dict[str, str]]:
    """Clinical review points for the assembled day.

    Each item is {'level', 'topic', 'text'}. Level is 'review' (a dietitian
    should decide) or 'note' (tell the client). Nothing here is a blocking
    error: every one of these is a legitimate plan for SOME client and wrong
    for another, and that judgement needs a person who knows the client.
    """
    out: List[Dict[str, str]] = []
    names = [str(n) for n in food_names]
    n = {k.lower(): v for k, v in (nutrients or {}).items()}

    def _hits(rx):
        return sorted({x for x in names if rx.search(x)})

    sulf = _hits(SULFITE_RE)
    if sulf:
        out.append({"level": "note", "topic": "Sulfites",
                    "text": f"Contains sulfited dried fruit ({', '.join(sulf)}). "
                            f"Sulfites trigger wheezing in a minority of people "
                            f"with asthma. Unsulfured dried fruit is a direct "
                            f"swap if the client reacts."})

    sug = _hits(ADDED_SUGAR_RE)
    if sug:
        out.append({"level": "review", "topic": "Added sugar",
                    "text": f"{len(sug)} food(s) carry added sugar or syrup "
                            f"({', '.join(sug)}). On a calorie-restricted plan "
                            f"these spend energy that buys no micronutrients. "
                            f"Unsweetened or juice-packed versions are usually "
                            f"available and free up room."})

    hg = _hits(HIGH_MERCURY_RE)
    if hg:
        out.append({"level": "review", "topic": "Mercury",
                    "text": f"{', '.join(hg)} are high-mercury species. Not "
                            f"suitable for anyone pregnant, planning pregnancy, "
                            f"breastfeeding, or for children."})
    hg2 = _hits(MODERATE_MERCURY_RE)
    if len(hg2) >= 2:
        out.append({"level": "note", "topic": "Mercury",
                    "text": f"Two or more moderate-mercury species in one day "
                            f"({', '.join(hg2)}). Fine occasionally; worth "
                            f"varying if this plan is repeated across a week."})

    raw = _hits(RAW_RISK_RE)
    if raw:
        out.append({"level": "review", "topic": "Raw / unpasteurised",
                    "text": f"{', '.join(raw)} carry a listeria or salmonella "
                            f"risk. Not suitable in pregnancy, for older "
                            f"adults, or for anyone immunocompromised."})

    vk = _hits(HIGH_VIT_K_RE)
    if len(vk) >= 3:
        out.append({"level": "review", "topic": "Vitamin K / warfarin",
                    "text": f"High in vitamin K ({', '.join(vk[:5])}"
                            f"{'...' if len(vk) > 5 else ''}). If the client "
                            f"takes warfarin this is NOT a reason to avoid "
                            f"these foods -- the requirement is a CONSISTENT "
                            f"daily intake, and a plan that swings from high "
                            f"to low is the actual hazard. Flag to whoever "
                            f"manages their INR before starting."})

    iron = n.get("iron, fe (mg)") or n.get("iron")
    if iron and float(iron) > 20:
        out.append({"level": "review", "topic": "Iron",
                    "text": f"Iron is {float(iron):.0f} mg/day, well above the "
                            f"8 mg adult male RDA. Below the 45 mg UL, so not "
                            f"unsafe, but high habitual intake is worth "
                            f"avoiding in men and postmenopausal women, and in "
                            f"anyone with haemochromatosis or a family history."})

    ca = n.get("calcium, ca (mg)") or n.get("calcium")
    ph = n.get("phosphorus, p (mg)") or n.get("phosphorus")
    if ca and ph and float(ca) > 0 and float(ph) / float(ca) > 1.8:
        out.append({"level": "note", "topic": "Calcium : phosphorus",
                    "text": f"Ca:P is about 1:{float(ph) / float(ca):.1f} "
                            f"({float(ca):.0f} mg : {float(ph):.0f} mg). A "
                            f"ratio this inverted is common on high-protein "
                            f"plans and is not harmful with normal kidney "
                            f"function, but it is a reason to keep calcium at "
                            f"the top of its range rather than the bottom."})

    fib = n.get("fiber, total dietary (g)") or n.get("fiber")
    if fib and float(fib) > 30:
        out.append({"level": "note", "topic": "Fibre",
                    "text": f"Fibre is {float(fib):.0f} g/day. Excellent, and a "
                            f"large jump for anyone not already eating this "
                            f"way. Build up over two to three weeks and "
                            f"increase fluid alongside, or the first few days "
                            f"will be uncomfortable enough to end the plan."})
    return out

FAT_PCT_ENERGY_MIN: float = 20.0
FAT_PCT_ENERGY_TARGET: float = 27.0
FAT_PCT_ENERGY_MAX: float = 35.0

def macro_distribution_review(nutrients: Dict[str, float]) -> List[Dict[str, str]]:
    """AMDR check, and the fat-floor diagnosis behind the unmet fat-soluble
    floors. Returns the same {'level','topic','text'} shape as above."""
    out: List[Dict[str, str]] = []
    n = {k.lower(): float(v) for k, v in (nutrients or {}).items()
         if isinstance(v, (int, float))}
    kcal = (n.get("energy (atwater specific factors) (kcal)")
            or n.get("energy") or 0.0)
    if kcal <= 0:
        return out
    fat = n.get("total lipid (fat) (g)") or 0.0
    pro = n.get("protein (g)") or 0.0
    cho = n.get("carbohydrate, by difference (g)") or 0.0

    fat_pct = 9.0 * fat / kcal * 100.0
    pro_pct = 4.0 * pro / kcal * 100.0
    cho_pct = 4.0 * cho / kcal * 100.0

    out.append({"level": "note", "topic": "Macronutrient split",
                "text": f"Fat {fat_pct:.0f}% of energy, protein {pro_pct:.0f}%, "
                        f"carbohydrate {cho_pct:.0f}%. AMDR is 20-35% fat, "
                        f"10-35% protein, 45-65% carbohydrate."})

    if fat_pct < FAT_PCT_ENERGY_TARGET:
        out.append({"level": "review", "topic": "Fat floor blocks LA and vitamin E",
                    "text": f"Fat is {fat_pct:.0f}% of energy, "
                            f"{'below' if fat_pct < FAT_PCT_ENERGY_MIN else 'at the bottom of'} "
                            f"the 20-35% AMDR. Linoleic acid and vitamin E "
                            f"both come almost entirely from oils, nuts and "
                            f"seeds, so a fat budget this tight makes those "
                            f"two floors unreachable no matter which foods are "
                            f"chosen -- and the 5 g nut-butter portions the "
                            f"plan keeps producing are the optimizer reaching "
                            f"for them with the only room it has. Raising fat "
                            f"toward {FAT_PCT_ENERGY_TARGET:.0f}% of energy "
                            f"(about {FAT_PCT_ENERGY_TARGET / 100 * kcal / 9:.0f} g) "
                            f"costs carbohydrate, not protein, and is the "
                            f"single change most likely to close both."})
    if pro_pct > 35:
        out.append({"level": "review", "topic": "Protein above AMDR",
                    "text": f"Protein is {pro_pct:.0f}% of energy, above the "
                            f"35% AMDR ceiling. Defensible short-term on a "
                            f"deficit for muscle preservation, but it is "
                            f"crowding out the fat and carbohydrate the plan "
                            f"needs for its other floors."})
    return out

_PACKED_IN_LIQUID_RE = re.compile(
    r"\b(solids?\s+and\s+liquids?|syrup\s+pack|in\s+(heavy|light|extra\s+heavy)\s+syrup|"
    r"packed\s+in\s+(oil|water|juice|brine))\b", re.I)
_DRAINED_ROW_RE = re.compile(r"\b(drained|drained\s+solids?)\b", re.I)
_RECIPE_DRAINS_RE = re.compile(
    r"\b(drain|drained|draining|rinse|rinsed|rinsing|tip\s+away|"
    r"discard\s+the\s+(liquid|syrup|brine|oil))\b", re.I)

def nutrition_recipe_mismatch(
    recipes: Dict[str, Any],
) -> List[Dict[str, str]]:
    """Catch recipes that discard liquid the nutrient row still counts.

    The v11-v13 P.M. Snack used "Apricots, canned, extra heavy syrup pack,
    ... solids AND LIQUIDS" and its recipe opened by rinsing the syrup off
    under cold water for thirty seconds. Both are individually right. Together
    they mean the plan's energy and carbohydrate for that food describe syrup
    the client was told to pour down the sink.

    Small in one food, but it propagates: those grams are in the meal band, in
    the day total and in every nutrient row of the comparison table. The fix
    is to choose the food row matching how the food is actually used, so this
    reports rather than silently adjusts.
    """
    out: List[Dict[str, str]] = []
    for meal, rec in (recipes or {}).items():
        steps = " ".join(_recipe_step_texts(rec)).lower()
        for ing in (rec.get("ingredients") or []):
            name = str(ing.get("name") or "")
            if _PACKED_IN_LIQUID_RE.search(name) and _RECIPE_DRAINS_RE.search(steps):
                out.append({
                    "level": "review", "topic": "Numbers vs food",
                    "text": f"{meal}: '{name}' is a solids-AND-LIQUIDS row, so "
                            f"its energy and carbohydrate include the packing "
                            f"liquid -- but the recipe drains or rinses it "
                            f"away. The plan is counting syrup the client "
                            f"pours off. Use the drained-solids row for this "
                            f"food instead."})
            elif (_DRAINED_ROW_RE.search(name)
                  and not _RECIPE_DRAINS_RE.search(steps)):
                out.append({
                    "level": "note", "topic": "Numbers vs food",
                    "text": f"{meal}: '{name}' is a DRAINED row, but the "
                            f"recipe never says to drain it. Add the draining "
                            f"step or the sodium and liquid come along "
                            f"uncounted."})
    return out

def practicality_review(
    split,
    recipes: Dict[str, Any],
    column_map: Dict[str, Any],
) -> List[Dict[str, str]]:
    """Shopping and cooking burden, as a client would experience it."""
    out: List[Dict[str, str]] = []
    try:
        f_col = _cfg(column_map, "food_col") or "food"
        names = [str(x) for x in split[f_col].tolist()]
    except Exception:
        return out

    distinct = sorted(set(names))
    if len(distinct) > 18:
        out.append({"level": "note", "topic": "Shopping burden",
                    "text": f"{len(distinct)} distinct foods for one day. That "
                            f"is a full shop for a single day's eating, and "
                            f"most of it will not be used up. Worth checking "
                            f"which items carry over if this plan is repeated."})

    once = [d for d in distinct if names.count(d) == 1]
    single_meal = [d for d in once if not is_pure_fat(d)]
    if len(single_meal) > 12:
        out.append({"level": "note", "topic": "Single-use foods",
                    "text": f"{len(single_meal)} foods appear in exactly one "
                            f"meal and nowhere else. Each is a separate "
                            f"purchase used once; consider whether any could "
                            f"be repeated across two meals to cut waste."})

    appliances: set = set()
    total_steps = 0
    for rec in (recipes or {}).values():
        total_steps += len(rec.get("steps") or [])
        for eq in (rec.get("equipment") or []):
            appliances.add(str(eq).lower())
    if total_steps > 30:
        out.append({"level": "note", "topic": "Cooking burden",
                    "text": f"{total_steps} cooking steps across the day, "
                            f"spread over five separate cooked meals. That is "
                            f"a lot of kitchen time for one person on a "
                            f"weekday; batch-cooking the protein would cut it."})

    soaks = [n for n in distinct if needs_overnight_soak(n)]
    if soaks:
        out.append({"level": "review", "topic": "Advance preparation",
                    "text": f"{', '.join(soaks)} must be started the night "
                            f"before. Make sure the client is told this at "
                            f"handover, not just in the recipe -- a soak read "
                            f"at six in the evening has already been missed."})
    return out

def clinical_review(result: Dict[str, Any]) -> Dict[str, Any]:
    """Everything in this part, run over an assembled plan.

    Returns {'allergens': {...}, 'flags': [ {...}, ... ]}. Nothing here
    blocks: these are judgements that need a person who knows the client.
    """
    split = result.get("rebuilt_meal_split")
    recipes = result.get("recipes") or {}
    cmap = result.get("column_map") or {}
    f_col = _cfg(cmap, "food_col") or "food"
    try:
        names = [str(x) for x in split[f_col].tolist()]
    except Exception:
        names = []

    nutrients = result.get("nutrition_summary") or {}
    if not isinstance(nutrients, dict):
        nutrients = {}

    flags: List[Dict[str, str]] = []
    flags += clinical_safety_flags(names, nutrients)
    flags += meal_structure_review(result)
    flags += plan_pairing_review(result)
    try:
        for meal in split[_cfg(cmap, "meal_col") or "meal"].astype(str).unique():
            sub_ = split[split[_cfg(cmap, "meal_col") or "meal"].astype(str)
                         == meal]
            flags += meal_time_plausibility(
                meal, sub_[_cfg(cmap, "food_col") or "food"].astype(str).tolist())
        flags += portion_realism_review(split, cmap)
    except Exception:
        pass
    flags += macro_distribution_review(nutrients)
    flags += nutrition_recipe_mismatch(recipes)
    if split is not None:
        flags += practicality_review(split, recipes, cmap)

    return {"allergens": detect_allergens(names), "flags": flags}

