def plate_role(food_name: Any, subgroup: Any = None) -> str:
    """What job this food does on a plate: anchor, base, vegetable, fat..."""
    sg = str(subgroup or "").strip()
    if not sg:
        sg = classify_food(food_name)[1]
    return PLATE_ROLE_BY_SUBGROUP.get(sg, "other")

MEAL_MACRO_SHARES: Dict[str, Dict[str, float]] = {
    "Breakfast":  {"protein": 0.25, "carb": 0.22, "fat": 0.22},
    "A.M. Snack": {"protein": 0.12, "carb": 0.13, "fat": 0.13},
    "Lunch":      {"protein": 0.25, "carb": 0.28, "fat": 0.27},
    "P.M. Snack": {"protein": 0.10, "carb": 0.12, "fat": 0.13},
    "Dinner":     {"protein": 0.28, "carb": 0.25, "fat": 0.25},
}
MEAL_MACRO_TOLERANCE: float = 0.40

def meal_macro_targets(meal_name: Any,
                       day_protein_g: float,
                       day_carb_g: float,
                       day_fat_g: float) -> Optional[Dict[str, float]]:
    """Grams of each macro this meal should carry, or None if unknown slot."""
    key = None
    for k in MEAL_MACRO_SHARES:
        if str(k).strip().lower() == str(meal_name).strip().lower():
            key = k
            break
    if key is None:
        return None
    sh = MEAL_MACRO_SHARES[key]
    return {"protein": sh["protein"] * float(day_protein_g),
            "carb": sh["carb"] * float(day_carb_g),
            "fat": sh["fat"] * float(day_fat_g)}

