_REQUIRES_HOB_RE = re.compile(
    r"\b(saucepan|pan|skillet|frying|fry|sear|saute|sauté|simmer|boil|"
    r"steam|roast|bake|oven|grill|broil|hob|stove|poach|braise)\w*\b", re.I)

def _slot_of(meal_name: Any) -> str:
    text = str(meal_name).strip().lower()
    slot = MEAL_NAME_ALIASES.get(text, "")
    if slot:
        return slot
    for key, val in (("snack", "snack"), ("breakfast", "breakfast"),
                     ("lunch", "lunch"), ("dinner", "dinner"),
                     ("supper", "dinner"), ("brunch", "lunch")):
        if key in text:
            return val
    return ""

MEAL_NAME_ALIASES.update({
    "a.m. snack": "snack", "p.m. snack": "snack",
    "am snack": "snack", "pm snack": "snack",
    "a.m snack": "snack", "p.m snack": "snack",
    "morning snack": "snack", "afternoon snack": "snack",
    "first snack": "snack", "second snack": "snack",
    "snack 1": "snack", "snack 2": "snack",
})

def validate_meal_structure(
    meal_name: Any,
    ingredient_names: Sequence[str],
    recipe: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, str]]:
    """Does this meal read as a meal, and can it be eaten where it is eaten?

    Returns [{'level','topic','text'}]. Levels are 'review' (a dietitian
    should look) and 'note'. Nothing here blocks: a plan that is odd-looking
    but nutritionally sound is a judgement call, and the person making it
    needs to know the client.
    """
    slot = _slot_of(meal_name)
    tpl = MEAL_TEMPLATES.get(slot)
    if not tpl:
        return []

    names = [str(n) for n in ingredient_names if str(n).strip()]
    if not names:
        return []

    roles = [plate_role(n) for n in names]
    present = set(roles)
    substantive = [n for n, r in zip(names, roles)
                   if r not in ("aromatic",) and not is_pure_fat(n)]
    out: List[Dict[str, str]] = []

    n = len(substantive)
    if n > tpl["max_items"]:
        out.append({"level": "review", "topic": f"{tpl['label']} structure",
                    "text": f"{n} components ({', '.join(substantive)}). "
                            f"Beyond {tpl['max_items']} a card stops reading "
                            f"as a dish and starts reading as a list. Ask "
                            f"whether a cook would put these in one pan."})
    elif n < tpl["min_items"]:
        out.append({"level": "review", "topic": f"{tpl['label']} structure",
                    "text": f"Only {n} component(s). A {tpl['label'].lower()} "
                            f"with fewer than {tpl['min_items']} rarely reads "
                            f"as a meal or holds anyone until the next one."})

    for group in tpl.get("required_any", []):
        if not (present & set(group)):
            out.append({"level": "review", "topic": f"{tpl['label']} has no anchor",
                        "text": f"Nothing here is a {' or '.join(group)}. "
                                f"A {tpl['label'].lower()} needs something to "
                                f"be built around."})
    for need in tpl.get("required_all", []):
        if need not in present:
            out.append({"level": "review", "topic": f"{tpl['label']} missing {need}",
                        "text": f"No {need} in this {tpl['label'].lower()}. "
                                f"At a main meal that is not optional."})

    bases = [nm for nm, r in zip(names, roles) if r == "carb_base"]
    if len(bases) > 1 and slot in ("lunch", "dinner", "breakfast"):
        out.append({"level": "review", "topic": "Two starch bases",
                    "text": f"{', '.join(bases)} are all carbohydrate bases "
                            f"in one meal. A plate has one thing carrying it; "
                            f"two is how a meal ends up reading as a list of "
                            f"components rather than a dish. Keep the one "
                            f"that suits the protein and move the other."})

    anchors = [nm for nm, r in zip(names, roles) if r == "protein_anchor"]
    if len(anchors) > 1 and slot in ("lunch", "dinner", "breakfast"):
        out.append({"level": "review", "topic": "Two protein anchors",
                    "text": f"{', '.join(anchors)} are all main proteins in "
                            f"one meal. Two unrelated anchors is a counter "
                            f"display rather than a plate; keep one and move "
                            f"the other."})

    missing_rec = [r for r in tpl.get("recommended", []) if r not in present]
    if missing_rec and n >= tpl["min_items"]:
        out.append({"level": "note", "topic": f"{tpl['label']} balance",
                    "text": f"No {', '.join(missing_rec)}. Not wrong, but a "
                            f"{tpl['label'].lower()} usually has one, and a "
                            f"fat element is what makes vegetables palatable "
                            f"and carries their fat-soluble vitamins."})

    if recipe:
        steps_txt = " ".join(_recipe_step_texts(recipe))
        mins = _duration_minutes(steps_txt)
        if mins > tpl["max_active_minutes"]:
            out.append({"level": "review", "topic": f"{tpl['label']} takes too long",
                        "text": f"Longest step is {mins:.0f} minutes against a "
                                f"{tpl['max_active_minutes']}-minute guide for "
                                f"this slot. Time is the commonest reason a "
                                f"plan is abandoned, and it is abandoned at "
                                f"the slot that costs the most."})
        if tpl.get("no_cooking") and _REQUIRES_HOB_RE.search(steps_txt):
            out.append({"level": "review", "topic": "Snack needs a stove",
                        "text": f"This snack is cooked on a hob. A snack is "
                                f"eaten at a desk or in a car -- if it needs a "
                                f"pan the client will eat something else "
                                f"instead. Rebuild it as something eaten "
                                f"straight from the container."})

    soaks = [nm for nm in names if needs_overnight_soak(nm)]
    if soaks and not tpl.get("allow_overnight_prep"):
        out.append({"level": "review", "topic": "Advance prep in the wrong slot",
                    "text": f"{', '.join(soaks)} must be started the night "
                            f"before, and it is in {tpl['label']}. Overnight "
                            f"preparation belongs at dinner, the one meal "
                            f"people plan ahead for."})

    if tpl.get("must_be_portable"):
        risky = [nm for nm in names if RAW_RISK_RE.search(nm)]
        if risky:
            out.append({"level": "review", "topic": "Carried food, raw ingredient",
                        "text": f"{', '.join(risky)} in a meal that is likely "
                                f"carried and eaten hours later. Raw or "
                                f"unpasteurised food held at room temperature "
                                f"is the classic packed-lunch hazard."})
    return out

def meal_structure_review(result: Dict[str, Any]) -> List[Dict[str, str]]:
    """Run the architecture check over every meal in an assembled plan."""
    out: List[Dict[str, str]] = []
    split = result.get("rebuilt_meal_split")
    recipes = result.get("recipes") or {}
    cmap = result.get("column_map") or {}
    f_col = _cfg(cmap, "food_col") or "food"
    m_col = _cfg(cmap, "meal_col") or "meal"
    if split is None or getattr(split, "empty", True):
        return out
    try:
        for meal in split[m_col].astype(str).unique():
            names = split.loc[split[m_col].astype(str) == meal,
                              f_col].astype(str).tolist()
            out.extend(validate_meal_structure(meal, names, recipes.get(meal)))
    except Exception as exc:
        out.append({"level": "note", "topic": "Meal structure review",
                    "text": f"skipped: {type(exc).__name__}: {exc}"})
    return out

def describe_meal_templates() -> List[Tuple[str, str]]:
    """(label, shape) for each slot, for the client document."""
    seen, out = set(), []
    for tpl in MEAL_TEMPLATES.values():
        if tpl["label"] in seen:
            continue
        seen.add(tpl["label"])
        out.append((tpl["label"], tpl["shape"]))
    return out

def client_readiness_audit(result: Dict[str, Any]) -> Dict[str, Any]:
    """Whole-document check. Returns {'blocking': [...], 'advisory': [...]}"""
    blocking: List[str] = []
    advisory: List[str] = []

    recipes = result.get("recipes") or {}
    split = result.get("rebuilt_meal_split")
    cmap = result.get("column_map") or {}
    f_col = _cfg(cmap, "food_col") or "food"
    g_col = _cfg(cmap, "grams_col") or "grams"
    m_col = _cfg(cmap, "meal_col") or "meal"

    for meal, rec in recipes.items():
        names = [str(i.get("name")) for i in (rec.get("ingredients") or [])]
        if not names:
            continue
        if not (rec.get("steps") or []):
            blocking.append(f"{meal}: no cooking steps at all.")
        ok, probs = validate_cooking_adequacy(rec, names)
        if not ok:
            blocking.append(f"{meal}: {probs[0]}")
        ok, probs = validate_prep_plausibility(rec, names)
        if not ok:
            blocking.append(f"{meal}: {probs[0]}")
        for p in standalone_edibility_problems(meal, names):
            (blocking if "different food" in p else advisory).append(p)

    if split is not None and not getattr(split, "empty", True):
        for _, r in split.iterrows():
            nm = str(r.get(f_col))
            gv = pd.to_numeric(r.get(g_col), errors="coerce")
            gv = float(gv) if pd.notna(gv) else 0.0
            sg = classify_food(nm)[1]

            why = sourcing_exclusion(nm, sg, "US")
            if why:
                blocking.append(f"'{nm}' cannot be bought by a client: {why}")

            cap = culinary_herb_cap_g(nm)
            if cap is not None and gv > cap + 0.5:
                blocking.append(
                    f"'{nm}' at {gv:.0f} g is a culinary herb served by the "
                    f"bowl (culinary quantity is about {cap:.0f} g).")

            if is_dessert_or_sweet(nm):
                slot = MEAL_NAME_ALIASES.get(str(r.get(m_col)).strip().lower(), "")
                if slot and slot != "snack":
                    advisory.append(
                        f"'{nm}' is a dessert placed in {r.get(m_col)}.")

            if gv > 300:
                advisory.append(
                    f"'{nm}' at {gv:.0f} g is a very large single portion; "
                    f"check it plates as one serving.")

    notes_all = [str(n) for n in (result.get("notes") or [])]
    for s in notes_all:
        if s.startswith("OUT OF BAND:") or s.startswith("MEAL BAND NOT ENFORCED:"):
            blocking.append(s)
        elif s.startswith("DAY ENERGY NOT RECONCILED:"):
            blocking.append(s)
        elif s.startswith("TOKEN PORTION:"):
            advisory.append(s)

    enforced = {s.split(":", 1)[1].split(" moved")[0].strip()
                for s in notes_all if s.startswith("MEAL BAND ENFORCED:")}
    failed = {s.split(":", 1)[1].split(" finished")[0].split(" was")[0].strip()
              for s in notes_all
              if s.startswith(("OUT OF BAND:", "MEAL BAND NOT ENFORCED:"))}
    for meal in enforced & failed:
        blocking.append(
            f"CONTRADICTION: the log reports {meal} as both band-enforced "
            f"and out of band. One of those is false; do not trust either "
            f"until the rescale is traced.")

    adequacy = result.get("adequacy") or {}
    for row in (adequacy.get("subgroup_coverage") or []):
        try:
            pct = float(row.get("pct") or 0)
            if pct < 100:
                advisory.append(
                    f"Food group '{row.get('label')}' at {pct:.0f}% of floor.")
        except Exception:
            continue

    try:
        clin = clinical_review(result)
        for f in clin["flags"]:
            advisory.append(f"[{f['topic']}] {f['text']}")
        if clin["allergens"] and not result.get("allergen_declaration_rendered"):
            blocking.append(
                "No allergen declaration in a plan containing: "
                + ", ".join(clin["allergens"]) + ".")
    except Exception as exc:
        advisory.append(f"Clinical review skipped: {type(exc).__name__}: {exc}")

    return {"blocking": blocking, "advisory": advisory,
            "ready": not blocking}

def print_client_readiness(audit: Dict[str, Any]) -> None:
    """Show the verdict at the console, before anyone opens the document."""
    print("\n" + "=" * 72)
    if audit.get("ready"):
        print("  CLIENT-READINESS: PASS - no blocking issues found.")
    else:
        print("  CLIENT-READINESS: BLOCKED - do not send this to a client.")
    for b in audit.get("blocking") or []:
        print(f"    BLOCKING  {b}")
    for a in (audit.get("advisory") or [])[:12]:
        print(f"    advisory  {a}")
    n_adv = len(audit.get("advisory") or [])
    if n_adv > 12:
        print(f"    ... and {n_adv - 12} more advisory item(s)")
    print("=" * 72 + "\n")

def write_client_docx(result, person=None, cfg=None, output_dir="output",
                      target_kcal=None):
    """The document a DIETITIAN would hand a client.

    write_docx() below produces a DEVELOPMENT LOG -- adjustments made,
    nutrients before and after substitution, band checks, quality warnings.
    All of that is essential and none of it belongs in front of a client. It
    is why "reads like raw optimizer output rather than something a
    nutritionist curated" is the one criticism that never improved across
    versions: the nutrition kept getting better and the DOCUMENT never changed
    shape.

    The two audiences want opposite things, so they get two documents. This
    one answers only what a client asks: who is this for, what am I aiming
    for, what do I eat, what do I buy, how do I cook it. No substitution log,
    no MAR, no band arithmetic, no internal warnings.
    """
    from docx import Document
    from docx.shared import Pt

    os.makedirs(output_dir, exist_ok=True)
    path = os.path.join(output_dir, "diet_plan_client.docx")

    _clin = clinical_review(result)
    result["allergen_declaration_rendered"] = True

    audit = client_readiness_audit(result)
    print_client_readiness(audit)

    doc = Document()

    def _write_clinical_section(document, clin):
        """Allergen declaration and clinical review, in the client document.

        Placed near the FRONT, before the meals. An allergen statement a
        client meets on page four, after they have already read the recipes,
        is a statement that arrived too late to be safe.
        """
        h = document.add_paragraph("Before you start: allergens and safety")
        h.runs[0].bold = True
        h.runs[0].font.size = Pt(13)

        allergens = clin.get("allergens") or {}
        if allergens:
            ap = document.add_paragraph(
                "This plan CONTAINS the following major allergens. Check every "
                "one against your own allergies and intolerances before you "
                "shop, and tell your dietitian if any of them is a problem for "
                "you -- do not simply leave the food out, because it is there "
                "to do a job and something has to replace it.")
            ap.runs[0].italic = True
            for allergen, foods in allergens.items():
                document.add_paragraph(
                    f"{allergen.upper()} - in: {', '.join(foods)}",
                    style="List Bullet")
        else:
            document.add_paragraph(
                "No major allergens (milk, egg, fish, shellfish, tree nuts, "
                "peanuts, wheat, soy, sesame) were identified in this plan. "
                "This is a check on food names, not a guarantee -- always read "
                "the label on anything you buy.")

        review = [f for f in (clin.get("flags") or [])
                  if f.get("level") == "review"]
        notes_c = [f for f in (clin.get("flags") or [])
                   if f.get("level") != "review"]
        if review:
            rh = document.add_paragraph("For your dietitian to review")
            rh.runs[0].bold = True
            for f in review:
                document.add_paragraph(f"{f['topic']}: {f['text']}",
                                       style="List Bullet")
        if notes_c:
            nh = document.add_paragraph("Practical notes")
            nh.runs[0].bold = True
            for f in notes_c:
                document.add_paragraph(f"{f['topic']}: {f['text']}",
                                       style="List Bullet")
        document.add_paragraph("")

    if not audit.get("ready"):
        warn = doc.add_paragraph(
            "NOT FOR CLIENT RELEASE - this plan did not pass review")
        warn.runs[0].bold = True
        warn.runs[0].font.size = Pt(14)
        wp = doc.add_paragraph(
            "The issues below must be resolved before this document is given "
            "to anyone. They are printed here rather than hidden because a "
            "plan that fails review quietly is worse than one that fails "
            "loudly.")
        wp.runs[0].italic = True
        for b in audit["blocking"]:
            doc.add_paragraph(b, style="List Bullet")
        doc.add_page_break()

    _write_clinical_section(doc, _clin)

    doc.add_heading("Your Daily Eating Plan", level=0)

    if person is not None:
        bits = []
        for lbl, attr, unit in (("Age", "age", ""), ("Sex", "sex", ""),
                                ("Weight", "weight_kg", " kg"),
                                ("Height", "height_cm", " cm"),
                                ("Activity", "activity", "")):
            v = getattr(person, attr, None)
            if v:
                bits.append(f"{lbl}: {v}{unit}")
        if bits:
            p = doc.add_paragraph("Prepared for -- " + "  |  ".join(bits))
            p.runs[0].font.size = Pt(9)
    else:
        p = doc.add_paragraph(
            "NO CLIENT PROFILE ATTACHED. This plan should not be used for a "
            "specific person until age, weight, activity and relevant medical "
            "history have been recorded and the targets checked against them.")
        p.runs[0].bold = True

    summary = result.get("nutrition_summary")
    day = None
    try:
        if summary is not None and not summary.empty:
            t = summary[summary["meal"] == "TOTAL (day)"]
            day = t.iloc[0] if not t.empty else None
    except Exception:
        day = None

    if day is not None:
        doc.add_heading("Your daily targets", level=1)
        doc.add_paragraph(
            f"Energy: about {float(day['kcal']):,.0f} kcal a day."
            + (f"  Target {float(target_kcal):,.0f} kcal."
               if target_kcal else ""))
        doc.add_paragraph(
            f"Protein: about {float(day['protein_g']):,.0f} g a day. Protein "
            f"is kept high on purpose -- under a calorie deficit it is what "
            f"protects muscle while you lose fat.")

    split = result.get("rebuilt_meal_split")
    cmap = result.get("column_map") or {}
    mcol = _cfg(cmap, "meal_col") or "meal"
    fcol = _cfg(cmap, "food_col") or "food"
    gcol = _cfg(cmap, "grams_col") or "grams"
    recipes = result.get("recipes") or {}

    if split is not None and not split.empty:
        doc.add_heading("Your day", level=1)
        for meal in (MEAL_SLOTS if "MEAL_SLOTS" in globals()
                     else sorted(split[mcol].astype(str).unique())):
            grp = split[split[mcol].astype(str) == str(meal)]
            if grp.empty:
                continue
            doc.add_heading(str(meal), level=2)
            for _, r in grp.iterrows():
                g = pd.to_numeric(r.get(gcol), errors="coerce")
                doc.add_paragraph(
                    f"{str(r.get(fcol))} - {float(g) if pd.notna(g) else 0:.0f} g",
                    style="List Bullet")
            try:
                _cs = plan_as_client_sees_it(
                    split, cmap, recipes)
                _row = next((r for r in _cs
                             if str(r["meal"]) == str(meal)), None)
            except Exception:
                _row = None
            if _row:
                dp = doc.add_paragraph(
                    f"{_row['title']}  (about {_row['kcal_rounded']} kcal)")
                dp.runs[0].bold = True
                for it in _row["items"]:
                    doc.add_paragraph(f"{it['plain']} - {it['portion']}",
                                      style="List Bullet")

            rec = recipes.get(str(meal))
            if rec and rec.get("steps"):
                doc.add_paragraph(f"How to make it: {rec.get('title','')}")

                prep = rec.get("prep_ahead") or []
                if prep:
                    hp = doc.add_paragraph("Start this the day before:")
                    hp.runs[0].bold = True
                    for line in prep:
                        doc.add_paragraph(line, style="List Bullet")

                for i, step in enumerate(rec.get("steps", []), 1):
                    doc.add_paragraph(f"{i}. {step}")
                if rec.get("common_mistake"):
                    mp = doc.add_paragraph(
                        f"Most common mistake: {rec['common_mistake']}")
                    mp.runs[0].font.size = Pt(9)
                if rec.get("storage"):
                    sp = doc.add_paragraph(f"Leftovers: {rec['storage']}")
                    sp.runs[0].font.size = Pt(9)

    if split is not None and not split.empty:
        doc.add_heading("Shopping list for the day", level=1)
        doc.add_paragraph(
            "Amounts are rounded up to something you can actually buy. Where "
            "a food is used in more than one meal it is listed once, totalled.")
        fdb = result.get("food_db_ref")
        if fdb is not None:
            try:
                for aisle, items in build_shopping_list(split, fdb, cmap):
                    doc.add_heading(aisle, level=2)
                    for nm, qty in items:
                        doc.add_paragraph(f"{nm} - {qty}", style="List Bullet")
            except Exception as exc:
                doc.add_paragraph(f"(shopping list unavailable: "
                                  f"{type(exc).__name__})")
        else:
            tot: Dict[str, float] = {}
            for _, r in split.iterrows():
                g = pd.to_numeric(r.get(gcol), errors="coerce")
                nm = str(r.get(fcol))
                tot[nm] = tot.get(nm, 0.0) + (float(g) if pd.notna(g) else 0.0)
            for nm in sorted(tot):
                doc.add_paragraph(f"{nm} - {tot[nm]:.0f} g", style="List Bullet")

    doc.add_heading("A few notes", level=1)
    for line in (
        "Weigh foods raw unless a recipe says otherwise.",
        "Plain water is free -- drink it with and between meals.",
        "If a meal leaves you hungry, tell your dietitian rather than "
        "adding food that is not on the plan; the balance matters more than "
        "any single item.",
        "This plan is one day. Repeating a single day indefinitely is not "
        "the intention -- it is a pattern to work from.",
    ):
        doc.add_paragraph(line, style="List Bullet")

    doc.save(path)
    return path

def write_docx(
    summary_df: pd.DataFrame,
    adjustments_log: pd.DataFrame,
    recipes: Dict[str, Dict[str, Any]],
    notes: List[str],
    output_dir: str,
    nutrient_change: Optional[pd.DataFrame] = None,
    adequacy: Optional[Dict[str, Any]] = None,
    front_cmp: Optional[Dict[str, Any]] = None,
) -> str:
    """
    Write the review document.

    Sections, in the order a reviewer reads them:
      1. daily totals and a per-meal target-band vs. final-kcal table, so band
         compliance is verifiable at a glance;
      2. the combined Adjustments Log (the core deliverable);
      3. one recipe card per meal, final composition;
      4. Important Notes - low-confidence substitutions, blocked shifts, meals
         that fell back to the template, and whether Gemini ran at all.

    Returns the path, or "" if python-docx is not installed (the run still
    succeeds; the caller is told in the console summary).
    """
    try:
        from docx import Document
        from docx.shared import Pt
    except ImportError as exc:
        notes.append(
            f"No .docx written: python-docx could not be imported ({exc}). "
            f"Install it with: pip install python-docx  "
            f"(the package is 'python-docx', the import name is 'docx')."
        )
        return ""

    os.makedirs(output_dir, exist_ok=True)
    path = os.path.join(output_dir, "rebuilt_diet_plan.docx")

    doc = Document()
    doc.add_heading("Rebuilt Diet Plan - Adjustments and Recipes", level=0)
    n_rescaled = 0
    try:
        if "portion_rescaled" in adjustments_log.columns:
            n_rescaled = int(
                adjustments_log["portion_rescaled"]
                .apply(lambda v: bool(v) if v is not None else False)
                .astype(bool).sum())
    except Exception:
        n_rescaled = 0
    if n_rescaled:
        doc.add_paragraph(
            f"Portions came from the optimizer. {n_rescaled} of them were "
            f"rescaled during substitution so that the replacement food "
            f"delivers the same {RESCALE_TARGET.upper()} the original did. "
            f"Every rescale is listed in the adjustments log below. A portion "
            f"is one degree of freedom, so holding one nutrient means the "
            f"others move: compare the before/after table above to see which."
        )
    else:
        doc.add_paragraph(
            "Portions in this plan were fixed by the optimizer and have not "
            "been changed. This document records food substitutions, meal "
            "reassignments, and the resulting recipes."
        )

    doc.add_heading("Daily summary and calorie-band check", level=1)
    total_row = summary_df[summary_df["meal"] == "TOTAL (day)"]
    if not total_row.empty:
        doc.add_paragraph(
            f"Daily total: {float(total_row.iloc[0]['kcal']):.0f} kcal, "
            f"{float(total_row.iloc[0]['protein_g']):.1f} g protein."
        )

    t = doc.add_table(rows=1, cols=6)
    t.style = "Table Grid"
    for i, h in enumerate(["Meal", "Target min (kcal)", "Target max (kcal)",
                           "Final kcal", "Protein (g)", "In band?"]):
        t.rows[0].cells[i].text = h
    for _, r in summary_df.iterrows():
        c = t.add_row().cells
        c[0].text = str(r["meal"])
        c[1].text = "" if pd.isna(r["band_min"]) else f"{float(r['band_min']):.0f}"
        c[2].text = "" if pd.isna(r["band_max"]) else f"{float(r['band_max']):.0f}"
        c[3].text = f"{float(r['kcal']):.0f}"
        c[4].text = f"{float(r['protein_g']):.1f}"
        c[5].text = "" if r["in_band"] is None else ("YES" if r["in_band"] else "NO - REVIEW")

    if adequacy:
        doc.add_heading("Dietary adequacy (MAR) before and after rebuild",
                        level=1)
        doc.add_paragraph(
            "Mean Adequacy Ratio uses the same formula as the front-wide "
            "comparison: NAR = min(intake / floor, 1) per nutrient, averaged. "
            "The difference is WHICH plan is scored. The front-wide table "
            "scores plans as they leave the optimizer; this scores the plan in "
            "this document, after substitutions, portion rescaling and meal "
            "moves. Quote the AFTER figure when comparing against reference "
            "diets, because it is the only one describing what is actually "
            "eaten."
        )
        t = doc.add_table(rows=1, cols=3)
        t.style = "Light Grid Accent 1"
        for i, h in enumerate(["Measure", "As optimized", "As issued"]):
            t.rows[0].cells[i].text = h
        for lbl, kb, ka, suf in [
            ("Mean Adequacy Ratio", "mar_before", "mar_after", "%"),
            ("Nutrient floors met", "floors_met_before_pct",
             "floors_met_after_pct", "%"),
        ]:
            c = t.add_row().cells
            c[0].text = lbl
            c[1].text = f"{adequacy[kb]:.1f}{suf}"
            c[2].text = f"{adequacy[ka]:.1f}{suf}"

        if adequacy.get("reference_mar"):
            doc.add_paragraph("Against the reference diets, recomputed for "
                              "the plan as issued:")
            rt = doc.add_table(rows=1, cols=4)
            rt.style = "Light Grid Accent 1"
            for i, h in enumerate(["Reference", "Its MAR",
                                   "As optimized", "As issued"]):
                rt.rows[0].cells[i].text = h
            for name, val in adequacy["reference_mar"].items():
                c = rt.add_row().cells
                c[0].text = str(name)
                c[1].text = f"{float(val):.1f}%"
                c[2].text = ("beats it"
                             if adequacy["beats_reference_before"].get(name)
                             else "does not")
                c[3].text = ("beats it"
                             if adequacy["beats_reference_after"].get(name)
                             else "does not")

        if adequacy.get("subgroup_coverage"):
            doc.add_paragraph(
                "Food-group coverage against each group's own floor. Reported "
                "separately because an aggregate MAR averages roughly thirty "
                "floors, so one missing food group costs only a few points "
                "and can hide inside a number that still reads as excellent.")
            gt = doc.add_table(rows=1, cols=4)
            gt.style = "Light Grid Accent 1"
            for i, h in enumerate(["Food group", "In plan", "Floor", "% of floor"]):
                gt.rows[0].cells[i].text = h
            for r in adequacy["subgroup_coverage"]:
                c = gt.add_row().cells
                c[0].text = str(r["group"])
                c[1].text = f"{r['grams']:,.0f} g"
                c[2].text = f"{r['floor_g']:,.0f} g"
                c[3].text = (f"{r['pct_of_floor']:.0f}%"
                             + ("" if r["met"] else "  BELOW FLOOR"))

        if front_cmp and front_cmp.get("n_front"):
            doc.add_paragraph(
                f"Against the {front_cmp['n_front']} Pareto-optimal plans this "
                f"one came from, the plan AS ISSUED scores "
                f"{front_cmp['rebuilt_mar']:.2f}% and beats "
                f"{front_cmp['n_front_beaten']} of them "
                f"({front_cmp['percentile']:.0f}th percentile), "
                f"{front_cmp['vs_front_median']:+.2f} points from the front "
                f"median. The front-wide comparison in the main results scores "
                f"plans as they leave the optimizer and does not describe this "
                f"document; report both figures rather than substituting one "
                f"for the other."
            )
            if front_cmp.get("beats_reference"):
                rt2 = doc.add_table(rows=1, cols=3)
                rt2.style = "Light Grid Accent 1"
                for i, h in enumerate(["Reference (regime-matched)",
                                       "Its MAR", "Plan as issued"]):
                    rt2.rows[0].cells[i].text = h
                for nm, v in sorted(front_cmp["references"].items(),
                                    key=lambda kv: -kv[1]):
                    c = rt2.add_row().cells
                    c[0].text = str(nm)
                    c[1].text = f"{float(v):.1f}%"
                    c[2].text = ("beats it"
                                 if front_cmp["beats_reference"].get(nm)
                                 else "does not")

        if adequacy.get("floors_short_after"):
            doc.add_paragraph(
                "Nutrient floors NOT met in the plan as issued: "
                + ", ".join(str(x) for x in adequacy["floors_short_after"][:12])
                + ("..." if len(adequacy["floors_short_after"]) > 12 else "")
            )

    if nutrient_change is not None and not nutrient_change.empty:
        doc.add_heading("Nutrients before and after substitution", level=1)
        doc.add_paragraph(
            "Day totals for the whole plan, computed the same way on both "
            "sides so any difference is a real change in the food. Rows are "
            "ordered by the size of the relative change, largest first. "
            f"Portions are rescaled during substitution to AIM at holding "
            f"{RESCALE_TARGET.upper()} constant. That aim is not always met: "
            f"portions are capped at {RESCALE_MAX_GRAMS:.0f} g, so a swap "
            f"needing more than the cap is clamped and the target nutrient "
            f"falls short anyway. Read the {RESCALE_TARGET.upper()} row below "
            f"to see what actually happened rather than assuming it held."
        )
        cols = ["nutrient", "before", "after", "change", "pct_change"]
        t = doc.add_table(rows=1, cols=len(cols))
        t.style = "Light Grid Accent 1"
        for i, h in enumerate(["Nutrient", "Before", "After", "Change", "% change"]):
            t.rows[0].cells[i].text = h
        for _, r in nutrient_change.iterrows():
            c = t.add_row().cells
            c[0].text = str(r["nutrient"])
            c[1].text = f"{r['before']:,.2f}"
            c[2].text = f"{r['after']:,.2f}"
            c[3].text = f"{r['change']:+,.2f}"
            c[4].text = ("-" if r["pct_change"] is None
                         else f"{r['pct_change']:+,.1f}%")
        tgt_row = nutrient_change[nutrient_change["nutrient"].astype(str)
                                  .str.lower().str.contains(
                                      str(RESCALE_TARGET).lower(), na=False)]
        if not tgt_row.empty:
            tr = tgt_row.iloc[0]
            pc = tr["pct_change"]
            if pc is not None and abs(float(pc)) >= 2.0:
                doc.add_paragraph(
                    f"NOTE: portions were rescaled to hold "
                    f"{RESCALE_TARGET.upper()} constant, but "
                    f"{tr['nutrient']} still moved {float(pc):+.1f}% "
                    f"({tr['before']:,.2f} to {tr['after']:,.2f}). That means "
                    f"at least one swap was clamped by the "
                    f"{RESCALE_MAX_GRAMS:.0f} g portion ceiling. See the "
                    f"PROTEIN NOT RETAINED entries in the notes for which."
                )

        crossed = nutrient_change[
            nutrient_change["crossed_below_rda"]
            | nutrient_change["crossed_over_ul"]]
        if not crossed.empty:
            doc.add_paragraph(
                "Crossed a reference limit during the rebuild (was acceptable "
                "before, is not after):"
            )
            for _, r in crossed.iterrows():
                which = ("fell below RDA" if r["crossed_below_rda"]
                         else "rose above UL")
                doc.add_paragraph(
                    f"{r['nutrient']}: {which} - {r['before']:,.2f} to "
                    f"{r['after']:,.2f}", style="List Bullet")

    doc.add_heading("Adjustments log", level=1)
    if adjustments_log.empty:
        doc.add_paragraph("No substitutions or meal shifts were required.")
    else:
        cols = ["type", "food", "replacement_or_target", "reason", "status"]
        t2 = doc.add_table(rows=1, cols=len(cols))
        t2.style = "Table Grid"
        for i, h in enumerate(["Type", "Original food",
                               "Replacement / new meal", "Reason", "Status"]):
            t2.rows[0].cells[i].text = h
        for _, r in adjustments_log.iterrows():
            c = t2.add_row().cells
            c[0].text = str(r.get("type", ""))
            c[1].text = str(r.get("food", ""))
            if r.get("type") == "MEAL SHIFT":
                c[2].text = str(r.get("target_meal") or "-")
                c[4].text = ("APPLIED" if r.get("shift_applied")
                             else f"BLOCKED - {r.get('blocked_reason', '')}")
            else:
                c[2].text = str(r.get("replacement_food") or "-")
                c[4].text = ("APPLIED" if r.get("substitution_applied")
                             else "NOT APPLIED - manual decision needed")
            c[3].text = str(r.get("reason", ""))

    doc.add_heading("Recipes", level=1)
    for meal, rec in recipes.items():
        doc.add_heading(f"{meal}: {rec.get('title', '')}", level=2)
        source = "Gemini-generated" if rec.get("used_gemini") else "templated (no model output used)"
        p = doc.add_paragraph(f"Source: {source}")
        p.runs[0].font.size = Pt(9)

        if not rec.get("used_gemini"):
            wp = doc.add_paragraph(
                "TEMPLATE ONLY - full recipe not generated. "
                f"Reason: {rec.get('fallback_reason') or 'unknown'}. "
                "The ingredients and amounts below are correct and were not "
                "affected; only the cooking instructions are missing. "
                "Re-run retry_failed_recipes() to fill these in.")
            for r_ in wp.runs:
                r_.bold = True

        meta = " | ".join(p for p in (str(rec.get("yield_note") or ""),
                                      str(rec.get("total_time") or "")) if p)
        if meta:
            mp = doc.add_paragraph(meta)
            mp.runs[0].font.size = Pt(9)

        if rec.get("equipment"):
            doc.add_paragraph("Equipment: " + ", ".join(
                str(e) for e in rec["equipment"]))

        doc.add_paragraph("Ingredients:")
        for ing in rec.get("ingredients", []):
            line = f"{ing.get('name','')} - {ing.get('amount','')}"
            if ing.get("prep_note"):
                line += f" ({ing['prep_note']})"
            doc.add_paragraph(line, style="List Bullet")

        doc.add_paragraph("Method:")
        detailed = rec.get("steps_detailed") or []
        if detailed:
            for s in detailed:
                doc.add_paragraph(str(s.get("instruction") or ""),
                                  style="List Number")
                sub = " | ".join(p for p in (str(s.get("duration") or ""),
                                             str(s.get("cue") or "")) if p)
                if sub:
                    sp = doc.add_paragraph(sub)
                    sp.runs[0].font.size = Pt(8)
        else:
            for step in rec.get("steps", []):
                doc.add_paragraph(str(step), style="List Number")

        if rec.get("common_mistake"):
            doc.add_paragraph(f"Watch out: {rec['common_mistake']}")
        if rec.get("storage"):
            doc.add_paragraph(f"Storage: {rec['storage']}")

        if rec.get("approx_note"):
            doc.add_paragraph(str(rec["approx_note"]))

    doc.add_heading("Important notes", level=1)
    if not notes:
        doc.add_paragraph("Nothing requiring manual attention was recorded.")
    for note in notes:
        doc.add_paragraph(note, style="List Bullet")

    try:
        doc.save(path)
        return path
    except PermissionError:
        alt = os.path.join(
            output_dir,
            f"rebuilt_diet_plan_{time.strftime('%Y%m%d_%H%M%S')}.docx",
        )
        try:
            doc.save(alt)
            notes.append(
                f"'{os.path.basename(path)}' was locked (it is probably open in "
                f"Word), so this run was written to "
                f"'{os.path.basename(alt)}' instead."
            )
            return alt
        except Exception as exc:
            notes.append(f"No .docx written: {type(exc).__name__}: {exc}")
            return ""
    except Exception as exc:
        notes.append(f"No .docx written: {type(exc).__name__}: {exc}")
        return ""

def _nutrient_drift(
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    orig_pos: int,
    orig_grams: float,
    cand_pos: int,
    cand_grams: float,
) -> Optional[float]:
    """Mean relative change across EVERY scored nutrient, at served portions.

    WHY THIS IS NOT COSINE SIMILARITY. The candidate ranking upstream uses
    cosine on the scaled nutrient matrix, which measures whether two foods have
    the same SHAPE. Two foods can have near-identical shape and still deliver
    very different absolute amounts of everything -- that is precisely how a
    0.85 "match" removed a third of a day's protein. Cosine also has no way to
    say WHICH nutrients moved, so a swap that holds twenty nutrients steady and
    halves one important one scores the same as the reverse.

    Drift asks the question the reviewer actually asks: for this food, at the
    portion it is actually served, how much did each nutrient move? It is
    computed per nutrient as |after - before| / before, then averaged, so every
    nutrient counts equally regardless of unit -- micrograms of selenium and
    grams of protein contribute on the same footing.

    Nutrients that were ZERO in the original are skipped rather than counted as
    infinite drift: a food that contributed no vitamin D cannot be said to have
    lost any, and including them would let a swap look catastrophic for adding
    something harmless.

    Returns None when no nutrient column can be read, so the caller can fall
    back to the existing ranking rather than treat "no data" as "no drift".
    """
    cols = _resolve_nutrient_cols(food_db, column_map)
    if not cols:
        return None
    basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
    try:
        before_row = food_db.iloc[int(orig_pos)]
        after_row = food_db.iloc[int(cand_pos)]
    except Exception:
        return None

    diffs: List[float] = []
    for c in cols:
        b = pd.to_numeric(before_row.get(c), errors="coerce")
        a = pd.to_numeric(after_row.get(c), errors="coerce")
        if pd.isna(b) or pd.isna(a):
            continue
        b_amt = float(b) * orig_grams / basis
        a_amt = float(a) * cand_grams / basis
        if abs(b_amt) < 1e-9:
            continue
        diffs.append(abs(a_amt - b_amt) / abs(b_amt))
    if not diffs:
        return None
    return float(sum(diffs) / len(diffs))

DRIFT_SELECTION_WEIGHT: float = 1.0

def _row_nutrients(
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    db_pos: int,
    grams: float,
) -> Dict[str, float]:
    """Every scored nutrient this food contributes at `grams`."""
    basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
    out: Dict[str, float] = {}
    try:
        r = food_db.reset_index(drop=True).iloc[int(db_pos)]
    except Exception:
        return out
    for c in _resolve_nutrient_cols(food_db, column_map):
        v = pd.to_numeric(r.get(c), errors="coerce")
        if pd.notna(v):
            out[c] = float(v) * grams / basis
    return out

def _floor_state(
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    plan: pd.DataFrame,
    person: Any = None,
) -> Tuple[Dict[str, float], Dict[str, float]]:
    """(day totals, floors) for nutrients this plan ALREADY meets.

    Only nutrients at or above their floor BEFORE the rebuild are returned. The
    rebuild is answerable for what it breaks; a shortfall the optimizer already
    shipped is not something a substitution can be asked to repair, and treating
    it as a constraint would make every candidate look infeasible.
    """
    try:
        rda = micronutrient_rda(person) if person is not None else {}
    except Exception:
        rda = {}

    cols = _resolve_nutrient_cols(food_db, column_map)
    if not cols:
        return {}, {}

    idx = _build_db_index(food_db.reset_index(drop=True), column_map)
    db = food_db.reset_index(drop=True)
    basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
    fcol, gcol = _cfg(column_map, "food_col"), _cfg(column_map, "grams_col")

    totals = {c: 0.0 for c in cols}
    for _, r in plan.iterrows():
        pos = idx.get(_norm(r.get(fcol)))
        if pos is None:
            continue
        g = pd.to_numeric(r.get(gcol), errors="coerce")
        g = float(g) if pd.notna(g) else 0.0
        for c in cols:
            v = pd.to_numeric(db.iloc[pos].get(c), errors="coerce")
            if pd.notna(v):
                totals[c] += float(v) * g / basis

    floors: Dict[str, float] = {}
    for c in cols:
        if not _floorable(c):
            continue
        rel = totals[c] * NUTRIENT_RETENTION_MIN if totals[c] > 0.0 else 0.0
        abs_floor = 0.0
        r = rda.get(c)
        if r and totals[c] >= float(r):
            abs_floor = float(r)
        floor = max(rel, abs_floor)
        if floor > 0.0:
            floors[c] = floor
    return {c: totals[c] for c in floors}, floors

def _floor_penalty(
    day_totals: Dict[str, float],
    floors: Dict[str, float],
) -> float:
    """Weighted shortfall below the protected floors. 0.0 = all intact.

    Each breach counts as its RELATIVE depth below the floor, times the
    nutrient's priority weight -- so a nutrient 40% under its floor is worse
    than one 5% under, and protein counts for more than either at equal depth.
    Nutrients above their floor contribute nothing: being far above a floor is
    not a virtue to be maximised, which is why this is a penalty and not a
    score.
    """
    pen = 0.0
    for c, floor in floors.items():
        amt = day_totals.get(c, 0.0)
        if floor > 0.0 and amt < floor:
            pen += _floor_weight(c) * (floor - amt) / floor
    return pen

def find_day_level_duplicates(work, food_db, column_map, verbose=True):
    """Near-identical foods appearing anywhere in the DAY, not just one meal.

    _consolidate_similar_ingredients() groups by MEAL, so two olive varieties
    land in one line only if they share a meal. Put them in Breakfast and
    Dinner and nothing notices -- which is what a reviewer saw twice: "my diet
    plan has two varieties of olives". From a shopping and cooking point of
    view that is one ingredient bought twice, whichever meals it lands in.

    REPORTED, not merged. Merging across meals would move food between meals
    and undo the arrangement the split objective just solved for -- a
    different and larger decision than tidying one plate. This surfaces the
    pairs so a reviewer can collapse them deliberately.
    """
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    group_col = _cfg(column_map, "group_col")
    if food_col not in work.columns:
        return []
    idx = _build_db_index(food_db.reset_index(drop=True), column_map)
    db = food_db.reset_index(drop=True)

    def _sg(name):
        pos = idx.get(_norm(name))
        if pos is None or not group_col or group_col not in db.columns:
            return ""
        return _norm(db.iloc[pos].get(group_col))

    rows = [(str(r[food_col]), str(r[meal_col])) for _, r in work.iterrows()]
    out, used = [], set()
    for i, (a, ma) in enumerate(rows):
        if i in used:
            continue
        grp = [(a, ma)]
        for j in range(i + 1, len(rows)):
            if j in used:
                continue
            b, mb = rows[j]
            if _sg(a) and _sg(b) != _sg(a):
                continue
            if difflib.SequenceMatcher(None, _norm(a), _norm(b)).ratio() \
                    >= CONSOLIDATE_NAME_SIMILARITY:
                grp.append((b, mb)); used.add(j)
        if len(grp) > 1:
            used.add(i)
            out.append({"foods": [g[0] for g in grp],
                        "meals": [g[1] for g in grp]})
    if verbose and out:
        print(BOLD + "\n--- SAME INGREDIENT, DIFFERENT MEALS ---" + RESET)
        for r in out:
            print(f"  {len(r['foods'])} near-identical items across "
                  f"{', '.join(sorted(set(r['meals'])))}:")
            for fn, mn in zip(r["foods"], r["meals"]):
                print(f"      {mn:<12} {fn}")
        print("  These are one ingredient from a shopping point of view. "
              "Per-meal")
        print("  consolidation does not catch them because they sit in "
              "different meals.")
    return out

def _consolidate_similar_ingredients(
    work: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
) -> Tuple[pd.DataFrame, List[Dict[str, Any]]]:
    """
    Merge NEAR-identical foods sitting in the same meal into one row.

    DISTINCT FROM _consolidate_duplicates(), which merges rows whose names are
    EXACTLY equal after a substitution lands a food next to a copy of itself.
    That one is lossless -- same food, same composition, grams simply added.
    This one is not: it merges DIFFERENT foods judged to be the same
    ingredient, so the survivor's composition ends up applied to the whole
    amount and nutrients move slightly. Both run, exact-match first.

    WHY THIS IS NOT PURELY COSMETIC. A reviewer found a P.M. Snack holding
    three olive varieties at 5 g each rather than one 15 g serving, and called
    it cosmetic. The output is cosmetic; the cause is not. NSGA-III treats
    every database row as an independent decision variable, so three olive rows
    are three separate levers it can pull, and splitting a portion across them
    is often very slightly better on some objective than concentrating it. The
    optimizer has no concept of "these are the same ingredient", so nothing
    upstream stops it and nothing downstream noticed.

    It also compounds the item-count problem reported separately: a meal can
    reach eleven "ingredients" while containing far fewer actual foods.

    WHAT COUNTS AS THE SAME INGREDIENT. Two rows merge only when they share a
    Food_Subgroup AND their names are similar above a threshold. Both
    conditions are required: name similarity alone would merge "Oil, olive"
    with "Olives, ripe", and subgroup alone would merge every leafy green in
    the meal into one. The survivor is the largest portion, on the assumption
    that the optimizer's dominant choice is the one it meant.

    CONSERVATISM. The merged row carries the SUM of the grams, so energy and
    every nutrient shift slightly -- the survivor's composition now applies to
    the whole amount. That is a real change to the plan and is why merging is
    restricted to foods that are genuinely near-identical, and why every merge
    is logged. Nothing merges across meals.
    """
    if not CONSOLIDATE_DUPLICATE_FOODS:
        return work, []

    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    grams_col = _cfg(column_map, "grams_col")
    group_col = _cfg(column_map, "group_col")
    if not (food_col and meal_col and grams_col):
        return work, []

    db_idx = _build_db_index(food_db.reset_index(drop=True), column_map)
    db = food_db.reset_index(drop=True)

    def _subgroup(name: Any) -> str:
        pos = db_idx.get(_norm(name))
        if pos is None or not group_col or group_col not in db.columns:
            return ""
        return _norm(db.iloc[pos].get(group_col))

    log: List[Dict[str, Any]] = []
    drop_ids: List[Any] = []
    df = work.copy()

    for meal, grp in df.groupby(df[meal_col].astype(str)):
        rows = list(grp.index)
        used: set = set()
        for i, ai in enumerate(rows):
            if ai in used:
                continue
            a_name = str(df.at[ai, food_col])
            a_sg = _subgroup(a_name)
            cluster = [ai]
            for bi in rows[i + 1:]:
                if bi in used:
                    continue
                b_name = str(df.at[bi, food_col])
                if a_sg and _subgroup(b_name) != a_sg:
                    continue
                sim = difflib.SequenceMatcher(
                    None, _norm(a_name), _norm(b_name)).ratio()
                if sim >= CONSOLIDATE_NAME_SIMILARITY:
                    cluster.append(bi)
            if len(cluster) < 2:
                continue

            gram_of = {k: float(pd.to_numeric(df.at[k, grams_col],
                                              errors="coerce") or 0.0)
                       for k in cluster}
            keep = max(cluster, key=lambda k: gram_of[k])
            total = sum(gram_of.values())
            merged = [str(df.at[k, food_col]) for k in cluster if k != keep]

            df.at[keep, grams_col] = total
            for k in cluster:
                used.add(k)
                if k != keep:
                    drop_ids.append(df.at[k, ROW_ID_COL])

            log.append({
                "type": "CONSOLIDATION",
                "row_id": df.at[keep, ROW_ID_COL],
                "food": "; ".join(merged),
                "original_meal": meal,
                "target_meal": meal,
                "replacement_food": str(df.at[keep, food_col]),
                "reason": (
                    f"{len(cluster)} near-identical foods in {meal} were "
                    f"merged into one {total:.0f} g serving of "
                    f"'{str(df.at[keep, food_col])}'. They share a food "
                    f"subgroup and closely matching names, so they are the "
                    f"same ingredient as far as a shopper is concerned. "
                    f"Merged away: {'; '.join(merged)}. Nutrients shift "
                    f"slightly because the survivor's composition now applies "
                    f"to the whole amount."
                ),
                "shift_applied": True,
                "blocked_reason": "",
                "_meal_col": meal_col,
            })

    if drop_ids:
        df = df[~df[ROW_ID_COL].isin(drop_ids)].reset_index(drop=True)
    return df, log

def _invalidate_precomputed_kcal(
    df: pd.DataFrame,
    mask: Any,
    column_map: Dict[str, Any],
) -> pd.DataFrame:
    """Mark rows whose grams changed so their kcal is recomputed, not reused.

    THE BUG THIS FIXES, IN FULL, BECAUSE IT IS SUBTLE AND IT SHIPPED.

    _attach_row_nutrients() has an asymmetry that is documented but easy to
    miss. Protein is ALWAYS derived from grams:

        proteins.append(p_basis * grams / basis)

    Energy is not. When column_map["meal_kcal_col"] is configured, energy is
    taken verbatim from that column and the grams are ignored:

        if pd.notna(v):
            kcals.append(float(v))          # trusted, grams irrelevant

    The contract for "this row changed, please recompute" is to set the
    precomputed value to NaN, which the substitution path does and which the
    comment beside that branch spells out.

    _reconcile_meal_bands() and _reconcile_day_energy() both scale grams and
    then drop ROW_KCAL_COL before re-attaching -- but ROW_KCAL_COL is the
    DERIVED column, not the SOURCE one. Dropping the output of a cache does
    not invalidate the cache. So the stale optimizer energy was re-trusted
    verbatim while protein was recomputed from the new grams, which is
    exactly the fingerprint a reviewer found in v12: P.M. Snack protein fell
    20.6 -> 19.8 g (x0.96, the scale factor) while its energy sat at 330 ->
    330 and stayed out of band.

    Note this was ALSO true of _reconcile_day_energy() before today. It has
    been silently failing to change energy for as long as meal_kcal_col has
    been configured, which is worth knowing when reading any past run where
    the day total did not move.
    """
    kcol = _cfg(column_map, "meal_kcal_col")
    if not kcol or kcol not in df.columns:
        return df
    df = df.copy()
    df[kcol] = pd.to_numeric(df[kcol], errors="coerce")
    df.loc[mask, kcol] = float("nan")
    return df

def _reconcile_meal_cardinality(
    work: pd.DataFrame,
    column_map: Dict[str, Any],
    max_items: Optional[int] = None,
) -> Tuple[pd.DataFrame, List[str]]:
    """Move surplus items out of overloaded meals into meals with room.

    WHY THIS IS A REPAIR AND NOT A CONSTRAINT. The note this replaces told
    reviewers a 7-item lunch "comes from the optimizer rather than the rebuild
    - it needs a cardinality penalty upstream, not a fix here." The same file
    then explains, 800 lines later, why that is wrong:

        "The optimizer cannot fix this at all: it has no meal concept. It
        optimizes the whole day as one flat list, and meals are assigned
        afterwards, HERE."

    Both notes have been in the file together for several versions, and
    reviewers have been following the first one upstream to a place where
    nothing can help. Twenty-two foods over five meals is four or five per
    meal if they are spread and eight-and-two if they are not, and the thing
    that decides which is the arrangement, not the search.

    EXCHANGE_MAX_ITEMS_PER_MEAL already weights this in the arrangement
    objective. A weight loses to any nutrient term that disagrees, which is
    the same story as the meal bands and the food-group floors. So this is the
    same answer as those: keep the weight, add a deterministic repair that
    runs afterwards.

    WHICH ITEM MOVES. Never the anchor, never the largest portion -- those are
    what the meal IS. The item that moves is the one that belongs least: worst
    mean compatibility with the rest of the meal, smallest portion as the
    tie-break. WHERE IT GOES: the meal with the most room that it is
    compatible with and permitted in. If nowhere qualifies, it stays and is
    reported, because a food shoved into a meal it clashes with is not an
    improvement on a crowded plate.
    """
    notes: List[str] = []
    cap = int(max_items or globals().get("MAX_ITEMS_PER_MEAL", 6))
    meal_col = _cfg(column_map, "meal_col")
    food_col = _cfg(column_map, "food_col")
    grams_col = _cfg(column_map, "grams_col")
    if not meal_col or meal_col not in work.columns:
        return work, notes

    df = work.copy()
    for _pass in range(12):
        counts = df[meal_col].astype(str).value_counts()
        over = [m for m, c in counts.items() if c > cap]
        if not over:
            break
        meal = over[0]
        grp = df[df[meal_col].astype(str) == meal]
        others = [str(m) for m in counts.index if str(m) != meal]

        rows = []
        for idx, r in grp.iterrows():
            nm = str(r.get(food_col))
            if plate_role(nm) in ("protein_anchor", "composite"):
                continue
            mates = [(str(o.get(food_col)), classify_food(str(o.get(food_col)))[1])
                     for i2, o in grp.iterrows() if i2 != idx]
            if mates:
                sc = sum(pair_compatibility(
                    _flavour_family(classify_food(nm)[1], nm),
                    _flavour_family(sg2, n2)) for n2, sg2 in mates) / len(mates)
            else:
                sc = 1.0
            g = pd.to_numeric(pd.Series([r.get(grams_col)]),
                              errors="coerce").fillna(0.0).iloc[0]
            rows.append((sc, float(g), idx, nm))
        if not rows:
            notes.append(
                f"TOO MANY ITEMS: {meal} has {len(grp)} foods (cap {cap}) and "
                f"every one of them is a protein anchor or composite dish. "
                f"This needs different food selection, not rearrangement.")
            break

        rows.sort()
        _, _, move_idx, move_name = rows[0]

        best_dest, best_key = None, None
        mv_fam = _flavour_family(classify_food(move_name)[1], move_name)
        for dest in others:
            dgrp = df[df[meal_col].astype(str) == dest]
            if len(dgrp) >= cap:
                continue
            role, spec = _infer_role(move_name)
            allowed = (spec or {}).get("meals") or []
            slot = _slot_of(dest)
            if role and allowed and slot and slot not in allowed:
                continue
            mates = [(str(o.get(food_col)),
                      classify_food(str(o.get(food_col)))[1])
                     for _, o in dgrp.iterrows()]
            fit = (sum(pair_compatibility(mv_fam, _flavour_family(sg2, n2))
                       for n2, sg2 in mates) / len(mates)) if mates else 1.0
            if fit < MIN_PAIR_COMPATIBILITY:
                continue
            key = (-(cap - len(dgrp)), -fit)
            if best_key is None or key < best_key:
                best_dest, best_key = dest, key

        if best_dest is None:
            notes.append(
                f"TOO MANY ITEMS: {meal} has {len(grp)} foods (cap {cap}). "
                f"'{move_name}' is the worst fit but there is nowhere "
                f"compatible to move it -- every other meal is full or would "
                f"clash. Rearranging cannot fix this one; the day is carrying "
                f"more separate foods than five meals can hold.")
            break

        df.at[move_idx, meal_col] = best_dest
        notes.append(
            f"ITEM MOVED: '{move_name}' moved from {meal} ({len(grp)} foods, "
            f"cap {cap}) to {best_dest}. It had the weakest flavour fit with "
            f"the rest of {meal} and is not its anchor. Calorie bands are "
            f"re-checked after this, so the move may shift portions.")
    return df, notes

def _reconcile_protein_anchors(
    work: pd.DataFrame,
    column_map: Dict[str, Any],
) -> Tuple[pd.DataFrame, List[str]]:
    """One main protein per meal: move the surplus somewhere it belongs.

    The reviewed Dinner held pork AND beef. Both are defensible foods and both
    were in band; two roasts on one plate is still not a dish. The arrangement
    objective weights this (EXCH_W_PROTEIN_ANCHOR) and the weight lost.
    """
    notes: List[str] = []
    meal_col = _cfg(column_map, "meal_col")
    food_col = _cfg(column_map, "food_col")
    grams_col = _cfg(column_map, "grams_col")
    if not meal_col or meal_col not in work.columns:
        return work, notes
    df = work.copy()

    for _pass in range(8):
        moved = False
        for meal, grp in df.groupby(df[meal_col].astype(str)):
            anchors = [(idx, str(r.get(food_col))) for idx, r in grp.iterrows()
                       if plate_role(str(r.get(food_col))) == "protein_anchor"]
            if len(anchors) < 2:
                continue
            def _g(i):
                v = pd.to_numeric(pd.Series([df.at[i, grams_col]]),
                                  errors="coerce").fillna(0.0).iloc[0]
                return float(v)
            anchors.sort(key=lambda t: _g(t[0]), reverse=True)
            idx, name = anchors[1]
            dest = None
            for cand, cgrp in df.groupby(df[meal_col].astype(str)):
                if str(cand) == str(meal):
                    continue
                if any(plate_role(str(r.get(food_col))) == "protein_anchor"
                       for _, r in cgrp.iterrows()):
                    continue
                slot = _slot_of(cand)
                role, spec = _infer_role(name)
                allowed = (spec or {}).get("meals") or []
                if role and allowed and slot and slot not in allowed:
                    continue
                dest = str(cand)
                break
            if dest:
                df.at[idx, meal_col] = dest
                notes.append(
                    f"SECOND ANCHOR MOVED: '{name}' moved from {meal} to "
                    f"{dest}. {meal} held two main proteins "
                    f"({', '.join(n for _, n in anchors)}); a plate is built "
                    f"on one.")
                moved = True
                break
            else:
                notes.append(
                    f"TWO PROTEIN ANCHORS: {meal} holds "
                    f"{', '.join(n for _, n in anchors)} and every other meal "
                    f"already has an anchor. The day is carrying more main "
                    f"proteins than it has meals for.")
        if not moved:
            break
    return df, notes

RECONCILE_MAX_PASSES: int = 4

def _reconcile_bands_and_energy(
    work: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    meal_kcal_bands: Dict[str, Any],
    target_kcal: float,
    substituted_ids: Optional[set] = None,
) -> Tuple[pd.DataFrame, List[str]]:
    """Run the meal-band and day-energy passes to a joint fixed point.

    THE BUG THIS FIXES, WHICH I CAUSED AND THEN MIS-FIXED.

    v12 logged "MEAL BAND ENFORCED: P.M. Snack moved 330 -> 330 kcal" beside
    "OUT OF BAND: P.M. Snack". I traced that to a stale energy cache, fixed
    the cache, and added a guard so the ENFORCED note could only be written
    once the number was verified in band.

    The same contradiction then appeared in v21, in Lunch. The guard was
    working exactly as designed. The problem is WHEN it runs:

        Stage 3c-i   meal bands   -> verifies, writes "MEAL BAND ENFORCED"
        Stage 3c     day energy   -> rescales every portion in the day
        Stage 4      verification -> writes "OUT OF BAND"

    The day-energy pass scales portions to hit the day total, and it is
    meal-band blind. So it takes a meal that Stage 3c-i has just placed
    inside its band and pushes it back out. The ENFORCED note was TRUE WHEN
    WRITTEN and false by the time the document was produced.

    That is why it recurred in a different meal: it is not about which meal
    or which number, it is about a claim being published from an intermediate
    state that a later stage then invalidates. Verifying harder at Stage 3c-i
    cannot fix it, because there is nothing wrong at Stage 3c-i.

    TWO CHANGES, and the second matters more than the first:

      1. The two passes now run alternately to a fixed point rather than
         once each in sequence. Meal bands, then day energy, then meal bands
         again, until both hold or RECONCILE_MAX_PASSES is spent.

      2. NO NOTE IS WRITTEN FROM INSIDE THE LOOP. Intermediate notes are
         discarded, and the report is generated afterwards by comparing the
         ORIGINAL state to the FINAL one. A note can therefore only ever
         describe what the reader will actually see in the plan.

    If the loop does not converge -- the two constraints genuinely fight,
    which is possible when a meal's smallest sensible portions already
    exceed its band -- it says so, and says which meal, rather than claiming
    a success it did not achieve.
    """
    meal_col = _cfg(column_map, "meal_col")
    if not meal_col or meal_col not in work.columns:
        return work, []

    def _meal_kcal(df):
        out: Dict[str, float] = {}
        for meal, grp in df.groupby(df[meal_col].astype(str)):
            out[str(meal)] = float(
                pd.to_numeric(grp[ROW_KCAL_COL], errors="coerce")
                .fillna(0.0).sum())
        return out

    def _day_kcal(df):
        return float(pd.to_numeric(df[ROW_KCAL_COL], errors="coerce")
                     .fillna(0.0).sum())

    def _in_band(meal, kc):
        band = (meal_kcal_bands or {}).get(meal)
        if not band:
            return True
        try:
            return float(band[0]) - 0.5 <= kc <= float(band[1]) + 0.5
        except Exception:
            return True

    before = _meal_kcal(work)
    day_tol = float(globals().get("DAY_KCAL_TOLERANCE_FRAC", 0.02))
    passes = 0

    for passes in range(1, RECONCILE_MAX_PASSES + 1):
        try:
            work, _ = _reconcile_meal_bands(
                work, food_db, column_map, meal_kcal_bands)
        except Exception:
            pass
        try:
            work, _ = _reconcile_day_energy(
                work, food_db, column_map, target_kcal=target_kcal,
                substituted_ids=substituted_ids)
        except Exception:
            pass

        now = _meal_kcal(work)
        day_ok = abs(_day_kcal(work) - target_kcal) <= target_kcal * day_tol
        if day_ok and all(_in_band(m_, k_) for m_, k_ in now.items()):
            break

    notes: List[str] = []
    after = _meal_kcal(work)
    day_end = _day_kcal(work)

    for meal, kc_after in sorted(after.items()):
        kc_before = before.get(meal, kc_after)
        band = (meal_kcal_bands or {}).get(meal)
        if not band:
            continue
        try:
            lo, hi = float(band[0]), float(band[1])
        except Exception:
            continue
        was_in = lo - 0.5 <= kc_before <= hi + 0.5
        is_in = lo - 0.5 <= kc_after <= hi + 0.5
        if was_in and is_in:
            continue
        if is_in:
            notes.append(
                f"MEAL BAND ENFORCED: {meal} moved {kc_before:.0f} -> "
                f"{kc_after:.0f} kcal into its {lo:.0f}-{hi:.0f} band by "
                f"rescaling portions. Verified against the FINAL plan, after "
                f"day-energy reconciliation, so this figure is the one in the "
                f"document. Food choices were NOT changed.")
        else:
            notes.append(
                f"MEAL BAND NOT ENFORCED: {meal} is at {kc_after:.0f} kcal "
                f"against {lo:.0f}-{hi:.0f} (was {kc_before:.0f}) after "
                f"{passes} reconciliation pass(es). The meal-band and "
                f"day-energy passes could not both be satisfied: pulling this "
                f"meal into band pushes the day total out of tolerance, or "
                f"the other way round. Do not treat this meal's energy as "
                f"corrected.")

    if abs(day_end - target_kcal) > 0.5:
        if abs(day_end - target_kcal) <= target_kcal * day_tol:
            notes.append(
                f"DAY ENERGY RECONCILED: total is {day_end:,.0f} kcal against "
                f"a {target_kcal:,.0f} target, inside the "
                f"{day_tol:.0%} tolerance.")
        else:
            notes.append(
                f"DAY ENERGY NOT RECONCILED: total is {day_end:,.0f} kcal "
                f"against a {target_kcal:,.0f} target, outside the "
                f"{day_tol:.0%} tolerance after {passes} pass(es).")

    if passes >= RECONCILE_MAX_PASSES:
        notes.append(
            f"RECONCILIATION DID NOT SETTLE: the meal-band and day-energy "
            f"passes were still changing the plan after "
            f"{RECONCILE_MAX_PASSES} rounds. The figures above are the final "
            f"state and are accurate, but the two constraints are fighting "
            f"and a dietitian should look at the meal listed as NOT ENFORCED.")
    return work, notes

def _reconcile_meal_bands(
    work: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    meal_kcal_bands: Dict[str, Any],
) -> Tuple[pd.DataFrame, List[str]]:
    """Force every meal inside its own calorie band by rescaling portions.

    WHY THIS EXISTS. A review asked why "P.M. Snack finished at 330 kcal
    against a band of 195-318" while the note beside it correctly said the
    violation was not caused by any swap. The note then guessed at three
    causes -- a duplicate-row merge, a food missing from food_db counted as
    zero, a band the optimizer could not meet -- and all three were wrong.

    The real answer is that NOTHING EVER ENFORCED A MEAL BAND. In
    DietProblem, self.n_band is 2, and both of those inequality constraints
    are on fm.target_kcal, which is the DAY total. There is no per-meal band
    constraint. Meal-band adherence exists only as SEL_W_MEAL_BAND = 0.50, a
    weight used to rank candidate solutions after the search -- a preference
    among finalists, not a bound on any of them. The rebuild band-checks its
    OWN shifts and substitutions, which is why a violation genuinely cannot
    come from a swap; a meal simply arrives out of band from the optimizer
    and no later stage looks.

    THIS FILE ALREADY LEARNED THIS LESSON ONCE. _reconcile_day_energy()
    below was written because day energy was weighted rather than bounded,
    and its docstring says it plainly: "Weighting cannot guarantee a bound. A
    run finished 26% over target with every term working exactly as
    designed, because 'prefer' is not 'enforce'." That is this bug, one level
    down. The day total got its enforcement pass and the meals never did.

    HOW. Same discipline as the day pass, and the same refusals:

      * Portions are scaled; foods are never swapped. Food choices were made
        for safety and practicality and are not relitigated over arithmetic.
      * Scaling is confined to the offending meal, so fixing P.M. Snack
        cannot disturb a Dinner that is already in band.
      * The meal is scaled to the NEAREST EDGE of its band, not to the
        midpoint. A meal 12 kcal over its ceiling needs a 4% trim, not a 20%
        one; moving it to the middle would be a larger change to the plan
        than the problem justifies.
      * Rows that would land under TOKEN_PORTION_MIN_G are held out of the
        scaling and the remaining rows absorb the correction instead. The
        v11 plan reported two 5 g nut-butter portions as "token portions --
        a garnish with a gram weight rather than a serving", which is the
        system flagging its own arithmetic as clutter. A pass that creates
        the thing the next pass complains about is not finished.
      * A meal that cannot be brought inside its band within the portion
        bounds is REPORTED, not forced. A portion nobody can eat is not a
        fix.

    Runs BEFORE _reconcile_day_energy(), because moving meals changes the day
    total and the day is the outer constraint. Returns (work, notes).
    """
    notes: List[str] = []
    if not meal_kcal_bands:
        return work, notes

    grams_col = _cfg(column_map, "grams_col")
    meal_col = _cfg(column_map, "meal_col")
    if not grams_col or not meal_col or meal_col not in work.columns:
        return work, notes

    df = work.copy()
    floor_g = float(globals().get("TOKEN_PORTION_MIN_G", 15.0))

    for meal_name, band in meal_kcal_bands.items():
        if not band:
            continue
        try:
            lo, hi = float(band[0]), float(band[1])
        except Exception:
            continue

        mask = df[meal_col].astype(str).str.strip().str.lower() == \
            str(meal_name).strip().lower()
        if not mask.any():
            continue

        cur = float(pd.to_numeric(df.loc[mask, ROW_KCAL_COL],
                                  errors="coerce").fillna(0.0).sum())
        if lo <= cur <= hi or cur <= 0:
            continue

        target = hi if cur > hi else lo
        factor = target / cur

        g_all = pd.to_numeric(df.loc[mask, grams_col],
                              errors="coerce").fillna(0.0)
        keep = (g_all * factor) >= floor_g if factor < 1.0 else \
            pd.Series(True, index=g_all.index)
        movable = mask.copy()
        movable.loc[g_all.index] = mask.loc[g_all.index] & keep

        if not movable.any():
            notes.append(
                f"MEAL BAND NOT ENFORCED: {meal_name} is at {cur:.0f} kcal "
                f"against {lo:.0f}-{hi:.0f}, but every portion in it would "
                f"fall below {floor_g:.0f} g if scaled. This meal needs a "
                f"different food, not a different number.")
            continue

        move_kcal = float(pd.to_numeric(df.loc[movable, ROW_KCAL_COL],
                                        errors="coerce").fillna(0.0).sum())
        held_kcal = cur - move_kcal
        if move_kcal <= 0:
            continue
        factor = (target - held_kcal) / move_kcal
        if factor <= 0:
            notes.append(
                f"MEAL BAND NOT ENFORCED: {meal_name} at {cur:.0f} kcal "
                f"against {lo:.0f}-{hi:.0f} cannot be corrected by scaling; "
                f"the portions held back at minimum size already exceed the "
                f"band on their own.")
            continue

        g = pd.to_numeric(df.loc[movable, grams_col],
                          errors="coerce").fillna(0.0)
        newg = (g * factor).clip(lower=RESCALE_MIN_GRAMS,
                                 upper=RESCALE_MAX_GRAMS)
        df.loc[movable, grams_col] = newg.astype(float)

        df = _invalidate_precomputed_kcal(df, movable, column_map)
        df = df.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL], errors="ignore")
        df, _ = _attach_row_nutrients(df, food_db, column_map)

        after = float(pd.to_numeric(df.loc[mask, ROW_KCAL_COL],
                                    errors="coerce").fillna(0.0).sum())
        held = int((mask & ~movable).sum())

        if not (lo - 0.5 <= after <= hi + 0.5):
            notes.append(
                f"MEAL BAND NOT ENFORCED: {meal_name} was rescaled to "
                f"{factor:.0%} of previous size but finished at {after:.0f} "
                f"kcal, still outside {lo:.0f}-{hi:.0f} (was {cur:.0f}). "
                f"The rescale ran and did not achieve the band. Do not treat "
                f"this meal's energy as corrected.")
            continue

        notes.append(
            f"MEAL BAND ENFORCED: {meal_name} moved {cur:.0f} -> {after:.0f} "
            f"kcal into its {lo:.0f}-{hi:.0f} band by rescaling portions "
            f"({factor:.0%} of previous size"
            + (f"; {held} portion(s) held at size to avoid creating a "
               f"garnish" if held else "")
            + "). Food choices were NOT changed. Scaling moves every nutrient "
              "in the scaled rows together, so check the before/after table.")

    return df, notes

def _reconcile_day_energy(
    work: pd.DataFrame,
    food_db: pd.DataFrame,
    column_map: Dict[str, Any],
    target_kcal: float,
    substituted_ids: Optional[set] = None,
) -> Tuple[pd.DataFrame, List[str]]:
    """
    Force the rebuilt day inside DAY_KCAL_TOLERANCE_FRAC of its target.

    WHY A SEPARATE PASS. The selection objective WEIGHTS day energy, which
    makes it a preference: the search prefers candidates that keep the day on
    target, but if no candidate does, it still picks one and the day drifts.
    Weighting cannot guarantee a bound. A run finished 26% over target with
    every term working exactly as designed, because "prefer" is not "enforce".

    So the tolerance is enforced here instead, once, after every swap and shift
    has settled and the true day total is finally known.

    HOW, AND IN WHAT ORDER. Portions are scaled, never foods swapped -- the
    food choices were made for safety and practicality and must not be
    relitigated over arithmetic.

      1. SUBSTITUTED ROWS FIRST. The drift was created by the swaps, so it is
         corrected where it was caused. A row that ballooned to 250 g of
         condensed soup is scaled back before an untouched row is disturbed at
         all.
      2. ALL ROWS, PROPORTIONALLY, only if step 1 cannot close the gap within
         the portion bounds. Uniform scaling preserves every ratio in the plan
         exactly -- the nutrient PROFILE is untouched, the whole day just moves
         together -- but it also scales protein down, so it is the fallback
         rather than the first move.

    Both steps respect RESCALE_MIN_GRAMS/RESCALE_MAX_GRAMS, so the tolerance
    can still be missed when the bounds make it unreachable. That case is
    reported rather than forced, because a portion nobody can eat is not a fix.
    """
    notes: List[str] = []
    if not target_kcal or target_kcal <= 0:
        return work, notes

    grams_col = _cfg(column_map, "grams_col")
    tol = DAY_KCAL_TOLERANCE_FRAC
    df = work.copy()

    def _day() -> float:
        return float(pd.to_numeric(df[ROW_KCAL_COL], errors="coerce")
                     .fillna(0.0).sum())

    start = _day()
    if abs(start - target_kcal) <= target_kcal * tol:
        return df, notes

    def _rescale(mask: pd.Series, factor: float) -> None:
        """Scale the masked rows by `factor`, honouring the portion bounds."""
        g = pd.to_numeric(df.loc[mask, grams_col], errors="coerce").fillna(0.0)
        newg = (g * factor).clip(lower=RESCALE_MIN_GRAMS,
                                 upper=RESCALE_MAX_GRAMS)
        df.loc[mask, grams_col] = newg.astype(float)

    for stage in ("substituted", "all"):
        cur = _day()
        if abs(cur - target_kcal) <= target_kcal * tol:
            break
        if stage == "substituted":
            if not substituted_ids:
                continue
            mask = df[ROW_ID_COL].isin(substituted_ids)
            if not mask.any():
                continue
            sub_kcal = float(pd.to_numeric(df.loc[mask, ROW_KCAL_COL],
                                           errors="coerce").fillna(0.0).sum())
            rest = cur - sub_kcal
            if sub_kcal <= 0:
                continue
            factor = (target_kcal - rest) / sub_kcal
            if factor <= 0:
                continue
        else:
            mask = pd.Series(True, index=df.index)
            factor = target_kcal / cur if cur > 0 else 1.0

        _rescale(mask, factor)
        df = _invalidate_precomputed_kcal(df, mask, column_map)
        df = df.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL], errors="ignore")
        df, _ = _attach_row_nutrients(df, food_db, column_map)

    end = _day()
    if abs(end - start) <= 0.5 and abs(start - target_kcal) > target_kcal * tol:
        notes.append(
            f"DAY ENERGY NOT RECONCILED: the rescale ran but the day total "
            f"did not move ({start:,.0f} kcal against a {target_kcal:,.0f} "
            f"target). Treat the day energy as uncorrected.")
    if abs(end - start) > 0.5:
        notes.append(
            f"DAY ENERGY RECONCILED: total moved {start:,.0f} -> {end:,.0f} "
            f"kcal against a {target_kcal:,.0f} target, by rescaling portions "
            f"(substituted rows first, then proportionally). Food choices were "
            f"NOT changed. Scaling moves every nutrient in the scaled rows "
            f"together, so check the before/after table for what else moved."
        )
    if abs(end - target_kcal) > target_kcal * tol:
        notes.append(
            f"DAY ENERGY STILL OUT: {end:,.0f} kcal against {target_kcal:,.0f} "
            f"({100.0 * (end - target_kcal) / target_kcal:+.1f}%). The portion "
            f"bounds ({RESCALE_MIN_GRAMS:.0f}-{RESCALE_MAX_GRAMS:.0f} g) make "
            f"the tolerance unreachable for this plan. Forcing it would need "
            f"portions outside those bounds, which is not a fix - the plan "
            f"needs a different food, not a different number."
        )
    return df, notes

def rebuild_plan_with_recipes(
    food_db: pd.DataFrame,
    diet_plan: pd.DataFrame,
    meal_split: pd.DataFrame,
    meal_kcal_bands: Optional[Dict[str, Tuple[float, float]]] = None,
    column_map: Optional[Dict[str, Any]] = None,
    gemini_api_key: str = "",
    output_dir: str = "output",
    person: Any = None,
    soft_targets: Optional[Dict[str, float]] = None,
    reference_mar: Optional[Dict[str, float]] = None,
    front_result: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Substitute unsafe/impractical foods, shift misplaced ones within their
    calorie bands, and generate a recipe per meal.

    Returns:
        {
          "rebuilt_meal_split": pd.DataFrame,
          "adjustments_log":    pd.DataFrame,   # substitutions AND meal shifts
          "recipes":            dict[meal_name -> recipe_dict],
          "final_meal_kcal":    dict[meal_name -> float],
          "used_gemini":        bool,
          "docx_path":          str,
          "csv_path":           str,
          # extras, harmless to ignore:
          "nutrition_summary":  pd.DataFrame,
          "micronutrient_summary": pd.DataFrame,   # day totals vs RDA / UL
          "notes":              list[str],
          "meal_kcal_bands":    dict,
        }

    Writes rebuilt_diet_plan.docx and adjustments_log.csv into output_dir.

    Always returns successfully: an empty or invalid gemini_api_key means every
    recipe is templated and used_gemini is False; every meal shift being blocked
    by its band means zero applied shifts and a fully-explained log. Neither is
    an error condition.
    """
    column_map = dict(column_map or {})
    food_col = _cfg(column_map, "food_col")
    meal_col = _cfg(column_map, "meal_col")
    grams_col = _cfg(column_map, "grams_col")
    kcal_col = _cfg(column_map, "kcal_col")
    db_food_col = _cfg(column_map, "db_food_col") or food_col
    category_col = _cfg(column_map, "category_col") or _cfg(column_map, "group_col")

    _require_columns(meal_split, [food_col, meal_col, grams_col], "meal_split")
    _require_columns(food_db, [db_food_col, kcal_col], "food_db")

    notes: List[str] = []

    work = meal_split.copy().reset_index(drop=True)
    work[ROW_ID_COL] = range(len(work))
    work, missing_from_db = _attach_row_nutrients(work, food_db, column_map)
    pre_rebuild_day_kcal = float(pd.to_numeric(
        work[ROW_KCAL_COL], errors="coerce").fillna(0.0).sum())

    if missing_from_db:
        notes.append(
            f"{len(missing_from_db)} plan food(s) could not be matched to a row in "
            f"food_db and were treated as 0 kcal: "
            f"{', '.join(missing_from_db[:8])}"
            f"{' ...' if len(missing_from_db) > 8 else ''}. "
            f"Check the food-name spelling in the optimizer output."
        )

    if diet_plan is not None and food_col in getattr(diet_plan, "columns", []):
        plan_names = {_norm(n) for n in diet_plan[food_col]}
        split_names = {_norm(n) for n in work[food_col]}
        only_in_plan = plan_names - split_names
        if only_in_plan:
            notes.append(
                f"{len(only_in_plan)} food(s) appear in diet_plan but not in "
                f"meal_split; they are absent from every meal and from the recipes."
            )

    if not meal_kcal_bands:
        meal_kcal_bands = derive_meal_kcal_bands(work, column_map, food_db, TOLERANCE_PCT)
        notes.append(
            f"The optimizer did not supply explicit calorie bands, so they were "
            f"derived as +/-{TOLERANCE_PCT * 100:.0f}% around each meal's current "
            f"total kcal."
        )
    meal_kcal_bands = {str(k): (float(v[0]), float(v[1])) for k, v in meal_kcal_bands.items()}

    unbanded = [m for m in work[meal_col].astype(str).unique() if m not in meal_kcal_bands]
    if unbanded:
        notes.append(
            f"No calorie band supplied for: {', '.join(unbanded)}. Foods will not "
            f"be shifted into or out of these meals, since the constraint cannot "
            f"be verified."
        )

    work = flag_foods(work, column_map)
    flagged = work[work["flag_category"] != ""]
    flagged_names = [str(n) for n in flagged[food_col]]

    sub_log: List[Dict[str, Any]] = []
    db_pos_index = _build_db_index(food_db.reset_index(drop=True), column_map)
    try:
        floor_running, floor_targets = _floor_state(
            food_db, column_map, meal_split, person=person)
        _lim_cols = [c for c in _resolve_nutrient_cols(food_db, column_map)
                     if _is_limit_nutrient(c)]
        limit_baseline: Dict[str, float] = {}
        if _lim_cols:
            _bi = _build_db_index(food_db.reset_index(drop=True), column_map)
            _bd = food_db.reset_index(drop=True)
            _basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
            for _, _r in meal_split.iterrows():
                _p = _bi.get(_norm(_r.get(food_col)))
                if _p is None:
                    continue
                _g = pd.to_numeric(_r.get(grams_col), errors="coerce")
                _g = float(_g) if pd.notna(_g) else 0.0
                for _c in _lim_cols:
                    _v = pd.to_numeric(_bd.iloc[_p].get(_c), errors="coerce")
                    if pd.notna(_v):
                        limit_baseline[_c] = (limit_baseline.get(_c, 0.0)
                                              + float(_v) * _g / _basis)
        limit_running = dict(limit_baseline)
    except Exception as exc:
        floor_running, floor_targets = {}, {}
        limit_baseline, limit_running = {}, {}
    day_kcal_running = float(pre_rebuild_day_kcal)
    day_target_running = float(pre_rebuild_day_kcal) or 0.0
    running_kcal: Dict[str, float] = {
        str(m): float(g[ROW_KCAL_COL].sum())
        for m, g in work.groupby(work[meal_col].astype(str))
    }

    def _cand_kcal(cand: Dict[str, Any], grams: float) -> Optional[float]:
        """kcal this candidate contributes at the ORIGINAL portion.

        Portions are never re-optimized here, so the only thing that changes is
        energy density. Returns None when the candidate's kcal cannot be read,
        in which case the band test is skipped rather than guessed at.
        """
        try:
            v = pd.to_numeric(food_db.iloc[int(cand["db_index"])][kcal_col],
                              errors="coerce")
            if pd.isna(v):
                return None
            basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
            return float(v) * grams / basis
        except Exception:
            return None

    def _cand_protein(cand: Dict[str, Any], grams: float) -> Optional[float]:
        """Protein this candidate contributes at `grams`. None if unreadable."""
        pcol = _cfg(column_map, "protein_col")
        if not pcol or pcol not in food_db.columns:
            return None
        try:
            v = pd.to_numeric(food_db.iloc[int(cand["db_index"])][pcol],
                              errors="coerce")
            if pd.isna(v):
                return None
            basis = float(_cfg(column_map, "nutrient_basis_g") or 100.0) or 100.0
            return float(v) * grams / basis
        except Exception:
            return None

    for _, row in flagged.iterrows():
        grams = pd.to_numeric(row.get(grams_col), errors="coerce")
        grams = float(grams) if pd.notna(grams) else 0.0
        meal_name = str(row[meal_col])
        band = meal_kcal_bands.get(meal_name)
        old_kcal = float(pd.to_numeric(row.get(ROW_KCAL_COL), errors="coerce") or 0.0)

        old_protein_row = float(pd.to_numeric(row.get(ROW_PROTEIN_COL),
                                              errors="coerce") or 0.0)
        _op = db_pos_index.get(_norm(row.get(food_col)))
        old_row_nutrients = (_row_nutrients(food_db, column_map, _op, grams)
                             if _op is not None else {})

        candidates = find_substitute(row, food_db, column_map, exclude_flagged=flagged_names)

        _clamp_info: Dict[int, Tuple[bool, float]] = {}

        def _portion_for(cand: Dict[str, Any]) -> Tuple[float, Optional[float], bool]:
            """(grams, kcal, was_rescaled) for this candidate in this row.

            Rescaling and the band test have to be resolved TOGETHER. Testing
            the band at the original grams and then rescaling afterwards makes
            the two fight: the selector rejects a candidate for an energy delta
            that the rescale was about to remove. So the portion is settled
            first and the band is judged on the result.

            WHICH NUTRIENT THE PORTION IS SOLVED FOR is set by RESCALE_TARGET.
            One portion is one degree of freedom, so this holds protein OR
            energy, not both -- see that constant for why protein is the
            default here.
            """
            ck = _cand_kcal(cand, grams)
            if ck is None:
                return grams, None, False
            if not (RESCALE_PORTION_ON_SUBSTITUTION and grams > 0.0):
                return grams, ck, False

            f_energy = (old_kcal / ck) if (ck > 0.0 and old_kcal > 0.0) else None
            cp = _cand_protein(cand, grams)
            f_protein = ((old_protein_row / cp)
                         if (cp and cp > 0.0 and old_protein_row > 0.0) else None)

            mode = str(RESCALE_TARGET).lower()
            if mode == "protein":
                factor = f_protein if f_protein is not None else f_energy
            elif mode == "balanced" and f_protein and f_energy:
                factor = (f_protein * f_energy) ** 0.5
            else:
                factor = f_energy if f_energy is not None else f_protein
            if factor is None or factor <= 0.0:
                return grams, ck, False

            cf = max(RESCALE_MIN_FACTOR, min(RESCALE_MAX_FACTOR, factor))
            g_ideal = grams * factor
            _plo, _phi = portion_bounds_for(
                food_db, column_map, int(cand["db_index"]), grams)
            g2 = max(_plo, min(_phi, grams * cf))
            _clamped = abs(g_ideal - g2) > 0.5
            _shortfall = (abs(g_ideal - g2) / g_ideal) if g_ideal > 0 else 0.0
            _clamp_info[id(cand)] = (_clamped, _shortfall)
            if abs(g2 - grams) <= 0.5:
                return grams, ck, False
            return g2, _cand_kcal(cand, g2), True

        best = candidates[0] if candidates else None
        new_grams, chosen_kcal, rescaled = (grams, None, False)
        band_forced = False

        if candidates:
            resolved = [(c,) + _portion_for(c) for c in candidates]

            old_protein = old_protein_row
            protein_forced = False
            floors_broken: List[str] = []
            settled = False

            if candidates:
                best_pick = None
                for c in candidates:
                    _plo, _phi = portion_bounds_for(
                        food_db, column_map, int(c["db_index"]), grams)
                    lo = max(_plo, grams * RESCALE_MIN_FACTOR)
                    hi = min(_phi, grams * RESCALE_MAX_FACTOR)
                    if hi < lo:
                        lo = hi = grams
                    steps = max(2, int(PORTION_SEARCH_STEPS))
                    trials = [grams] + [
                        lo + (hi - lo) * i / (steps - 1) for i in range(steps)]
                    for g_try in trials:
                        cand_tot = _row_nutrients(
                            food_db, column_map, int(c["db_index"]), g_try)
                        day = {
                            k: floor_running.get(k, 0.0) - old_row_nutrients.get(k, 0.0)
                               + cand_tot.get(k, 0.0)
                            for k in floor_targets
                        }
                        pen = _floor_penalty(day, floor_targets)
                        lim_day = {
                            k: limit_running.get(k, 0.0)
                               - old_row_nutrients.get(k, 0.0)
                               + cand_tot.get(k, 0.0)
                            for k in limit_baseline
                        }
                        lim_pen = _limit_penalty(lim_day, limit_baseline)
                        k_try = _cand_kcal(c, g_try)
                        band_ok = True
                        if band and k_try is not None:
                            base_k = running_kcal.get(meal_name, 0.0) - old_kcal
                            band_ok = band[0] <= base_k + k_try <= band[1]
                        drift = _nutrient_drift(
                            food_db, column_map,
                            db_pos_index.get(_norm(row.get(food_col))), grams,
                            int(c["db_index"]), g_try)
                        cl, cl_short = _clamp_info.get(id(c), (False, 0.0))

                        day_ok = True
                        if day_target_running:
                            day_after = (day_kcal_running - old_kcal
                                         + (k_try or 0.0))
                            day_ok = abs(day_after - day_target_running) <= \
                                day_target_running * DAY_KCAL_TOLERANCE_FRAC

                        day_dev = 0.0
                        if day_target_running:
                            day_after = (day_kcal_running - old_kcal
                                         + (k_try or 0.0))
                            excess = (abs(day_after - day_target_running)
                                      / day_target_running) - DAY_KCAL_TOLERANCE_FRAC
                            day_dev = max(0.0, excess)

                        band_dev = 0.0
                        if band and k_try is not None:
                            base_k = running_kcal.get(meal_name, 0.0) - old_kcal
                            after_k = base_k + k_try
                            span = max(1.0, band[1] - band[0])
                            if after_k < band[0]:
                                band_dev = (band[0] - after_k) / span
                            elif after_k > band[1]:
                                band_dev = (after_k - band[1]) / span

                        cost = (SEL_W_SODIUM_FORM
                                * _sodium_form_penalty(c.get("food_name"))
                                + SEL_W_FLOOR * pen
                                + SEL_W_DAY_KCAL * day_dev
                                + SEL_W_MEAL_BAND * band_dev
                                + SEL_W_CLAMP * cl_short
                                + SEL_W_LIMIT * lim_pen
                                + SEL_W_DRIFT * (drift if drift is not None
                                                 else 1.0))
                        key = (round(cost, 6), -float(c.get("score") or 0.0))
                        if best_pick is None or key < best_pick[0]:
                            best_pick = (key, c, g_try, k_try, pen, day)

                if best_pick is not None:
                    _, c_, g_, k_, pen_, day_ = best_pick
                    best = c_
                    rescaled = abs(g_ - grams) > 0.5
                    new_grams, chosen_kcal = g_, k_
                    band_forced = bool(
                        band and k_ is not None
                        and not (band[0] <= running_kcal.get(meal_name, 0.0)
                                 - old_kcal + k_ <= band[1])
                        and band[0] <= running_kcal.get(meal_name, 0.0) <= band[1])
                    floors_broken = [
                        c2 for c2, fl in floor_targets.items()
                        if fl > 0.0 and day_.get(c2, 0.0) < fl]
                    p_new = _cand_protein(best, new_grams)
                    protein_forced = bool(
                        old_protein > 0.0 and p_new is not None
                        and p_new < PROTEIN_RETENTION_MIN * old_protein)
                    _chosen_tot = _row_nutrients(
                        food_db, column_map, int(best["db_index"]), new_grams)
                    for k2 in floor_targets:
                        floor_running[k2] = (
                            floor_running.get(k2, 0.0)
                            - old_row_nutrients.get(k2, 0.0)
                            + _chosen_tot.get(k2, 0.0))
                    for k3 in limit_baseline:
                        limit_running[k3] = (
                            limit_running.get(k3, 0.0)
                            - old_row_nutrients.get(k3, 0.0)
                            + _chosen_tot.get(k3, 0.0))
                    settled = best is not None

            if not settled:
                if DRIFT_SELECTION_WEIGHT > 0.0 and len(resolved) > 1:
                    orig_pos = db_pos_index.get(_norm(row.get(food_col)))
                    if orig_pos is not None:
                        scored = []
                        for r_ in resolved:
                            d = _nutrient_drift(
                                food_db, column_map, orig_pos, grams,
                                int(r_[0]["db_index"]), r_[1])
                            scored.append((d if d is not None else float("inf"), r_))
                        scored.sort(key=lambda t: t[0])
                        resolved = [r_ for _, r_ in scored]

                if band:
                    base = running_kcal.get(meal_name, 0.0) - old_kcal
                    fits = [r for r in resolved
                            if r[2] is not None and band[0] <= base + r[2] <= band[1]]
                    if fits:
                        best, new_grams, chosen_kcal, rescaled = fits[0]
                    else:
                        best, new_grams, chosen_kcal, rescaled = resolved[0]
                        was_in_band = (band[0] <= running_kcal.get(meal_name, 0.0)
                                       <= band[1])
                        band_forced = was_in_band
                else:
                    best, new_grams, chosen_kcal, rescaled = resolved[0]

        if best is not None and old_protein_row > 0.0:
            _p_new = _cand_protein(best, new_grams)
            if _p_new is not None:
                protein_forced = _p_new < PROTEIN_RETENTION_MIN * old_protein_row

        if best and chosen_kcal is not None and meal_name in running_kcal:
            running_kcal[meal_name] += chosen_kcal - old_kcal
            day_kcal_running += chosen_kcal - old_kcal

        entry: Dict[str, Any] = {
            "type": "SUBSTITUTION",
            "row_id": row[ROW_ID_COL],
            "food": str(row[food_col]),
            "meal": str(row[meal_col]),
            "flag_category": row["flag_category"],
            "flag_reason_key": row["flag_reason_key"],
            "grams": round(grams, 1),
            "replacement_food": best["food_name"] if best else "",
            "similarity_score": round(best["score"], 3) if best else None,
            "alternatives": "; ".join(
                f"{c['food_name']} ({c['score']:.2f})"
                for c in candidates[1:TOP_N_SUBSTITUTES]
            ),
            "substitution_applied": bool(best),
            "band_forced": band_forced,
            "protein_forced": protein_forced,
            "portion_clamped": bool(
                _clamp_info.get(id(best), (False, 0.0))[0]) if best else False,
            "floors_broken": "; ".join(floors_broken) if floors_broken else "",
            "nutrient_drift": (
                round(_nutrient_drift(
                    food_db, column_map,
                    db_pos_index.get(_norm(row.get(food_col))), grams,
                    int(best["db_index"]), new_grams) or 0.0, 3)
                if best and db_pos_index.get(_norm(row.get(food_col))) is not None
                else None),
            "protein_original": round(old_protein, 1),
            "protein_replacement": round(
                _cand_protein(best, new_grams) or 0.0, 1) if best else None,
            "grams_original": round(grams, 1),
            "grams_rescaled": round(float(new_grams), 1) if best else None,
            "portion_rescaled": bool(rescaled),
            "_grams_col": grams_col,
            "low_confidence": bool(best and best["score"] < LOW_CONFIDENCE_SIMILARITY),
            "group_relaxed": bool(best and best.get("group_relaxed")),
            "_food_col": food_col,
        }
        entry["reason"] = build_reason(
            flag_category=row["flag_category"],
            original_food=entry["food"],
            replacement_food=entry["replacement_food"],
            why=row["flag_why"],
            score=entry["similarity_score"] or 0.0,
            grams=grams,
        )
        sub_log.append(entry)

        if entry.get("portion_clamped"):
            notes.append(
                f"UNSERVABLE MATCH: '{entry['replacement_food']}' cannot "
                f"deliver what '{entry['food']}' contributed at any portion up "
                f"to the {RESCALE_MAX_GRAMS:.0f} g ceiling, so it was capped "
                f"at {entry['grams_rescaled']:.0f} g and falls short. This is "
                f"usually a CONCENTRATE being replaced by its fluid form "
                f"(dried dairy, powders, pastes), where no servable amount of "
                f"the replacement matches the original. Raising the ceiling is "
                f"the wrong fix - it would just produce a portion nobody eats. "
                f"The database needs a comparable concentrated form."
            )
        if entry.get("floors_broken"):
            notes.append(
                f"FLOOR BROKEN BY SUBSTITUTION: replacing '{entry['food']}' "
                f"pushed these below their RDA for the day: "
                f"{entry['floors_broken']}. No candidate at any portion within "
                f"bounds kept them all intact - the database has no close "
                f"enough replacement, which is a POOL problem rather than a "
                f"selection one."
            )
        if entry.get("protein_forced"):
            notes.append(
                f"PROTEIN NOT RETAINED: replacing '{entry['food']}' cost "
                f"protein - {entry['protein_original']:.1f} g in the original "
                f"row against {entry['protein_replacement']:.1f} g in "
                f"'{entry['replacement_food']}'. No candidate in the database "
                f"kept at least {PROTEIN_RETENTION_MIN:.0%} of it even after "
                f"rescaling the portion to {entry['grams_rescaled']:.0f} g. "
                f"If that figure equals the {RESCALE_MAX_GRAMS:.0f} g ceiling, "
                f"the portion was CLAMPED and the shortfall is the cap, not "
                f"the food - a denser replacement or a higher "
                f"RESCALE_MAX_GRAMS would close it."
            )
        if entry.get("portion_rescaled"):
            notes.append(
                f"PORTION RESCALED: '{entry['food']}' -> "
                f"'{entry['replacement_food']}' has a different composition, so "
                f"the portion moved from {entry['grams_original']:.0f} g to "
                f"{entry['grams_rescaled']:.0f} g to hold this row's "
                f"{RESCALE_TARGET.upper()} at the value the optimizer chose. "
                f"A portion is one degree of freedom, so what is NOT the "
                f"rescale target has moved instead. Check the new portion is a "
                f"sensible serving of the new food."
            )
        if entry["band_forced"]:
            notes.append(
                f"BAND-FORCED SUBSTITUTION: no replacement for "
                f"'{entry['food']}' in {entry['meal']} keeps that meal inside "
                f"its calorie band at the fixed {grams:.0f} g portion, so the "
                f"closest nutritional match was used anyway and the meal is "
                f"expected to finish out of band. Safety and practicality "
                f"outrank the band here, but the portion needs a manual look."
            )
        if entry["low_confidence"]:
            notes.append(
                f"LOW-CONFIDENCE SUBSTITUTION: '{entry['food']}' -> "
                f"'{entry['replacement_food']}' scored only "
                f"{entry['similarity_score']:.2f} (threshold "
                f"{LOW_CONFIDENCE_SIMILARITY:.2f}). Review this swap manually."
            )
        if entry["group_relaxed"]:
            notes.append(
                f"'{entry['food']}' had too few same-food-group candidates, so the "
                f"search was widened to the whole database."
            )
        if not best:
            notes.append(
                f"NO SUBSTITUTE FOUND for '{entry['food']}' ({row['flag_category']}). "
                f"It remains in the plan and needs a manual decision."
            )

    work = apply_substitutions(work, sub_log)
    meal_kcal_col = _cfg(column_map, "meal_kcal_col")
    if meal_kcal_col and meal_kcal_col in work.columns:
        changed = [e["row_id"] for e in sub_log if e.get("substitution_applied")]
        if changed:
            work[meal_kcal_col] = work[meal_kcal_col].astype(float)
            work.loc[work[ROW_ID_COL].isin(changed), meal_kcal_col] = float("nan")
    work = work.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL], errors="ignore")
    work, _ = _attach_row_nutrients(work, food_db, column_map)

    work = flag_misplaced_foods(work, column_map)
    misplaced_count = int(work["misplaced"].sum())
    shift_log = _plan_meal_shifts(work, meal_kcal_bands, column_map)
    work = apply_meal_shifts(work, shift_log)

    for entry in shift_log:
        if not entry["shift_applied"]:
            notes.append(
                f"BLOCKED SHIFT: '{entry['food']}' stays in {entry['original_meal']} "
                f"- {entry['blocked_reason']}. A two-way exchange was also tried "
                f"and no partner food kept both meals in band."
            )
        elif entry.get("resolved_by_swap"):
            notes.append(
                f"RESOLVED BY EXCHANGE: '{entry['food']}' moved "
                f"{entry['original_meal']} -> {entry['target_meal']} as a two-way "
                f"swap, because a one-way move would have dropped "
                f"{entry['original_meal']} below its calorie floor."
            )

    if MERGE_DUPLICATE_ROWS_IN_MEAL:
        work, merge_notes = _consolidate_duplicates(work, column_map)
        if merge_notes:
            notes.extend(merge_notes)
            work = work.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL], errors="ignore")
            work, _ = _attach_row_nutrients(work, food_db, column_map)

    try:
        work, consolidation_log = _consolidate_similar_ingredients(
            work, food_db, column_map)
    except Exception as exc:
        consolidation_log = []
        notes.append(f"Ingredient consolidation skipped: "
                     f"{type(exc).__name__}: {exc}")
    if consolidation_log:
        work = work.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL], errors="ignore")
        work, _ = _attach_row_nutrients(work, food_db, column_map)
        for entry in consolidation_log:
            notes.append(f"MERGED SIMILAR: {entry['reason']}")

    try:
        _clamped = []
        for _i, _r in work.iterrows():
            _nm = str(_r.get(food_col))
            _cap = culinary_herb_cap_g(_nm)
            if _cap is None:
                continue
            _g = pd.to_numeric(_r.get(grams_col), errors="coerce")
            _g = float(_g) if pd.notna(_g) else 0.0
            if _g > _cap:
                work.at[_i, grams_col] = _cap
                _clamped.append((_nm, _g, _cap))
        if _clamped:
            work = work.drop(columns=[ROW_KCAL_COL, ROW_PROTEIN_COL],
                             errors="ignore")
            work, _ = _attach_row_nutrients(work, food_db, column_map)
            for _nm, _old, _cap in _clamped:
                notes.append(
                    f"PORTION CLAMPED: '{_nm}' reduced from {_old:.0f} g to "
                    f"{_cap:.0f} g. This is a culinary herb; it is eaten by "
                    f"the tablespoon. Any micronutrient it was carrying needs "
                    f"to come from somewhere else."
                )
    except Exception as exc:
        notes.append(f"Garnish-portion clamp skipped: "
                     f"{type(exc).__name__}: {exc}")

    try:
        work, _card_notes = _reconcile_meal_cardinality(work, column_map)
        notes.extend(_card_notes)
        work, _anch_notes = _reconcile_protein_anchors(work, column_map)
        notes.extend(_anch_notes)
    except Exception as exc:
        notes.append(f"Item-count reconciliation skipped: "
                     f"{type(exc).__name__}: {exc}")

    try:
        _sub_ids = {e.get("row_id") for e in sub_log
                    if e.get("substitution_applied")}
        work, _band_notes = _reconcile_bands_and_energy(
            work, food_db, column_map, meal_kcal_bands,
            target_kcal=pre_rebuild_day_kcal, substituted_ids=_sub_ids)
        notes.extend(_band_notes)
    except Exception as exc:
        notes.append(f"Band/energy reconciliation skipped: "
                     f"{type(exc).__name__}: {exc}")

    summary = summarize_nutrition(work, food_db, column_map, meal_kcal_bands)
    out_of_band = summary[(summary["in_band"] == False)]
    band_forced_meals = {str(e["meal"]) for e in sub_log if e.get("band_forced")}
    for _, r in out_of_band.iterrows():
        meal_name = str(r["meal"])
        if meal_name in band_forced_meals:
            tail = ("This was predicted: the band-forced substitution above "
                    "had no in-band alternative at the fixed portion.")
        else:
            tail = ("Shifts and substitutions are both band-checked, so this "
                    "is NOT from a swap, and the meal-band reconciliation in "
                    "Stage 3c-i could not correct it within the portion "
                    "bounds. Look for a MEAL BAND NOT ENFORCED note above "
                    "for the specific reason. This usually means the meal "
                    "holds one food whose smallest sensible portion already "
                    "exceeds the band, so it needs a different food rather "
                    "than a different number.")
        notes.append(
            f"OUT OF BAND: {meal_name} finished at {float(r['kcal']):.0f} kcal "
            f"against a band of {float(r['band_min']):.0f}-{float(r['band_max']):.0f}. "
            + tail
        )

    day_kcal = float(summary[summary["meal"] == "TOTAL (day)"]["kcal"].iloc[0]) \
        if not summary[summary["meal"] == "TOTAL (day)"].empty else 0.0
    banded = [meal_kcal_bands[m] for m in meal_kcal_bands
              if m in set(work[meal_col].astype(str))]
    day_target = None
    for src in (person, None):
        for attr in ("target_kcal", "kcal_target", "energy_target"):
            v = getattr(src, attr, None) if src is not None else None
            if v:
                try:
                    day_target = float(v)
                except Exception:
                    day_target = None
            if day_target:
                break
        if day_target:
            break
    if day_target is None:
        day_target = pre_rebuild_day_kcal or None

    if day_target and day_kcal > 0.0:
        tol = DAY_KCAL_TOLERANCE_FRAC
        lo_t, hi_t = day_target * (1 - tol), day_target * (1 + tol)
        if not (lo_t <= day_kcal <= hi_t):
            delta = day_kcal - day_target
            notes.append(
                f"DAY OFF TARGET: the rebuilt plan totals {day_kcal:,.0f} kcal "
                f"against a target of {day_target:,.0f} "
                f"({delta:+,.0f} kcal, {100.0 * delta / day_target:+.1f}%, "
                f"tolerance +/-{tol:.0%}). Every meal can still pass its own "
                f"band while this fails: the bands sum to a window roughly "
                f"five times wider than the target's tolerance, so they "
                f"constrain the shape of the day, not its total. With "
                f"RESCALE_TARGET='{RESCALE_TARGET}' the portions hold that "
                f"nutrient and let energy move, which is the usual source of "
                f"a drift this size."
            )

    if banded and day_kcal > 0.0:
        day_min = sum(b[0] for b in banded)
        day_max = sum(b[1] for b in banded)
        if day_kcal < day_min:
            short = day_min - day_kcal
            notes.append(
                f"DAY UNDER TARGET: the plan totals {day_kcal:.0f} kcal against "
                f"a summed band minimum of {day_min:.0f} kcal - short by "
                f"{short:.0f} kcal ({100.0 * short / day_min:.1f}%). Per-meal "
                f"bands are checked individually and cannot see this; a day can "
                f"be short overall while few meals look wrong. Under calorie "
                f"restriction an unintended extra deficit of this size is a "
                f"clinical problem, not a rounding one, so it needs a decision "
                f"before the plan is issued."
            )
        elif day_kcal > day_max:
            over = day_kcal - day_max
            notes.append(
                f"DAY OVER TARGET: the plan totals {day_kcal:.0f} kcal against "
                f"a summed band maximum of {day_max:.0f} kcal - over by "
                f"{over:.0f} kcal ({100.0 * over / day_max:.1f}%)."
            )

    day_protein = float(
        summary[summary["meal"] == "TOTAL (day)"]["protein_g"].iloc[0]) \
        if not summary[summary["meal"] == "TOTAL (day)"].empty else 0.0
    pre_protein = float(pd.to_numeric(
        meal_split.get(ROW_PROTEIN_COL), errors="coerce").fillna(0.0).sum()) \
        if ROW_PROTEIN_COL in meal_split.columns else 0.0
    if pre_protein > 0.0 and day_protein < 0.90 * pre_protein:
        lost = pre_protein - day_protein
        notes.append(
            f"DAY PROTEIN DOWN: {day_protein:.0f} g after the rebuild against "
            f"{pre_protein:.0f} g before it - {lost:.0f} g lost "
            f"({100.0 * lost / pre_protein:.0f}%). Under calorie restriction "
            f"protein is the macro the plan exists to protect, and because "
            f"the portion rescale is currently solving for "
            f"'{RESCALE_TARGET}', this may not show up in the calorie totals "
            f"at all."
        )

    for meal, grp in work.groupby(work[meal_col].astype(str)):
        if len(grp) > MAX_ITEMS_PER_MEAL:
            notes.append(
                f"TOO MANY ITEMS: {meal} contains {len(grp)} separate foods "
                f"(over {MAX_ITEMS_PER_MEAL}). Nobody cooks an "
                f"{len(grp)}-ingredient plate as one dish. This is flagged "
                f"BEFORE the Stage 3e repair runs; check for an ITEM MOVED "
                f"note below. If none appears, rearrangement could not fix "
                f"it. Note the old wording here sent reviewers upstream to "
                f"NSGA-III, which has no meal concept at all - it optimises "
                f"the day as one flat list and meals are assigned "
                f"afterwards, so a cardinality penalty there cannot spread "
                f"items across meals."
            )

    prot_col_name = _cfg(column_map, "protein_col")
    if prot_col_name and ROW_PROTEIN_COL in work.columns:
        for meal, grp in work.groupby(work[meal_col].astype(str)):
            mains = grp[pd.to_numeric(grp[ROW_PROTEIN_COL], errors="coerce")
                        .fillna(0.0) >= PROTEIN_MAIN_G]
            if len(mains) >= MAX_PROTEIN_MAINS_PER_MEAL + 1:
                notes.append(
                    f"PROTEIN CROWDING: {meal} holds {len(mains)} separate "
                    f"foods carrying {PROTEIN_MAIN_G:.0f} g protein or more "
                    f"({', '.join(str(x) for x in mains[food_col].head(4))}). "
                    f"Each placement may be individually valid, but the meal "
                    f"reads as several mains at once - check it against the "
                    f"meals around it."
                )

    try:
        micro = summarize_micronutrients(
            work, food_db, column_map, person=person)
    except Exception as exc:
        micro = pd.DataFrame()
        notes.append(f"Micronutrient summary unavailable: "
                     f"{type(exc).__name__}: {exc}")
    if not micro.empty:
        for _, r in micro[micro["over_ul"]].iterrows():
            notes.append(
                f"MICRONUTRIENT OVER UL: {r['nutrient']} at "
                f"{r['day_total']} ({r['pct_ul']:.0f}% of UL) after the "
                f"rebuild. Substitutions and portion rescaling both move "
                f"micronutrients more than they move energy, so this is "
                f"reported against the REBUILT plan, not the optimizer's."
            )
        low = micro[micro["below_rda"]]
        if not low.empty:
            notes.append(
                "BELOW RDA after rebuild: "
                + ", ".join(f"{r['nutrient']} ({r['pct_rda']:.0f}%)"
                            for _, r in low.head(8).iterrows())
                + ("..." if len(low) > 8 else "")
            )

    try:
        _day_dups = find_day_level_duplicates(work, food_db, column_map,
                                              verbose=False)
        for _d in _day_dups:
            notes.append(
                "SAME INGREDIENT IN TWO MEALS: "
                + " / ".join(_d["foods"])
                + f" (in {', '.join(sorted(set(_d['meals'])))}). These are one "
                  "ingredient to buy and cook; per-meal consolidation does not "
                  "catch them because they sit in different meals.")
    except Exception as exc:
        _day_dups = []
        notes.append(f"Day-level duplicate scan skipped: "
                     f"{type(exc).__name__}: {exc}")

    try:
        _tokens = find_token_portions(work, food_db, column_map, verbose=False)
        for _t in _tokens:
            notes.append(
                f"TOKEN PORTION: {_t['grams']:.0f} g of '{_t['food']}' is "
                f"below {MIN_SERVABLE_GRAMS:.0f} g -- a garnish with a gram "
                f"weight rather than a serving. It clutters the plate and the "
                f"shopping list without changing what anyone eats; consider "
                f"removing it and letting the energy reconciliation absorb it.")
    except Exception as exc:
        _tokens = []
        notes.append(f"Token-portion scan skipped: {type(exc).__name__}: {exc}")

    final_meal_kcal = {
        str(r["meal"]): float(r["kcal"])
        for _, r in summary.iterrows() if r["meal"] != "TOTAL (day)"
    }

    cat_lookup: Dict[str, str] = {}
    if category_col and category_col in food_db.columns:
        for _, r in food_db.iterrows():
            cat_lookup.setdefault(_norm(r[db_food_col]), str(r[category_col]))

    cooking_methods = {
        str(name): assign_cooking_method(str(name), cat_lookup.get(_norm(name), ""))
        for name in work[food_col].unique()
    }

    _key_ok = bool(str(gemini_api_key or "").strip())
    if not _key_ok:
        msg = ("NO GEMINI API KEY: every meal will use the templated recipe "
               "card. Those cards are cookable -- correct times, doneness "
               "cues and storage -- but they are shorter than model-written "
               "ones and this is NOT the full output. Set the key and run "
               "retry_failed_recipes() to fill them in.")
        print(f"\n  {'!' * 66}\n  {msg}\n  {'!' * 66}\n")
        notes.append(msg)
    elif GEMINI_PREFLIGHT_ON_BATCH:
        try:
            _call_gemini("Reply with the single word: ok", gemini_api_key,
                         max_attempts=1,
                         timeout=GEMINI_PREFLIGHT_TIMEOUT_S,
                         deadline=time.monotonic() + GEMINI_PREFLIGHT_MAX_WAIT_S)
        except Exception as exc:
            msg = (f"GEMINI PREFLIGHT FAILED ({type(exc).__name__}: "
                   f"{str(exc)[:120]}). Recipes will be attempted anyway -- "
                   f"the retry policy handles a transient outage -- but if "
                   f"every meal comes back templated, this is why.")
            print(f"\n  {msg}\n")
            notes.append(msg)

    recipes: Dict[str, Dict[str, Any]] = {}
    meal_order = list(dict.fromkeys(work[meal_col].astype(str)))
    for i, meal in enumerate(meal_order):
        rows = work[work[meal_col].astype(str) == meal]
        recipes[meal] = build_recipe(
            meal_name=meal,
            meal_foods_df=rows,
            cooking_methods=cooking_methods,
            kcal=float(rows[ROW_KCAL_COL].sum()),
            protein=float(rows[ROW_PROTEIN_COL].sum()),
            gemini_api_key=gemini_api_key,
            column_map=column_map,
        )
        if gemini_api_key and i < len(meal_order) - 1:
            time.sleep(GEMINI_INTER_CALL_DELAY_S)

    used_gemini = any(r.get("used_gemini") for r in recipes.values())
    if not gemini_api_key:
        notes.append(
            "No Gemini API key was supplied for this run, so every recipe uses the "
            "templated fallback."
        )
    for meal, rec in recipes.items():
        if rec.get("gemini_added_ingredient"):
            notes.append(
                f"gemini_added_ingredient: True for {meal}. The model's recipe "
                f"introduced or renamed an ingredient, so it was rejected and the "
                f"templated recipe was used instead."
            )
        elif not rec.get("used_gemini") and gemini_api_key:
            notes.append(
                f"{meal} used the templated fallback: {rec.get('fallback_reason', '')}"
            )

    adjustments_log = pd.DataFrame(sub_log + shift_log + consolidation_log)
    if not adjustments_log.empty:
        adjustments_log = adjustments_log.drop(
            columns=[c for c in adjustments_log.columns if c.startswith("_")],
            errors="ignore",
        )
        front = ["type", "food", "meal", "original_meal", "target_meal",
                 "replacement_food", "similarity_score", "reason",
                 "substitution_applied", "shift_applied", "blocked_reason"]
        ordered = [c for c in front if c in adjustments_log.columns]
        adjustments_log = adjustments_log[
            ordered + [c for c in adjustments_log.columns if c not in ordered]
        ]
        for col, filler in (("target_meal", ""), ("original_meal", ""),
                            ("replacement_food", ""), ("blocked_reason", ""),
                            ("meal", ""), ("alternatives", ""),
                            ("flag_category", ""), ("flag_reason_key", ""),
                            ("shift_applied", False), ("substitution_applied", False),
                            ("low_confidence", False), ("group_relaxed", False),
                            ("kcal_moved", 0.0), ("grams", 0.0)):
            if col in adjustments_log.columns:
                s = adjustments_log[col]
                adjustments_log[col] = s.where(s.notna(), filler).infer_objects(
                    copy=False)

    csv_path = write_csv(adjustments_log, output_dir)
    try:
        nutrient_change = summarize_nutrient_change(
            meal_split, work, food_db, column_map,
            person=person)
    except Exception as exc:
        nutrient_change = pd.DataFrame()
        notes.append(f"Before/after nutrient table unavailable: "
                     f"{type(exc).__name__}: {exc}")
    try:
        adequacy = summarize_adequacy(
            meal_split, work, food_db, column_map,
            soft_targets=soft_targets, reference_mar=reference_mar)
    except Exception as exc:
        adequacy = {}
        notes.append(f"Adequacy comparison unavailable: "
                     f"{type(exc).__name__}: {exc}")
    front_cmp: Dict[str, Any] = {}
    if adequacy and front_result:
        try:
            front_cmp = compare_rebuilt_to_front(
                front_result, adequacy["mar_after"], verbose=False)
            if front_cmp.get("n_front"):
                notes.append(
                    f"VS THE FRONT: the issued plan scores "
                    f"{front_cmp['rebuilt_mar']:.2f}% MAR and beats "
                    f"{front_cmp['n_front_beaten']}/{front_cmp['n_front']} of "
                    f"the Pareto-front plans it came from "
                    f"({front_cmp['percentile']:.0f}th percentile). The "
                    f"front-wide statistics describe plans AS OPTIMIZED; this "
                    f"is the plan AS ISSUED. Quote this one for this document."
                )
        except Exception as exc:
            notes.append(f"Front comparison unavailable: "
                         f"{type(exc).__name__}: {exc}")
    if adequacy:
        d = adequacy["mar_delta"]
        if abs(d) >= 0.5:
            notes.append(
                f"ADEQUACY CHANGED: MAR moved {adequacy['mar_before']:.1f}% -> "
                f"{adequacy['mar_after']:.1f}% ({d:+.1f} points) across the "
                f"rebuild. The front-wide comparison scores the plan AS "
                f"OPTIMIZED; this is the plan as ISSUED. Quote this figure "
                f"when comparing against DASH/MIND/Mediterranean, not the "
                f"front-wide one."
            )
        lost = [k for k, v in adequacy["beats_reference_before"].items()
                if v and not adequacy["beats_reference_after"].get(k)]
        if lost:
            notes.append(
                f"REFERENCE-DIET ADVANTAGE LOST: the optimized plan beat "
                f"{', '.join(lost)} on MAR; the rebuilt plan does not. The "
                f"substitutions that cost it were made for safety or "
                f"practicality, so this is a real trade rather than an error "
                f"- but the front-wide claim no longer holds for this plan."
            )
    _self = {}
    try:
        _self = score_plan_quality(
            {**{"rebuilt_meal_split": work, "column_map": column_map,
                "recipes": recipes, "nutrition_summary": summary,
                "micronutrient_summary": micro, "nutrient_change": nutrient_change,
                "adequacy": adequacy, "day_level_duplicates": _day_dups}},
            person=person, verbose=False)
        _low = [k for k, v in _self["scores"].items() if v < 6.0]
        for _k in _low:
            notes.append(
                f"QUALITY SCREEN: {_k} scores {_self['scores'][_k]}/10 -- "
                + "; ".join(_self["notes"][_k] or ["see the detail above"])
                + ". Review before this is issued.")
    except Exception as exc:
        notes.append(f"Quality screen unavailable: {type(exc).__name__}: {exc}")

    docx_path = write_docx(summary, adjustments_log, recipes, notes,
                           output_dir, nutrient_change=nutrient_change,
                           adequacy=adequacy, front_cmp=front_cmp)
    try:
        client_path = write_client_docx(
            {"nutrition_summary": summary, "rebuilt_meal_split": work,
             "column_map": column_map, "recipes": recipes,
             "food_db_ref": food_db},
            person=person, output_dir=output_dir)
        print(f"  Client-facing plan: {client_path}")
    except Exception as exc:
        client_path = ""
        notes.append(f"Client document not written: "
                     f"{type(exc).__name__}: {exc}")

    rebuilt = work.drop(columns=[c for c in INTERNAL_COLS if c in work.columns],
                        errors="ignore")

    applied_subs = sum(1 for e in sub_log if e["substitution_applied"])
    low_conf = sum(1 for e in sub_log if e["low_confidence"])
    applied_shifts = sum(1 for e in shift_log if e["shift_applied"])
    blocked_shifts = [e for e in shift_log if not e["shift_applied"]]
    gemini_meals = [m for m, r in recipes.items() if r.get("used_gemini")]
    fallback_meals = [m for m, r in recipes.items() if not r.get("used_gemini")]

    print("\n" + "=" * 72)
    print("DIET PLAN REBUILD SUMMARY")
    print("=" * 72)
    print(f"Foods flagged for substitution : {len(sub_log)}")
    print(f"Substitutions made             : {applied_subs}")
    print(f"Low-confidence matches (<{LOW_CONFIDENCE_SIMILARITY:.2f}) : {low_conf}"
          + ("  <-- manual review needed" if low_conf else ""))
    print(f"Foods flagged as misplaced     : {misplaced_count}")
    print(f"Meal shifts applied            : {applied_shifts}")
    print(f"Meal shifts blocked by band    : {len(blocked_shifts)}")
    for e in blocked_shifts:
        print(f"    - {e['food']} ({e['original_meal']}): {e['blocked_reason']}")
    print(f"Recipes via Gemini             : {len(gemini_meals)}"
          + (f"  [{', '.join(gemini_meals)}]" if gemini_meals else ""))
    print(f"Recipes via template fallback  : {len(fallback_meals)}"
          + (f"  [{', '.join(fallback_meals)}]" if fallback_meals else ""))
    if not gemini_api_key:
        print("    (no API key supplied this run - Gemini was not called)")
    elif fallback_meals:
        print("    Gemini was tried but did not produce a usable recipe:")
        seen_reasons = set()
        for meal in fallback_meals:
            reason = (recipes[meal].get("fallback_reason")
                      or ("rejected: introduced an ingredient not in the meal"
                          if recipes[meal].get("gemini_added_ingredient") else "")
                      or "unknown reason")
            if reason not in seen_reasons:
                seen_reasons.add(reason)
                print(f"      - {reason}")
        print("    Everything else in this run is unaffected; the recipes above")
        print("    use the templated fallback built from the assigned methods.")
    print(f"Meals outside their kcal band  : {len(out_of_band)}")
    print(f"Written: {csv_path}")
    print(f"Written: {docx_path or '(docx skipped - python-docx not installed)'}")
    print("=" * 72 + "\n")

    return {
        "rebuilt_meal_split": rebuilt,
        "adjustments_log": adjustments_log,
        "recipes": recipes,
        "final_meal_kcal": final_meal_kcal,
        "used_gemini": used_gemini,
        "docx_path": docx_path,
        "csv_path": csv_path,
        "nutrition_summary": summary,
        "micronutrient_summary": micro,
        "nutrient_change": nutrient_change,
        "adequacy": adequacy,
        "front_comparison": front_cmp,
        "column_map": column_map,
        "day_level_duplicates": _day_dups,
        "quality": _self,
        "food_db_ref": food_db,
        "client_docx_path": client_path,
        "token_portions": _tokens,
        "notes": notes,
        "meal_kcal_bands": meal_kcal_bands,
    }

import getpass as _getpass

REBUILD_RESTRICT_TO_CANDIDATE_POOL = True

REBUILD_OUTPUT_DIR = "rebuild_output"

REBUILD_PROTEIN_COL = "Protein (G)"

def prompt_gemini_api_key(skip_prompt: bool = False) -> str:
    """Ask for the Google Gemini API key. This is the UI 'input box'.

    Asked HERE, at pool selection, rather than at the end of the run. A
    research-grade run is long; stopping for a prompt after it finishes means
    an unattended run sits waiting instead of finishing its output. The key is
    held in a local variable and handed to the rebuild module at the end.

    Read with getpass so the key is NOT echoed to the terminal and does not
    end up in a scrollback buffer or a screen recording. getpass fails on some
    IDE consoles that do not present a real tty, so it falls back to input()
    with an explicit warning that the key WILL be visible.

    Pressing Enter is a valid answer: the rebuild still runs and every recipe
    uses the templated fallback. Nothing here writes the key to disk.
    """
    if skip_prompt:
        return ""

    print("\n--- Recipe generation (optional) -----------------------------")
    print("  Paste a Google Gemini API key to have recipes written for each")
    print("  meal. Press Enter to skip -- the plan, the substitutions and the")
    print("  meal shifts are all produced either way, using templated recipes.")
    print("  The key is used in memory only: never printed, never logged,")
    print("  never written to any output file.")
    try:
        key = _getpass.getpass("  Gemini API key (hidden, Enter to skip): ").strip()
    except Exception:
        print("  (this console cannot hide input -- the key WILL be visible)")
        key = input("  Gemini API key (Enter to skip): ").strip()

    if key:
        print(f"  checking the key (up to "
              f"{GEMINI_PREFLIGHT_MAX_WAIT_S:.0f}s) ...", end="", flush=True)
        ok, msg = check_gemini_access(key)
        if ok:
            print(f"\n  -> key {msg}; recipes will be generated via Gemini.")
        else:
            print(f"\n  -> key check FAILED: {msg}")
            print("     The run will continue and use templated recipes.")
            print("     Common causes: the Generative Language API is not")
            print("     enabled for this key, the key is restricted, or the")
            print("     free-tier quota is exhausted.")
            again = input("  Re-enter the key? [y/N]: ").strip().lower()
            if again == "y":
                return prompt_gemini_api_key()
    else:
        print("  -> no key given; templated recipes will be used.")
    return key

def _rebuild_protein_col(df) -> str:
    """Pick the protein column, tolerating schema differences between pools."""
    if REBUILD_PROTEIN_COL in df.columns:
        return REBUILD_PROTEIN_COL
    for c in nc.COL_CANDIDATES.get("protein", []):
        if c in df.columns:
            return c
    return ""

def build_rebuild_inputs(fm, x):
    """Assemble everything rebuild_plan_with_recipes() needs, in memory.

    Returns (food_db, diet_plan, meal_split, meal_kcal_bands, column_map).

    Nothing here re-derives nutrition. build_meal_split() is called a second
    time rather than having its result threaded through report(); it is
    deterministic (ties break on name, by design, so the arrangement is
    reproducible), so this reproduces exactly the split that was printed.
    """
    x = np.asarray(x, dtype=float)
    desc_col = fm._desc_col()

    if REBUILD_RESTRICT_TO_CANDIDATE_POOL:
        food_db = fm.df.iloc[list(fm.cand_idx)].copy()
    else:
        food_db = fm.df.copy()
    food_db = food_db.drop_duplicates(subset=[desc_col], keep="first")

    plan_rows = [
        {"food": str(fm.names[k]), "grams": round(float(xk) * 100.0, 1)}
        for k, xk in enumerate(x) if float(xk) * 100.0 > 1e-9
    ]
    diet_plan = pd.DataFrame(plan_rows, columns=["food", "grams"])

    assign, meal_kcal = build_meal_split(fm, x)
    split_rows = []
    for meal in MEAL_SLOTS:
        for name, grams, kcal in assign[meal]:
            split_rows.append({"meal": meal, "food": str(name),
                               "grams": round(float(grams), 1),
                               "kcal": round(float(kcal), 1)})
    meal_split = pd.DataFrame(split_rows, columns=["meal", "food", "grams", "kcal"])

    total_kcal = float(sum(meal_kcal.values())) or 1.0
    tol = MEAL_BAND_TOLERANCE_PP / 100.0
    meal_kcal_bands = {}
    for meal in MEAL_SLOTS:
        lo, hi = MEAL_KCAL_BAND[meal]
        meal_kcal_bands[meal] = (max(0.0, (lo - tol) * total_kcal),
                                 (hi + tol) * total_kcal)

    column_map = {
        "food_col": "food",
        "meal_col": "meal",
        "grams_col": "grams",
        "meal_kcal_col": "kcal",
        "db_food_col": desc_col,
        "kcal_col": fm.energy_col,
        "protein_col": _rebuild_protein_col(food_db),
        "group_col": ("Food_Subgroup" if "Food_Subgroup" in food_db.columns
                      else ("Food_Type" if "Food_Type" in food_db.columns
                            else "")),
        "category_col": ("Food_Subgroup" if "Food_Subgroup" in food_db.columns
                         else ""),
        "nutrient_basis_g": 100.0,
    }
    column_map = {k: v for k, v in column_map.items() if v != ""}
    return food_db, diet_plan, meal_split, meal_kcal_bands, column_map

def run_post_optimization_rebuild(fm, cfg, front_X, front_obj,
                                  gemini_api_key: str = ""):
    """Run the rebuild stage on the recommended plan. Never aborts the run.

    Picks the same recommended plan report() printed (pick_recommended with
    cfg.mcdm_weights), so the rebuilt plan corresponds to the plan the user
    just read -- not to some other point on the front.

    Wrapped in try/except on purpose. This stage runs AFTER the expensive
    NSGA-III run and after every core output file is already on disk. An
    import error or a schema surprise here must not destroy a finished run,
    so failures are reported and swallowed.

    Returns the result dict from rebuild_plan_with_recipes(), or None.
    """
    try:
        rec = pick_recommended(front_obj, cfg.mcdm_weights)
        x = front_X[rec]

        food_db, diet_plan, meal_split, bands, column_map = \
            build_rebuild_inputs(fm, x)

        print("\n" + "=" * 72)
        print("POST-OPTIMIZATION REBUILD (substitutions, meal shifts, recipes)")
        print("=" * 72)
        print(f"  Candidate foods available for substitution: {len(food_db)}"
              + ("  (candidate pool only)" if REBUILD_RESTRICT_TO_CANDIDATE_POOL
                 else "  (full loaded pool)"))
        print("  Portions are NOT re-optimized at this stage.")

        result = rebuild_plan_with_recipes(
            food_db=food_db,
            diet_plan=diet_plan,
            meal_split=meal_split,
            meal_kcal_bands=bands,
            column_map=column_map,
            gemini_api_key=gemini_api_key,
            output_dir=REBUILD_OUTPUT_DIR,
            person=getattr(fm, "person", None),
            soft_targets=dict(getattr(fm, "soft_list", []) or []),
            reference_mar=default_reference_mar(cfg),
        )

        if gemini_api_key:
            try:
                result = retry_failed_recipes(result, food_db, column_map,
                                              gemini_api_key,
                                              output_dir=REBUILD_OUTPUT_DIR)
            except Exception as _e:
                print(f"  (recipe retry skipped: {type(_e).__name__}: {_e})")

        try:
            score_plan_quality(result, cfg=cfg,
                               person=getattr(fm, "person", None))
            plan_signoff_checklist(result, cfg=cfg,
                                   person=getattr(fm, "person", None))
        except Exception as _e:
            import traceback as _tb
            print("\n" + "!" * 72)
            print(f"  RELEASE GATE DID NOT RUN -- {type(_e).__name__}: {_e}")
            print("  No allergen check, no meal-structure review, no prep-")
            print("  safety check ran. Any quality scores above are NOT")
            print("  evidence the plan is sound. Do not issue this plan.")
            print("!" * 72 + "\n")
            _tb.print_exc()
        return result

    except Exception as exc:
        msg = str(exc)
        if gemini_api_key:
            msg = msg.replace(gemini_api_key, "***REDACTED***")
        print(f"\n[rebuild] stage failed and was skipped: "
              f"{type(exc).__name__}: {msg[:300]}")
        print("[rebuild] the optimizer's own outputs above are complete "
              "and unaffected.")
        return None

