def meal_archetype_problems(meal, subgroups):
    """What is structurally wrong with this plate for this meal slot."""
    rule = MEAL_ARCHETYPES.get(str(meal))
    if not rule:
        return []
    needs_anchor, needs_base, max_sweet, min_veg = rule
    subs = [str(x).strip() for x in subgroups]
    if not subs:
        return []
    out = []
    if needs_anchor and not any(x in MEAL_ANCHOR_SUBGROUPS for x in subs):
        out.append("no protein anchor")
    if needs_base and not any(x in MEAL_BASE_SUBGROUPS for x in subs):
        out.append("no staple or vegetable base")
    _produce = set(VEGETABLE_SUBGROUPS)
    if str(meal) == "Breakfast":
        _produce = _produce | set(FRUIT_SUBGROUPS)
    n_veg = sum(1 for x in subs if x in _produce)
    if min_veg and n_veg < min_veg:
        label = "fruit or vegetable" if str(meal) == "Breakfast" else "vegetable"
        out.append(f"{n_veg} {label}(s), needs {min_veg}")
    n_liquid = sum(1 for x in subs if x in LIQUID_SUBGROUPS)
    if n_liquid > MAX_LIQUID_ITEMS_PER_MEAL:
        out.append(f"{n_liquid} separate liquids in one meal -- that is a "
                   f"drink, not a plate")
    sweet = sum(1 for x in subs if x in SWEET_SUBGROUPS) / len(subs)
    if sweet > max_sweet:
        out.append(f"{sweet:.0%} sweet components (max {max_sweet:.0%}) "
                   f"-- this reads as a dessert, not a {meal}")
    return out

_FAMILY_REFINEMENTS = (
    ("meat_egg", r"\b(beef|veal|pork|lamb|mutton|goat|venison|bison|"
                 r"boar|ham|bacon|sausage|steak|sirloin|ribeye|brisket|"
                 r"tenderloin|meatballs?|meatloa[fv]|burgers?|patt(y|ies)|"
                 r"chop|cutlet|mince|salami|prosciutto|chorizo)\b",
     "red_meat"),
    ("meat_egg", r"\b(chicken|turkey|duck|goose|poultry|quail)\b", "poultry"),
    ("meat_egg", r"\b(egg|eggs|omelet|albumen)\b", "egg"),
    ("fruit", r"\b(sugared|sweetened|candied|glace|glac\u00e9|in\s+syrup|"
              r"heavy\s+syrup|with\s+added\s+sugar|crystalli[sz]ed)\b",
     "fruit_sweetened"),
    ("fruit", r"\b(dried|dehydrated|raisins?|sultanas?|prunes?|dates?|"
              r"currants?|figs?|apricots?,\s*dried)\b",
     "fruit_dried"),
    ("vegetable", r"\b(dried|dehydrated|pickled|brined|fermented)\b",
     "vegetable_preserved"),
    ("nut_seed", r"\b(butter|paste|tahini|spread)\b", "nut_butter"),
)
_FAMILY_REFINE_C = [(p, re.compile(rx, re.I), r)
                    for p, rx, r in _FAMILY_REFINEMENTS]

def _flavour_family(subgroup: Any, name: Any = "") -> str:
    """Flavour family for one food, refined by its name where that matters."""
    base = FLAVOUR_FAMILY_OF_SUBGROUP.get(str(subgroup).strip(), "")
    text = str(name or "")
    if not base or not text:
        return base
    for parent, rx, refined in _FAMILY_REFINE_C:
        if base == parent and rx.search(text):
            return refined
    return base

