PAIR_UNKNOWN_DEFAULT: float = 0.80

PAIR_UNKNOWN_SEEN: Dict[Tuple[str, str], int] = {}

def pair_compatibility(fam_a: str, fam_b: str) -> float:
    """Compatibility of two flavour families, symmetric, in 0..1."""
    if not fam_a or not fam_b:
        key = (fam_a or "?", fam_b or "?")
        PAIR_UNKNOWN_SEEN[key] = PAIR_UNKNOWN_SEEN.get(key, 0) + 1
        return PAIR_UNKNOWN_DEFAULT
    if fam_a == fam_b:
        return float(SAME_FAMILY_COMPATIBILITY.get(fam_a, 1.0))
    hit = FLAVOUR_COMPATIBILITY.get(
        (fam_a, fam_b), FLAVOUR_COMPATIBILITY.get((fam_b, fam_a)))
    if hit is None:
        key = tuple(sorted((fam_a, fam_b)))
        PAIR_UNKNOWN_SEEN[key] = PAIR_UNKNOWN_SEEN.get(key, 0) + 1
        return PAIR_UNKNOWN_DEFAULT
    return float(hit)

def _canonicalise_flavour_matrix() -> int:
    """Make FLAVOUR_COMPATIBILITY genuinely symmetric. Returns clashes fixed.

    pair_compatibility() looks up (a, b) and falls back to (b, a), which is
    only symmetric if the table never holds both with different values. It
    held 54 such pairs:

        (red_meat, poultry) = 0.40   but  (poultry, red_meat) = 0.50
        (egg, seafood)      = 0.60   but  (seafood, egg)      = 0.35

    So the compatibility of two foods depended on the order they happened to
    appear in the meal list -- the same plate could score 0.35 or 0.60
    depending on how the rows were sorted. That is the kind of defect that
    makes a reviewer distrust every number in the document, and it was
    introduced by the loop that copies a parent family's row onto its refined
    children: it writes both directions from two different source rows.

    Resolved by keeping the LOWER value of any clashing pair. A pairing
    flagged that should not have been costs a dietitian a glance; one missed
    reaches a client.
    """
    canon: Dict[Tuple[str, str], float] = {}
    clashes = 0
    for (a, b), v in list(FLAVOUR_COMPATIBILITY.items()):
        key = (a, b) if a <= b else (b, a)
        if key in canon and abs(canon[key] - float(v)) > 1e-9:
            clashes += 1
            canon[key] = min(canon[key], float(v))
        else:
            canon[key] = float(v)
    FLAVOUR_COMPATIBILITY.clear()
    for (a, b), v in canon.items():
        FLAVOUR_COMPATIBILITY[(a, b)] = v
        if a != b:
            FLAVOUR_COMPATIBILITY[(b, a)] = v
    return clashes

FLAVOUR_MATRIX_CLASHES_FIXED = _canonicalise_flavour_matrix()

def pairing_matrix_audit(
    food_names: Optional[Sequence[str]] = None,
    verbose: bool = True,
) -> Dict[str, Any]:
    """Which family pairs can occur, and which of them have no entry?

    Written because the matrix was silently strongest where it knew least.
    A coverage figure turns "the pairing looks fine" into a number that can
    be checked, and it is the only way a gap like the 1,055 familyless rows
    becomes visible before a client sees the plan rather than after.

    Pass the real food list to audit against what the pool ACTUALLY contains
    rather than against every family the code can name.
    """
    import itertools as _it
    fams: Dict[str, int] = {}
    unfamilied: List[str] = []
    if food_names:
        for n in food_names:
            try:
                sg = classify_food(n)[1]
                if sourcing_exclusion(n, sg, "US"):
                    continue
                f = _flavour_family(sg, n)
            except Exception:
                continue
            if f:
                fams[f] = fams.get(f, 0) + 1
            else:
                unfamilied.append(str(n))
    else:
        for f in set(FLAVOUR_FAMILY_OF_SUBGROUP.values()):
            if f:
                fams[f] = 0

    present = sorted(fams)
    pairs = list(_it.combinations(present, 2)) + [(f, f) for f in present]
    missing: List[Tuple[str, str]] = []
    for a, b in pairs:
        if a == b:
            if a not in SAME_FAMILY_COMPATIBILITY:
                missing.append((a, b))
        elif ((a, b) not in FLAVOUR_COMPATIBILITY
              and (b, a) not in FLAVOUR_COMPATIBILITY):
            missing.append((a, b))

    cov = (len(pairs) - len(missing)) / max(len(pairs), 1)
    out = {"families": fams, "n_pairs": len(pairs), "missing_pairs": missing,
           "coverage": cov, "unfamilied_foods": unfamilied,
           "n_unfamilied": len(unfamilied),
           "unknown_pairs_seen": dict(PAIR_UNKNOWN_SEEN)}
    if verbose:
        print(f"\n  PAIRING MATRIX COVERAGE: "
              f"{len(pairs) - len(missing)}/{len(pairs)} pairs "
              f"({cov:.0%})")
        if missing:
            print(f"    {len(missing)} pair(s) with no entry -> "
                  f"PAIR_UNKNOWN_DEFAULT ({PAIR_UNKNOWN_DEFAULT}):")
            for a, b in missing[:12]:
                print(f"      {a} x {b}")
        if unfamilied:
            print(f"    {len(unfamilied)} food(s) with no flavour family at "
                  f"all; these score {PAIR_UNKNOWN_DEFAULT} against "
                  f"everything:")
            for n in unfamilied[:5]:
                print(f"      {n[:64]}")
    return out

def meal_compatibility(subgroups: Sequence[Any],
                       names: Optional[Sequence[Any]] = None
                       ) -> Tuple[float, List[Tuple[str, str, float]]]:
    """(worst pairwise score, list of offending pairs) for one meal.

    `names` is optional so the existing call in _exchange_score keeps working
    unchanged; passing it enables the name-level refinements.
    """
    names = list(names or [""] * len(list(subgroups)))
    fams = [_flavour_family(sg, nm)
            for sg, nm in zip(subgroups, names + [""] * len(list(subgroups)))]
    worst, bad = 1.0, []
    for i in range(len(fams)):
        for j in range(i + 1, len(fams)):
            sc = pair_compatibility(fams[i], fams[j])
            worst = min(worst, sc)
            if sc < MIN_PAIR_COMPATIBILITY:
                bad.append((fams[i], fams[j], sc))
    return worst, bad

import math
from functools import lru_cache

MEAL_AWARE_MODE: str = "soft"

DECODER_SLOTS: Tuple[str, ...] = ("Breakfast", "A.M. Snack", "Lunch",
                                  "P.M. Snack", "Dinner")
DECODER_MAIN_SLOTS: Tuple[str, ...] = ("Breakfast", "Lunch", "Dinner")
DECODER_MAX_ITEMS: int = 5
DECODER_MIN_ITEMS: int = 2

MEAL_CONSTRAINT_SCALE: float = 1.0

MEAL_AWARE_HARD_TIER2: bool = False

MEAL_PENALTY_WEIGHT: float = 0.5

DECODER_MIN_ACTIVE_G: float = 5.0

@lru_cache(maxsize=8192)
def _cached_role(name: str) -> str:
    try:
        return plate_role(name)
    except Exception:
        return "other"

@lru_cache(maxsize=8192)
def _cached_family(name: str) -> str:
    try:
        return _flavour_family(classify_food(name)[1], name)
    except Exception:
        return ""

@lru_cache(maxsize=65536)
def _cached_pair(fam_a: str, fam_b: str) -> float:
    try:
        return float(pair_compatibility(fam_a, fam_b))
    except Exception:
        return 1.0

def _active_indices(x, min_g: float = DECODER_MIN_ACTIVE_G):
    """Indices of foods actually present in this candidate day."""
    return [i for i, g in enumerate(np.asarray(x, dtype=float)) if g >= min_g]

def meal_feasibility_violation(fm, x) -> List[float]:
    """Can this day be arranged into meals AT ALL? Three counting checks.

    Necessary, not sufficient -- passing these does not mean a good
    arrangement exists, only that no arithmetic makes one impossible. That is
    exactly what a cheap constraint should be: it removes the hopeless without
    pretending to judge the rest.

    Returns violations in g(x) <= 0 form. Always the same length, because
    n_ieq_constr is fixed at construction and a variable-length g is reported
    by pymoo as an opaque reshape error.
    """
    idx = _active_indices(x)
    n_slots = len(DECODER_SLOTS)
    n_items = len(idx)

    over_capacity = n_items - n_slots * DECODER_MAX_ITEMS

    anchors = 0
    for i in idx:
        try:
            if _cached_role(fm.names[i]) == "protein_anchor":
                anchors += 1
        except Exception:
            pass
    over_anchors = anchors - n_slots

    under_capacity = (len(DECODER_MAIN_SLOTS) * DECODER_MIN_ITEMS
                      + (n_slots - len(DECODER_MAIN_SLOTS))) - n_items

    s = MEAL_CONSTRAINT_SCALE
    return [s * over_capacity / max(n_slots, 1),
            s * over_anchors / max(n_slots, 1),
            s * under_capacity / max(n_slots, 1)]

def decode_to_meals(
    fm,
    x,
    slots: Sequence[str] = DECODER_SLOTS,
) -> Dict[str, List[int]]:
    """Assign this day's foods to meals. Deterministic, greedy, cheap.

    Deterministic matters more than optimal here. The decoder is called once
    per individual per generation, so the same genotype must always produce
    the same phenotype -- otherwise the fitness landscape is noisy and the
    search is chasing its own decoder. Greedy in three passes:

      1. Anchors, largest first, one per main slot then to snacks.
      2. Bases and vegetables to the slot with the fewest items.
      3. Everything else to the slot where it fits best, by flavour
         compatibility with what is already there, breaking ties on room.

    Not an optimal assignment. An exact one (it is a small assignment problem
    and an ILP would solve it) would cost far more per evaluation than the
    quality difference is worth, and would make the fitness of a day depend on
    a solver's tie-breaking.
    """
    idx = _active_indices(x)
    xa = np.asarray(x, dtype=float)
    assign: Dict[str, List[int]] = {s: [] for s in slots}
    if not idx:
        return assign

    roles: Dict[int, str] = {}
    for i in idx:
        roles[i] = _cached_role(fm.names[i])

    def _room(s):
        return DECODER_MAX_ITEMS - len(assign[s])

    anchors = sorted([i for i in idx if roles[i] == "protein_anchor"],
                     key=lambda i: -xa[i])
    order = list(DECODER_MAIN_SLOTS) + [s for s in slots
                                        if s not in DECODER_MAIN_SLOTS]
    for n_, i in enumerate(anchors):
        target = order[n_] if n_ < len(order) else max(slots, key=_room)
        assign[target].append(i)

    used = {i for v in assign.values() for i in v}
    spare = [i for i in idx if i not in used
             and roles[i] in ("dairy", "composite")]
    for s in DECODER_MAIN_SLOTS:
        if spare and not any(roles[i] in MAIN_ANCHOR_ROLES for i in assign[s]):
            assign[s].append(spare.pop(0))

    for role in ("carb_base", "vegetable"):
        for i in [j for j in idx if roles[j] == role]:
            target = min(slots, key=lambda s: (len(assign[s]), s))
            assign[target].append(i)

    placed = {i for v in assign.values() for i in v}
    for i in [j for j in idx if j not in placed]:
        fam_i = _cached_family(fm.names[i])
        best, best_key = None, None
        for s in slots:
            if _room(s) <= 0:
                continue
            mates = assign[s]
            if mates:
                fit = sum(_cached_pair(fam_i, _cached_family(fm.names[j]))
                          for j in mates) / len(mates)
            else:
                fit = 1.0
            key = (-fit, len(mates))
            if best_key is None or key < best_key:
                best, best_key = s, key
        assign[best or slots[-1]].append(i)
    return assign

def meal_structure_violation(fm, x) -> List[float]:
    """Per-meal violations of the decoded arrangement, as g(x) <= 0 terms.

    Four constraints, each summed across meals and normalised by the number of
    slots so one whole violation costs about 1.0:

      1. items over the cap
      2. protein anchors over one
      3. meals with no anchor at all
      4. within-meal flavour pairs below MIN_PAIR_COMPATIBILITY

    Deliberately NOT included: per-meal calorie bands. The decoder assigns
    foods, not grams, so a meal's energy is whatever its foods happen to carry
    and penalising the optimizer for that would be punishing it for the
    decoder's choices rather than its own. Bands stay where they are enforced
    properly, in the Stage 3c-i rescale.
    """
    n_slots = len(DECODER_SLOTS)
    s = MEAL_CONSTRAINT_SCALE
    try:
        assign = decode_to_meals(fm, x)
    except Exception:
        return [0.0, 0.0, 0.0, 0.0]

    over_items = anchors_over = no_anchor = clashes = 0.0
    for slot, items in assign.items():
        over_items += max(0, len(items) - DECODER_MAX_ITEMS)
        try:
            names = [fm.names[i] for i in items]
        except Exception:
            continue
        n_anchor = sum(1 for n_ in names
                       if _cached_role(n_) == "protein_anchor")
        anchors_over += max(0, n_anchor - 1)
        if slot in DECODER_MAIN_SLOTS and names and not any(
                _cached_role(n_) in MAIN_ANCHOR_ROLES for n_ in names):
            no_anchor += 1
        if len(names) > 1:
            fams = [_cached_family(n_) for n_ in names]
            for a_ in range(len(fams)):
                for b_ in range(a_ + 1, len(fams)):
                    sc = _cached_pair(fams[a_], fams[b_])
                    if sc < MIN_PAIR_COMPATIBILITY:
                        clashes += MIN_PAIR_COMPATIBILITY - sc

    return [s * over_items / n_slots, s * anchors_over / n_slots,
            s * no_anchor / n_slots, s * clashes / n_slots]

N_MEAL_FEASIBILITY_CONSTRAINTS: int = 3
N_MEAL_STRUCTURE_CONSTRAINTS: int = 4

def n_meal_constraints(mode: Optional[str] = None) -> int:
    """How many rows PART 2F-0h adds to g, for the active mode.

    Tier 2 only appears in g when MEAL_AWARE_HARD_TIER2 is on; otherwise it
    goes to the objective as a penalty and adds no constraint rows at all.
    """
    m = (mode or MEAL_AWARE_MODE or "off").lower()
    if m in ("off", "soft"):
        return 0
    if m == "feasibility":
        return N_MEAL_FEASIBILITY_CONSTRAINTS
    if m == "strict":
        return N_MEAL_FEASIBILITY_CONSTRAINTS + N_MEAL_STRUCTURE_CONSTRAINTS
    return (N_MEAL_FEASIBILITY_CONSTRAINTS
            + (N_MEAL_STRUCTURE_CONSTRAINTS if MEAL_AWARE_HARD_TIER2 else 0))

def meal_soft_penalty(fm, x, mode: Optional[str] = None) -> float:
    """Arrangement quality as a penalty, in roughly 0..1 per violation.

    Zero when tier 2 is hard (it is in g instead) or the mode excludes it, so
    the two paths can never both charge for the same violation.
    """
    m = (mode or MEAL_AWARE_MODE or "off").lower()
    if m == "off":
        return 0.0
    try:
        total = 0.0
        if m == "soft":
            t1 = meal_feasibility_violation(fm, x)
            total += sum(math.log1p(max(0.0, v)) for v in t1)
        elif any(v > 0 for v in meal_feasibility_violation(fm, x)):
            return 0.0
        if m in ("soft", "full") and not MEAL_AWARE_HARD_TIER2:
            total += sum(max(0.0, v)
                         for v in meal_structure_violation(fm, x))
        return float(total)
    except Exception:
        return 0.0

def preflight_feasibility(fm, cfg=None, n_samples: int = 400) -> Dict[str, Any]:
    """Can ANY random point satisfy the hard constraints? Answer in seconds.

    Written after two full runs -- roughly five hours of compute between them
    -- each returned "0 non-dominated solutions across 21 seeds". Both times
    the answer was available in under a second from random sampling, and both
    times nobody asked before committing the cluster.

    Samples random points in the box and reports how many clear every hard
    constraint. A rate of zero here means the run WILL return nothing, and no
    generation budget changes that. Call it before any long run.
    """
    import numpy as _np
    rng = _np.random.default_rng(0)
    xl = _np.asarray(getattr(fm, "xl", None) if getattr(fm, "xl", None)
                     is not None else _np.zeros(len(fm.names)), dtype=float)
    xu = _np.asarray(getattr(fm, "xu", None) if getattr(fm, "xu", None)
                     is not None else _np.full(len(fm.names), 200.0),
                     dtype=float)
    n_meal = n_meal_constraints()
    feasible = 0
    worst: Dict[int, float] = {}
    for _ in range(n_samples):
        x = rng.uniform(xl, xu)
        g = meal_constraints(fm, x) if n_meal else []
        if not g or all(v <= 0 for v in g):
            feasible += 1
        for i, v in enumerate(g):
            worst[i] = max(worst.get(i, float("-inf")), v)
    rate = feasible / max(n_samples, 1)
    return {
        "mode": MEAL_AWARE_MODE, "n_hard_constraints": n_meal,
        "feasible_fraction": rate, "worst_violation_by_row": worst,
        "verdict": (
            "SAFE: no hard meal constraints; the feasible region is unchanged."
            if n_meal == 0 else
            (f"SAFE: {rate:.0%} of random points clear the meal constraints."
             if rate > 0.01 else
             f"WILL RETURN 0 SOLUTIONS: no random point in {n_samples} clears "
             f"the hard meal constraints (worst violations {worst}). This is "
             f"a cardinality constraint on a large pool -- set "
             f"MEAL_AWARE_MODE='soft' rather than raising n_gen.")),
    }

def meal_constraints(fm, x, mode: Optional[str] = None) -> List[float]:
    """All PART 2F-0h constraints for the active mode, in g(x) <= 0 form."""
    m = (mode or MEAL_AWARE_MODE or "off").lower()
    if m in ("off", "soft"):
        return []
    out = list(meal_feasibility_violation(fm, x))
    if m != "feasibility" and MEAL_AWARE_HARD_TIER2:
        if any(v > 0 for v in out):
            out.extend([0.0] * N_MEAL_STRUCTURE_CONSTRAINTS)
        else:
            out.extend(meal_structure_violation(fm, x))
    return out

CUISINE_SIGNATURES: Dict[str, str] = {
    "mediterranean": r"\b(olive|oregano|basil|rosemary|thyme|feta|halloumi|"
                     r"tomato|aubergine|eggplant|courgette|zucchini|"
                     r"chickpea|tahini|lemon|parsley|anchov|sardine|"
                     r"couscous|bulgur|pine\s+nut|caper|artichoke)\b",
    "south_asian": r"\b(cumin|coriander|turmeric|garam|masala|asafo|hing|"
                   r"curry\s+lea|mustard\s+seed|fenugreek|methi|"
                   r"dal|dhal|lentil|chana|rajma|paneer|ghee|"
                   r"basmati|chapati|roti|naan|tamarind|jaggery|"
                   r"cardamom|clove|cinnamon|ginger|chili|chilli)\b",
    "east_asian": r"\b(soy\s+sauce|tamari|miso|mirin|sesame|ginger|"
                  r"scallion|spring\s+onion|bok\s+choy|pak\s+choi|"
                  r"shiitake|maitake|enoki|nori|seaweed|wakame|"
                  r"tofu|tempeh|edamame|rice\s+vinegar|"
                  r"noodle|udon|soba|daikon|napa)\b",
    "latin": r"\b(cilantro|coriander\s+lea|lime|jalapeno|jalapeño|chipotle|"
             r"black\s+bean|pinto|masa|tortillas?|avocado|"
             r"tomatillo|cumin|oregano|plantain|queso)\b",
    "north_european": r"\b(dill|caraway|juniper|horseradish|rye|"
                      r"potato|beetroot|beet|cabbage|herring|"
                      r"salmon|mackerel|soured\s+cream|buttermilk|"
                      r"mustard|apple|barley)\b",
    "middle_eastern": r"\b(tahini|sumac|za'?atar|pomegranate|"
                      r"chickpea|bulgur|freekeh|mint|"
                      r"yogh?urt|labneh|date|pistachio|"
                      r"cinnamon|allspice|lamb|aubergine|eggplant)\b",
}
_CUISINE_C = {k: re.compile(v, re.I) for k, v in CUISINE_SIGNATURES.items()}

UNIVERSAL_SEASONING_RE = re.compile(
    r"\b(lemon|lime|vinegar|salt|black\s+pepper|white\s+pepper|"
    r"garlic|onion|shallot|parsley|olive\s+oil|bay\s+lea)\b", re.I)

UNIVERSAL_FOODS_RE = re.compile(
    r"\b(rice|wheat|oat|maize|corn|potato|onion|garlic|salt|pepper,?\s*black|"
    r"water|oil|butter|egg|eggs|milk|chicken|beef|pork|lamb|fish|"
    r"carrot|pea|bean|apple|banana|orange|sugar|flour|honey|"
    r"yogh?urt|cheese|bread|pasta|lentil|spinach|tomato|"
    r"mushroom|cucumber|lettuce|broccoli|cauliflower|nut|seed)\b",
    re.I)

def food_cuisines(food_name: Any) -> set:
    """Cooking traditions this food is a signature ingredient of.

    Empty set means "universal or unrecognised", which is deliberately the
    same answer: both mean the food is no evidence either way, and treating
    an unrecognised food as an outlier would make the review noisiest exactly
    where it knows least.
    """
    text = str(food_name or "")
    return {c for c, rx in _CUISINE_C.items() if rx.search(text)}

def meal_cuisine_coherence(
    food_names: Sequence[str],
) -> Tuple[float, set, List[str]]:
    """(coherence 0-1, shared traditions, outlier foods) for one meal.

    Coherence is the share of cuisine-bearing foods that fit the meal's
    dominant tradition. A meal of entirely universal foods scores 1.0 -- rice,
    chicken and carrots is not incoherent, it is just unmarked.
    """
    marked: List[Tuple[str, set]] = []
    for n in food_names:
        cs = food_cuisines(n)
        if cs:
            marked.append((str(n), cs))
    if len(marked) < 2:
        return 1.0, set(), []

    counts: Dict[str, int] = {}
    for _, cs in marked:
        for c in cs:
            counts[c] = counts.get(c, 0) + 1
    best_c, best_n = None, -1
    for cand in counts:
        n_fit = sum(1 for _, cs in marked if cand in cs)
        if n_fit > best_n:
            best_c, best_n = cand, n_fit
    dominant = {best_c} if best_c else set()

    fits = [n for n, cs in marked if best_c in cs]
    outliers = [n for n, cs in marked
                if not (cs & dominant)
                and not UNIVERSAL_FOODS_RE.search(n)
                and not UNIVERSAL_SEASONING_RE.search(n)]
    return len(fits) / len(marked), dominant, outliers

ACID_RE = re.compile(
    r"\b(lemon|lime|vinegar|tamarind|yogh?urt|buttermilk|curd|"
    r"tomato|tomatoes|pomegranate|sumac|kimchi|sauerkraut|pickle|"
    r"wine|citrus|orange\s+juice|amchur|kokum)\b", re.I)
AROMATIC_RE = re.compile(
    r"\b(onion|garlic|ginger|shallot|leek|scallion|spring\s+onion|chive|"
    r"cumin|coriander|cilantro|basil|oregano|thyme|rosemary|dill|"
    r"parsley|mint|sage|bay|paprika|chili|chilli|pepper|"
    r"turmeric|cinnamon|clove|cardamom|masala|curry|mustard\s+seed|"
    r"celery|fennel|lemongrass|sesame|soy\s+sauce|miso)\b", re.I)

DISH_ELEMENTS = ("anchor", "base", "vegetable", "fat", "acid", "aromatic")

def dish_elements_present(food_names: Sequence[str]) -> Dict[str, List[str]]:
    """Which of the five dish elements this meal actually has."""
    out: Dict[str, List[str]] = {k: [] for k in DISH_ELEMENTS}
    for n in food_names:
        name = str(n)
        role = plate_role(name)
        if role in ("protein_anchor", "composite"):
            out["anchor"].append(name)
        elif role == "carb_base":
            out["base"].append(name)
        elif role == "vegetable":
            out["vegetable"].append(name)
        if role == "fat_element" or is_pure_fat(name):
            out["fat"].append(name)
        if ACID_RE.search(name):
            out["acid"].append(name)
        if AROMATIC_RE.search(name):
            out["aromatic"].append(name)
    return out

CLASSIC_PARTNERS: Dict[str, Tuple[str, ...]] = {
    r"\bsalmon|trout|mackerel|sardine|herring\b":
        ("lemon", "dill", "potato", "asparagus", "yogurt or soured cream",
         "cucumber", "mustard", "rye"),
    r"\bcod|haddock|pollock|snapper|tilapia|sole|halibut\b":
        ("lemon", "parsley", "potato", "peas", "tomato", "olive oil",
         "capers", "fennel"),
    r"\bshrimps?|prawns?|crabs?|lobsters?\b":
        ("garlic", "lemon", "chili", "rice", "tomato", "butter", "parsley"),
    r"\bchicken|turkey|poultry\b":
        ("lemon", "garlic", "thyme", "rice", "potato", "carrot", "yogurt",
         "paprika"),
    r"\bbeef|lamb|mutton\b":
        ("onion", "garlic", "rosemary", "potato", "carrot", "tomato",
         "red wine", "cumin"),
    r"\bpork\b": ("apple", "sage", "mustard", "fennel", "cabbage", "potato"),
    r"\begg|eggs\b": ("tomato", "spinach", "onion", "cheese", "chili",
                      "bread", "chive"),
    r"\bchickpea|garbanzo\b":
        ("cumin", "lemon", "tahini", "tomato", "spinach", "olive oil",
         "garlic", "coriander"),
    r"\blentil|dal|dhal\b":
        ("cumin", "onion", "garlic", "tomato", "ginger", "turmeric",
         "spinach", "lemon", "rice"),
    r"\bblack\s+bean|pinto|kidney\s+bean\b":
        ("cumin", "onion", "lime", "coriander", "tomato", "rice", "chili"),
    r"\btofu|tempeh|soy\s+curd|curd\s+cheese\b":
        ("soy sauce", "ginger", "garlic", "sesame", "spring onion", "rice",
         "chili", "bok choy"),
    r"\bpaneer\b": ("tomato", "onion", "ginger", "garam masala", "spinach",
                    "coriander", "cream"),
    r"\byogh?urt\b": ("berries", "honey", "nuts", "cucumber", "mint",
                      "cumin", "oats"),
    r"\boat|oats|porridge\b":
        ("milk", "cinnamon", "banana", "berries", "nuts", "honey",
         "seeds"),
}
_PARTNERS_C = [(re.compile(k, re.I), v) for k, v in CLASSIC_PARTNERS.items()]

def classic_partners(food_name: Any) -> Tuple[str, ...]:
    """Foods routinely eaten with this one. Empty if we have no opinion."""
    text = str(food_name or "")
    for rx, partners in _PARTNERS_C:
        if rx.search(text):
            return partners
    return ()

def suggest_pairings(food_names: Sequence[str]) -> List[str]:
    """Classic partners for this meal's anchors that are not already here."""
    present = " ".join(str(n).lower() for n in food_names)
    out: List[str] = []
    for n in food_names:
        if plate_role(n) not in ("protein_anchor", "composite"):
            continue
        for p in classic_partners(n):
            head = p.split()[0].lower()
            if head not in present and p not in out:
                out.append(p)
    return out[:6]

def pairing_review(
    meal_name: Any,
    food_names: Sequence[str],
    subgroups: Optional[Sequence[str]] = None,
) -> List[Dict[str, str]]:
    """Does this meal read as a dish, and what would make it one?"""
    names = [str(n) for n in food_names if str(n).strip()]
    if len(names) < 2:
        return []
    out: List[Dict[str, str]] = []
    slot = _slot_of(meal_name)
    label = MEAL_TEMPLATES.get(slot, {}).get("label", str(meal_name))

    try:
        sgs = list(subgroups) if subgroups else [classify_food(n)[1]
                                                for n in names]
        worst, bad = meal_compatibility(sgs, names)
        if bad:
            pairs = "; ".join(f"{a} with {b} ({sc:.1f})" for a, b, sc in bad[:3])
            out.append({
                "level": "review", "topic": f"{label} clashing pairs",
                "text": f"{pairs}. These score below the "
                        f"{MIN_PAIR_COMPATIBILITY:.1f} compatibility "
                        f"threshold. The arrangement objective already "
                        f"weights this at {EXCH_W_COMPATIBILITY:.2f}, "
                        f"averaged over five meals -- which is why a single "
                        f"bad pair can survive it. Reported here because it "
                        f"did."})
    except Exception:
        pass

    coh, dominant, outliers = meal_cuisine_coherence(names)
    if coh < 0.6 and outliers:
        out.append({
            "level": "review", "topic": f"{label} mixes traditions",
            "text": f"Most of this meal reads as "
                    f"{' or '.join(sorted(dominant))}, but "
                    f"{', '.join(outliers)} belongs to a different one. Not "
                    f"wrong -- plenty of good cooking crosses traditions -- "
                    f"but a client reading the card will not see a dish, and "
                    f"a plan that does not look like food gets replaced with "
                    f"food."})

    if slot in ("lunch", "dinner"):
        el = dish_elements_present(names)
        missing = [k for k in ("fat", "acid", "aromatic") if not el[k]]
        if len(missing) >= 2:
            out.append({
                "level": "note", "topic": f"{label} has no seasoning",
                "text": f"No {', no '.join(missing)}. None of these carries "
                        f"meaningful calories or nutrients, so nothing in the "
                        f"objective ever asks for them -- which is exactly "
                        f"why they go missing. A squeeze of lemon, an onion "
                        f"and a spoon of oil change nothing in the nutrient "
                        f"table and decide whether this gets eaten twice."})

    sugg = suggest_pairings(names)
    if sugg and (out or coh < 0.8):
        out.append({
            "level": "note", "topic": f"{label} would pair well with",
            "text": f"{', '.join(sugg)}. These are routine partners for the "
                    f"protein already in this meal, so adding one or two "
                    f"turns a list of components into a recognisable dish "
                    f"without changing what the plan is doing nutritionally."})
    return out

def plan_pairing_review(result: Dict[str, Any]) -> List[Dict[str, str]]:
    """Run the pairing review over every meal in an assembled plan."""
    out: List[Dict[str, str]] = []
    split = result.get("rebuilt_meal_split")
    cmap = result.get("column_map") or {}
    f_col = _cfg(cmap, "food_col") or "food"
    m_col = _cfg(cmap, "meal_col") or "meal"
    if split is None or getattr(split, "empty", True):
        return out
    try:
        for meal in split[m_col].astype(str).unique():
            names = split.loc[split[m_col].astype(str) == meal,
                              f_col].astype(str).tolist()
            out.extend(pairing_review(meal, names))
    except Exception as exc:
        out.append({"level": "note", "topic": "Pairing review",
                    "text": f"skipped: {type(exc).__name__}: {exc}"})
    return out

