_HH_UNITS_C = [(re.compile(p, re.I), lbl, g, plural, whole)
               for p, lbl, g, plural, whole in HOUSEHOLD_UNITS]

HOUSEHOLD_SNAP_FRAC: float = 0.15
HOUSEHOLD_SNAP_MIN_G: float = 5.0

_USABLE_FRACTIONS = (0.25, 0.3333333333, 0.5, 0.6666666667, 0.75, 1.0)
_SPOON_FRACTIONS = (0.5, 1.0)

def household_unit_for(food_name: Any) -> Optional[Tuple[str, float, str, bool]]:
    """(label, grams per unit, plural, whole-only) for this food, or None."""
    text = str(food_name or "")
    for rx, lbl, g, plural, whole in _HH_UNITS_C:
        if rx.search(text):
            return lbl, g, plural, whole
    return None

def _format_count(n: float, label: str, plural: str) -> str:
    """'2 slices', '1/2 cup cooked', '1 1/2 tbsp' -- as a person would say it."""
    whole = int(n)
    frac = n - whole
    frac_txt = ""
    for f, t in ((0.25, "1/4"), (0.3333333333, "1/3"), (0.5, "1/2"),
                 (0.6666666667, "2/3"), (0.75, "3/4")):
        if abs(frac - f) < 0.06:
            frac_txt = t
            break
    name = label if (whole == 1 and not frac_txt) else plural
    if whole and frac_txt:
        return f"{whole} {frac_txt} {name}"
    if frac_txt:
        return f"{frac_txt} {label}"
    return f"{whole} {name}"

def snap_to_household(
    food_name: Any,
    grams: float,
) -> Tuple[float, str]:
    """(grams, household description) for one portion.

    Returns the ORIGINAL grams when the nearest unit is too far away, so the
    optimizer's nutritional intent is never quietly overridden for the sake of
    a rounder number. The description is still produced in that case, phrased
    as an approximation, because "about 1 1/2 tbsp" helps a client even when
    the underlying figure is 22 g rather than 21.
    """
    try:
        g = float(grams)
    except (TypeError, ValueError):
        return grams, ""
    unit = household_unit_for(food_name)
    if not unit or g <= 0:
        return g, ""
    label, per, plural, whole_only = unit

    if whole_only:
        n = max(1.0, round(g / per))
        return n * per, _format_count(n, label, plural)

    raw = g / per
    fracs = (_SPOON_FRACTIONS if label in ("tsp", "tbsp")
             else _USABLE_FRACTIONS)
    best = min(
        (abs(raw - (w + f)) , w + f)
        for w in range(0, int(raw) + 2)
        for f in (0.0,) + fracs
        if (w + f) > 0
    )[1]
    snapped = best * per
    tolerance = max(HOUSEHOLD_SNAP_FRAC * g, HOUSEHOLD_SNAP_MIN_G)
    if abs(snapped - g) <= tolerance:
        return snapped, _format_count(best, label, plural)
    return g, f"about {_format_count(raw, label, plural)}"

def household_portion_text(food_name: Any, grams: float) -> str:
    """Just the description, for the document. Empty when there is no unit."""
    return snap_to_household(food_name, grams)[1]

BREAKFAST_UNUSUAL_RE = re.compile(
    r"\b(oyster|clam|mussel|squid|octopus|lobster|crab|"
    r"liver|kidney|heart|tripe|sweetbread|"
    r"lamb|mutton|goat|venison|duck|goose|"
    r"aubergine|eggplant|artichoke|okra|"
    r"broccoli\s+raab|rapini)\b", re.I)

BREAKFAST_TYPICAL_RE = re.compile(
    r"\b(oat|porridge|cereal|muesli|granola|bread|toast|bagel|"
    r"egg|yogh?urt|milk|cheese|butter|jam|honey|"
    r"banana|apple|berr|orange|juice|"
    r"bacon|sausage|ham|salmon,\s*smoked|"
    r"idli|dosa|upma|poha|paratha|congee|"
    r"coffee|tea|smoothie|pancake|waffle)\b", re.I)

def meal_time_plausibility(
    meal_name: Any,
    food_names: Sequence[str],
) -> List[Dict[str, str]]:
    """Would a person eat this at this time of day?"""
    if _slot_of(meal_name) != "breakfast":
        return []
    odd = [str(n) for n in food_names if BREAKFAST_UNUSUAL_RE.search(str(n))]
    if not odd:
        return []
    familiar = [str(n) for n in food_names if BREAKFAST_TYPICAL_RE.search(str(n))]
    return [{
        "level": "note", "topic": "Breakfast at 7am",
        "text": f"{', '.join(odd)} at breakfast. Nutritionally fine, and "
                f"breakfast is the most culturally variable meal there is -- "
                f"fish for breakfast is ordinary in Japan, Norway and "
                f"Scotland. But if this client eats a Western breakfast they "
                f"will not cook "
                + ("this" if len(odd) == 1 else "these") +
                f" on a weekday morning"
                + (f", and the plan already has {', '.join(familiar[:2])} "
                   f"that would carry the meal" if familiar else "") +
                f". Worth asking rather than assuming."}]

def portion_realism_review(
    split,
    column_map: Dict[str, Any],
) -> List[Dict[str, str]]:
    """Portions a client cannot measure without kitchen scales."""
    out: List[Dict[str, str]] = []
    try:
        f_col = _cfg(column_map, "food_col") or "food"
        g_col = _cfg(column_map, "grams_col") or "grams"
        unmeasurable = []
        for _, r in split.iterrows():
            nm = str(r.get(f_col))
            g = pd.to_numeric(pd.Series([r.get(g_col)]),
                              errors="coerce").fillna(0.0).iloc[0]
            if household_unit_for(nm) is None and float(g) > 0:
                unmeasurable.append(f"{nm} ({float(g):.0f} g)")
        if len(unmeasurable) > 6:
            out.append({
                "level": "note", "topic": "Portions need scales",
                "text": f"{len(unmeasurable)} of this plan's foods have no "
                        f"household measure and are given in grams only. That "
                        f"is workable for a client with scales and a guess "
                        f"for everyone else. Adding these foods to "
                        f"HOUSEHOLD_UNITS would fix it for every future plan."})
    except Exception:
        pass
    return out

_NAME_DROP_RE = re.compile(
    r"\b(raw|cooked|dry\s+heat|moist\s+heat|boiled|braised|roasted|"
    r"with(out)?\s+salt|added\s+salt|drained|solids?(\s+and\s+liquids?)?|"
    r"mixed\s+species|all\s+varieties|commercially\s+prepared|"
    r"prepared[\s-]from[\s-]recipe|enriched|unenriched|fortified|"
    r"includes\s+.*|NS\s+as\s+to.*|"
    r"flesh\s+and\s+skin|meat\s+only|meat\s+and\s+skin|"
    r"retail\s+parts|separable\s+lean.*|trimmed.*|"
    r"long[\s-]grain|short[\s-]grain|regular|"
    r"nfs|unspecified|whole\s+grain,?)\b", re.I)

_NAME_CATEGORY_HEADS = {
    "fish", "mollusks", "molluscs", "crustaceans", "beef", "pork", "lamb",
    "poultry", "chicken", "turkey", "game meat", "nuts", "seeds", "spices",
    "cereals", "cereals ready-to-eat", "snacks", "soup", "sauce", "oil",
    "oils", "beverages", "babyfood", "desserts", "candies", "leavening agents",
    "salad dressing", "milk", "cheese", "yogurt", "egg", "eggs", "bread",
    "vegetables", "fruits", "alcoholic beverage", "infant formula",
}

_GENERIC_QUALIFIERS = {
    "whole", "raw", "plain", "fresh", "dried", "cooked", "boiled", "roasted",
    "nonfat", "low fat", "lowfat", "reduced fat", "full fat", "skim",
    "salted", "unsalted", "sweetened", "unsweetened", "light", "regular",
    "large", "medium", "small", "extra large", "with skin", "without skin", "with peel", "without peel",
    "with refuse", "flesh only", "peeled",
    "with salt", "without salt", "salad or cooking", "all types",
    "meat only", "meat and skin", "broilers or fryers", "young",
    "canned", "frozen", "chilled", "ground", "sliced", "chopped",
}

def plain_food_name(food_name: Any, max_words: int = 3) -> str:
    """A database name, as a person would say it.

    "Fish, salmon, sockeye, cooked, dry heat"        -> "sockeye salmon"
    "Chicken, broilers or fryers, breast, roasted"   -> "chicken breast"
    "Eggs, whole, raw"                               -> "eggs"
    "Oil, olive, salad or cooking"                   -> "olive oil"

    Conservative: when stripping would leave nothing that identifies the food,
    the original comes back. A long name is a cosmetic problem; a name that no
    longer says which food it is, is a shopping error.
    """
    raw = str(food_name or "").strip()
    if not raw:
        return ""
    parts = [p.strip() for p in raw.split(",") if p.strip()]
    if not parts:
        return raw

    head = parts[0]
    rest = parts[1:]
    head_is_category = head.lower() in _NAME_CATEGORY_HEADS

    specifics = [p for p in rest
                 if p.lower() not in _GENERIC_QUALIFIERS
                 and not _NAME_DROP_RE.fullmatch(p.strip())
                 and _NAME_DROP_RE.sub("", p).strip(" ,-")]
    specifics = [_NAME_DROP_RE.sub("", p).strip(" ,-") for p in specifics]
    specifics = [p for p in specifics
                 if p and p.lower() not in _GENERIC_QUALIFIERS]

    if head_is_category and specifics:
        name = specifics[0]
        if len(specifics) > 1 and len(specifics[1].split()) <= 2:
            name = f"{specifics[1]} {name}"
        if re.match(r"^(breast|thigh|leg|loin|shoulder|ribeye|drumstick|"
                    r"wing|mince|ground|fillet|chop|rib|brisket|flank|"
                    r"sirloin|tenderloin)\b", str(name), re.I):
            name = f"{head.lower()} {name}"
        elif head.lower() in {"oil", "oils", "sauce", "soup", "cheese",
                              "bread", "milk", "yogurt", "spices", "cereals"}:
            name = f"{name} {head.lower().rstrip('s') if head.lower() in {'oils'} else head.lower()}"
    elif head_is_category:
        name = head
    else:
        name = head
        if specifics and len(specifics[0].split()) <= 2:
            name = f"{specifics[0]} {name}"

    name = re.sub(r"\s{2,}", " ", str(name)).strip(" ,-()")
    if len(name.split()) > max_words:
        name = " ".join(name.split()[:max_words])
    return name or raw

_TITLE_SMALL = {"with", "and", "or", "in", "on", "a", "the", "of", "&"}

def _titlecase(text: str) -> str:
    words = re.sub(r"\s{2,}", " ", str(text)).strip().split()
    out = []
    for i, w in enumerate(words):
        out.append(w if (w.lower() in _TITLE_SMALL and i > 0)
                   else (w if w[:1].isupper() else w.capitalize()))
    return " ".join(out)

_METHOD_ADJECTIVE = {
    "bake": "Baked", "roast": "Roasted", "grill": "Grilled",
    "pan-sear": "Pan-seared", "sear": "Seared", "sauté": "Sautéed",
    "saute": "Sautéed", "steam": "Steamed", "boil": "Boiled",
    "poach": "Poached", "simmer": "Simmered", "stir-fry": "Stir-fried",
    "press and sear": "Pan-seared", "soak and simmer": "Slow-cooked",
    "warm gently": "Warm", "serve as-is": "", "use as bought": "",
    "serve chilled": "Chilled", "serve raw": "Fresh", "scramble": "Scrambled",
}

def _method_word(food_name: Any) -> str:
    try:
        method = str(assign_cooking_method(food_name).get("method", "")).lower()
    except Exception:
        return ""
    for key, adj in _METHOD_ADJECTIVE.items():
        if key in method:
            return adj
    return ""

def dish_name_for(meal_name: Any, food_names: Sequence[str]) -> str:
    """A dish name for this meal, built from what is actually in it."""
    names = [str(n) for n in food_names if str(n).strip()]
    if not names:
        return str(meal_name)

    by_role: Dict[str, List[str]] = {}
    for n in names:
        by_role.setdefault(plate_role(n), []).append(n)

    anchors = by_role.get("protein_anchor") or by_role.get("composite") or []
    bases = by_role.get("carb_base") or []
    vegs = by_role.get("vegetable") or []
    fruits = by_role.get("fruit") or []
    dairy = by_role.get("dairy") or []
    fats = by_role.get("fat_element") or []
    slot = _slot_of(meal_name)

    def _t(s):
        return plain_food_name(s).strip()

    if anchors:
        adj = _method_word(anchors[0])
        head = f"{adj} {_t(anchors[0])}".strip()
        bowlish = bases and re.search(
            r"\b(rice|quinoa|couscous|bulgur|barley|oat|noodle|pasta)\b",
            str(bases[0]), re.I)
        if bases and vegs and bowlish:
            return _titlecase(f"{head} & {_t(bases[0])} bowl")
        if vegs:
            veg_word = ("roasted vegetables" if len(vegs) > 1 else _t(vegs[0]))
            return _titlecase(f"{head} with {veg_word}")
        if bases:
            return _titlecase(f"{head} with {_t(bases[0])}")
        return _titlecase(head)

    if dairy and (fruits or fats):
        return _titlecase(f"{_t(dairy[0])} with {_t((fruits or fats)[0])}")
    if fruits and fats:
        return _titlecase(f"{_t(fruits[0])} with {_t(fats[0])}")
    if bases and fruits:
        return _titlecase(f"{_t(bases[0])} with {_t(fruits[0])}")
    return _titlecase(" & ".join(_t(n) for n in names[:2])) or str(meal_name)

def plan_as_client_sees_it(
    split,
    column_map: Dict[str, Any],
    recipes: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """The plan restructured the way a dietitian writes one out.

    One entry per meal: the slot, a rounded calorie figure, a dish name, and
    the ingredient lines in household units. This is the shape the client
    document renders, and keeping it as data rather than building it inline in
    the docx writer means the same structure can go to a PDF, an app or a
    printout without any of them re-deriving it.
    """
    out: List[Dict[str, Any]] = []
    f_col = _cfg(column_map, "food_col") or "food"
    g_col = _cfg(column_map, "grams_col") or "grams"
    m_col = _cfg(column_map, "meal_col") or "meal"
    k_col = ROW_KCAL_COL

    order = {"Breakfast": 0, "A.M. Snack": 1, "Lunch": 2,
             "P.M. Snack": 3, "Dinner": 4}
    meals = sorted(split[m_col].astype(str).unique(),
                   key=lambda s: order.get(s, 99))
    for meal in meals:
        grp = split[split[m_col].astype(str) == meal]
        names = grp[f_col].astype(str).tolist()
        try:
            kcal = float(pd.to_numeric(grp[k_col], errors="coerce")
                         .fillna(0.0).sum())
        except Exception:
            kcal = 0.0
        rec = (recipes or {}).get(meal) or {}
        title = str(rec.get("title") or "").strip() or dish_name_for(meal, names)

        lines = []
        for _, r in grp.iterrows():
            nm = str(r.get(f_col))
            g = pd.to_numeric(pd.Series([r.get(g_col)]),
                              errors="coerce").fillna(0.0).iloc[0]
            snapped, household = snap_to_household(nm, float(g))
            lines.append({
                "food": nm, "plain": plain_food_name(nm),
                "grams": float(snapped),
                "portion": (f"{household} ({snapped:.0f} g)" if household
                            else f"{snapped:.0f} g"),
            })
        out.append({"meal": meal, "kcal": kcal,
                    "kcal_rounded": int(round(kcal / 25.0) * 25),
                    "title": title, "items": lines})
    return out

EXCHANGE_TEMPLATE_ACTIVE: bool = True

_EXCH_SAVED_TARGET = dict(MEAL_KCAL_TARGET)
_EXCH_SAVED_BAND = dict(MEAL_KCAL_BAND)
_EXCH_TEMPLATE_INSTALLED = False

def _install_exchange_template(verbose: bool = True) -> None:
    """Point MEAL_KCAL_TARGET / MEAL_KCAL_BAND at the exchange template."""
    global _EXCH_TEMPLATE_INSTALLED
    if not EXCHANGE_TEMPLATE_ACTIVE or _EXCH_TEMPLATE_INSTALLED:
        return
    MEAL_KCAL_TARGET.update(EXCHANGE_KCAL_SHARE)
    for m in MEAL_SLOTS:
        MEAL_KCAL_BAND[m] = (EXCHANGE_MAIN_MEAL_BAND if m in MAIN_MEALS
                             else EXCHANGE_SNACK_BAND)
    _EXCH_TEMPLATE_INSTALLED = True
    if verbose:
        print("    - meal split: EXCHANGE TEMPLATE (kcal + protein + groups)")
        print("    - main-meal kcal band widened to "
              f"{EXCHANGE_MAIN_MEAL_BAND[0]*100:.0f}-"
              f"{EXCHANGE_MAIN_MEAL_BAND[1]*100:.0f}% to admit the template")

def _restore_calorie_only_template(verbose: bool = True) -> None:
    """Undo _install_exchange_template(). Called on entering dish mode."""
    global _EXCH_TEMPLATE_INSTALLED
    if not _EXCH_TEMPLATE_INSTALLED:
        return
    MEAL_KCAL_TARGET.clear()
    MEAL_KCAL_TARGET.update(_EXCH_SAVED_TARGET)
    MEAL_KCAL_BAND.clear()
    MEAL_KCAL_BAND.update(_EXCH_SAVED_BAND)
    _EXCH_TEMPLATE_INSTALLED = False
    if verbose:
        print("    - exchange template REMOVED (dish pool); bands restored")

_exch_prev_disable_dish_mode = disable_dish_mode
_exch_prev_enable_dish_mode = enable_dish_mode

def disable_dish_mode(verbose=True):
    _exch_prev_disable_dish_mode(verbose)
    _install_exchange_template(verbose)

def enable_dish_mode(verbose=True):
    _exch_prev_enable_dish_mode(verbose)
    _restore_calorie_only_template(verbose)

def _exchange_group_of(subgroup: str):
    """Exchange group for a Food_Subgroup, or None if it counts in none."""
    s = str(subgroup).strip()
    for grp, members in EXCHANGE_GROUP_SUBGROUPS.items():
        if s in members:
            return grp
    return None

def _exchange_servings_usable(fm) -> bool:
    """True if serving weights are real, so exchange COUNTS mean something.

    _serving_g_arr() fills missing weights with 100.0. If the run skipped the
    serving-weights CSV every food gets 100 g and an "exchange" silently
    becomes a hectogram -- 250 g of milk would read as 2.5 dairy exchanges
    and 250 g of spinach as 2.5 vegetable exchanges, which is not what either
    number means. Detect that and drop the exchange term rather than print a
    table of confident nonsense.
    """
    if SERVING_G_COL not in fm.df.columns:
        return False
    a = pd.to_numeric(fm.df.iloc[fm.cand_idx][SERVING_G_COL], errors="coerce")
    return bool(a.notna().sum() > 0 and a.dropna().nunique() > 1)

def _exchange_items(fm, x):
    """Per-food kcal, grams, protein and exchange count for the chosen day.

    Positional alignment: fm.names, fm.energy_arr, _nutrient_arrays(),
    _serving_g_arr() and fm.df.iloc[fm.cand_idx] are ALL indexed by candidate
    position, so index k means the same food in every one of them. x is in
    100 g units, matching the rest of the module -- x[k] * 100 is grams and
    x[k] * per_100g_value is that food's contribution. Do NOT divide by 100
    again.
    """
    x = np.asarray(x, dtype=float)
    energy = np.asarray(fm.energy_arr, dtype=float)
    prot100 = _nutrient_arrays(fm)["protein"]
    serv_g = _serving_g_arr(fm)
    subs = fm.df.iloc[fm.cand_idx]["Food_Subgroup"].astype(str).to_numpy() \
        if "Food_Subgroup" in fm.df.columns else np.array([""] * len(x))

    items = []
    for k, xk in enumerate(x):
        grams = float(xk) * 100.0
        if grams <= 1e-9:
            continue
        sg = str(subs[k]) if k < len(subs) else ""
        sv = float(serv_g[k]) if k < len(serv_g) and serv_g[k] > 0 else 100.0
        items.append({
            "pos": k,
            "name": str(fm.names[k]),
            "sg": sg,
            "grams": grams,
            "kcal": float(xk) * float(energy[k]),
            "protein_g": float(xk) * float(prot100[k]),
            "group": _exchange_group_of(sg),
            "servings": grams / sv,
        })
    return items

def _exchange_targets(items, servings_ok: bool):
    """Per-meal kcal, protein and per-group exchange targets for THIS day.

    Every target is the day's own total times the template's share, so the
    template carries no absolute numbers -- see the block header.
    """
    total_kcal = sum(i["kcal"] for i in items) or 1.0
    total_prot = sum(i["protein_g"] for i in items) or 1.0

    t_kcal = {m: total_kcal * EXCHANGE_KCAL_SHARE[m] for m in MEAL_SLOTS}
    t_prot = {m: total_prot * EXCHANGE_PROTEIN_SHARE[m] for m in MEAL_SLOTS}

    day_group = {g: 0.0 for g in EXCHANGE_GROUPS}
    if servings_ok:
        for i in items:
            if i["group"]:
                day_group[i["group"]] += i["servings"]

    t_exch = {g: {m: 0.0 for m in MEAL_SLOTS} for g in EXCHANGE_GROUPS}
    for g in EXCHANGE_GROUPS:
        w = EXCHANGE_GROUP_MEAL_WEIGHTS.get(g, [1.0] * len(MEAL_SLOTS))
        wsum = float(sum(w)) or 1.0
        for j, m in enumerate(MEAL_SLOTS):
            t_exch[g][m] = day_group[g] * (w[j] / wsum)

    total_exch = sum(day_group.values())
    return {
        "kcal": t_kcal, "protein": t_prot, "exch": t_exch,
        "total_kcal": total_kcal, "total_protein": total_prot,
        "total_exch": total_exch, "day_group": day_group,
    }

def _exchange_state(assign):
    """Per-meal kcal / protein / per-group exchange totals for an arrangement."""
    st = {
        "kcal": {m: 0.0 for m in MEAL_SLOTS},
        "protein": {m: 0.0 for m in MEAL_SLOTS},
        "exch": {g: {m: 0.0 for m in MEAL_SLOTS} for g in EXCHANGE_GROUPS},
        "items": {m: 0 for m in MEAL_SLOTS},
        "subgroups": {m: [] for m in MEAL_SLOTS},
    }
    for m in MEAL_SLOTS:
        st["items"][m] = len(assign[m])
        st["subgroups"][m] = [it["sg"] for it in assign[m]]
        for it in assign[m]:
            st["kcal"][m] += it["kcal"]
            st["protein"][m] += it["protein_g"]
            if it["group"]:
                st["exch"][it["group"]][m] += it["servings"]
    return st

def _exchange_score(st, tg, w_exch: float) -> float:
    """Weighted deviation of an arrangement from the template. Lower is better.

    Each term is divided by the day's total of that quantity first, so all
    three are fractions of the day and the weights are dimensionless.
    """
    vk = 0.0
    for m in MEAL_SLOTS:
        lo, hi = MEAL_KCAL_BAND[m]
        lo_k, hi_k = lo * tg["total_kcal"], hi * tg["total_kcal"]
        if st["kcal"][m] < lo_k:
            vk += lo_k - st["kcal"][m]
        elif st["kcal"][m] > hi_k:
            vk += st["kcal"][m] - hi_k
    vk /= tg["total_kcal"]

    vp = sum(abs(st["protein"][m] - tg["protein"][m]) for m in MEAL_SLOTS)
    vp /= tg["total_protein"]

    ve = 0.0
    if w_exch > 0.0 and tg["total_exch"] > 0.0:
        for g in EXCHANGE_GROUPS:
            for m in MEAL_SLOTS:
                ve += abs(st["exch"][g][m] - tg["exch"][g][m])
        ve /= tg["total_exch"]

    vi = 0.0
    if EXCH_W_ITEM_COUNT > 0.0 and EXCHANGE_MAX_ITEMS_PER_MEAL > 0:
        n_total = sum(st["items"].values()) or 1
        over = sum(max(0, st["items"][m] - EXCHANGE_MAX_ITEMS_PER_MEAL)
                   for m in MEAL_SLOTS)
        vi = over / n_total

    vf = 0.0
    if EXCH_W_MEAL_PROTEIN_FLOOR > 0.0 and tg["total_protein"] > 0:
        short = 0.0
        for m in MEAL_SLOTS:
            fl = MEAL_PROTEIN_FLOOR_G.get(m, 0.0)
            if fl > 0.0 and st["protein"][m] < fl:
                short += fl - st["protein"][m]
        vf = short / tg["total_protein"]

    vcap = 0.0
    if EXCH_W_MEAL_PROTEIN_CEILING > 0.0 and tg["total_protein"] > 0:
        over = sum(max(0.0, st["protein"][m] - MEAL_PROTEIN_CEILING_G)
                   for m in MEAL_SLOTS)
        vcap = over / tg["total_protein"]

    vc = 0.0
    if EXCH_W_COMPATIBILITY > 0.0 and st.get("subgroups"):
        pen = 0.0
        for m in MEAL_SLOTS:
            _, bad = meal_compatibility(st["subgroups"][m])
            pen += sum(MIN_PAIR_COMPATIBILITY - sc for _, _, sc in bad)
        vc = pen / max(1, len(MEAL_SLOTS))

    va = 0.0
    if EXCH_W_PROTEIN_ANCHOR > 0.0 and st.get("subgroups"):
        surplus = 0
        for m_ in MEAL_SLOTS:
            n_anchor = sum(1 for sg in st["subgroups"][m_]
                           if str(sg).strip() in PROTEIN_ANCHOR_SUBGROUPS)
            surplus += max(0, n_anchor - MEAL_PROTEIN_ANCHORS_MAX)
        va = surplus / max(1, len(MEAL_SLOTS))

    vr = 0.0
    if EXCH_W_ARCHETYPE > 0.0 and st.get("subgroups"):
        probs = sum(len(meal_archetype_problems(m_, st["subgroups"][m_]))
                    for m_ in MEAL_SLOTS)
        vr = probs / max(1, len(MEAL_SLOTS))

    return (EXCH_W_KCAL * vk + EXCH_W_PROTEIN * vp + w_exch * ve
            + EXCH_W_ITEM_COUNT * vi + EXCH_W_MEAL_PROTEIN_FLOOR * vf
            + EXCH_W_COMPATIBILITY * vc + EXCH_W_PROTEIN_ANCHOR * va
            + EXCH_W_ARCHETYPE * vr + EXCH_W_MEAL_PROTEIN_CEILING * vcap)

def _exchange_build_meal_split(fm, x):
    """Arrange the day's foods against the exchange template.

    Same two-stage shape as PART 2E -- deal, then local search over single
    moves and pairwise swaps -- but the objective is the three-term score
    above rather than calorie-band violation alone.
    """
    items = _exchange_items(fm, x)
    if not items:
        return ({m: [] for m in MEAL_SLOTS}, {m: 0.0 for m in MEAL_SLOTS})

    servings_ok = _exchange_servings_usable(fm)
    w_exch = EXCH_W_EXCHANGE if servings_ok else 0.0
    tg = _exchange_targets(items, servings_ok)

    assign = {m: [] for m in MEAL_SLOTS}
    st = _exchange_state(assign)

    for it in sorted(items, key=lambda t: (-t["protein_g"], -t["kcal"], t["name"])):
        open_meals = [mm for mm in MEAL_SLOTS
                      if len(assign[mm]) < EXCHANGE_MAX_ITEMS_PER_MEAL]
        candidate_meals = open_meals or list(MEAL_SLOTS)
        best_m, best_v = None, None
        for m in candidate_meals:
            assign[m].append(it)
            trial = _exchange_state(assign)
            v = _exchange_score(trial, tg, w_exch)
            assign[m].pop()
            if best_v is None or v < best_v:
                best_m, best_v = m, v
        assign[best_m or MEAL_SLOTS[0]].append(it)
    st = _exchange_state(assign)

    best = _exchange_score(st, tg, w_exch)
    for _ in range(EXCHANGE_REBALANCE_PASSES):
        improved = False
        for src_m in MEAL_SLOTS:
            for it in list(assign[src_m]):
                for dst_m in MEAL_SLOTS:
                    if dst_m == src_m:
                        continue
                    if (len(assign[dst_m]) >= EXCHANGE_MAX_ITEMS_PER_MEAL
                            and len(assign[src_m])
                            <= EXCHANGE_MAX_ITEMS_PER_MEAL):
                        continue
                    assign[src_m].remove(it)
                    assign[dst_m].append(it)
                    v = _exchange_score(_exchange_state(assign), tg, w_exch)
                    if v < best - 1e-12:
                        best, improved = v, True
                        break
                    assign[dst_m].remove(it)
                    assign[src_m].append(it)
                else:
                    continue
                break
        for i, a_m in enumerate(MEAL_SLOTS):
            for b_m in MEAL_SLOTS[i + 1:]:
                for ia in list(assign[a_m]):
                    if ia not in assign[a_m]:
                        continue
                    for ib in list(assign[b_m]):
                        if ib not in assign[b_m]:
                            continue
                        assign[a_m].remove(ia)
                        assign[b_m].remove(ib)
                        assign[a_m].append(ib)
                        assign[b_m].append(ia)
                        v = _exchange_score(_exchange_state(assign), tg, w_exch)
                        if v < best - 1e-12:
                            best, improved = v, True
                            break
                        assign[a_m].remove(ib)
                        assign[b_m].remove(ia)
                        assign[a_m].append(ia)
                        assign[b_m].append(ib)
                    else:
                        continue
                    break
        if not improved:
            break

    st = _exchange_state(assign)

    globals()["_LAST_EXCHANGE_DIAGNOSTICS"] = {
        "state": st, "targets": tg, "servings_ok": servings_ok,
        "score": best,
        "unmapped": sorted({it["sg"] for it in items if not it["group"]}),
    }

    out = {m: sorted([(it["name"], it["grams"], it["kcal"])
                      for it in assign[m]], key=lambda t: (-t[2], t[0]))
           for m in MEAL_SLOTS}
    return out, {m: float(st["kcal"][m]) for m in MEAL_SLOTS}

_calorie_only_build_meal_split = build_meal_split
_calorie_only_print_meal_split = print_meal_split

_LAST_EXCHANGE_DIAGNOSTICS = None

def _use_exchange_template() -> bool:
    """Exchange template applies to the INGREDIENT pool only (choice 1)."""
    return EXCHANGE_TEMPLATE_ACTIVE and not globals().get("DISH_MODE", False)

def build_meal_split(fm, x):
    """Dispatch on pool type. Dish mode keeps PART 2E's calorie-only split."""
    if not _use_exchange_template():
        return _calorie_only_build_meal_split(fm, x)
    return _exchange_build_meal_split(fm, x)

def _fmt_exch(v: float) -> str:
    """Exchange counts to the nearest half, which is how the template reads."""
    h = round(v * 2.0) / 2.0
    if h <= 0.0:
        return "-"
    return f"{h:.0f}" if abs(h - round(h)) < 1e-9 else f"{h:.1f}"

def print_meal_split(fm, cfg, x):
    """Print the Diet Plan Split and save it to CSV.

    Dish mode defers to PART 2E entirely. Ingredient mode prints PART 2E's
    per-meal food listing first (unchanged, so nothing is lost), then the
    template grid: kcal, protein and exchange counts per meal, each against
    its target.
    """
    if not _use_exchange_template():
        return _calorie_only_print_meal_split(fm, cfg, x)

    assign, meal_kcal = build_meal_split(fm, x)
    diag = globals().get("_LAST_EXCHANGE_DIAGNOSTICS") or {}
    st, tg = diag.get("state"), diag.get("targets")
    servings_ok = bool(diag.get("servings_ok"))
    total = sum(meal_kcal.values()) or 1.0

    print(BOLD + "\n--- DIET PLAN SPLIT (5 meals, exchange template) ---" + RESET)
    print("  Foods are arranged against a per-meal template of energy,")
    print("  protein and exchange counts. The template is stored as SHARES,")
    print("  so the numbers below are this day's own totals redistributed --")
    print("  not fixed values carried over from another plan.")
    print("  NSGA-III optimized the WHOLE DAY as one flat list; it has no")
    print("  per-meal objective. Everything below is REPORTED, not enforced.")

    csv_rows, flagged = [], []
    print(f"\n  {'Meal':<12}{'kcal':>8}{'% day':>8}{'band':>14}")
    print("  " + "-" * 44)
    for meal in MEAL_SLOTS:
        kc = meal_kcal[meal]
        pct = 100.0 * kc / total
        lo, hi = MEAL_KCAL_BAND[meal]
        tol = MEAL_BAND_TOLERANCE_PP
        ok = lo * 100 - tol <= pct <= hi * 100 + tol
        if not ok:
            flagged.append((meal, pct, lo * 100, hi * 100))
        print(f"\n  {meal:<12}{kc:>8.0f}{pct:>7.1f}%"
              + "{:.0f}-{:.1f}%".format(lo * 100, hi * 100).rjust(13)
              + (" " if ok else "!"))
        if assign[meal]:
            for name, g, k in assign[meal]:
                print(f"      - {name[:52]:<54}{g:>7.0f} g{k:>8.0f} kcal")
                csv_rows.append({"meal": meal, "food": name,
                                 "grams": round(g, 1), "kcal": round(k, 1)})
        else:
            print("      -- NO FOOD PLACED --")

    print("\n  " + "-" * 44)
    print(f"  {'TOTAL':<12}{total:>8.0f}{100.0:>7.1f}%")

    if st and tg:
        hdr = ["Breakfast", "Snack 1", "Lunch", "Snack 2", "Dinner"]
        print(BOLD + "\n  --- TEMPLATE GRID (actual, target in brackets) ---"
              + RESET)
        line = "  " + " " * 16 + "".join(h.rjust(15) for h in hdr)
        print(line)
        print("  " + "-" * (16 + 15 * 5))

        row = "  " + "kcal".ljust(16)
        for m in MEAL_SLOTS:
            cell = "{:.0f} [{:.0f}]".format(st["kcal"][m], tg["kcal"][m])
            row += cell.rjust(15)
        print(row)

        row = "  " + "Protein (g)".ljust(16)
        for m in MEAL_SLOTS:
            cell = "{:.0f} [{:.0f}]".format(st["protein"][m], tg["protein"][m])
            row += cell.rjust(15)
        print(row)

        if servings_ok:
            for g in EXCHANGE_GROUPS:
                if tg["day_group"].get(g, 0.0) <= 0.0:
                    continue
                row = "  " + g.ljust(16)
                for m in MEAL_SLOTS:
                    a = _fmt_exch(st["exch"][g][m])
                    t = _fmt_exch(tg["exch"][g][m])
                    row += "{} [{}]".format(a, t).rjust(15)
                print(row)
        else:
            print("\n  Exchange COUNTS were not computed for this run: no")
            print("  serving-weights CSV was supplied, so every food defaults")
            print("  to a 100 g serving and a count would just be hectograms.")
            print("  Energy and protein above are unaffected. Supply the")
            print("  serving-weights file at the prompt to get the group rows.")

        if diag.get("unmapped"):
            print(f"\n  Subgroups counted in NO exchange group "
                  f"({len(diag['unmapped'])}): "
                  + ", ".join(diag["unmapped"][:8])
                  + (" ..." if len(diag["unmapped"]) > 8 else ""))
            print("  Their energy and protein DO count; only the group rows")
            print("  omit them. See EXCHANGE_GROUP_SUBGROUPS for why.")

        over_cap = [(mm, st["protein"][mm]) for mm in MEAL_SLOTS
                    if st["protein"][mm] > MEAL_PROTEIN_CEILING_G]
        if over_cap:
            print("\n  ! meals above the MPS saturation point "
                  f"({MEAL_PROTEIN_CEILING_G:.0f} g):")
            for mm, got in over_cap:
                waste = got - MEAL_PROTEIN_CEILING_G
                print(f"      {mm:<12} {got:5.1f} g  ({waste:.0f} g beyond "
                      f"what one sitting can use for tissue)")
            print("    Muscle protein synthesis saturates per meal. Protein")
            print("    above this is oxidised for energy, so it counts toward")
            print("    the day total and does no muscle work. Spreading it")
            print("    costs nothing and is what the Muscle objective is for.")

        short = [(mm, st["protein"][mm], MEAL_PROTEIN_FLOOR_G.get(mm, 0.0))
                 for mm in MEAL_SLOTS
                 if st["protein"][mm] < MEAL_PROTEIN_FLOOR_G.get(mm, 0.0)]
        if short:
            print("\n  ! meals below the MPS protein threshold:")
            for mm, got, fl in short:
                print(f"      {mm:<12} {got:5.1f} g  (floor {fl:.0f} g)")
            print("    Total protein can be on target while these fail --")
            print("    muscle protein synthesis is threshold-triggered per")
            print("    meal, so distribution is the thing being measured here.")
            print("    The split cannot create protein the day does not have;")
            print("    if this persists, the DAY needs more protein or the")
            print("    optimizer needs to spread it across more foods.")

        arche = [(mm, meal_archetype_problems(mm, st["subgroups"][mm]))
                 for mm in MEAL_SLOTS]
        arche = [(mm, p) for mm, p in arche if p]
        if arche:
            print("\n  ! meals that do not read as the meal they are:")
            for mm, probs in arche:
                print(f"      {mm:<12} {'; '.join(probs)}")
            print("    Nutrient totals can be correct while the PLATE is")
            print("    wrong. A dessert in the dinner slot is the failure a")
            print("    client sees first, whatever the numbers say.")

        counts = [len(assign[mm]) for mm in MEAL_SLOTS]
        print("\n  " + "Items per meal".ljust(16)
              + "".join(str(c).rjust(15) for c in counts))
        over = [mm for mm in MEAL_SLOTS
                if len(assign[mm]) > EXCHANGE_MAX_ITEMS_PER_MEAL]
        if over:
            print(f"  ! over the {EXCHANGE_MAX_ITEMS_PER_MEAL}-item cap: "
                  + ", ".join(over))
            print("    The arrangement could not spread them further without")
            print("    pushing a meal out of its calorie band. Nutrition wins")
            print("    that tie deliberately - see EXCH_W_ITEM_COUNT.")

        print(f"\n  Template deviation score: {diag.get('score', 0.0):.4f}  "
              "(0 = every meal exactly on template)")

    if flagged:
        print("\n  ! meals outside their calorie band:")
        for meal, pct, lo, hi in flagged:
            print(f"      {meal:<12} {pct:5.1f}%  (band {lo:.0f}-{hi:.1f}%)")
        print("    The day's foods could not be partitioned to fit. A pool of")
        print("    few large portions cannot hit a narrow snack band -- that")
        print("    is a selection problem, not an arrangement one.")

    for meal in MEAL_SLOTS:
        csv_rows.append({"meal": meal, "food": "__MEAL_TOTAL__",
                         "grams": round(sum(g for _, g, _ in assign[meal]), 1),
                         "kcal": round(meal_kcal[meal], 1)})
    pd.DataFrame(csv_rows).to_csv(cfg.meal_split_csv, index=False)
    print(f"\n  Saved: {cfg.meal_split_csv}")

    if st and tg:
        grid_path = re.sub(r"\.csv$", "", str(cfg.meal_split_csv)) + "_template.csv"
        grid_rows = []
        for m in MEAL_SLOTS:
            r = {"meal": m,
                 "kcal": round(st["kcal"][m], 1),
                 "kcal_target": round(tg["kcal"][m], 1),
                 "protein_g": round(st["protein"][m], 1),
                 "protein_g_target": round(tg["protein"][m], 1)}
            for g in EXCHANGE_GROUPS:
                key = g.lower().replace(" ", "_")
                if servings_ok:
                    r[key] = round(st["exch"][g][m], 2)
                    r[f"{key}_target"] = round(tg["exch"][g][m], 2)
                else:
                    r[key] = ""
                    r[f"{key}_target"] = ""
            grid_rows.append(r)
        try:
            pd.DataFrame(grid_rows).to_csv(grid_path, index=False)
            print(f"  Saved: {grid_path}")
        except Exception as exc:
            print(f"  (template grid not written: {type(exc).__name__}: {exc})")

